// The act step (SPEC 2, 6, 7, 8, 10): the one dispatcher from an action's kind to its executor,
// what an act-mode pass does once observe has read the factory (what the agent list proves,
// wakes past their timeout, plan, then plan's actions in order: start each ledger entry,
// pre-check usage for a token-spending class, run the executor, finish the entry with what it
// reported), and what the hooks between passes do to the ledger (an agent's answer, in text or
// through its answer tool, a wake's turn, the wake answer tool, `/factory retry`). Every entry
// that moves gets its `loop` event, once.
// register.ts holds $, builds the ActIo and keeps the store; everything here works through the
// ActIo and the live ledger, so the tests drive whole passes, and the argv safety test every
// executor, with a recording fake. The setting `planner` picks the layer that plans (v1's plan.ts,
// or v2/plan.ts), and with the v2 shadow on, v2 plans beside v1 and is only logged (v2 SPEC 2.3).
import { cliExecutors } from './act-cli'
import { agentExecutors, agentOf, interim, onAgentAnswer, onToolAnswer, purposeOfKey, repairAskOf, scriptAnswered } from './act-agents'
import { mergeExecutors } from './act-merge'
import type { ActIo, AgentAnswer, EventFields, Exec, ExecCtx, Executor, RunInit, RunResult } from './exec'
import { GITHUB_V2 } from './foundation'
import { changedEntries, finish, loopEvent, reconcileAgents, retryIssue, start } from './ledger'
import type { Runtime } from './observe'
import { plan, turnEnded } from './plan'
import { repairPrompt } from './prompts'
import { preCheck } from './rails'
import type { BreakerNotice } from './rails'
import type { Action, ActionKind, AgentStatus, AgentType, Config, Control, LedgerEntry, Ms, PlanResult, State } from './types'
import { planV2 } from './v2/plan'
import { V2_EXECUTORS, executorOf } from './v2/registry'
import { stepAnswered, stepAnswers, stepRecorded } from './v2/steps'
import { STEP_AGENT, V2_ACTION_KINDS } from './v2/types'
import { answerTool, expireWakes, onTurnComplete, onTurnStart, wakeExecutors } from './wake'
import type { TurnEnd } from './wake'

const HOUR = 3_600_000
const SUMMARY_MAX = 200
// callum-flow-event is one jq call and one append; a minute is ample
const EVENT_TIMEOUT_MS = 60_000

// Every kind's executor (SPEC 6.1): v1's, and v2's for its new kinds (v2/registry.ts). act.test.ts
// checks that no ActionKind lacks one.
export const EXECUTORS: Partial<Record<ActionKind, Executor>> = {
  ...cliExecutors,
  ...mergeExecutors,
  ...agentExecutors,
  ...wakeExecutors,
  ...Object.fromEntries(V2_ACTION_KINDS.map(kind => [kind, V2_EXECUTORS[kind]])),
}

// The kinds that write to GitHub, held for the rest of a pass once one met a rate limit, as
// plan holds them while the backoff lasts (plan.ts GITHUB, SPEC 10.2).
export const GITHUB_KINDS: readonly ActionKind[] = [
  'claim',
  'heartbeat',
  'sweep',
  'guard',
  'update-behind',
  'fix-linkage',
  'merge',
  'rollout',
  'close-issue',
  'release-parent',
  'abandon',
  'milestone-later',
  'milestone-expect',
  'pr-reopen',
  'pr-comment',
  'pr-close',
]

const WAKES: readonly ActionKind[] = ['judge', 'task', 'tell']

// dispatch: the action's executor, run once; under planner v2, v2's own for the kind first (a
// reused kind may have a v2 behaviour), run again after a GitHub blip (registry.ts). A kind with no
// executor, or an executor that throws, is a failed attempt; neither is a reason to stop the pass.
export async function dispatch(ctx: ExecCtx, action: Action): Promise<Exec> {
  const run = ctx.rt.config.planner === 'v2' ? executorOf(action.kind, EXECUTORS) : EXECUTORS[action.kind]
  if (run === undefined) return { status: 'failed', summary: `no executor for ${action.kind}`, noRetry: true }
  try {
    return await run(ctx, action)
  } catch (err) {
    return { status: 'failed', summary: clip(`${action.kind}: the executor threw: ${message(err)}`) }
  }
}

// --- commands and events (SPEC 6.1, 7.4, 11.1) ---------------------------------------------------

// commandOf: ExecCtx.cmd: the argv from the main checkout (or init.cwd) with the runtime's
// environment, which carries the repo, the configured labels and, when not acting, the event
// sink. stdin passes through as given, an empty string included. Each command joins the pass's
// list for the decision log.
export function commandOf(io: ActIo, rt: Runtime, log: string[]): ExecCtx['cmd'] {
  return (argv: string[], init: RunInit): Promise<RunResult> => {
    log.push(argv.join(' ').slice(0, 160))
    const run: RunInit & { cwd: string; env: Record<string, string> } = { cwd: init.cwd ?? rt.cwd, env: rt.env, timeoutMs: init.timeoutMs }
    if (init.stdin !== undefined) run.stdin = init.stdin
    return io.run(argv, run)
  }
}

// eventArgv: `callum-flow-event <state>` with the fields as its flags.
export function eventArgv(state: string, f: EventFields): string[] {
  const argv = ['callum-flow-event', state]
  if (f.issue !== undefined && f.issue !== null) argv.push('--issue', String(f.issue))
  if (f.run !== undefined && f.run !== null) argv.push('--run', f.run)
  if (f.branch !== undefined && f.branch !== null) argv.push('--branch', f.branch)
  if (f.pr !== undefined && f.pr !== null) argv.push('--pr', String(f.pr))
  if (f.head !== undefined && f.head !== null) argv.push('--head', f.head)
  if (f.note !== undefined && f.note !== null) argv.push('--note', f.note)
  return argv
}

// eventOf: ExecCtx.event. callum-flow-event exits non-zero only on a usage error (2); the error
// carries the exit as `exitCode`, which the executors read to never retry it.
export function eventOf(cmd: ExecCtx['cmd']): ExecCtx['event'] {
  return async (state, fields) => {
    const r = await cmd(eventArgv(state, fields), { timeoutMs: EVENT_TIMEOUT_MS })
    if (r.exitCode === 0) return
    const why = r.stderr.trim().split('\n').pop() ?? ''
    throw Object.assign(new Error(`callum-flow-event ${state}: exit ${r.exitCode}${why === '' ? '' : `: ${why}`}`), { exitCode: r.exitCode })
  }
}

// --- the live ledger ---------------------------------------------------------------------------

// The ledger as the driver holds it: one array, replaced whole by every transition. The pass and
// the hooks that fire during it (an agent's answer, a wake's turn) apply their transitions to the
// array as it is then, with no await between the read and the write, so neither loses the other's.
// logged: the loop event last logged for each key (logLoop); a ledger loaded from the store or the
// event log starts it with loggedOf, since each of its entries was logged as it got there.
export type Live = { ledger: LedgerEntry[]; logged?: Map<string, string> }

// loggedOf: the loop event each entry of a loaded ledger already logged.
export function loggedOf(ledger: readonly LedgerEntry[]): Map<string, string> {
  const out = new Map<string, string>()
  for (const entry of ledger) {
    const argv = loopEvent(entry)
    if (argv !== null) out.set(entry.key, JSON.stringify(argv))
  }
  return out
}

// transition: apply fn to the live ledger; the entries it changed, for their loop events.
export function transition(live: Live, fn: (ledger: LedgerEntry[]) => LedgerEntry[]): LedgerEntry[] {
  const before = live.ledger
  live.ledger = fn(before)
  return changedEntries(before, live.ledger)
}

// What an act step works with.
export type ActEnv = {
  io: ActIo
  // the acting runtime: its env sends events to the real log
  rt: Runtime
  live: Live
  // the pass's command list, for the decision log
  commands: string[]
  // a fresh wake id (SPEC 8.1 `id=`)
  wakeId: () => string
  // $.session.id(): the session a wake it submits belongs to ('' when unknown)
  session: string
  // writes the live ledger to the store: an attempt's start before its executor runs, and every
  // transition before its loop event, so a reload at any point finds what already happened;
  // false when it was not written
  save: () => Promise<boolean>
  // this session still holds the act lock, renewed now; once it does not, the pass runs nothing
  // more. Asked before every action.
  holds: () => Promise<boolean>
  // the kill switch is set (SPEC 11.3): one stat, asked before every action but the title and
  // before a notice goes out; once it is, the pass runs nothing more
  killed: () => Promise<boolean>
  // what went wrong outside any one action (a loop event not logged), for the decision log
  problems: string[]
}

export function ctxOf(env: ActEnv, state: State, entry: LedgerEntry): ExecCtx {
  const cmd = commandOf(env.io, env.rt, env.commands)
  return { io: env.io, rt: env.rt, state, entry, cmd, event: eventOf(cmd), wakeId: env.wakeId }
}

// logLoop: the `loop` event of each entry a transition moved that logs one: agents, wakes and
// owner notices (D-09, ledger.ts loopEvent), one per transition: an entry whose event would say
// just what its key's last one said is not logged again. A wake's turn taking its id, its
// reminder going out, and a turn that starts inside its submit (so turn.start moves the entry
// before the executor finishes it) each change the entry but not its event (run 2, #536). A
// failed log is noted, never retried.
export async function logLoop(env: Pick<ActEnv, 'io' | 'rt' | 'commands' | 'problems' | 'live'>, entries: readonly LedgerEntry[]): Promise<void> {
  const cmd = commandOf(env.io, env.rt, env.commands)
  const logged = (env.live.logged ??= new Map())
  for (const entry of entries) {
    const argv = loopEvent(entry)
    if (argv === null) continue
    const said = JSON.stringify(argv)
    if (logged.get(entry.key) === said) continue
    logged.set(entry.key, said)
    try {
      const r = await cmd(argv, { timeoutMs: EVENT_TIMEOUT_MS })
      if (r.exitCode !== 0) env.problems.push(clip(`loop event ${entry.key}: exit ${r.exitCode}`))
    } catch (err) {
      env.problems.push(clip(`loop event ${entry.key}: ${message(err)}`))
    }
  }
  // a key the ledger no longer holds (pruned, or a notice a retry cleared) is forgotten
  const held = new Set(env.live.ledger.map(e => e.key))
  for (const key of logged.keys()) if (!held.has(key)) logged.delete(key)
}

// --- one pass's actions ------------------------------------------------------------------------

// One action's result, for the decision log (SPEC 12); at: when it started, for the trace (#552),
// absent for an action held before it started.
export type ActOutcome = { key: string; kind: ActionKind; status: Exec['status']; ms: Ms; summary: string; at?: Ms }

export type ActReport = {
  outcomes: ActOutcome[]
  // an executor met a GitHub rate limit: register sets the backoff (SPEC 10.2)
  rateLimited: boolean
  // the title the title action set, when it did
  title: string | null
  // the kill switch stopped the pass between actions: register shows the loop off at once
  killed: boolean
}

// runActions: plan's actions in plan's order (finish in-flight work before starting new work).
// The kill switch is asked before each action but the title (bookkeeping only): an action
// already running finishes, and once the switch is seen every action left is skipped (#557).
export async function runActions(env: ActEnv, state: State, actions: readonly Action[]): Promise<ActReport> {
  const report: ActReport = { outcomes: [], rateLimited: false, title: null, killed: false }
  const github = env.rt.config.planner === 'v2' ? GITHUB_V2 : GITHUB_KINDS
  for (const action of actions) {
    if (!report.killed && action.kind !== 'title' && (await env.killed())) report.killed = true
    if (report.killed) {
      report.outcomes.push({ key: action.key, kind: action.kind, status: 'skipped', ms: 0, summary: 'kill switch' })
      continue
    }
    if (!(await env.holds())) {
      report.outcomes.push({ key: action.key, kind: action.kind, status: 'skipped', ms: 0, summary: 'held: the act lock is no longer this session\'s' })
      continue
    }
    if (report.rateLimited && github.includes(action.kind)) {
      report.outcomes.push({ key: action.key, kind: action.kind, status: 'skipped', ms: 0, summary: 'held: GitHub rate limit met this pass' })
      continue
    }
    const out = await actOne(env, state, action)
    report.outcomes.push(out.outcome)
    if (out.exec.status === 'failed' && out.exec.rateLimited === true) report.rateLimited = true
    if (action.kind === 'title' && out.exec.status === 'done') report.title = action.text
  }
  return report
}

// actOne: one action through the ledger (SPEC 7): start (a retry keeps the key and counts an
// attempt), the usage pre-check for start, develop and drive (a refusal puts the entry back as
// it stood, SPEC 10.7), the running entry saved, the executor, then finish with its Exec and
// { config, prev }. The title is compared, not keyed (SPEC 5.8 O1), so it runs without an entry.
export async function actOne(env: ActEnv, state: State, action: Action): Promise<{ outcome: ActOutcome; exec: Exec }> {
  const t0 = await env.io.now()
  const done = async (exec: Exec) => {
    const ms = (await env.io.now()) - t0
    return { exec, outcome: { key: action.key, kind: action.kind, status: exec.status, ms, summary: clip(exec.summary), at: t0 } }
  }
  if (action.kind === 'title') return done(await dispatch(ctxOf(env, state, start([], action, t0).entry), action))

  const s = start(env.live.ledger, action, t0, env.session)
  // no loop event yet: the start and its finish are one transition, logged once
  env.live.ledger = s.ledger
  const opts = { config: env.rt.config, prev: s.prev }
  const refused = await preCheck({ usage: env.io.usage, now: env.io.now }, action, env.rt.config, state.control.usageOverride)
  if (refused !== null) {
    const now = await env.io.now()
    env.live.ledger = finish(env.live.ledger, action.key, refused, now, opts)
    await env.save()
    return done(refused)
  }
  // the entry is in the store, running, before anything happens: a reload, a crash or a restart
  // (restart-self ends the session) mid-action finds it and marks it lost, so its attempt counts
  // and its rule re-derives what to do (SPEC 7.5). A ledger that cannot be saved starts nothing.
  if (!(await env.save())) {
    const held: Exec = { status: 'skipped', summary: 'held: the ledger was not saved, so nothing starts' }
    env.live.ledger = finish(env.live.ledger, action.key, held, await env.io.now(), opts)
    return done(held)
  }
  const exec = await dispatch(ctxOf(env, state, s.entry), action)
  await record(env, action.key, s.entry, exec, opts)
  return done(exec)
}

// record: finish the attempt with the executor's Exec, saved before its loop event, unless a hook
// already ended it: a wake answered (or a tell delivered) before its submit returned stays
// answered, and an entry a later attempt or a hook replaced is left alone (SPEC 8.2, wake.ts
// onTurnStart); the hook saved it.
async function record(
  env: ActEnv,
  key: string,
  started: LedgerEntry,
  exec: Exec,
  opts: { config: Runtime['config']; prev: LedgerEntry | null },
): Promise<void> {
  const now = await env.io.now()
  const current = env.live.ledger.find(e => e.key === key)
  if (current === undefined || current.startedAt !== started.startedAt || current.attempts !== started.attempts) return
  if (exec.status === 'running' && current.status !== 'running') return
  const moved = transition(env.live, l => finish(l, key, exec, now, opts))
  await env.save()
  await logLoop(env, moved)
}

// --- notices from outside plan (SPEC 9.2, 11.2, 11.4) --------------------------------------------

// openWake: a judge, task or tell that is still running. Only one wake is open at a time (O2).
export function openWake(ledger: readonly LedgerEntry[]): LedgerEntry | undefined {
  return ledger.find(e => e.status === 'running' && WAKES.includes(e.kind))
}

// sendNotice: a tell that comes from outside plan (a rail, the ping breaker, failing passes) goes
// out through the wake executor under its own key, once, and only while no wake is open: a key
// the ledger holds was sent, unless it was lost (the engine dropped it before its turn); an open
// wake keeps it waiting (the caller keeps it pending), as does the kill switch.
export async function sendNotice(env: ActEnv, state: State, tell: Action): Promise<'sent' | 'waiting' | 'failed'> {
  if (env.live.ledger.some(e => e.key === tell.key && e.status !== 'lost')) return 'sent'
  if (openWake(env.live.ledger) !== undefined || (await env.killed())) return 'waiting'
  const { exec } = await actOne(env, state, tell)
  return exec.status === 'running' || exec.status === 'done' ? 'sent' : 'failed'
}

// passErrorTell: three passes in a row threw (SPEC 10.9): the owner hears of it once per spell.
export function passErrorTell(since: Ms, passes: number, error: string): Action {
  return {
    kind: 'tell',
    wake: 'pass-error',
    key: `tell:pass-error:${since}`,
    class: 'owner',
    rule: 'O2',
    reason: 'tell pass-error',
    issue: null,
    fields: { passes: String(passes) },
    context: [`last error: ${error.replace(/\s+/g, ' ').slice(0, 300)}`],
  }
}

// --- rate-cap holds (SPEC 11.4, D-24) ---------------------------------------------------------------

// capKey: a rate cap plan tripped (a bucket, or '<kind>:<issue>') as its hourly loop event's key.
export function capKey(capped: string, now: Ms): string {
  return `cap:${capped}:${Math.floor(now / HOUR)}`
}

// capEventArgv: a rate-cap hold has no ledger entry of its own, so its `loop` event is built
// here: one per capped bucket or kind and issue per hour, status held.
export function capEventArgv(capped: string, now: Ms): string[] {
  const [kind = capped, issue] = capped.split(':')
  const argv = ['callum-flow-event', 'loop']
  if (issue !== undefined && /^\d+$/.test(issue)) argv.push('--issue', issue)
  argv.push('--note', `kind=${kind} key=${capKey(capped, now)} status=held`)
  return argv
}

// breakerEventArgv: the ping-storm breaker opened (SPEC 2, 11.4, D-39): its `loop` event, beside
// its one tell.
export function breakerEventArgv(b: BreakerNotice): string[] {
  return ['callum-flow-event', 'loop', '--note', `kind=breaker key=breaker:pings:${b.since} status=open passes=${b.passes} until=${b.until}`]
}

// --- what a reload and the agent list prove (SPEC 3.3, 7.5, 10.4) --------------------------------

export type ListedAgent = { id: string; status: AgentStatus }

// How long an agent sent the repair message counts as at work while the list still shows its
// turn ended, idle or completed (reconcilable): the engine resumes it from its transcript (#548),
// and when the list shows that is not proven. Past it, the usual one pass of grace, then lost.
export const REPAIR_GRACE_MS = 5 * 60_000

// reconcilable: the agent list as reconcileAgents should judge it. An agent listed idle has ended
// its turn as one listed completed has (plan.ts turnEnded, #560), and each rule here reads them
// alike. An agent whose answer is being handled counts as running, listed or not, so a pass in
// between never marks it lost: that covers an agent whose repair message is on its way, since
// agentAnswered holds it in `answering` until the engine answers the send. So does one whose
// turn ended within REPAIR_GRACE_MS of its repair message being delivered (repairing: when each
// went out, until its next turn.complete), for the loop awaits its reply; an agent first listed
// with its turn ended counts as running for that pass, since its turn.complete may still be on
// its way (seen: when each id was first so listed, idle then completed being one sighting). seen
// and repairing are updated in place.
export function reconcilable(
  agents: readonly ListedAgent[],
  answering: ReadonlySet<string>,
  seen: Map<string, Ms>,
  now: Ms,
  repairing: Map<string, Ms>,
): ListedAgent[] {
  for (const [id, at] of [...repairing]) if (now - at > REPAIR_GRACE_MS) repairing.delete(id)
  const out = agents.map(a => {
    if (answering.has(a.id)) return { id: a.id, status: 'running' as AgentStatus }
    if (!turnEnded(a.status)) return a
    if (repairing.has(a.id)) return { id: a.id, status: 'running' as AgentStatus }
    const first = seen.get(a.id)
    if (first === undefined) seen.set(a.id, now)
    return first === undefined || first === now ? { id: a.id, status: 'running' as AgentStatus } : a
  })
  for (const id of answering) if (!agents.some(a => a.id === id)) out.push({ id, status: 'running' })
  for (const id of [...seen.keys()]) if (!agents.some(a => a.id === id && turnEnded(a.status))) seen.delete(id)
  return out
}

// updateDone: rule H4's restart for this update ran and the workspace came back: its entry is
// lost (the session restarted under it), or done before this module loaded. dev-restart-self
// returns once Coder accepts the build, minutes before the container is replaced, so a restart
// this module saw end is not done yet: the drain holds until the new session loads (D-15).
// control.updateDue is then cleared, or the loop would drain forever. A failed restart keeps the
// drain, and plan tells the owner (agent-failed).
export function updateDone(ledger: readonly LedgerEntry[], control: Control, loadedAt: Ms): boolean {
  const due = control.updateDue
  if (due === null) return false
  const restart = ledger.find(e => e.key === `restart:${due.at}`)
  return restart?.status === 'lost' || (restart?.status === 'done' && (restart.endedAt ?? loadedAt) < loadedAt)
}

// --- one act-mode pass, from what observe read (SPEC 2) --------------------------------------------

// What the hooks between passes share with the pass: the agents whose answer is being handled,
// when each agent was first listed with its turn ended (idle or completed), and when each was
// sent its repair message (reconcilable).
export type Between = { answering: Set<string>; completedSeen: Map<string, Ms>; repairing: Map<string, Ms> }

// The pass's agent list: only a read that worked may mark agents lost.
export type Listed = { ok: boolean; agents: ListedAgent[] }

// planned: when plan handed its actions over and how long it took (performance.now()), for the
// trace (#552); shadow: the v2 shadow's plan, logged and never executed
export type Acted = { state: State; result: PlanResult; report: ActReport; planned: { at: Ms; ms: number }; shadow: Shadowed | null }

// The v2 shadow's plan, or why it could not plan: a shadow that throws never fails the pass.
export type Shadowed = PlanResult | { error: string }

// planPass: the planner's plan (v2 SPEC 2.3), and with planner v1 and the shadow on, the v2
// shadow's beside it, which is logged and never executed. The shadow plans with the settings v2
// would run with (v2Config: v2's defaults where no file sets a key), in the pass's mode.
export function planPass(state: State, config: Config, v2Config: Config = config): { result: PlanResult; shadow: Shadowed | null } {
  if (config.planner === 'v2') return { result: planV2(state, config), shadow: null }
  const result = plan(state, config)
  if (config.shadow !== 'v2') return { result, shadow: null }
  try {
    return { result, shadow: planV2(state, { ...v2Config, mode: config.mode }) }
  } catch (err) {
    return { result, shadow: { error: clip(`the v2 shadow threw: ${message(err)}`) } }
  }
}

// finishAsRead: an answer read for an entry, applied only while the entry still runs as it was
// read (its turn.complete may have finished it during the read); the entries it moved.
function finishAsRead(env: ActEnv, was: LedgerEntry, exec: Exec, now: Ms): LedgerEntry[] {
  const current = env.live.ledger.find(e => e.key === was.key)
  if (current?.status !== 'running' || current.agentId !== was.agentId || current.startedAt !== was.startedAt) return []
  return transition(env.live, l => finish(l, was.key, exec, now, { config: env.rt.config }))
}

// answeredBeforeLost: the agent entries the agent list would mark lost (gone from it, or its turn
// ended with no answer read) whose agent recorded an answer with the answer script that passes its
// checks (#561): each is finished with that answer, as its turn.complete would have finished it
// (act-agents.ts scriptAnswered). An entry its turn.complete finished during the read is left
// alone.
async function answeredBeforeLost(env: ActEnv, state: State, agents: readonly ListedAgent[], now: Ms): Promise<LedgerEntry[]> {
  const before = env.live.ledger
  // reconcileAgents keeps the ledger's order, entry for entry
  const reconciled = reconcileAgents(before, agents, now)
  const lost = before.filter((e, i) => e.status === 'running' && reconciled[i]?.status === 'lost')
  const moved: LedgerEntry[] = []
  for (const was of lost) {
    const exec = was.kind === 'agent-step' ? await stepRecorded(ctxOf(env, state, was), was, true) : await scriptAnswered(ctxOf(env, state, was), was)
    if (exec !== null) moved.push(...finishAsRead(env, was, exec, now))
  }
  return moved
}

// actPass: the act-mode pass once the rails passed and observe read the factory: what the agent
// list proves (SPEC 3.3, 10.4) and wakes past their timeout (SPEC 8.2) go into the ledger first,
// then plan reads the state with that ledger, and its actions run in plan's order.
export async function actPass(env: ActEnv, observed: State, listed: Listed, between: Between): Promise<Acted> {
  const now = observed.now
  const moved: LedgerEntry[] = []
  if (listed.ok) {
    const agents = reconcilable(listed.agents, between.answering, between.completedSeen, now, between.repairing)
    moved.push(...(await answeredBeforeLost(env, observed, agents, now)))
    moved.push(...transition(env.live, l => reconcileAgents(l, agents, now)))
  }
  for (const u of expireWakes(env.live.ledger, now, env.rt.config)) moved.push(...transition(env.live, l => finish(l, u.key, u, now)))
  // under planner v2 a recorded answer ends its step when read (v2 SPEC 10.8)
  if (env.rt.config.planner === 'v2') for (const r of await stepAnswers(env.live.ledger, e => ctxOf(env, observed, e))) moved.push(...finishAsRead(env, r.entry, r.exec, now))
  if (moved.length > 0) {
    await env.save()
    await logLoop(env, moved)
  }
  const state = { ...observed, ledger: env.live.ledger }
  const from = performance.now()
  const { result, shadow } = planPass(state, env.rt.config, env.rt.v2Config)
  const planned = { ms: performance.now() - from, at: await env.io.now() }
  const report = await runActions(env, state, result.actions)
  return { state, result, report, planned, shadow }
}

// --- between passes: the hooks that feed the ledger (SPEC 2, 8.2, 10.4) ----------------------------

// The one repair message to an agent of the loop, of the type it runs as (a v1 agent's, or a v2
// step's agent type, plugin:name): null once delivered, else why not, in the engine's own words.
export type Repair = (agentId: string, text: string, type: AgentType | `${string}:${string}`) => Promise<string | null>

// What an agent's answer did: 'applied' (its entry finished; repaired when a repair message went
// out before it), 'repair' (unreadable, so the agent was asked once more), 'waiting' (interim),
// 'recorded' (its tool already answered), 'dropped' or 'not ours'. key: its entry; via: how an
// applied answer came (the answer script's file, #561, or its text); scriptProblem: what kept a
// file it recorded out; undelivered: why its repair message was not delivered, whole, for the
// decision log (the entry's summary keeps a clipped copy, #559).
export type Answered = {
  result: 'applied' | 'repair' | 'waiting' | 'recorded' | 'dropped' | 'not ours'
  why?: string
  key?: string
  repaired?: boolean
  via?: 'script' | 'text'
  scriptProblem?: string
  undelivered?: string
}

// agentAnswered: an agent of the loop finished (its turn.complete): its answer is read into the
// outcome (act-agents.ts onAgentAnswer: the file it recorded with the answer script, else its
// text; it logs the verdict and superseded events) and its entry finished. 'applied' asks for a
// pass. An agent the ledger never held is 'not ours'; an answer for an entry that no longer runs
// (an A1 stop timed it out, a retry replaced it) is logged and dropped, never applied, and the
// closing words of an agent whose tool already answered change nothing. An interim answer (no
// machine line, #545) from an agent atWork finds still at work leaves its entry running for its
// next answer, up to its timeout (rule A1); atWork is asked only then. A final answer with no
// machine line first gets one repair message to the same agent, naming what was wrong and asking
// again on the channel its spawn was asked on (#548, #561): the entry runs on with its attempt
// unspent, and only an answer still unreadable after it, or a message that could not be
// delivered, fails the attempt (or sends the designer's report to the model, rule D3) as before.
// A tool call is answered outside the hook queue (#558), so it may finish the entry while this
// answer is read: the entry is checked again just before each change, with no await between, and
// an entry its tool finished meanwhile is 'recorded', the text never read over it.
export async function agentAnswered(
  env: ActEnv,
  state: State,
  answer: AgentAnswer,
  between: Between,
  atWork: (agentId: string) => Promise<boolean> = async () => false,
  repair: Repair = async () => 'the loop sends no messages from here',
): Promise<Answered> {
  const id = answer.agentId
  const entry = env.live.ledger.find(e => e.agentId === id && (e.kind === 'spawn' || e.kind === 'delegate' || e.kind === 'agent-step'))
  if (entry === undefined) return { result: 'not ours' }
  if (entry.status === 'done') return { result: 'recorded', key: entry.key }
  if (entry.status !== 'running') return { result: 'dropped', why: `late answer for ${entry.key} (${entry.status})` }
  between.answering.add(id)
  between.repairing.delete(id)
  try {
    // a v2 agent step's answer is read by steps.ts, and is never interim (v2 SPEC 10.8)
    const step = entry.kind === 'agent-step' ? await stepAnswered(ctxOf(env, state, entry), entry, answer) : null
    const read = step === null ? await onAgentAnswer(ctxOf(env, state, entry), entry, answer) : { exec: step.exec, problem: step.problem, via: 'script' as const, channel: 'script' as const }
    let exec = read.exec
    const ours = (e: LedgerEntry | undefined): e is LedgerEntry => e !== undefined && e.agentId === id && e.startedAt === entry.startedAt
    const still = () => {
      const current = env.live.ledger.find(e => e.key === entry.key)
      return ours(current) && current.status === 'running' ? current : null
    }
    // the attempt no longer runs: its tool answered meanwhile, or a stop or a retry ended it
    const ended = (): Answered => {
      const current = env.live.ledger.find(e => e.key === entry.key)
      return ours(current) && current.status === 'done' ? { result: 'recorded', key: entry.key } : { result: 'dropped', why: `answer for ${entry.key} came after the entry ended` }
    }
    if (still() === null) return ended()
    const unread = step === null ? interim(answer, exec) : step.repair !== null
    if (step === null && unread && (await atWork(id))) {
      return { result: 'waiting', why: `interim answer for ${entry.key}: the agent still works, so its final answer is awaited` }
    }
    const at = await env.io.now()
    const current = still()
    if (current === null) return ended()
    const repaired = current.reminded === true
    const type = agentOf(entry)
    let refused: string | undefined
    if (unread && !repaired && (step !== null || type !== null)) {
      const problem = read.problem ?? 'no machine line'
      // the repair is on the entry before it goes out, so a reload never sends a second one
      const marked = transition(env.live, l => finish(l, entry.key, { status: 'running', reminded: true }, at))
      await env.save()
      await logLoop(env, marked)
      // the channel the spawn's prompt asked for (its record); text when it names none, or the
      // script's job file is gone. A v2 step's own repair asks for the script again.
      let ask: { text: string; type: AgentType | `${string}:${string}` } = { text: step?.repair ?? '', type: step?.subagentType ?? STEP_AGENT.build }
      if (step === null && type !== null) {
        const { channel, script } = await repairAskOf(env, entry, read.channel)
        ask = { text: repairPrompt(type, purposeOfKey(entry.key), problem, channel, script), type }
      }
      const undelivered = await repair(id, ask.text, ask.type)
      if (undelivered === null) {
        // listed idle or completed until the message resumes it, which the list may show late: the
        // passes take it as at work for a while, then count that listing afresh
        between.completedSeen.delete(id)
        between.repairing.set(id, at)
        return { result: 'repair', why: problem, key: entry.key }
      }
      refused = undelivered
      exec = { ...exec, summary: clip(`${exec.summary}; the repair message was not delivered: ${undelivered}`) }
    }
    const now = await env.io.now()
    if (still() === null) return ended()
    const moved = transition(env.live, l => finish(l, entry.key, exec, now, { config: env.rt.config }))
    await env.save()
    await logLoop(env, moved)
    const applied: Answered = { result: 'applied', key: entry.key, repaired, via: read.via }
    if (read.scriptProblem !== undefined) applied.scriptProblem = read.scriptProblem
    if (refused !== undefined) applied.undelivered = refused
    return applied
  } finally {
    between.answering.delete(id)
  }
}

// The refusal of a tool call that could not be decided in time (#558): the agent answers in text.
export const TOOL_LATE = 'Not recorded: the factory loop could not check this answer in time; reply with your text lines instead.'

// Asked just before a tool call changes the ledger: false once the caller has answered the call
// without it (register.ts bounded), and then nothing changes.
export type Claim = () => boolean

// What an answer tool's call did: ok and the text the agent reads; key: the entry it answered;
// after: an accepted call's follow-up, run once the call has its answer (#558): its events, the
// ledger saved and the entry's loop event, in that order (its input was saved before the call was
// recorded); notes on what failed, for the decision log.
export type ToolAnswered = { ok: boolean; text: string; key?: string; repaired?: boolean; after?: (env: ActEnv) => Promise<string[]> }

// agentToolAnswered: an agent's answer tool (agent-tools.ts, #548), tied to the entry that
// spawned it by the call's agentId. Only an agent whose entry still runs may answer: the main
// conversation, an agent the loop did not start (an implementer's own sub-agents among them) and
// one whose answer is in are refused. A call the contract refuses changes nothing and tells the
// agent what to correct; an accepted one finishes the entry at once, as its text would (its
// turn's closing words are then not read). Both channels share the reading, so a tool answer
// means exactly what the same answer in text means. The call is answered before the engine gives
// up on it (#558): the entry is checked and finished in the live ledger with no await between,
// so the answer is true when given and every hook and pass after it sees the entry done, and
// what is slow is left to `after`.
export async function agentToolAnswered(
  env: ActEnv,
  state: State,
  tool: string,
  input: unknown,
  agentId: string | undefined,
  claim: Claim = () => true,
): Promise<ToolAnswered> {
  const no = (why: string, key?: string): ToolAnswered => (key === undefined ? { ok: false, text: `Not recorded: ${why}.` } : { ok: false, text: `Not recorded: ${why}.`, key })
  if (agentId === undefined) return no('this tool takes the answer of an agent the factory loop started, and the main conversation is none')
  const entry = env.live.ledger.find(e => e.agentId === agentId && (e.kind === 'spawn' || e.kind === 'delegate'))
  if (entry === undefined) return no('the factory loop is waiting on no answer from this agent')
  if (entry.status !== 'running') {
    return no(entry.status === 'done' ? 'your answer is already recorded; end your turn' : `the factory loop no longer waits on this agent (${entry.status})`, entry.key)
  }
  const r = await onToolAnswer(ctxOf(env, state, entry), entry, tool, input)
  if ('refused' in r) return no(r.refused, entry.key)
  const now = await env.io.now()
  const current = env.live.ledger.find(e => e.key === entry.key)
  if (current === undefined || current.agentId !== agentId || current.status !== 'running' || current.startedAt !== entry.startedAt) {
    return no('the factory loop stopped waiting on this agent meanwhile', entry.key)
  }
  if (!claim()) return { ok: false, text: TOOL_LATE, key: entry.key }
  const moved = transition(env.live, l => finish(l, entry.key, r.exec, now, { config: env.rt.config }))
  const after = async (later: ActEnv): Promise<string[]> => {
    const notes = await r.after(ctxOf(later, state, entry))
    await keep(later, moved)
    return notes
  }
  return { ok: true, text: `Recorded: ${r.exec.summary}. End your turn now; no reply lines are needed.`, key: entry.key, repaired: current.reminded === true, after }
}

// keep: what follows a transition a hook made at once in the live ledger (#558): the ledger
// saved, then the moved entries' loop events.
export async function keep(env: ActEnv, moved: readonly LedgerEntry[]): Promise<void> {
  if (moved.length === 0) return
  await env.save()
  await logLoop(env, moved)
}

const WAKE_HEAD = /^(JUDGE|TASK|TELL) /m

// wakeStarted: a turn that opens with a wake's first line is that wake's turn (wake.ts
// onTurnStart). A frame the engine puts before a plugin's prompt is skipped to that line.
export async function wakeStarted(env: ActEnv, said: string, turnId: string): Promise<boolean> {
  const at = said.search(WAKE_HEAD)
  if (at < 0) return false
  const now = await env.io.now()
  const u = onTurnStart(env.live.ledger, said.slice(at), turnId)
  if (u === null) return false
  const moved = transition(env.live, l => finish(l, u.key, u, now))
  await env.save()
  await logLoop(env, moved)
  return true
}

// wakeEnded: a main-loop turn ended (wake.ts onTurnComplete): its ANSWER blocks close their
// wakes, a tell's own turn delivers it, an unanswered wake gets its one reminder. The caller
// submits the prompts (never awaiting them inside the turn's own hook), logs the problems, and
// pings when a wake moved.
export async function wakeEnded(env: ActEnv, turn: TurnEnd): Promise<{ moved: boolean; prompts: string[]; problems: string[] }> {
  const now = await env.io.now()
  const out = onTurnComplete(env.live.ledger, turn, env.rt.repo)
  const moved = out.updates.flatMap(u => transition(env.live, l => finish(l, u.key, u, now)))
  if (moved.length > 0) {
    await env.save()
    await logLoop(env, moved)
  }
  return { moved: out.updates.length > 0, prompts: out.prompts, problems: out.problems }
}

// wakeAnswered: mcp__factory-loop__answer, checked as the ANSWER block is (wake.ts answerTool)
// and recorded in the live ledger at once, with no await between the check and the change, as an
// agent's tool is (#558); `moved` asks for keep, once the call has its answer. claim: as for
// agentToolAnswered.
export async function wakeAnswered(
  env: ActEnv,
  input: unknown,
  agentId: string | undefined,
  claim: Claim = () => true,
): Promise<{ ok: boolean; text: string; moved: LedgerEntry[] }> {
  const now = await env.io.now()
  const r = answerTool(env.live.ledger, input, env.rt.repo, agentId === undefined ? {} : { agentId })
  const update = r.update
  if (update === null) return { ok: r.ok, text: r.text, moved: [] }
  if (!claim()) return { ok: false, text: TOOL_LATE, moved: [] }
  return { ok: r.ok, text: r.text, moved: transition(env.live, l => finish(l, update.key, update, now)) }
}

// retried: `/factory retry <N>` clears the issue's exhausted entries in the live ledger at once
// (D-38, ledger.ts retryIssue): the keys it cleared, and the entries it moved, for keep once the
// op has its answer (#558).
export function retried(env: Pick<ActEnv, 'live' | 'rt'>, issue: number): { cleared: string[]; moved: LedgerEntry[] } {
  let cleared: string[] = []
  const moved = transition(env.live, l => {
    const r = retryIssue(l, issue, env.rt.config)
    cleared = r.cleared
    return r.ledger
  })
  return { cleared, moved }
}

// --- small helpers --------------------------------------------------------------------------------

function clip(text: string): string {
  return text.length > SUMMARY_MAX ? `${text.slice(0, SUMMARY_MAX - 3)}...` : text
}

function message(err: unknown): string {
  return err instanceof Error ? err.message : String(err)
}

files.hooks/act-agents.ts:
// The agent executors (SPEC 6.1): `spawn` (designer, adjudicator, fixer) and `delegate` (route,
// the `delegated` event, then the implementer), and onAgentAnswer and onToolAnswer, which read
// an agent's answer, from its turn.complete (the file it recorded with the answer script, #561,
// else its text) or its answer tool (#548), into the outcome plan reads next pass. They decide
// nothing (plan did): the prompt comes from prompts.ts and the reading of the answer from
// replies.ts and contract.mjs, all pure, and readAnswer, readScriptAnswer and readToolAnswer
// below are pure too, so tests and the replay harness drive them without the engine. Every
// answer in text is saved whole first (exec.ts answerPath), so a judge(report) or judge(handoff)
// wake points the model at the file (SPEC 7.2); a tool call's input is saved once the call has
// its answer (#558).
import { TOOL_OF } from './agent-tools'
import { CONTRACT_OF, checkAnswer, jobPathOf, jobText, parseAnswer } from './contract.mjs'
import type { AnswerOutcome, Check, Job } from './contract.mjs'
import { ANSWER_SCRIPT, answerPath, detailOf, rateLimited, scriptAnswerPath } from './exec'
import type { AgentAnswer, EventFields, Exec, ExecCtx, Executor, RunResult, SpawnInput } from './exec'
import type { Runtime } from './observe'
import { descriptionOf, nameOf, promptOf, scriptShaped } from './prompts'
import type { AgentAction, InFlight, PromptEnv, ScriptPlace } from './prompts'
import { isBriefUrl, readAdjudicator, readDesigner, readHandoff } from './replies'
import type { ActionKind, AdjudicatorPurpose, AgentStatus, AgentType, AnswerChannel, LedgerEntry, State } from './types'

// callum-flow-implementer-route's timeout (SPEC 6.1: route 60 s).
export const ROUTE_TIMEOUT_MS = 60_000
// The exit recorded for a command that never exited (it could not start, or timed out).
const NO_EXIT = -1
const SUMMARY_MAX = 200
const PURPOSES: readonly AdjudicatorPurpose[] = ['gate', 'weakening', 'merge']
const CHANNELS: readonly AnswerChannel[] = ['script', 'tool', 'text']
const MODEL = /^[A-Za-z0-9._-]+$/

// --- pure helpers ------------------------------------------------------------------------------

// agentOf: the agent an entry ran: its spawn's type; a delegate's is the implementer.
export function agentOf(entry: LedgerEntry): AgentType | null {
  if (entry.kind === 'delegate') return 'implementer'
  return entry.kind === 'spawn' ? (entry.agent ?? null) : null
}

// purposeOfKey: an adjudicator's purpose, from plan's key families (adjudicate:,
// adjudicate-weakening:, adjudicate-merge:).
export function purposeOfKey(key: string): AdjudicatorPurpose | null {
  if (key.startsWith('adjudicate-merge:')) return 'merge'
  if (key.startsWith('adjudicate-weakening:')) return 'weakening'
  if (key.startsWith('adjudicate:')) return 'gate'
  return null
}

// routedModel: callum-flow-implementer-route prints exactly one line, the model alias the
// implementer runs on (images/base/callum-flow-implementer-route); anything else is null.
export function routedModel(stdout: string): string | null {
  const lines = stdout
    .split('\n')
    .map(l => l.trim())
    .filter(l => l !== '')
  const only = lines.length === 1 ? lines[0] : undefined
  return only !== undefined && MODEL.test(only) ? only : null
}

// modelLabelOf: the issue's `model:<alias>` label (lower-cased, the first in sorted order, as
// plan reads it), which the implementer passes on to the sub-agents it spawns.
export function modelLabelOf(state: State, issue: number | null): string | null {
  const labels = (state.issues.find(i => i.number === issue)?.labels ?? [])
    .map(l => l.toLowerCase())
    .filter(l => l.startsWith('model:'))
    .sort()
  const first = labels[0]?.slice('model:'.length)
  return first !== undefined && MODEL.test(first) ? first : null
}

// inFlightOf: the other issues' current branches, for the designer (orchestrator skill step 2).
export function inFlightOf(state: State, issue: number | null): InFlight[] {
  return state.runs
    .filter(r => !r.superseded && r.issue !== issue)
    .map(r => ({ branch: r.branch, issue: r.issue }))
    .sort((a, b) => (a.branch < b.branch ? -1 : a.branch > b.branch ? 1 : 0))
}

export type SpawnOptions = {
  repo: string
  attempt: number
  // the model to run on: the issue's label for a spawn, the route's answer for a delegate
  model: string | null
  modelOverride: string | null
  inFlight: InFlight[]
  notes?: readonly string[]
  // the channel the prompt asks for (config answerChannel), and for the script channel the
  // script and this attempt's answer file (#561)
  channel?: AnswerChannel
  script?: ScriptPlace | null
}

// notesOf: the owner's notes for an issue, and those for every issue, oldest first (SPEC 4.3).
export function notesOf(state: State, issue: number | null): string[] {
  return state.control.notes.filter(note => note.issue === null || note.issue === issue).map(note => note.text)
}

// The agent type each agent is spawned as. The callum-flow adjudicator and designer list their
// tools, and an agent calls nothing its list leaves out, so they could never reach their answer
// tools (#548): the loop spawns its own copies of them (agents/*.md), the same definitions with
// ToolSearch and the answer tool added to `tools:`, which tests/factory-loop-agents.test.js keeps
// in step. The implementer and fixer list no tools, so they inherit every one.
export const SUBAGENT_OF: Record<AgentType, string> = {
  adjudicator: 'factory-loop:adjudicator',
  designer: 'factory-loop:designer',
  implementer: 'callum-flow:implementer',
  fixer: 'callum-flow:fixer',
}

// spawnInputOf: what $.agent.spawn gets: the agent's type, its prompt, and the issue in the
// description and name (D-11). No model leaves the agent's frontmatter model in charge.
export function spawnInputOf(action: AgentAction, opts: SpawnOptions): SpawnInput {
  const type: AgentType = action.kind === 'delegate' ? 'implementer' : action.agent
  const env: PromptEnv = { repo: opts.repo, modelOverride: opts.modelOverride, inFlight: opts.inFlight, notes: opts.notes ?? [], channel: opts.channel ?? 'text', script: opts.script ?? null }
  const input: SpawnInput = {
    subagentType: SUBAGENT_OF[type],
    prompt: promptOf(action, env),
    description: descriptionOf(action),
    name: nameOf(action, opts.attempt),
  }
  if (opts.model !== null && MODEL.test(opts.model)) input.model = opts.model
  return input
}

// --- what a spawn leaves for its answer -----------------------------------------------------------

// The spawn record: written before the spawn, read back with the answer. It holds what the
// ledger entry has no field for: the branch the spawn named (the adjudicator's verdict events
// carry it; a fixer that reports another one supersedes the old run), the adjudicator's purpose,
// and the channel the prompt asked for, with the answer file it named for the script (#561), so
// a repair message asks again the way the agent was first asked. The prompt is kept for the
// owner, beside the answer.
export type SpawnRecord = {
  key: string
  attempt: number
  agent: AgentType
  purpose: AdjudicatorPurpose | null
  issue: number | null
  run: string | null
  branch: string | null
  subagentType: string
  model: string | null
  channel: AnswerChannel
  answerFile: string | null
  prompt: string
}

export function spawnRecordPath(loopDir: string, key: string): string {
  return `${loopDir}/spawns/${key.replace(/[^A-Za-z0-9._-]+/g, '_')}.json`
}

function recordOf(action: AgentAction, input: SpawnInput, attempt: number, script: ScriptPlace | null, channel: AnswerChannel): SpawnRecord {
  const spawn = action.kind === 'spawn' ? action : null
  return {
    key: action.key,
    attempt,
    agent: action.kind === 'delegate' ? 'implementer' : action.agent,
    purpose: spawn?.agent === 'adjudicator' ? spawn.purpose : null,
    issue: action.issue,
    run: spawn !== null && spawn.agent !== 'designer' ? spawn.run : null,
    branch: namedBranchOf(action),
    subagentType: input.subagentType,
    model: input.model ?? null,
    channel,
    answerFile: script?.file ?? null,
    prompt: input.prompt,
  }
}

// namedBranchOf: the branch a spawn names (an adjudicator's or fixer's), or null.
function namedBranchOf(action: AgentAction): string | null {
  const spawn = action.kind === 'spawn' ? action : null
  return spawn !== null && spawn.agent !== 'designer' && spawn.branch !== '' ? spawn.branch : null
}

// parseRecord: a saved spawn record's branch, purpose and channel, or null when it does not read.
// A record from before the channel was kept names none.
export function parseRecord(text: string | null): (Pick<SpawnRecord, 'branch' | 'purpose'> & { channel: AnswerChannel | null }) | null {
  if (text === null) return null
  try {
    const v: unknown = JSON.parse(text)
    if (v === null || typeof v !== 'object') return null
    const r = v as Record<string, unknown>
    return {
      branch: typeof r.branch === 'string' && r.branch !== '' ? r.branch : null,
      purpose: PURPOSES.find(p => p === r.purpose) ?? null,
      channel: CHANNELS.find(c => c === r.channel) ?? null,
    }
  } catch {
    return null
  }
}

// --- reading an answer --------------------------------------------------------------------------

export type AgentEvent = { state: string; fields: EventFields }
export type AnswerInfo = {
  repo: string
  // the branch the spawn named (spawn record, else the run's branch in the state)
  branch: string | null
  // the spawn record's purpose, when the key does not say
  purpose: AdjudicatorPurpose | null
  // the channel the spawn's prompt asked for (its record), null when not known
  channel?: AnswerChannel | null
}
// problem: what kept an answer from being read (no machine line), for the repair message (#548)
export type AnswerRead = { exec: Exec; events: AgentEvent[]; problem: string | null }
// How an answer came: recorded with the answer script, through the tool, or in text.
export type AnswerVia = 'script' | 'tool' | 'text'

// readAnswer: an agent's answer as an Exec, and the events its outcome logs (SPEC 7.3, 7.4):
// - a turn that ended in error, aborted or refused is a failed attempt (SPEC 10.4);
// - the designer's report is done, parsed or { unparsed: true } (rule D3 sends that one to the
//   model);
// - the adjudicator's reply is done with its verdict lines, each logged as a `verdict` event,
//   or a failed attempt when it does not parse (rule P2 retries);
// - an implementer's or fixer's handoff is done with its fields, or failed when it does not
//   parse; a fixer that reports a branch other than the one it was sent to supersedes the old
//   run (I-39).
// A reply with no machine line says why, in its summary and in problem.
export function readAnswer(entry: LedgerEntry, answer: AgentAnswer, info: AnswerInfo): AnswerRead {
  const type = agentOf(entry)
  const who = `${type ?? entry.kind} #${entry.issue ?? '?'}`
  const failed = (summary: string, problem: string | null = null, noRetry = false): AnswerRead => ({
    exec: noRetry ? { status: 'failed', summary: clip(summary), noRetry } : { status: 'failed', summary: clip(summary) },
    events: [],
    problem,
  })
  if (type === null) return failed(`${entry.key}: no agent entry`, null, true)
  if (answer.reason !== 'answer') return failed(`${who}: its turn ended: ${answer.reason}`)
  if (type === 'designer') {
    const r = readDesigner(answer.answer, info.repo, entry.issue)
    if (typeof r !== 'string') return doneRead(entry, type, r, info, 'text')
    const exec: Exec = { status: 'done', outcome: { kind: 'designer', unparsed: true }, summary: clip(`${who}: ${r}; the report is saved for judge(report)`) }
    return { exec, events: [], problem: r }
  }
  if (type === 'adjudicator') {
    const purpose = purposeOfKey(entry.key) ?? info.purpose
    if (purpose === null) return failed(`${who}: ${entry.key} names no adjudicator purpose`, null, true)
    const r = readAdjudicator(answer.answer, purpose)
    return typeof r === 'string' ? failed(`${who}: the ${purpose} reply does not parse: ${r}`, r) : doneRead(entry, type, r, info, 'text')
  }
  const r = readHandoff(answer.answer, type === 'fixer' ? info.branch : null)
  return typeof r === 'string' ? failed(`${who}: the handoff does not parse: ${r}`, r) : doneRead(entry, type, r, info, 'text')
}

// jobOf: what checking this entry's answer needs, from what the loop knows itself (the entry, its
// spawn record and the runtime): the contract of its agent, the review's purpose, the repo and
// issue a brief must be on, the branch a fixer was sent to. Every structured answer is checked
// against it (contract.mjs checkAnswer), never against anything the agent wrote; null when the
// loop cannot tell which review an adjudicator's is.
export function jobOf(entry: LedgerEntry, type: AgentType, info: AnswerInfo): Job | null {
  const purpose = type === 'adjudicator' ? (purposeOfKey(entry.key) ?? info.purpose) : null
  if (type === 'adjudicator' && purpose === null) return null
  return { contract: CONTRACT_OF[type], purpose, repo: info.repo, issue: entry.issue, branch: type === 'fixer' ? info.branch : null }
}

// readToolAnswer: an agent's answer through its tool (agent-tools.ts), read as readAnswer reads
// its text: the same outcome and events, or why the call is refused (another agent's tool, an
// input that breaks the contract), which the agent reads and corrects. Pure.
export function readToolAnswer(entry: LedgerEntry, tool: string, input: unknown, info: AnswerInfo): AnswerRead | { refused: string } {
  const type = agentOf(entry)
  if (type === null) return { refused: `${entry.key} ran no agent` }
  if (tool !== TOOL_OF[type]) return { refused: `${tool} is not the answer of a ${type}: call ${TOOL_OF[type]} instead` }
  const job = jobOf(entry, type, info)
  if (job === null) return { refused: 'the loop cannot tell which review this is: reply in your output contract instead' }
  const check = checkAnswer(job, input)
  return check.ok ? doneRead(entry, type, check.outcome, info, 'tool') : { refused: `${check.problems.join('; ')}. Correct the call and call ${tool} again` }
}

// readScriptAnswer: the file an agent recorded with the answer script (#561), read and checked
// again against the job the loop knows (jobOf), never the job file beside it, so it means exactly
// what the same answer through the tool or in text means: the same outcome and events, or what
// is wrong with it, for the repair message. Pure.
export function readScriptAnswer(entry: LedgerEntry, body: string, info: AnswerInfo): AnswerRead | { problem: string } {
  const type = agentOf(entry)
  if (type === null) return { problem: `${entry.key} ran no agent` }
  const job = jobOf(entry, type, info)
  if (job === null) return { problem: 'the factory loop cannot tell which review this is' }
  const file = parseAnswer(body, job.contract)
  const check: Check<AnswerOutcome> = file.ok ? checkAnswer(job, file.outcome) : file
  return check.ok ? doneRead(entry, type, check.outcome, info, 'script') : { problem: `the answer recorded with the answer script does not pass its checks: ${check.problems.join('; ')}` }
}

// doneRead: a read outcome as a done Exec and the events it logs, whichever channel gave it; an
// answer through the tool or the script says so in its summary.
function doneRead(entry: LedgerEntry, type: AgentType, outcome: AnswerOutcome, info: AnswerInfo, via: AnswerVia): AnswerRead {
  const who = (inner: string[]) => {
    const all = via === 'text' ? inner : [...inner, via]
    return `${type} #${entry.issue ?? '?'}${all.length === 0 ? '' : ` (${all.join(', ')})`}`
  }
  const done = (summary: string, events: AgentEvent[] = []): AnswerRead => ({ exec: { status: 'done', outcome, summary: clip(summary) }, events, problem: null })
  if (outcome.kind === 'designer') {
    return done(`${who([])}: brief ${outcome.brief ?? 'none'}, created ${outcome.created.join(',') || 'none'}, pending decision ${outcome.pendingDecision ? 'yes' : 'no'}`)
  }
  if (outcome.kind === 'adjudicator') {
    const purpose = purposeOfKey(entry.key) ?? info.purpose ?? 'gate'
    const events = outcome.verdicts.map(line => ({
      state: 'verdict',
      fields: { issue: entry.issue, run: entry.run, branch: info.branch, note: line },
    }))
    const report = outcome.report === null ? '' : `, bump ${outcome.report.bump}, flags ${outcome.report.flags.join(',') || 'none'}`
    const n = outcome.verdicts.length
    return done(`${who([purpose])}: ACTION ${outcome.action.type}, ${n} verdict line${n === 1 ? '' : 's'}${report}`, events)
  }
  const named = type === 'fixer' ? info.branch : null
  const events: AgentEvent[] = []
  if (type === 'fixer' && outcome.newBranch !== null && named !== null && entry.run !== null) {
    events.push({ state: 'superseded', fields: { issue: entry.issue, run: entry.run, note: `by ${outcome.newBranch}` } })
  }
  const parts = [`run ${outcome.run ?? 'none'}`, `head ${outcome.head ?? 'none'}`]
  if (outcome.notGated) parts.push('NOT GATED')
  if (outcome.newBranch !== null) parts.push(`branch ${outcome.newBranch}`)
  return done(`${who([])}: ${parts.join(', ')}`, events)
}

// --- an interim answer (#545) ----------------------------------------------------------------

// One row of the agent list as the interim check reads it.
export type ListedLoop = { id: string; status: AgentStatus; parentId?: string }

const AT_WORK: readonly AgentStatus[] = ['pending', 'running', 'waiting']

// interim: an answer that ended its turn with no machine line (the designer's RESULT, the
// adjudicator's reply, a handoff's RESULT or NOT GATED), which an agent still at work may give
// before its final one. A turn that failed, and an answer read as a loop bug, are never interim.
export function interim(answer: AgentAnswer, exec: Exec): boolean {
  if (answer.reason !== 'answer') return false
  if (exec.status === 'failed') return exec.noRetry !== true
  return exec.status === 'done' && exec.outcome?.kind === 'designer' && 'unparsed' in exec.outcome
}

// stillAtWork: the agent list shows the agent holding background work (`waiting`), or a
// sub-agent it started still at work. Its own `running` proves nothing at its turn.complete: an
// agent that just ended is listed so until the engine marks it idle or completed.
export function stillAtWork(agents: readonly ListedLoop[], id: string): boolean {
  return agents.some(a => (a.id === id && a.status === 'waiting') || (a.parentId === id && AT_WORK.includes(a.status)))
}

// What goes between an answer and the reply to its repair message in the saved file.
export const REPAIR_REPLY = "--- the reply to the factory loop's repair message ---"
// What goes between an agent's final message and the answer it recorded with the answer script.
export const SCRIPT_RECORD = '--- the answer recorded with the answer script ---'

// scriptPlaceOf: the answer script and the answer file of an entry's attempt (#561): the paths a
// spawn's prompt names, and the only answer file read for that attempt.
export function scriptPlaceOf(rt: Pick<Runtime, 'pluginRoot' | 'loopDir'>, entry: Pick<LedgerEntry, 'key' | 'attempts' | 'startedAt'>): ScriptPlace {
  return { bin: `${rt.pluginRoot}/${ANSWER_SCRIPT}`, file: scriptAnswerPath(rt.loopDir, entry) }
}

// What an agent's turn.complete gave: the Exec to record, the problem for the repair message,
// how the answer came (via: the answer script's file, else its text), what kept a recorded file
// out (scriptProblem, for the decision log), and the channel its spawn was asked on (null: not
// known, so the setting's).
export type AnswerTaken = { exec: Exec; problem: string | null; via: 'script' | 'text'; scriptProblem?: string; channel: AnswerChannel | null }

// onAgentAnswer: an agent of the loop finished (its turn.complete). Its text is saved whole
// first. Then the answer it recorded with the answer script (#561) is read, only at the path
// issued for this attempt (scriptPlaceOf), and checked again; with none there, or one that fails
// its checks, its text is read as before. The events the outcome logs go out; the driver records
// the Exec, or first sends the agent the repair message for the problem (act.ts agentAnswered).
// An answer from the script follows the text in the saved file, under SCRIPT_RECORD. The reply
// to a repair goes after the answer it repairs, never over it: a designer's report is what
// judge(report) reads (rule D3), and the reply is a line at most. A failed save or event is
// noted in the summary but keeps the reading: re-running an agent costs far more.
export async function onAgentAnswer(ctx: ExecCtx, entry: LedgerEntry, answer: AgentAnswer): Promise<AnswerTaken> {
  const notes: string[] = []
  const path = answerPath(ctx.rt.loopDir, entry.key)
  let said: string | null = null
  try {
    const before = entry.reminded === true ? await ctx.io.readFile(path) : null
    said = before === null ? answer.answer : `${before.replace(/\n*$/, '')}\n\n${REPAIR_REPLY}\n\n${answer.answer}`
    await ctx.io.writeFile(path, said)
  } catch (err) {
    notes.push(`answer not saved: ${message(err)}`)
  }
  const info = await answerInfoOf(ctx, entry)
  const recorded = await scriptAnswerOf(ctx, entry)
  const script = recorded === null ? null : readScriptAnswer(entry, recorded.body, info)
  const channel = info.channel ?? null
  if (recorded !== null && script !== null && 'exec' in script) {
    if (said !== null) {
      try {
        await ctx.io.writeFile(path, `${said.replace(/\n*$/, '')}\n\n${SCRIPT_RECORD}\n\n${recorded.body.replace(/\n*$/, '')}\n`)
      } catch (err) {
        notes.push(`recorded answer not saved: ${message(err)}`)
      }
    }
    notes.push(...(await logEvents(ctx, script.events)))
    return { exec: noted(script.exec, notes), problem: null, via: 'script', channel }
  }
  const read = readAnswer(entry, answer, info)
  notes.push(...(await logEvents(ctx, read.events)))
  const scriptProblem = script !== null && !('exec' in script) ? script.problem : undefined
  const problem = read.problem === null || scriptProblem === undefined ? read.problem : `${scriptProblem}; and the reply: ${read.problem}`
  const out: AnswerTaken = { exec: noted(read.exec, notes), problem, via: 'text', channel }
  if (scriptProblem !== undefined) out.scriptProblem = scriptProblem
  return out
}

// scriptAnswerOf: the answer file at the path issued for this attempt, or null when there is none
// (the agent recorded nothing, or was asked on another channel). Nothing at any other path is
// read: who answered is the path.
async function scriptAnswerOf(ctx: ExecCtx, entry: LedgerEntry): Promise<{ body: string } | null> {
  try {
    const body = await ctx.io.readFile(scriptPlaceOf(ctx.rt, entry).file)
    return body === null ? null : { body }
  } catch {
    return null
  }
}

// scriptAnswered: the answer an agent of the loop recorded with the answer script, for an agent
// the agent list shows ended or gone before its turn.complete was read (act.ts actPass, #561): read
// and checked as onAgentAnswer reads it, saved under SCRIPT_RECORD (after an answer it repairs),
// its events logged, and the Exec to finish its entry with. Null when there is none or it fails
// its checks, and the entry is lost as before.
export async function scriptAnswered(ctx: ExecCtx, entry: LedgerEntry): Promise<Exec | null> {
  const recorded = await scriptAnswerOf(ctx, entry)
  if (recorded === null) return null
  const script = readScriptAnswer(entry, recorded.body, await answerInfoOf(ctx, entry))
  if (!('exec' in script)) return null
  const notes = ['read before its turn.complete']
  const path = answerPath(ctx.rt.loopDir, entry.key)
  try {
    const before = entry.reminded === true ? await ctx.io.readFile(path) : null
    const record = `${SCRIPT_RECORD}\n\n${recorded.body.replace(/\n*$/, '')}\n`
    await ctx.io.writeFile(path, before === null ? record : `${before.replace(/\n*$/, '')}\n\n${record}`)
  } catch (err) {
    notes.push(`recorded answer not saved: ${message(err)}`)
  }
  notes.push(...(await logEvents(ctx, script.events)))
  return noted(script.exec, notes)
}

// repairAskOf: the channel a repair message asks on (act.ts agentAnswered), with the answer
// script's place on the script channel: the channel the spawn's record names, the script only
// while this attempt's job file stands beside its answer file, since the script refuses an answer
// file without one. With no channel named (no record, or one from before the channel was kept) or
// no job file, text, the channel always read.
export async function repairAskOf(ctx: Pick<ExecCtx, 'io' | 'rt'>, entry: LedgerEntry, channel: AnswerChannel | null): Promise<{ channel: AnswerChannel; script: ScriptPlace | null }> {
  if (channel !== 'script') return { channel: channel ?? 'text', script: null }
  const place = scriptPlaceOf(ctx.rt, entry)
  const job = jobPathOf(place.file)
  let body: string | null = null
  try {
    body = job === null ? null : await ctx.io.readFile(job)
  } catch {
    body = null
  }
  return body === null ? { channel: 'text', script: null } : { channel: 'script', script: place }
}

// onToolAnswer: an agent of the loop called its answer tool, read against its spawn record. A
// call the contract refuses changes nothing. An accepted one has its input saved (as JSON) before
// the driver records it, so a pass that acts on the answer (judge(handoff) points the model at the
// saved answer) finds it there; a call then refused for time leaves the file to the text answer,
// which writes it again. It gives the Exec the driver records at once, as for an answer in text,
// and `after`, what follows once the call has its answer (#558): its events logged, through the
// ExecCtx it is handed; notes on what failed, for the decision log.
export async function onToolAnswer(
  ctx: ExecCtx,
  entry: LedgerEntry,
  tool: string,
  input: unknown,
): Promise<{ exec: Exec; after: (later: ExecCtx) => Promise<string[]> } | { refused: string }> {
  const read = readToolAnswer(entry, tool, input, await answerInfoOf(ctx, entry))
  if ('refused' in read) return read
  const saved: string[] = []
  try {
    await ctx.io.writeFile(answerPath(ctx.rt.loopDir, entry.key), JSON.stringify({ tool, input }, null, 2))
  } catch (err) {
    saved.push(`answer not saved: ${message(err)}`)
  }
  const after = async (later: ExecCtx): Promise<string[]> => [...saved, ...(await logEvents(later, read.events))]
  return { exec: read.exec, after }
}

// answerInfoOf: what reading an answer needs beside the entry: the branch and purpose its spawn
// record names. With no record, the run's branch in the state stands in.
async function answerInfoOf(ctx: ExecCtx, entry: LedgerEntry): Promise<AnswerInfo> {
  let record: ReturnType<typeof parseRecord> = null
  try {
    record = parseRecord(await ctx.io.readFile(spawnRecordPath(ctx.rt.loopDir, entry.key)))
  } catch {
    // no record
  }
  const branch = record?.branch ?? (entry.run === null ? null : (ctx.state.runs.find(r => r.run === entry.run)?.branch ?? null))
  return { repo: ctx.rt.repo, branch, purpose: record?.purpose ?? null, channel: record?.channel ?? null }
}

// logEvents: the events an outcome logs; a note when some could not be.
async function logEvents(ctx: ExecCtx, events: readonly AgentEvent[]): Promise<string[]> {
  let missed = 0
  for (const e of events) {
    try {
      await ctx.event(e.state, e.fields)
    } catch {
      missed += 1
    }
  }
  return missed > 0 ? [`${missed} of ${events.length} events not logged`] : []
}

function noted(exec: Exec, notes: readonly string[]): Exec {
  return notes.length === 0 ? exec : { ...exec, summary: clip(`${exec.summary}; ${notes.join('; ')}`) }
}

// --- the executors --------------------------------------------------------------------------------

function refused(why: string): Exec {
  return { status: 'failed', summary: clip(`refused: ${why}`), noRetry: true }
}

// scriptFor: on the script channel (config answerChannel, the default), the answer script and
// this attempt's answer file, once the job file the script checks against stands beside it; null
// when the channel is another, or the paths are not ones a prompt may carry, or the job file
// cannot be written, and the prompt then asks for text. The script channel is a TEMPORARY
// WORKAROUND (#561, DECISIONS D-74) for the registered answer tools (#548), which an agent the
// loop spawns from its timer cannot reach on Claude Code 2.1.296 and 2.1.299 (#560).
async function scriptFor(ctx: ExecCtx, action: AgentAction): Promise<ScriptPlace | null> {
  if (ctx.rt.config.answerChannel !== 'script') return null
  const place = scriptPlaceOf(ctx.rt, ctx.entry)
  const job = jobPathOf(place.file)
  if (job === null || !scriptShaped(place)) return null
  const type: AgentType = action.kind === 'delegate' ? 'implementer' : action.agent
  const purpose = action.kind === 'spawn' && action.agent === 'adjudicator' ? action.purpose : null
  try {
    await ctx.io.writeFile(job, jobText({ contract: CONTRACT_OF[type], purpose, repo: ctx.rt.repo, issue: action.issue, branch: type === 'fixer' ? namedBranchOf(action) : null }))
  } catch {
    return null
  }
  return place
}

// start: write the answer script's job file (on the script channel) and the spawn record, then
// spawn. A deny, a throw or a start with no agent id is a failed attempt; a started agent runs on,
// and its turn.complete ends the entry.
async function start(ctx: ExecCtx, action: AgentAction, model: string | null, env: Omit<PromptEnv, 'repo'>): Promise<Exec> {
  const script = await scriptFor(ctx, action)
  const channel: AnswerChannel = script !== null ? 'script' : ctx.rt.config.answerChannel === 'tool' ? 'tool' : 'text'
  const input = spawnInputOf(action, { repo: ctx.rt.repo, attempt: ctx.entry.attempts, model, channel, script, ...env })
  let saved = true
  try {
    const record = recordOf(action, input, ctx.entry.attempts, script, channel)
    await ctx.io.writeFile(spawnRecordPath(ctx.rt.loopDir, action.key), JSON.stringify(record, null, 2))
  } catch {
    saved = false
  }
  let r: { agentId?: string; deny?: string }
  try {
    r = await ctx.io.spawnAgent(input)
  } catch (err) {
    return { status: 'failed', summary: clip(`${input.subagentType}: the spawn threw: ${message(err)}`) }
  }
  if (typeof r.deny === 'string') return { status: 'failed', summary: clip(`${input.subagentType} denied: ${r.deny}`) }
  if (r.agentId === undefined || r.agentId === '') return { status: 'failed', summary: `${input.subagentType}: started with no agent id` }
  const on = input.model === undefined ? '' : ` (${input.model})`
  const note = saved ? '' : '; spawn record not saved'
  return { status: 'running', agentId: r.agentId, summary: clip(`${input.subagentType}${on} started for #${action.issue}: ${r.agentId}${note}`) }
}

// spawn: the designer, an adjudicator or a fixer, on the issue's model label when it has one.
const spawn: Executor = async (ctx, action) => {
  if (action.kind !== 'spawn') return refused(`the spawn executor got a ${action.kind} action`)
  if (action.issue === null) return refused(`${action.key} names no issue`)
  const inFlight = action.agent === 'designer' ? inFlightOf(ctx.state, action.issue) : []
  return start(ctx, action, action.model, { modelOverride: action.model, inFlight, notes: notesOf(ctx.state, action.issue) })
}

// delegate: `callum-flow-implementer-route <N>`, then `callum-flow-event delegated --issue <N>
// --note "brief <url>"`, then the implementer on the routed model (SPEC 6.1, I-32). A route
// that fails, or prints no model, ends it before anything is logged.
const delegate: Executor = async (ctx, action) => {
  if (action.kind !== 'delegate') return refused(`the delegate executor got a ${action.kind} action`)
  const n = action.issue
  if (n === null) return refused(`${action.key} names no issue`)
  // a brief travels as its URL only (I-33); anything else here is a loop bug
  if (!isBriefUrl(action.brief, ctx.rt.repo)) return refused(`${action.key}: the brief is not a comment URL on ${ctx.rt.repo}`)
  const argv = ['callum-flow-implementer-route', String(n)]
  let r: RunResult
  try {
    r = await ctx.cmd(argv, { timeoutMs: ROUTE_TIMEOUT_MS })
  } catch (err) {
    return { status: 'failed', outcome: { kind: 'cli', exit: NO_EXIT, detail: message(err).slice(0, 2000) }, summary: clip(`${argv[0]}: ${message(err)}`) }
  }
  if (r.exitCode !== 0) return routeFailure(r)
  const model = routedModel(r.stdout)
  if (model === null) {
    const detail = `printed no model: ${JSON.stringify(r.stdout.trim().slice(0, 200))}`
    return { status: 'failed', outcome: { kind: 'cli', exit: 0, detail }, summary: clip(`${argv[0]} ${detail}`) }
  }
  try {
    await ctx.event('delegated', { issue: n, note: `brief ${action.brief}` })
  } catch (err) {
    return eventFailure('delegated', err)
  }
  return start(ctx, action, model, { modelOverride: modelLabelOf(ctx.state, n), inFlight: [], notes: notesOf(ctx.state, n) })
}

// Exit 2 is the route's usage error, a loop bug never retried (SPEC 10.1).
function routeFailure(r: RunResult): Exec {
  const line = lastLine(r.stderr) || lastLine(r.stdout)
  const exec: Extract<Exec, { status: 'failed' }> = {
    status: 'failed',
    outcome: { kind: 'cli', exit: r.exitCode, detail: detailOf(r) },
    summary: clip(`callum-flow-implementer-route: exit ${r.exitCode}${line === '' ? '' : `: ${line}`}`),
  }
  if (r.exitCode === 2) exec.noRetry = true
  if (rateLimited(r.stderr)) exec.rateLimited = true
  return exec
}

// callum-flow-event exits non-zero only on a usage error (exit 2), never retried.
function eventFailure(state: string, err: unknown): Exec {
  const code = typeof err === 'object' && err !== null ? (err as { exitCode?: unknown }).exitCode : undefined
  const exit = typeof code === 'number' ? code : NO_EXIT
  const exec: Extract<Exec, { status: 'failed' }> = {
    status: 'failed',
    outcome: { kind: 'cli', exit, detail: message(err).slice(0, 2000) },
    summary: clip(`event ${state}: ${message(err)}`),
  }
  if (exit === 2) exec.noRetry = true
  return exec
}

export const agentExecutors: Partial<Record<ActionKind, Executor>> = { spawn, delegate }

// --- small text helpers ---------------------------------------------------------------------

function lastLine(text: string): string {
  return (
    text
      .split('\n')
      .map(l => l.trim())
      .filter(l => l !== '')
      .pop() ?? ''
  )
}

function clip(text: string): string {
  return text.length > SUMMARY_MAX ? `${text.slice(0, SUMMARY_MAX - 3)}...` : text
}

function message(err: unknown): string {
  return err instanceof Error ? err.message : String(err)
}

