// The settings `/factory config set|unset` writes into the workspace config file (SPEC 4.3): which
// keys the file may hold, how a typed key and value are checked (by loadConfig itself, so the op
// accepts exactly what the loader would), when a change applies, and the edit of the file's text.
// Pure: control.ts runs it over the file's read and write.
import { ATTEMPT_KEYS, COUNT_MAPS, DEFAULT_CONFIG, TIME_MAPS, loadConfig, parseDuration, shortDuration } from './config'
import type { Config } from './types'

// The workspace file's keys that are not settings: the plugin's options and the runtime's own.
// Every other key there is a setting, over the repo's file (v2 SPEC section 15: the workspace
// file may set any key and wins); answerTools, which answerChannel replaced (#561), is passed on
// only to be named as replaced.
export const RUNTIME_KEYS: readonly string[] = ['mode', 'repo', 'shadowDevice', 'runSource', 'checkout', 'poolSize', 'toolsDir', 'binDir']

// When a change to a key applies. runtime() (register.ts) reads the workspace file and the repo's
// every pass, and nothing below keeps a setting from an earlier pass (the settings cache holds the
// repo's file on origin, not a value of this one), so every key is next-pass; a key some module
// captured once at load would be marked `restart` here, with the reason beside it. A timeout is
// next-pass too, but an agent or wake already running keeps the one it took (effectText says so).
export type Effect = 'next-pass' | 'restart'
export const SETTING_EFFECT: Record<keyof Config | 'poolSize', Effect> = {
  mode: 'next-pass',
  shadowDevice: 'next-pass',
  readyLabel: 'next-pass',
  inDevLabel: 'next-pass',
  skipLabels: 'next-pass',
  trackerTitle: 'next-pass',
  usageSlowPct: 'next-pass',
  usageStopNewPct: 'next-pass',
  usageStopAllPct: 'next-pass',
  // the timer is re-armed when it changes (register.ts rearm)
  passEveryMs: 'next-pass',
  titleEveryMs: 'next-pass',
  reportEveryMs: 'next-pass',
  queueEveryMs: 'next-pass',
  githubEveryMs: 'next-pass',
  usageEveryMs: 'next-pass',
  milestoneEveryMs: 'next-pass',
  usageStaleMs: 'next-pass',
  heartbeatEveryMs: 'next-pass',
  sweepEveryMs: 'next-pass',
  checkoutEveryMs: 'next-pass',
  slowGapMs: 'next-pass',
  maxStartsPerPass: 'next-pass',
  maxInFlightIssues: 'next-pass',
  worktreeReserve: 'next-pass',
  reviewFixCap: 'next-pass',
  guardRecheckMs: 'next-pass',
  guardTtlMs: 'next-pass',
  respondSettleMs: 'next-pass',
  updateBehindRetryMs: 'next-pass',
  updateBehindRetries: 'next-pass',
  ciStallRecheckMs: 'next-pass',
  blindNoticeAfterMs: 'next-pass',
  agentTimeoutMs: 'next-pass',
  wakeTimeoutMs: 'next-pass',
  maxAttempts: 'next-pass',
  retryBackoffMs: 'next-pass',
  rateCaps: 'next-pass',
  allowActOutsideOrchestrator: 'next-pass',
  trace: 'next-pass',
  traceMaxBytes: 'next-pass',
  answerChannel: 'next-pass',
  planner: 'next-pass',
  shadow: 'next-pass',
  stateTimeoutMs: 'next-pass',
  ciStartMs: 'next-pass',
  ciRunMs: 'next-pass',
  prEveryMs: 'next-pass',
  maxTriages: 'next-pass',
  minimumReleaseCadenceMs: 'next-pass',
  maxLives: 'next-pass',
  triageModel: 'next-pass',
  reviewer: 'next-pass',
  reviewerModel: 'next-pass',
  gateCommands: 'next-pass',
  gateTimeoutMs: 'next-pass',
  // runtime() reads it from the workspace file every pass
  poolSize: 'next-pass',
}

// The keys that have an op of their own, and which op. `set` refuses them, so the plugin option,
// the runtime key and the v2 switch keep one path.
// the pool size runtime() uses when the workspace file sets none
export const DEFAULT_POOL_SIZE = 16

const OWN_OP: Record<string, string> = {
  mode: 'mode off|observe|act',
  planner: 'planner v1|v2',
  trace: 'trace on|off',
}

const MAPS: readonly string[] = [...TIME_MAPS, ...COUNT_MAPS]
const TIME: readonly string[] = TIME_MAPS

export type Checked = { ok: true; key: string; fileKey: string; sub: string | null; value: unknown } | { ok: false; error: string }

// the value text as JSON when it parses (3, true, null, ["npm test"]), else the plain string (6h)
export function valueOfText(text: string): unknown {
  try {
    return JSON.parse(text)
  } catch {
    return text
  }
}

// keyOf: a typed key as the canonical Config key and the spelling to write: `passEvery` is
// passEveryMs written as typed; `stateTimeout.design` is stateTimeoutMs, sub `design`.
export function keyOf(typed: string): { key: string; fileKey: string; sub: string | null } | null {
  const dot = typed.indexOf('.')
  const fileKey = dot < 0 ? typed : typed.slice(0, dot)
  const sub = dot < 0 ? null : typed.slice(dot + 1)
  const defaults = DEFAULT_CONFIG as unknown as Record<string, unknown>
  const key = fileKey === 'poolSize' || fileKey in defaults ? fileKey : `${fileKey}Ms` in defaults ? `${fileKey}Ms` : null
  return key === null || sub === '' ? null : { key, fileKey, sub }
}

// checkKey: the typed key alone (unset); checkSetting: a key and value typed by the owner, checked by loadConfig alone on a candidate
// file holding just that entry. Any problem, or an unknown key, refuses it with the loader's text.
export function checkKey(typed: string): Checked {
  const k = keyOf(typed)
  const bare = typed.split('.')[0] ?? typed
  if (bare in OWN_OP) return { ok: false, error: `${bare} has its own op: /factory ${OWN_OP[bare]}. Not changed.` }
  if (RUNTIME_KEYS.includes(bare) && bare !== 'poolSize') return { ok: false, error: `${bare} is a plugin option or runtime key, not a setting. Not changed.` }
  if (k === null) return { ok: false, error: `${typed}: unknown setting. Not changed.` }
  const isMap = MAPS.includes(k.key)
  if (isMap && k.sub === null) return { ok: false, error: `${typed}: name one entry, as ${k.fileKey}.<name>. Not changed.` }
  if (!isMap && k.sub !== null) return { ok: false, error: `${typed}: ${k.fileKey} has no entries. Not changed.` }
  if (k.sub !== null) {
    const known = k.key === 'maxAttempts' ? (ATTEMPT_KEYS as readonly string[]) : Object.keys((DEFAULT_CONFIG as unknown as Record<string, object>)[k.key] ?? {})
    if (!known.includes(k.sub)) return { ok: false, error: `${typed}: unknown entry. Not changed.` }
  }
  return { ok: true, ...k, value: undefined }
}

export function checkSetting(typed: string, value: unknown): Checked {
  const keyed = checkKey(typed)
  if (!keyed.ok) return keyed
  const k = keyed
  if (k.key === 'poolSize') {
    if (typeof value === 'number' && Number.isInteger(value) && value >= 1) return { ok: true, ...k, value }
    return { ok: false, error: `poolSize: ${JSON.stringify(value)} is not a whole number of at least 1. Not changed.` }
  }
  const candidate = k.sub === null ? { [k.fileKey]: value } : { [k.fileKey]: { [k.sub]: value } }
  const problems = loadConfig(candidate).problems
  if (problems.length > 0) return { ok: false, error: `${problems.join('; ')}. Not changed.` }
  return { ok: true, ...k, value }
}

// effectText: when a change to the key applies, from the table (a stub table in a test).
export function effectText(key: string, table: Record<string, Effect> = SETTING_EFFECT): string {
  if (table[key] === 'restart') return "after the loop's process restarts"
  return TIME.includes(key) && key !== 'stateTimeoutMs' ? 'from the next pass, to new work' : 'from the next pass'
}

// shown: a setting's value as the answer names it
export function shown(key: string, value: unknown): string {
  if (typeof value === 'number' && key.endsWith('Ms')) return shortDuration(value)
  if (value === null) return 'no cap'
  return typeof value === 'string' ? value : (JSON.stringify(value) ?? String(value))
}

// valueIn: the value of a canonical key (and sub-key) in a loaded config
export function valueIn(config: Config | { poolSize: number }, key: string, sub: string | null): unknown {
  const v = (config as unknown as Record<string, unknown>)[key]
  return sub === null ? v : (v as Record<string, unknown> | undefined)?.[sub]
}

export type Edited = { ok: true; text: string; changed: boolean } | { ok: false; error: string }

const isObject = (v: unknown): v is Record<string, unknown> => v !== null && typeof v === 'object' && !Array.isArray(v)

// editSetting: the workspace file's text with one setting set (value given) or removed (value
// undefined), every other key kept. A set of an Ms key writes the spelling typed and drops the
// other; a map entry merges into the object, and the last entry's removal drops the object. A file
// that is not a JSON object is left alone.
export function editSetting(text: string | null, k: { key: string; fileKey: string; sub: string | null }, value: unknown): Edited {
  let raw: unknown = {}
  if (text !== null && text.trim() !== '') {
    try {
      raw = JSON.parse(text)
    } catch {
      return { ok: false, error: 'the workspace config file is not valid JSON' }
    }
  }
  if (!isObject(raw)) return { ok: false, error: 'the workspace config file is not a JSON object' }
  const out: Record<string, unknown> = { ...raw }
  const names = k.key.endsWith('Ms') ? [k.key, k.key.slice(0, -2)] : [k.key]
  let changed = false
  if (k.sub === null) {
    for (const name of names) {
      if (name in out && (value === undefined || name !== k.fileKey)) {
        delete out[name]
        changed = true
      }
    }
    if (value !== undefined) {
      changed = changed || JSON.stringify(raw[k.fileKey]) !== JSON.stringify(value)
      out[k.fileKey] = value
    }
  } else {
    const sub = k.sub
    // both spellings' entries, the typed spelling's over the other's
    const merged: Record<string, unknown> = {}
    for (const name of [...names].reverse()) {
      const inner = out[name]
      if (isObject(inner)) Object.assign(merged, inner)
      delete out[name]
    }
    if (value === undefined) {
      changed = sub in merged
      delete merged[sub]
    } else {
      changed = JSON.stringify(raw[k.fileKey] !== undefined && isObject(raw[k.fileKey]) ? (raw[k.fileKey] as Record<string, unknown>)[sub] : undefined) !== JSON.stringify(value)
      merged[sub] = value
    }
    // the Ms spelling takes numbers only: an entry moved there from the short spelling keeps its meaning in ms
    if (k.fileKey === k.key) {
      for (const [name, v] of Object.entries(merged)) {
        const ms = typeof v === 'string' ? parseDuration(v) : null
        if (ms !== null) merged[name] = ms
      }
    }
    if (Object.keys(merged).length > 0) out[k.fileKey] = merged
  }
  return { ok: true, text: JSON.stringify(out, null, 2) + '\n', changed }
}

// withoutSetting: the workspace file's settings with the key (both spellings) or entry removed, as an
// unset leaves them: what the loader then reads, planner included.
export function withoutSetting(workspaceRaw: Record<string, unknown>, k: { key: string; fileKey: string; sub: string | null }): Record<string, unknown> {
  const edited = editSetting(JSON.stringify(workspaceRaw), k, undefined)
  return edited.ok ? (JSON.parse(edited.text) as Record<string, unknown>) : workspaceRaw
}

files.hooks/contract.mjs:
// The agents' answer contract (SPEC 7.3a): what an adjudicator's verdict, a designer's result and
// an implementer's or fixer's handoff must hold, checked field by field with every problem named
// at once, and the files of the answer script (#561). One plain-JS module with one reader of
// each answer: the loop imports it (the TypeScript hooks the engine runs: replies.ts,
// agent-tools.ts, act-agents.ts), and so does bin/factory-answer under plain node, so the
// registered tools, the script and the loop's own re-check of the script's file cannot drift.
// tests/answer-contract.test.ts (the loop) and tests/factory-loop-answer.test.js at the repo
// root (the script, run for real) hold both ends to one table of cases (tests/answer-cases.mjs).
// It uses ES2023 alone, nothing of Node or the engine. Its types are contract.d.mts's.
//
// The v2 rule layer's contracts (docs/factory-loop/v2/SPEC.md 5.2, 8.2, 8.7) live in
// v2/contracts-*.mjs, one module per area; this module imports them, so the answer script and the
// loop check a v2 answer alike, and a v2 job's contract is one of their names.

import { CONTRACTS as REVIEW } from './v2/contracts-review.mjs'
import { CONTRACTS as TRIAGE } from './v2/contracts-triage.mjs'
import { CONTRACTS as WORK } from './v2/contracts-work.mjs'

export const VERDICTS = Object.freeze(['CORRECT', 'WRONG', 'NIT', 'ENV', 'DUP'])
export const BUMPS = Object.freeze(['patch', 'minor', 'major'])
export const FLAGS = Object.freeze(['image', 'template', 'restart', 'run-it'])

// The ACTIONs that answer each purpose. A gate or a test-weakening review never merges or
// holds (types.ts, D-05); a merge review never drives the run's gate. escalate stays open to
// the merge review: its definition offers it, and plan holds on it as on `hold` (rule M5a).
export const ACTIONS_FOR = Object.freeze({
  gate: Object.freeze(['approve', 'fix', 'skip', 'fixer', 'escalate']),
  weakening: Object.freeze(['approve', 'fix', 'skip', 'fixer', 'escalate']),
  merge: Object.freeze(['merge', 'hold', 'fixer', 'escalate']),
})

// A finding id as no-mistakes names them (review-1).
export const FINDING_ID = /^[A-Za-z0-9][A-Za-z0-9_.:-]*$/

// The shape of each handoff id, as a RESULT line or a structured answer gives it.
export const HANDOFF_SHAPES = Object.freeze({ run: /^[A-Za-z0-9_-]+$/, sha: /^[0-9a-f]{7,40}$/i, branch: /^[A-Za-z0-9._/-]+$/ })

// A free-text value past this is refused: an answer points, it does not carry documents.
export const TEXT_MAX = 4000

// The contract each agent answers with; each answer tool is named after its contract.
export const CONTRACT_OF = Object.freeze({ adjudicator: 'verdict', designer: 'design', implementer: 'handoff', fixer: 'handoff' })
// v2's contracts by name, each { check(input, job), summary(input) }.
export const V2_CONTRACTS = Object.freeze({ ...WORK, ...REVIEW, ...TRIAGE })
const CONTRACTS = Object.freeze(['verdict', 'design', 'handoff', ...Object.keys(V2_CONTRACTS)])
const PURPOSES = Object.freeze(['gate', 'weakening', 'merge'])

// isBriefUrl: a brief comment's URL on an issue of this repo (on that issue, when given).
export function isBriefUrl(url, repo, issue = null) {
  const m = url.match(/^https:\/\/github\.com\/([^/\s]+\/[^/\s]+)\/issues\/(\d+)#issuecomment-\d+$/)
  if (m === null || (m[1] ?? '').toLowerCase() !== repo.toLowerCase()) return false
  return issue === null || Number(m[2]) === issue
}

// gatedWithoutRun: a handoff that says gated but names no run, as an agent that gave up and
// committed nothing may. Read as done, no rule would act on it (D4b retries only a delegate that
// failed, D5 only one not gated), so its issue would stall: it is unreadable instead.
export function gatedWithoutRun(fields) {
  return fields.gated && fields.run === null
}

// One SHA may be the other's short form.
function sameSha(a, b) {
  return a.startsWith(b) || b.startsWith(a)
}

// handoffOutcome: what a handoff's fields mean, from any channel: not gated when it says so, or
// when the run's head is not the agent's commit (implement-issue section 8: never rationalise a
// mismatch away); newBranch is the branch it reports when that is not the one the spawn named.
export function handoffOutcome(fields, namedBranch) {
  const mismatch = fields.head !== null && fields.commit !== null && !sameSha(fields.head, fields.commit)
  const named = namedBranch === null || namedBranch === '' ? null : namedBranch
  return {
    kind: 'handoff',
    notGated: !fields.gated || mismatch,
    run: fields.run,
    head: fields.head,
    newBranch: fields.branch !== null && fields.branch !== named ? fields.branch : null,
  }
}

// --- the checks: an input in, the outcome its text lines would give or every problem out ---------

function record(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v) ? v : null
}

function checked(problems, outcome) {
  return problems.length > 0 ? { ok: false, problems } : { ok: true, outcome: outcome() }
}

// strays: a field the contract does not have is named, never ignored: it is a misunderstanding.
function strays(o, allowed, at, problems) {
  for (const k of Object.keys(o)) if (!allowed.includes(k)) problems.push(`${at}${k} is not a field here`)
}

// text: a free-text field as one trimmed line (the text contract's lines are one line each);
// null when absent or null. Not text, empty where required, or over TEXT_MAX is a problem.
function text(v, name, problems, required) {
  if (v === undefined || v === null) {
    if (required) problems.push(`${name} is required`)
    return null
  }
  if (typeof v !== 'string') {
    problems.push(`${name} must be text`)
    return null
  }
  const t = v.replace(/\s+/g, ' ').trim()
  if (t === '' && required) problems.push(`${name} must not be empty`)
  else if (t.length > TEXT_MAX) problems.push(`${name} is over ${TEXT_MAX} characters`)
  else if (t !== '') return t
  return null
}

// clip: a value quoted in a problem as the model wrote it, cut to a readable length.
function clip(v) {
  const s = typeof v === 'string' ? JSON.stringify(v.length > 120 ? `${v.slice(0, 117)}...` : v) : (JSON.stringify(v) ?? String(v))
  return s.length > 124 ? `${s.slice(0, 121)}...` : s
}

// --- the adjudicator (SPEC 7.3) --------------------------------------------------------------

// The fields each action takes beside its type, as its ACTION line's grammar has them.
const ACTION_FIELDS = Object.freeze({
  approve: ['reason'],
  fix: ['findings', 'instructions', 'addFinding'],
  skip: [],
  fixer: ['instructions'],
  escalate: ['why'],
  merge: [],
  hold: ['reason'],
})
const REPORT_FIELDS = Object.freeze(['summary', 'bump', 'flags'])

// verdictLine: a finding as the verdict line the text contract gives, naming its id (once, when
// the reason already opens with it), for the verdict event and the rules that read the lines
// (P2a reads `ENV:`).
function verdictLine(verdict, id, reason) {
  const named = reason.startsWith(id) && !/[\w.-]/.test(reason.charAt(id.length))
  return named ? `${verdict}: ${reason}` : `${verdict}: ${id}: ${reason}`
}

// checkVerdict: an adjudicator's answer of this purpose.
export function checkVerdict(input, purpose) {
  const problems = []
  const o = record(input) ?? {}
  strays(o, ['findings', 'action', ...REPORT_FIELDS], '', problems)
  const judged = new Map()
  const verdicts = []
  const findings = Array.isArray(o.findings) ? o.findings : null
  if (findings === null) problems.push('findings must be a list of { id, verdict, reason } ([] when there is nothing to report)')
  for (const [i, raw] of (findings ?? []).entries()) {
    const at = `findings[${i}]`
    const f = record(raw)
    if (f === null) {
      problems.push(`${at} must be an object { id, verdict, reason }`)
      continue
    }
    strays(f, ['id', 'verdict', 'reason'], `${at}.`, problems)
    const id = typeof f.id === 'string' ? f.id.trim() : ''
    const verdict = VERDICTS.find(v => v === f.verdict)
    const reason = text(f.reason, `${at}.reason`, problems, true)
    if (verdict === undefined) problems.push(`${at}.verdict must be one of ${VERDICTS.join(', ')}`)
    if (!FINDING_ID.test(id)) problems.push(`${at}.id ${clip(f.id)} is not a finding id such as review-1`)
    else if (judged.has(id)) problems.push(`${at}.id ${id} is judged twice`)
    else if (verdict !== undefined) {
      judged.set(id, verdict)
      if (reason !== null) verdicts.push(verdictLine(verdict, id, reason))
    }
  }
  const action = actionOf(o.action, purpose, judged, problems)
  let report = null
  if (purpose === 'merge') report = reportOf(o, problems)
  else {
    const extra = REPORT_FIELDS.filter(k => o[k] !== undefined)
    if (extra.length > 0) problems.push(`${extra.join(', ')} answer a merge review only, and this is a ${purpose} review`)
  }
  if (action === null || problems.length > 0) return { ok: false, problems: problems.length > 0 ? problems : ['action is required'] }
  return { ok: true, outcome: { kind: 'adjudicator', verdicts, action, report } }
}

// actionOf: the one action, of a type the purpose allows, with the fields its type takes (the
// same as its ACTION line: a fix needs findings, instructions or a finding to add).
function actionOf(raw, purpose, judged, problems) {
  const allowed = ACTIONS_FOR[purpose]
  const a = record(raw)
  const type = allowed.find(t => t === a?.type)
  if (a === null || type === undefined) {
    problems.push(`action must be { type, ... } with type one of ${allowed.join(', ')}: a ${purpose} review takes no other`)
    return null
  }
  const fields = ACTION_FIELDS[type]
  for (const k of Object.keys(a)) {
    if (k !== 'type' && !fields.includes(k)) problems.push(`action ${type} takes ${fields.length === 0 ? 'no field but type' : fields.join(', ')}, not ${k}`)
  }
  switch (type) {
    case 'skip':
    case 'merge':
      return { type }
    case 'approve':
      return { type, reason: text(a.reason, 'action.reason', problems, false) }
    case 'fixer': {
      const instructions = text(a.instructions, 'action.instructions', problems, true)
      return instructions === null ? null : { type, instructions }
    }
    case 'escalate': {
      const why = text(a.why, 'action.why', problems, true)
      return why === null ? null : { type, why }
    }
    case 'hold': {
      const reason = text(a.reason, 'action.reason', problems, true)
      return reason === null ? null : { type, reason }
    }
    case 'fix': {
      const findings = fixIds(a.findings, judged, problems)
      const instructions = text(a.instructions, 'action.instructions', problems, false)
      let addFinding = null
      if (a.addFinding !== undefined && a.addFinding !== null) {
        if (record(a.addFinding) === null) problems.push('action.addFinding must be an object: the finding as no-mistakes takes it')
        else addFinding = JSON.stringify(a.addFinding)
      }
      if (findings === null && instructions === null && addFinding === null) problems.push('action fix needs findings, instructions or addFinding')
      return { type, findings, instructions, addFinding, ignore: declinedFindings([...judged.keys()], findings) }
    }
  }
  return null
}

// The id prefix the contract asks for a gap the reviewer missed, which the gate does not know.
const MISSED_ID = 'missed-'

// declinedFindings: the findings a fix leaves out of its selection, for respond's --ignore.
// no-mistakes 1.90+ takes declines only when named: every finding the gate shows must be in
// --findings or --ignore, or the respond is refused and the gate stays parked. So the loop
// declines what the adjudicator judged and did not select, the complement no-mistakes itself
// took before 1.90. A gap the reviewer missed (MISSED_ID) is not the gate's, so never declined.
// null when nothing is left out.
export function declinedFindings(judgedIds, findings) {
  const selected = new Set((findings ?? '').split(',').filter(id => id !== ''))
  const out = [...new Set(judgedIds)].filter(id => FINDING_ID.test(id) && !id.startsWith(MISSED_ID) && !selected.has(id))
  return out.length > 0 ? out.join(',') : null
}

// fixIds: a fix's finding ids, each one judged above as CORRECT or ENV: a fix for a WRONG, NIT or
// DUP finding would make the pipeline rewrite sound code (adjudicator.md). The loop has no view of
// the gate's own list, so an id the agent made up for a missed gap (MISSED_ID) is the one it can
// tell is not the gate's: respond would name a finding the gate does not have.
function fixIds(raw, judged, problems) {
  if (raw === undefined || raw === null) return null
  if (!Array.isArray(raw) || raw.length === 0 || !raw.every(id => typeof id === 'string')) {
    problems.push('action.findings must be a list of the ids of findings above')
    return null
  }
  const ids = [...new Set(raw.map(id => id.trim()))]
  for (const id of ids) {
    const verdict = judged.get(id)
    if (!FINDING_ID.test(id)) problems.push(`action.findings: ${clip(id)} is not a finding id`)
    else if (id.startsWith(MISSED_ID)) problems.push(`action.findings: ${id} is a gap the reviewer missed, which the gate does not know: put it in action.addFinding`)
    else if (verdict === undefined) problems.push(`action.findings: ${id} is not one of the findings above`)
    else if (verdict !== 'CORRECT' && verdict !== 'ENV') problems.push(`action.findings: ${id} is judged ${verdict}, and a fix is for CORRECT or ENV findings`)
  }
  return ids.join(',')
}

// reportOf: the merge review's summary, bump and flags (rule M4).
function reportOf(o, problems) {
  const summary = text(o.summary, 'summary', problems, true)
  const b = record(o.bump)
  const level = BUMPS.find(x => x === b?.level)
  let bumpReason = null
  if (b === null) problems.push('bump is required: { level: patch|minor|major, reason }')
  else {
    strays(b, ['level', 'reason'], 'bump.', problems)
    if (level === undefined) problems.push(`bump.level must be one of ${BUMPS.join(', ')}`)
    bumpReason = text(b.reason, 'bump.reason', problems, true)
  }
  const flags = []
  if (!Array.isArray(o.flags)) problems.push(`flags is required: a list of ${FLAGS.join(', ')} ([] for none)`)
  else {
    for (const raw of o.flags) {
      const flag = FLAGS.find(f => f === raw)
      if (flag === undefined) problems.push(`flags: ${clip(raw)} is not one of ${FLAGS.join(', ')}`)
      else if (!flags.includes(flag)) flags.push(flag)
    }
  }
  return summary === null || level === undefined || bumpReason === null ? null : { summary, bump: level, bumpReason, flags }
}

// --- the designer (SPEC 7.2) ------------------------------------------------------------------

// checkDesign: a designer's answer for this issue. A result that leaves the loop nothing to do
// (no brief, no created issues, no decision pending) is a forgotten field.
export function checkDesign(input, repo, issue) {
  const problems = []
  const o = record(input) ?? {}
  strays(o, ['brief', 'created', 'pendingDecision'], '', problems)
  const where = `${repo} issue ${issue ?? '<N>'}`
  let brief = null
  if (o.brief === undefined) problems.push(`brief is required: the brief comment's URL on ${where}, or null`)
  else if (o.brief !== null) {
    const url = typeof o.brief === 'string' ? o.brief.trim() : ''
    if (isBriefUrl(url, repo, issue)) brief = url
    else problems.push(`brief ${clip(o.brief)} is not a comment URL on ${where} (https://github.com/${repo}/issues/${issue ?? '<N>'}#issuecomment-<id>)`)
  }
  const created = Array.isArray(o.created) && o.created.every(n => Number.isInteger(n) && n > 0) ? [...new Set(o.created)] : null
  if (created === null) problems.push('created must be a list of the issue numbers you created ([] for none)')
  if (typeof o.pendingDecision !== 'boolean') problems.push('pendingDecision must be true or false')
  const pending = o.pendingDecision === true
  if (problems.length === 0 && brief === null && created?.length === 0 && !pending) {
    problems.push('with no brief, no created issues and no decision pending, the loop has nothing to hand on: give the brief URL')
  }
  return checked(problems, () => ({ kind: 'designer', brief, created: created ?? [], pendingDecision: pending }))
}

// --- implementer and fixer handoffs ---------------------------------------------------------

// checkHandoff: a handoff, read as its RESULT line is (handoffOutcome): not gated when it says so
// or its head is not its commit; a branch other than the one the spawn named is a new one; gated
// with no run is refused (gatedWithoutRun).
export function checkHandoff(input, namedBranch) {
  const problems = []
  const o = record(input) ?? {}
  strays(o, ['run', 'head', 'commit', 'gated', 'branch', 'pr'], '', problems)
  const id = (key, shape, what) => {
    const v = o[key]
    if (v === undefined) problems.push(`${key} is required (null for none)`)
    else if (v !== null) {
      if (typeof v === 'string' && shape.test(v.trim())) return v.trim()
      problems.push(`${key} ${clip(v)} is not ${what}, or null`)
    }
    return null
  }
  const run = id('run', HANDOFF_SHAPES.run, 'a pipeline run id')
  const head = id('head', HANDOFF_SHAPES.sha, 'a commit SHA of 7 to 40 hex digits')
  const commit = id('commit', HANDOFF_SHAPES.sha, 'a commit SHA of 7 to 40 hex digits')
  const branch = id('branch', HANDOFF_SHAPES.branch, 'a branch name')
  if (typeof o.gated !== 'boolean') problems.push('gated must be true or false')
  else if (o.run === null && gatedWithoutRun({ run, gated: o.gated })) problems.push('gated is true with run null, and with no pipeline run nothing is gated: give the run, or gated false')
  if (o.pr === undefined) problems.push('pr is required (null for none)')
  else if (o.pr !== null && !(Number.isInteger(o.pr) && o.pr > 0)) problems.push(`pr ${clip(o.pr)} is not a PR number, or null`)
  const pr = typeof o.pr === 'number' ? o.pr : null
  const gated = o.gated === true
  return checked(problems, () => handoffOutcome({ run, head: head?.toLowerCase() ?? null, commit: commit?.toLowerCase() ?? null, gated, branch, pr }, namedBranch))
}

// checkAnswer: an answer under its job: the contract, and what checking it needs (the review's
// purpose, the repo and issue a brief must be on, the branch a fixer was sent to). Every channel
// checks through this one call: the tool's hook and the loop's re-check with the job the loop
// knows from its ledger, the script with the job file the loop wrote at the spawn.
export function checkAnswer(job, input) {
  const v2 = Object.hasOwn(V2_CONTRACTS, job.contract) ? V2_CONTRACTS[job.contract] : undefined
  if (v2 !== undefined) return v2.check(input, job)
  if (job.contract === 'verdict') {
    if (job.purpose === null) return { ok: false, problems: ['the factory loop cannot tell which review this is'] }
    return checkVerdict(input, job.purpose)
  }
  if (job.contract === 'design') return checkDesign(input, job.repo, job.issue)
  return checkHandoff(input, job.branch)
}

// --- the answer script's files (#561) ------------------------------------------------------------

// An agent's answer file, at a path the loop names in its prompt, unique to the ledger entry and
// attempt, in <loop dir>/answers/; beside it the job file the loop writes before the spawn. The
// script writes the answer file alone, and only where a job file stands.
export const ANSWER_SUFFIX = '.answer.json'
export const JOB_SUFFIX = '.job.json'
export const ANSWER_NAME = /^[A-Za-z0-9][A-Za-z0-9._-]*\.answer\.json$/
// The loop dir's own name: <owner>__<repo> (loopDirOf).
export const LOOP_DIR_NAME = /^[A-Za-z0-9._-]+__[A-Za-z0-9._-]+$/

// loopBaseOf: the factory loop's directory under a config dir (CLAUDE_CONFIG_DIR, else
// ~/.claude), a trailing / on it dropped: its config.json, its OFF file and every repo's loop dir.
export function loopBaseOf(configDir) {
  return `${configDir.replace(/\/+$/, '')}/factory-loop`
}

// loopDirOf: a repo's loop dir, <config dir>/factory-loop/<owner>__<repo>: where the loop keeps
// that repo's files (register.ts runtime), and whose answers/ directory is the only place the
// answer script writes, for a job of that repo.
export function loopDirOf(configDir, repo) {
  return `${loopBaseOf(configDir)}/${repo.replace('/', '__')}`
}
const FILE_VERSION = 1

// jobPathOf: the job file beside an answer file, or null for a path that names no answer file.
export function jobPathOf(answerPath) {
  const slash = answerPath.lastIndexOf('/')
  const name = answerPath.slice(slash + 1)
  return ANSWER_NAME.test(name) ? `${answerPath.slice(0, slash + 1)}${name.slice(0, -ANSWER_SUFFIX.length)}${JOB_SUFFIX}` : null
}

// jobText: the job file's body. A v2 job's data (what its contract's check needs beside the
// answer) goes in only when it has some, so a v1 job's body is as it always was.
export function jobText(job) {
  const body = { v: FILE_VERSION, contract: job.contract, purpose: job.purpose, repo: job.repo, issue: job.issue, branch: job.branch }
  if (job.data !== undefined && job.data !== null) body.data = job.data
  return `${JSON.stringify(body, null, 2)}\n`
}

// parseJob: a job file's body as a job, or why it is none.
export function parseJob(body) {
  let v
  try {
    v = JSON.parse(body)
  } catch {
    return 'the job file is not JSON'
  }
  const o = record(v)
  if (o === null || o.v !== FILE_VERSION) return `the job file is not version ${FILE_VERSION} of the factory loop's job files`
  const contract = CONTRACTS.find(c => c === o.contract)
  const purpose = o.purpose === null ? null : (PURPOSES.find(p => p === o.purpose) ?? undefined)
  const issue = o.issue === null || (Number.isInteger(o.issue) && o.issue > 0) ? o.issue : undefined
  const branch = o.branch === null || (typeof o.branch === 'string' && o.branch !== '') ? o.branch : undefined
  const data = o.data === undefined || o.data === null ? null : (record(o.data) ?? undefined)
  if (contract === undefined || purpose === undefined || typeof o.repo !== 'string' || issue === undefined || branch === undefined || data === undefined) return 'the job file is not in the shape the factory loop writes'
  return data === null ? { contract, purpose, repo: o.repo, issue, branch } : { contract, purpose, repo: o.repo, issue, branch, data }
}

// answerSummary: a few words on an answer the script recorded, so the agent sees the loop will
// read what it meant.
export function answerSummary(contract, input) {
  const v2 = Object.hasOwn(V2_CONTRACTS, contract) ? V2_CONTRACTS[contract] : undefined
  if (v2 !== undefined) return v2.summary(input)
  const o = input !== null && typeof input === 'object' ? input : {}
  if (contract === 'verdict') {
    const n = Array.isArray(o.findings) ? o.findings.length : 0
    return `action ${o.action?.type}, ${n} finding${n === 1 ? '' : 's'}`
  }
  if (contract === 'design') return `brief ${o.brief ?? 'none'}, created ${(o.created ?? []).join(',') || 'none'}, pending decision ${o.pendingDecision ? 'yes' : 'no'}`
  return `run ${o.run ?? 'none'}, head ${o.head ?? 'none'}, gated ${o.gated ? 'yes' : 'no'}`
}

// answerText: the answer file's body for an input its job's contract takes, or the problems
// that keep it out. The input is kept as the agent gave it: the loop checks it again on reading.
export function answerText(job, input) {
  const check = checkAnswer(job, input)
  if (!check.ok) return check
  return { ok: true, outcome: `${JSON.stringify({ v: FILE_VERSION, contract: job.contract, answer: input }, null, 2)}\n` }
}

// parseAnswer: an answer file's body: the answer it carries, for this contract, still to be
// checked; or why it carries none.
export function parseAnswer(body, contract) {
  let v
  try {
    v = JSON.parse(body)
  } catch {
    return { ok: false, problems: ['the answer file is not JSON'] }
  }
  const o = record(v)
  if (o === null || o.v !== FILE_VERSION || !('answer' in o)) return { ok: false, problems: ['the answer file is not in the shape the answer script writes'] }
  if (o.contract !== contract) return { ok: false, problems: [`the answer file holds a ${clip(o.contract)} answer, and this agent answers with ${contract}`] }
  return { ok: true, outcome: o.answer }
}

files.hooks/config-view.ts:
// `/factory config` (#698): the settings the loop runs with, grouped, each with where its value
// came from. Pure: it renders the Runtime the last pass used (viewOf) and the control state, and
// reads no file, so it shows what the pass runs with, not what the files say now.
import { shortDuration } from './config'
import type { Runtime } from './observe'
import type { Config, Control, Ms } from './types'

// Where a value came from. plugin, env and directive are for the few values that have no settings
// layer: the plugin's options, the machine name, and control.json.
export type Source = 'default' | 'repo' | 'workspace' | 'plugin' | 'env' | 'directive'

// What runtime() adds to the Runtime for the view: the workspace file as read, the plugin's version.
export type ViewInputs = { workspaceRaw: Record<string, unknown>; pluginVersion: string; deviceFrom: Source }

// What the view needs of a pass's Runtime, with the parts a Runtime may lack filled in.
export type ConfigView = {
  config: Config
  device: string
  poolSize: number
  repoRaw: Record<string, unknown>
  workspaceRaw: Record<string, unknown>
  problems: readonly string[]
  modeFrom: Source
  deviceFrom: Source
  pluginVersion: string
}

const WIDTH = 60
const LABEL = 16
const VALUE = 22

// clock: a time as HH:MM UTC, with the date when it is not today's.
export function clock(at: Ms, now: Ms): string {
  const iso = new Date(at).toISOString()
  const day = iso.slice(0, 10) === new Date(now).toISOString().slice(0, 10) ? '' : `${iso.slice(0, 10)} `
  return `${day}${iso.slice(11, 16)} UTC`
}

const isObject = (v: unknown): v is Record<string, unknown> => v !== null && typeof v === 'object' && !Array.isArray(v)

// the spellings a settings file may use for a key: `passEveryMs` is also `passEvery`
function spellings(key: string): string[] {
  return key.endsWith('Ms') ? [key, key.slice(0, -2)] : [key]
}

// sets: whether a layer sets the key; `parent.sub` looks into the parent's object
function sets(layer: Record<string, unknown>, key: string): boolean {
  const [parent = '', sub] = key.split('.')
  if (sub === undefined) return spellings(parent).some(name => name in layer)
  return spellings(parent).some(name => {
    const inner = layer[name]
    return isObject(inner) && sub in inner
  })
}

// layerRejected: whether a config problem rejected the value this layer holds for the key (or for
// its parent object). A problem reads `name: <JSON of the value> is not ...`, so the rejected layer
// is the one whose value, written as JSON, is the one the problem quotes.
function layerRejected(problems: readonly string[], layer: Record<string, unknown>, key: string): boolean {
  const [parent = '', sub] = key.split('.')
  return spellings(parent).some(name => {
    const mine = layer[name]
    if (mine === undefined) return false
    const held = sub === undefined ? [[name, mine]] : [[name, mine], ...(isObject(mine) && sub in mine ? [[`${name}.${sub}`, mine[sub]]] : [])]
    return held.some(([label, value]) => problems.some(p => p.startsWith(`${label}: ${JSON.stringify(value) ?? String(value)} is not `)))
  })
}

// sourceOf: the layer a key's value in force came from: the workspace file if it set the key and
// the loader kept its value, else the repo's file likewise, else the default. A value the loader
// rejected is skipped, so the key shows the lower layer whose value is in force.
export function sourceOf(
  key: string,
  repoRaw: Record<string, unknown> | null,
  workspaceRaw: Record<string, unknown> | null,
  problems: readonly string[] = [],
): Source {
  if (workspaceRaw !== null && sets(workspaceRaw, key) && !layerRejected(problems, workspaceRaw, key)) return 'workspace'
  if (repoRaw !== null && sets(repoRaw, key) && !layerRejected(problems, repoRaw, key)) return 'repo'
  return 'default'
}

function originOf(file: Record<string, unknown>, key: string): Source {
  return typeof file[key] === 'string' && file[key] !== '' ? 'workspace' : 'plugin'
}

// viewOf: the view of the settings a pass ran with. A Runtime without the provenance fields
// (a test's, an older pass) reads as every value from its default.
export function viewOf(rt: Runtime & Partial<ViewInputs>): ConfigView {
  const file = rt.workspaceRaw ?? {}
  return {
    config: rt.config,
    device: rt.device,
    poolSize: rt.poolSize,
    repoRaw: rt.repoSettings ?? {},
    workspaceRaw: file,
    problems: rt.configProblems,
    modeFrom: originOf(file, 'mode'),
    deviceFrom: rt.deviceFrom ?? (rt.device === '' ? 'default' : 'env'),
    pluginVersion: rt.pluginVersion ?? 'unknown',
  }
}

type Row = { label: string; value: string; source?: Source | 'mixed'; note?: string }

const clip = (line: string) => (line.length <= WIDTH ? line : `${line.slice(0, WIDTH - 3)}...`)

function render(row: Row): string[] {
  // a label past the column still keeps a space before its value
  const head = `  ${row.label.padEnd(LABEL)}${row.label.length >= LABEL ? ' ' : ''}`
  const room = WIDTH - head.length - (row.source === undefined ? 0 : row.source.length + 1)
  const value = row.value.length > room ? `${row.value.slice(0, Math.max(0, room - 3))}...` : row.value
  const line = row.source === undefined ? `${head}${value}` : `${head}${value.padEnd(Math.min(VALUE, room))} ${row.source}`
  return [line.trimEnd(), ...(row.note === undefined ? [] : [clip(`    ${row.note}`)])]
}

// the one source of several keys, or mixed when they differ
function together(sources: Source[]): Source | 'mixed' {
  const first = sources[0] ?? 'default'
  return sources.every(s => s === first) ? first : 'mixed'
}

const MODE_NOTE = { off: 'runs nothing', observe: 'plans and logs only', act: 'does the work' }
const STATES = ['design', 'build', 'review', 'fix', 'queued', 'parked'] as const

// configText: the answer to `/factory config`. A null view is a loop that has not run a pass.
export function configText(view: ConfigView | null, control: Control, now: Ms): string {
  if (view === null) return 'Factory loop: no pass yet, so no settings are loaded.'
  const c = view.config
  const src = (key: string) => sourceOf(key, view.repoRaw, view.workspaceRaw, view.problems)
  const row = (label: string, key: string, value: string, note?: string): Row => ({ label, value, source: src(key), ...(note === undefined ? {} : { note }) })
  const ms = (key: keyof Config & string) => row(key.replace(/Ms$/, ''), key, shortDuration(c[key] as Ms))
  const override = control.usageOverride
  const live = override !== null && now < override.expiresAt

  const timeouts = STATES.map(name => ({ name, ms: c.stateTimeoutMs[name], from: src(`stateTimeoutMs.${name}`) }))
  const from = together(timeouts.map(t => t.from))
  const changed = (['repo', 'workspace'] as const)
    .map(s => ({ s, names: timeouts.filter(t => t.from === s).map(t => t.name) }))
    .filter(g => g.names.length > 0)
    .map(g => `${g.s}: ${g.names.join(' ')}`)
  const compact = timeouts.map(t => `${t.name} ${shortDuration(t.ms)}`)
  const half = Math.ceil(compact.length / 2)

  const groups: [string, string[]][] = [
    [
      'Loop',
      [
        ...render({ label: 'mode', value: c.mode, source: view.modeFrom, note: MODE_NOTE[c.mode] }),
        ...render(row('planner', 'planner', c.planner, c.planner === 'v2' ? 'v2 plans and acts' : 'v1 plans and acts')),
        ...render(ms('passEveryMs')),
        ...render({ label: 'plugin', value: view.pluginVersion }),
        ...render({ label: 'device', value: view.device === '' ? '(none)' : view.device, source: view.deviceFrom }),
      ],
    ],
    [
      'Capacity',
      [
        ...render(row('maxInFlight', 'maxInFlightIssues', c.maxInFlightIssues === null ? 'no cap' : String(c.maxInFlightIssues))),
        ...render({ label: 'poolSize', value: String(view.poolSize), source: typeof view.workspaceRaw.poolSize === 'number' ? 'workspace' : 'default' }),
        ...render(row('worktreeReserve', 'worktreeReserve', String(c.worktreeReserve))),
        ...render(row('maxStarts', 'maxStartsPerPass', String(c.maxStartsPerPass))),
        ...render({ label: 'serial', value: control.serial ? 'on' : 'off', source: 'directive' }),
        ...render({ label: 'new work', value: control.noNewWork ? 'off' : 'on', source: 'directive' }),
      ],
    ],
    [
      'Limits',
      [
        ...render(row('reviewFixCap', 'reviewFixCap', String(c.reviewFixCap))),
        ...render(row('maxLives', 'maxLives', String(c.maxLives))),
        ...render(row('maxTriages', 'maxTriages', String(c.maxTriages))),
        ...render(ms('minimumReleaseCadenceMs')),
        ...render({ label: 'stateTimeout', value: '', source: from, ...(from === 'mixed' && changed.length > 0 ? { note: changed.join('; ') } : {}) }),
        clip(`    ${compact.slice(0, half).join(' ')}`),
        clip(`    ${compact.slice(half).join(' ')}`),
      ],
    ],
    [
      'Agents and gates',
      [
        ...render(row('reviewer', 'reviewer', c.reviewer)),
        ...render(row('reviewerModel', 'reviewerModel', c.reviewerModel)),
        ...render(row('triageModel', 'triageModel', c.triageModel)),
        ...render({ label: 'gateCommands', value: c.gateCommands.length === 0 ? 'none' : '', source: src('gateCommands') }),
        ...c.gateCommands.map(cmd => clip(`    ${cmd}`)),
        ...render(ms('gateTimeoutMs')),
      ],
    ],
    [
      'Usage',
      [
        ...render({
          label: 'slow/new/all %',
          value: `${c.usageSlowPct} / ${c.usageStopNewPct} / ${c.usageStopAllPct}`,
          source: together([src('usageSlowPct'), src('usageStopNewPct'), src('usageStopAllPct')]),
          note: 'slow down / stop new work / stop all',
        }),
        ...render({
          label: 'override',
          value: live ? `to ${override.untilPct}% until ${clock(override.expiresAt, now)}` : 'none',
          source: 'directive',
        }),
      ],
    ],
    ['Config problems', view.problems.length === 0 ? ['  none'] : view.problems.map(p => clip(`  ${p}`))],
  ]
  return groups.flatMap(([title, lines], i) => [...(i === 0 ? [] : ['']), title, ...lines]).join('\n')
}

files.hooks/control.ts:
// The owner's controls (SPEC 4.3; DECISIONS D-15, D-16, D-33, D-35, D-38). `/factory <op>` and
// the control tool (mcp__factory-loop__control, input { op }) take the same op text: parseOp
// reads it, applyOp returns the new Control (the old one is never changed) with the effects the
// driver carries out and the one line the command or tool answers, and runOp makes the round
// trip over ActIo's readFile and writeFile: `<loop dir>/control.json`, which observe reads each
// pass, and the workspace config file for `mode`, `trace` and `planner`. Everything but runOp and
// its two file wrappers is pure, so the tests and the replay harness drive it without the engine.
// Under planner v2 three ops take v2's meaning (v2 SPEC appendix E), which v2/ops.ts holds:
// `resume <N...> ["note"]` unparks (P1), `drop` closes the current life's record (E1), and an issue
// that is not parked is not resumed; the caller says which planner is in force.
import type { CommandSpec, ToolSpec } from 'claude-code'

import type { PassSummary } from '../types'
import { EMPTY_CONTROL, controlFrom, loadConfig } from './config'
import { DEFAULT_POOL_SIZE, checkKey, checkSetting, editSetting, effectText, withoutSetting, shown, valueIn, valueOfText } from './config-keys'
import { clock, configText } from './config-view'
import type { ConfigView } from './config-view'
import { OPS, USAGE, helpText, hintText } from './control-help'
import type { OpName } from './control-help'
import type { ActIo } from './exec'
import type { Control, Mode, Ms } from './types'
import { applyDrop, applyUnpark, onlyParked, parseUnpark } from './v2/ops'
import type { Unpark } from './v2/ops'
import type { Planner } from './v2/types'

const MIN = 60_000
const HOUR = 60 * MIN
// an override longer than the seven-day usage window is a typo, not a plan (I-19)
const OVERRIDE_MAX_HOURS = 168
// a reason rides on the restart's ledger entry and the drain-slow tell; a note goes into every
// matching agent prompt (SPEC 6.3). Both are refused past these, never cut.
const REASON_MAX = 300
const NOTE_MAX = 2000

export { HINT_OPS, MEANING, OPS, USAGE, helpText, hintText } from './control-help'
export type { OpName } from './control-help'

// One op, parsed. An empty priority or only list clears it.
export type Op =
  | { op: 'status' }
  // no change: the read-only view; a change sets a key in the workspace config file, or removes it
  // (no value). The key is as typed (`passEvery`, `stateTimeout.design`)
  | { op: 'config'; change?: { key: string; value?: unknown } }
  | { op: 'help' }
  | { op: 'pause' | 'unpause' | 'skip' | 'noskip' | 'retry' | 'drop'; issue: number }
  | { op: 'priority' | 'only'; issues: number[] }
  | { op: 'serial' | 'new' | 'trace'; on: boolean }
  // null: `override off`
  | { op: 'override'; until: { pct: number; hours: number } | null }
  // 'issue:<N>' or 'run:<id>', as plan's resumes() matches them
  | { op: 'resume'; subject: string }
  // null: `update off`
  | { op: 'update'; reason: string | null }
  | { op: 'note'; issue: number | null; text: string }
  | { op: 'mode'; mode: Mode }
  | { op: 'planner'; planner: Planner }
  // v2's resume (v2/ops.ts)
  | Unpark

export type Parsed = { ok: true; op: Op } | { ok: false; error: string }

// What the driver carries out besides writing control.json: retryIssue through the ledger's
// retryIssue (D-38), mode, trace and planner into the workspace config file (runOp does those).
export type Setting = { key: string; fileKey: string; sub: string | null }
export type Effects = { retryIssue?: number; mode?: Mode; trace?: boolean; planner?: Planner; setting?: { k: Setting; value?: unknown } }

export type Applied = { control: Control; effects: Effects; changed: boolean; text: string }

// --- parsing ---------------------------------------------------------------------------------

const ISSUE = /^#?([1-9]\d{0,8})$/
// a pipeline run id (a ULID such as 01M4RQ0045AAAA); unprefixed, a number alone reads as an issue
const RUN_CHARS = /^[A-Za-z0-9][A-Za-z0-9._-]{0,99}$/
const RUN_ID = /^(?=.*[A-Za-z])[A-Za-z0-9][A-Za-z0-9._-]{0,99}$/
const DECIMAL = /^(\d+(?:\.\d+)?)$/

function issueOf(word: string | undefined): number | null {
  const m = word === undefined ? null : ISSUE.exec(word)
  return m?.[1] === undefined ? null : Number(m[1])
}

function bad(name: OpName, why?: string): Parsed {
  return { ok: false, error: `${why === undefined ? '' : `${name}: ${why}. `}Usage: ${USAGE[name]}` }
}

function allUsage(): string {
  return OPS.map(name => USAGE[name]).join(', ')
}

// parseOp: one op as the owner types it after `/factory`, or the tool's `op`. The op name and
// its keywords ignore case, numbers take an optional leading #, and a list may use commas. An
// empty op is `status`. Anything malformed is an error naming the op and its usage, so a bad
// op never makes a partial change. Under planner v2, `resume` takes issue numbers and an
// optional note in double quotes, and no run id.
export function parseOp(text: string, planner: Planner = 'v1'): Parsed {
  const words = text.trim().split(/\s+/).filter(w => w !== '')
  // the model may pass the command as typed
  if (words[0]?.toLowerCase() === '/factory') words.shift()
  const head = (words[0] ?? 'status').toLowerCase()
  const args = words.slice(1)
  const rest = args.join(' ')
  const word = args.length === 1 ? args[0]?.toLowerCase() : undefined
  if (head === 'help' || head === '--help' || head === '-h') return { ok: true, op: { op: 'help' } }
  if (!(OPS as readonly string[]).includes(head)) {
    return { ok: false, error: `Unknown op "${(words[0] ?? '').slice(0, 40)}". Ops: ${allUsage()}. /factory help explains each.` }
  }
  const name = head as OpName

  switch (name) {
    case 'status':
      return args.length === 0 ? { ok: true, op: { op: name } } : bad(name)
    case 'config': {
      if (args.length === 0) return { ok: true, op: { op: 'config' } }
      const verb = args[0]?.toLowerCase()
      const key = args[1]
      if (verb === 'unset' && key !== undefined && args.length === 2) return { ok: true, op: { op: 'config', change: { key } } }
      if (verb === 'set' && key !== undefined && args.length > 2) return { ok: true, op: { op: 'config', change: { key, value: valueOfText(args.slice(2).join(' ')) } } }
      return bad(name)
    }
    case 'pause':
    case 'unpause':
    case 'skip':
    case 'noskip':
    case 'retry':
    case 'drop': {
      const issue = args.length === 1 ? issueOf(args[0]) : null
      return issue === null ? bad(name, 'takes one issue number') : { ok: true, op: { op: name, issue } }
    }
    case 'priority':
    case 'only': {
      if (word === 'off') return { ok: true, op: { op: name, issues: [] } }
      const items = rest.split(/[\s,]+/).filter(w => w !== '')
      const issues = items.map(issueOf)
      if (items.length === 0 || issues.some(n => n === null)) return bad(name, 'takes issue numbers, or off')
      return { ok: true, op: { op: name, issues: [...new Set(issues as number[])] } }
    }
    case 'serial':
    case 'new':
    case 'trace':
      return word === 'on' || word === 'off' ? { ok: true, op: { op: name, on: word === 'on' } } : bad(name)
    case 'override': {
      if (word === 'off') return { ok: true, op: { op: 'override', until: null } }
      const pct = args.length === 2 ? DECIMAL.exec(args[0]?.replace(/%$/, '') ?? '') : null
      const hours = args.length === 2 ? DECIMAL.exec(args[1]?.replace(/h$/i, '') ?? '') : null
      if (pct?.[1] === undefined || hours?.[1] === undefined) return bad(name, 'takes a percentage and a number of hours')
      const p = Number(pct[1])
      const h = Number(hours[1])
      if (p <= 0 || p > 100) return bad(name, 'the percentage is above 0 and at most 100')
      if (h <= 0 || h > OVERRIDE_MAX_HOURS) return bad(name, `the hours are above 0 and at most ${OVERRIDE_MAX_HOURS}`)
      return { ok: true, op: { op: 'override', until: { pct: p, hours: h } } }
    }
    case 'resume': {
      if (planner === 'v2') {
        const unpark = parseUnpark(rest, issueOf, NOTE_MAX)
        return typeof unpark === 'string' ? bad(name, unpark) : { ok: true, op: unpark }
      }
      // `issue:<N>` and `run:<id>` (formatOp's spelling) are read too
      const arg = args.length === 1 ? (args[0] ?? '') : ''
      const prefixed = /^(issue|run):(.+)$/i.exec(arg)
      const kind = prefixed?.[1]?.toLowerCase()
      const value = prefixed?.[2] ?? arg
      const issue = kind === 'run' ? null : issueOf(value)
      if (issue !== null) return { ok: true, op: { op: 'resume', subject: `issue:${issue}` } }
      const run = kind === 'run' ? RUN_CHARS.test(value) : kind === undefined && RUN_ID.test(value)
      return run ? { ok: true, op: { op: 'resume', subject: `run:${value}` } } : bad(name, 'takes one issue number or run id')
    }
    case 'update':
      if (args.length === 0) return { ok: true, op: { op: 'update', reason: 'owner' } }
      if (word === 'off') return { ok: true, op: { op: 'update', reason: null } }
      if (rest.length > REASON_MAX) return bad(name, `the reason is at most ${REASON_MAX} characters`)
      return { ok: true, op: { op: 'update', reason: rest } }
    case 'note': {
      const issue = issueOf(args[0])
      const note = (issue === null ? args : args.slice(1)).join(' ')
      if (note === '') return bad(name, 'needs the text')
      if (note.length > NOTE_MAX) return bad(name, `the text is at most ${NOTE_MAX} characters`)
      return { ok: true, op: { op: 'note', issue, text: note } }
    }
    case 'mode':
      return word === 'off' || word === 'observe' || word === 'act' ? { ok: true, op: { op: 'mode', mode: word } } : bad(name)
    case 'planner':
      return word === 'v1' || word === 'v2' ? { ok: true, op: { op: 'planner', planner: word } } : bad(name)
  }
}

// issuesOf: the issues an op names, which its intervention attaches to (v2 SPEC 7.2); none for a
// fleet-level op.
export function issuesOf(op: Op): number[] {
  if ('issue' in op) return op.issue === null ? [] : [op.issue]
  if ('issues' in op) return [...op.issues]
  if (op.op === 'resume' && op.subject.startsWith('issue:')) return [Number(op.subject.slice('issue:'.length))]
  return []
}

// formatOp: the op as canonical text, for the decision log; parseOp reads it back, but for a
// note to every issue whose text starts with a number.
export function formatOp(op: Op): string {
  switch (op.op) {
    case 'status':
      return op.op
    case 'config':
      if (op.change === undefined) return 'config'
      return 'value' in op.change ? `config set ${op.change.key} ${JSON.stringify(op.change.value)}` : `config unset ${op.change.key}`
    case 'help':
      return 'help'
    case 'pause':
    case 'unpause':
    case 'skip':
    case 'noskip':
    case 'retry':
    case 'drop':
      return `${op.op} ${op.issue}`
    case 'priority':
    case 'only':
      return `${op.op} ${op.issues.length === 0 ? 'off' : op.issues.join(' ')}`
    case 'serial':
    case 'new':
    case 'trace':
      return `${op.op} ${op.on ? 'on' : 'off'}`
    case 'override':
      return op.until === null ? 'override off' : `override ${op.until.pct} ${op.until.hours}`
    case 'resume':
      return `resume ${op.subject}`
    case 'update':
      return op.reason === null ? 'update off' : `update ${op.reason}`
    case 'note':
      return `note ${op.issue === null ? '' : `${op.issue} `}${op.text}`
    case 'mode':
      return `mode ${op.mode}`
    case 'planner':
      return `planner ${op.planner}`
    case 'unpark':
      return `resume ${op.issues.join(' ')}${op.note === null ? '' : ` "${op.note}"`}`
  }
}

// --- applying --------------------------------------------------------------------------------

const tags = (issues: readonly number[]) => issues.map(n => `#${n}`).join(' ')
const same = (a: readonly number[], b: readonly number[]) => a.length === b.length && a.every((n, i) => n === b[i])

// applyChange: `config set|unset`: the key and value checked as loadConfig reads them, then the
// answer (the old value in force, the new one, when it applies) and the effect runOp writes. A
// refusal answers why and has no effect.
function applyChange(control: Control, change: { key: string; value?: unknown }, view: ConfigView | null): Applied {
  const set = 'value' in change
  const checked = set ? checkSetting(change.key, change.value) : checkKey(change.key)
  if (!checked.ok) return { control, effects: {}, changed: false, text: checked.error }
  const { key, sub } = checked
  const now = (config: Parameters<typeof valueIn>[0] | undefined) => (config === undefined ? undefined : valueIn(config, key, sub))
  // the value in force, and what an unset leaves in force: the repo's, else the default
  const was = key === 'poolSize' ? view?.poolSize : now(view?.config)
  const after = set ? change.value : key === 'poolSize' ? DEFAULT_POOL_SIZE : now(loadConfig(view?.repoRaw ?? {}, withoutSetting(view?.workspaceRaw ?? {}, checked)).config)
  const name = sub === null ? change.key : `${checked.fileKey}.${sub}`
  const text = `${set ? 'Set' : 'Unset'} ${name}: was ${was === undefined ? 'unknown' : shown(key, was)}, now ${shown(key, after)}; ${effectText(key)}.`
  const setting = { k: { key, fileKey: checked.fileKey, sub }, ...(set ? { value: change.value } : {}) }
  return { control, effects: { setting }, changed: false, text }
}

// applyOp: the op against the control state as it stands. The input is never changed: a change
// returns a new Control with new arrays for what changed. `changed` says whether control.json
// needs writing; an op that changes nothing (pausing a paused issue) answers so and writes
// nothing. `last` is the last pass, for status. Under planner v2 a drop applies to the life it
// closes, so a drop of an issue claimed again since is recorded again (v2 SPEC 4.1).
export function applyOp(control: Control, op: Op, now: Ms, last: PassSummary | null = null, planner: Planner = 'v1', view: ConfigView | null = null): Applied {
  const keep = (text: string, effects: Effects = {}): Applied => ({ control, effects, changed: false, text })
  const set = (patch: Partial<Control>, text: string): Applied => ({ control: { ...control, ...patch }, effects: {}, changed: true, text })

  switch (op.op) {
    case 'status':
      return keep(statusText(last, control, now))
    case 'config':
      return op.change === undefined ? keep(configText(view, control, now)) : applyChange(control, op.change, view)
    case 'help':
      return keep(helpText())
    case 'pause':
      return control.paused.includes(op.issue)
        ? keep(`#${op.issue} is already paused.`)
        : set({ paused: [...control.paused, op.issue] }, `Paused #${op.issue}: no action on it until unpause; its claim still renews.`)
    case 'unpause':
      return control.paused.includes(op.issue)
        ? set({ paused: control.paused.filter(n => n !== op.issue) }, `Unpaused #${op.issue}.`)
        : keep(`#${op.issue} is not paused.`)
    case 'skip':
      return control.skip.includes(op.issue)
        ? keep(`#${op.issue} is already skipped.`)
        : set({ skip: [...control.skip, op.issue] }, `Skipping #${op.issue}: it is never claimed.`)
    case 'noskip':
      return control.skip.includes(op.issue)
        ? set({ skip: control.skip.filter(n => n !== op.issue) }, `#${op.issue} can be claimed again.`)
        : keep(`#${op.issue} is not skipped.`)
    case 'priority':
      if (same(control.priority, op.issues)) return keep(op.issues.length === 0 ? 'No priority is set.' : `Priority is already ${tags(op.issues)}.`)
      return op.issues.length === 0
        ? set({ priority: [] }, 'Priority cleared.')
        : set({ priority: [...op.issues] }, `Priority: ${tags(op.issues)} are claimed first, in this order.`)
    case 'only':
      if (same(control.only, op.issues)) return keep(op.issues.length === 0 ? 'Only is already off.' : `Only is already ${tags(op.issues)}.`)
      return op.issues.length === 0
        ? set({ only: [] }, 'Only off: any ready issue can be claimed.')
        : set(
            { only: [...op.issues] },
            `Only ${tags(op.issues)}: claims only these, in this order (a tracker stands for its open sub-issues); work in flight goes on.`,
          )
    case 'serial':
      if (control.serial === op.on) return keep(`Serial is already ${op.on ? 'on' : 'off'}.`)
      return set({ serial: op.on }, op.on ? 'Serial on: one issue in flight at a time.' : 'Serial off.')
    case 'new':
      if (control.noNewWork === !op.on) return keep(`New work is already ${op.on ? 'on' : 'off'}.`)
      return set(
        { noNewWork: !op.on },
        op.on ? 'New work on.' : 'New work off: no new claims, designs or implementations; work in flight goes on.',
      )
    case 'override': {
      const live = control.usageOverride !== null && now < control.usageOverride.expiresAt
      if (op.until === null) {
        if (control.usageOverride === null) return keep('No usage override is set.')
        return set({ usageOverride: null }, live ? 'Usage override cleared.' : 'Expired usage override cleared.')
      }
      const expiresAt = now + Math.round(op.until.hours * HOUR)
      return set(
        { usageOverride: { untilPct: op.until.pct, expiresAt } },
        `Usage override: run past the usage tiers up to ${op.until.pct}% until ${clock(expiresAt, now)}.`,
      )
    }
    case 'resume': {
      const what = op.subject.startsWith('issue:') ? `issue #${op.subject.slice('issue:'.length)}` : `run ${op.subject.slice('run:'.length)}`
      return set({ resumed: [...control.resumed, { subject: op.subject, at: now }] }, `Resumed ${what}: its hold is released.`)
    }
    case 'retry':
      return keep(`Retry #${op.issue}: its exhausted actions are cleared.`, { retryIssue: op.issue })
    case 'update':
      if (op.reason === null) {
        return control.updateDue === null ? keep('No update is due.') : set({ updateDue: null }, 'Update cancelled: the loop stops draining.')
      }
      return set(
        { updateDue: { reason: op.reason, at: now } },
        `Update due (${op.reason}): the loop drains, then restarts this workspace once nothing is in flight.`,
      )
    case 'drop': {
      if (planner === 'v2') {
        const v2 = applyDrop(control, op.issue, now)
        return set(v2.patch, v2.text)
      }
      if (control.dropped.some(d => d.issue === op.issue)) return keep(`#${op.issue} is already dropped.`)
      // a pause holds every action, the abandon too (plan's owner filter)
      const paused = control.paused.includes(op.issue) ? ` It is paused: unpause it for the abandon to run.` : ''
      return set(
        { dropped: [...control.dropped, { issue: op.issue, at: now }] },
        `Dropped #${op.issue}: the loop abandons it and stops its agents.${paused}`,
      )
    }
    case 'note':
      return set(
        { notes: [...control.notes, { issue: op.issue, text: op.text, at: now }] },
        op.issue === null ? 'Note added for every issue: the next agent prompts carry it.' : `Note added for #${op.issue}: its next agent prompts carry it.`,
      )
    case 'mode':
      return keep(`Mode ${op.mode} set in the workspace config file; it applies from the next pass.`, { mode: op.mode })
    case 'planner':
      return keep(`Planner ${op.planner} set in the workspace config file; it plans and acts from the next pass.`, { planner: op.planner })
    case 'unpark': {
      const v2 = applyUnpark(control, op, now)
      return set(v2.patch, v2.text)
    }
    case 'trace':
      return keep(
        op.on
          ? "Trace on, in the workspace config file: from the next pass, each pass's timing goes to trace-YYYY-MM-DD.jsonl beside the decision log."
          : "Trace off, in the workspace config file: from the next pass, the decision log alone carries each pass's time.",
        { trace: op.on },
      )
  }
}

// retryText: what `retry <N>` answers once the driver ran the ledger's retryIssue (D-38).
export function retryText(issue: number, cleared: readonly string[]): string {
  if (cleared.length === 0) return `#${issue} has no exhausted actions: nothing to clear.`
  const shown = cleared.slice(0, 3).join(', ')
  const more = cleared.length > 3 ? ` and ${cleared.length - 3} more` : ''
  const noun = cleared.length === 1 ? 'action' : 'actions'
  return `Retry #${issue}: cleared ${cleared.length} exhausted ${noun} (${shown}${more}); its rules try again from the next pass.`
}

// --- status ----------------------------------------------------------------------------------

function ago(ms: Ms): string {
  if (ms < MIN) return `${Math.max(0, Math.round(ms / 1000))}s`
  if (ms < HOUR) return `${Math.floor(ms / MIN)}m`
  return `${Math.floor(ms / HOUR)}h ${Math.floor((ms % HOUR) / MIN)}m`
}

// directives: the control state in force, one short phrase each; an expired override is left out.
export function directives(control: Control, now: Ms): string[] {
  const out: string[] = []
  if (control.noNewWork) out.push('no new work')
  if (control.updateDue !== null) out.push(`update due since ${clock(control.updateDue.at, now)} (${control.updateDue.reason || 'no reason'})`)
  if (control.only.length > 0) out.push(`only ${tags(control.only)}`)
  if (control.priority.length > 0) out.push(`priority ${tags(control.priority)}`)
  if (control.serial) out.push('serial')
  if (control.paused.length > 0) out.push(`paused ${tags(control.paused)}`)
  if (control.skip.length > 0) out.push(`skip ${tags(control.skip)}`)
  const o = control.usageOverride
  if (o !== null && now < o.expiresAt) out.push(`usage override to ${o.untilPct}% until ${clock(o.expiresAt, now)}`)
  const dropped = [...new Set(control.dropped.map(d => d.issue))]
  if (dropped.length > 0) out.push(`dropped ${tags(dropped)}`)
  if (control.notes.length > 0) out.push(`${control.notes.length} ${control.notes.length === 1 ? 'note' : 'notes'}`)
  return out
}

// statusText: the `/factory status` answer: the last pass (PassSummary), its title, and the
// owner directives in force.
export function statusText(last: PassSummary | null, control: Control, now: Ms): string {
  const lines: string[] = []
  if (last === null) {
    lines.push('Factory loop: no pass yet.')
  } else {
    const noun = last.actions === 1 ? 'action' : 'actions'
    const layer = last.planner === undefined ? '' : `, planner ${last.planner}${last.planner === 'v1' && last.shadow === 'v2' ? ' with the v2 shadow' : ''}`
    lines.push(`Pass ${last.pass}, ${ago(now - last.at)} ago: ${last.mode}${layer}, tier ${last.tier}, ${last.actions} ${noun}, ${last.owner} for the owner.`)
    lines.push(last.title)
  }
  const d = directives(control, now)
  lines.push(d.length === 0 ? 'Directives: none.' : `Directives: ${d.join('; ')}.`)
  return lines.join('\n')
}

// --- the files -------------------------------------------------------------------------------

export function controlPath(loopDir: string): string {
  return `${loopDir}/control.json`
}

// The workspace config file (SPEC 4.1), where `mode` lives beside repo, shadowDevice and the rest.
export function configFilePath(configDir: string): string {
  return `${configDir}/factory-loop/config.json`
}

export type LoadedControl = { control: Control; error: string | null }

// loadControl: control.json's text as Control. A missing or empty file is no directive; a
// missing or malformed field takes its empty value (controlFrom). A file that is not a JSON
// object is an error, so a write never replaces directives the owner can still recover.
export function loadControl(text: string | null): LoadedControl {
  if (text === null || text.trim() === '') return { control: EMPTY_CONTROL, error: null }
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch {
    return { control: EMPTY_CONTROL, error: 'control.json is not valid JSON' }
  }
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) return { control: EMPTY_CONTROL, error: 'control.json is not a JSON object' }
  return { control: controlFrom(raw), error: null }
}

export function controlText(control: Control): string {
  return JSON.stringify(control, null, 2) + '\n'
}

// The workspace config file's keys an op writes.
export type SettingKey = 'mode' | 'trace' | 'planner'

// withSetting: the workspace config file's text with one key set (`mode`, `trace`, `planner`) and
// every other key kept, in place. A file that is not a JSON object is left alone: the owner's
// settings matter more than the op.
export function withSetting(text: string | null, key: SettingKey, value: Mode | Planner | boolean): { ok: true; text: string } | { ok: false; error: string } {
  let raw: unknown = {}
  if (text !== null && text.trim() !== '') {
    try {
      raw = JSON.parse(text)
    } catch {
      return { ok: false, error: 'the workspace config file is not valid JSON' }
    }
  }
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) return { ok: false, error: 'the workspace config file is not a JSON object' }
  return { ok: true, text: JSON.stringify({ ...(raw as Record<string, unknown>), [key]: value }, null, 2) + '\n' }
}

export function withMode(text: string | null, mode: Mode): { ok: true; text: string } | { ok: false; error: string } {
  return withSetting(text, 'mode', mode)
}

export type FileIo = Pick<ActIo, 'readFile' | 'writeFile'>

export async function readControl(io: FileIo, loopDir: string): Promise<LoadedControl> {
  return loadControl(await io.readFile(controlPath(loopDir)))
}

// writeControl: the whole file, every field (SPEC 4.3).
export async function writeControl(io: FileIo, loopDir: string, control: Control): Promise<void> {
  await io.writeFile(controlPath(loopDir), controlText(control))
}

// writeKey: `config set|unset` into the workspace file; changed says whether the file was written
export async function writeKey(io: FileIo, configDir: string, k: Setting, value: unknown): Promise<{ error: string | null; changed: boolean }> {
  const path = configFilePath(configDir)
  const next = editSetting(await io.readFile(path), k, value)
  if (!next.ok) return { error: next.error, changed: false }
  if (next.changed) await io.writeFile(path, next.text)
  return { error: null, changed: next.changed }
}

export async function writeSetting(io: FileIo, configDir: string, key: SettingKey, value: Mode | Planner | boolean): Promise<string | null> {
  const path = configFilePath(configDir)
  const next = withSetting(await io.readFile(path), key, value)
  if (!next.ok) return next.error
  await io.writeFile(path, next.text)
  return null
}

// --- the command and the tool ----------------------------------------------------------------

export type ControlPaths = { loopDir: string; configDir: string }

// The caller: `last` for status; agentId when the tool call came from inside an agent's loop; the
// planner in force (v1 when not said), and under planner v2 the issues parked now, as the last
// pass's records say (null: not known), so a resume of one that is not parked changes nothing.
export type OpFrom = { last?: PassSummary | null; agentId?: string; planner?: Planner; parked?: readonly number[] | null; view?: ConfigView | null }

// What `/factory` or the tool answers. ping: something changed (control.json, the mode, trace, or
// a retry to run), so the driver pings the loop and logs `logged` (SPEC 4.3). retryIssue: the
// driver runs the ledger's retryIssue and may answer retryText in place of `text`.
export type OpReply = {
  ok: boolean
  text: string
  op: Op | null
  control: Control | null
  ping: boolean
  retryIssue: number | null
  mode: Mode | null
  logged: string | null
}

const refused = (text: string, op: Op | null = null): OpReply => ({
  ok: false,
  text,
  op,
  control: null,
  ping: false,
  retryIssue: null,
  mode: null,
  logged: null,
})

// runOp: one op, start to finish: parse, read control.json, apply, write what changed. Only the
// main conversation changes directives: an agent the loop spawned may read the status, never
// set an op (SPEC 6.1: the loop's agents act on their own issue only).
export async function runOp(io: FileIo, paths: ControlPaths, input: string, now: Ms, from: OpFrom = {}): Promise<OpReply> {
  const planner = from.planner ?? 'v1'
  const parsed = parseOp(input, planner)
  if (!parsed.ok) return refused(parsed.error)
  // help reads and writes nothing, and an agent may ask for it as it may for the status
  if (parsed.op.op === 'help') return { ok: true, text: helpText(), op: null, control: null, ping: false, retryIssue: null, mode: null, logged: null }
  let op = parsed.op
  let aside = ''
  if (op.op === 'unpark') {
    const only = onlyParked(op, from.parked)
    if ('refused' in only) return refused(only.refused, op)
    op = only.op
    aside = only.aside
  }
  const viewOnly = op.op === 'status' || (op.op === 'config' && op.change === undefined)
  if (from.agentId !== undefined && !viewOnly) return refused('Not changed: only the main conversation sets owner directives.', op)
  let loaded: LoadedControl
  try {
    loaded = await readControl(io, paths.loopDir)
  } catch (err) {
    loaded = { control: EMPTY_CONTROL, error: `control.json could not be read (${String(err).slice(0, 200)})` }
  }
  if (viewOnly) {
    const text = op.op === 'status' ? statusText(from.last ?? null, loaded.control, now) : configText(from.view ?? null, loaded.control, now)
    const warning = loaded.error === null ? '' : `\n${loaded.error}: fix or remove it.`
    return { ok: true, text: text + warning, op, control: loaded.control, ping: false, retryIssue: null, mode: null, logged: null }
  }
  if (loaded.error !== null) return refused(`Not changed: ${loaded.error}; fix or remove it.`, op)
  const applied = applyOp(loaded.control, op, now, null, planner, from.view ?? null)
  if (op.op === 'config' && applied.effects.setting === undefined) return refused(applied.text, op)
  let text = applied.text
  let nothing = false
  try {
    const setting = applied.effects.setting
    if (setting !== undefined) {
      const wrote = await writeKey(io, paths.configDir, setting.k, setting.value)
      if (wrote.error !== null) return refused(`Not changed: ${wrote.error}.`, op)
      if (!wrote.changed) {
        text = `${op.change?.key ?? ''} ${op.change !== undefined && 'value' in op.change ? 'already has that value in the workspace config file' : 'is not set in the workspace config file'}: nothing changed.`
        nothing = true
      }
    }
    if (applied.changed) await writeControl(io, paths.loopDir, applied.control)
    for (const key of ['mode', 'trace', 'planner'] as const) {
      const value = applied.effects[key]
      const error = value === undefined ? null : await writeSetting(io, paths.configDir, key, value)
      if (error !== null) return refused(`Not changed: ${error}.`, op)
    }
  } catch (err) {
    return refused(`Not changed: the write failed (${String(err).slice(0, 200)}).`, op)
  }
  const ping = !nothing && (applied.changed || Object.keys(applied.effects).length > 0)
  return {
    ok: true,
    text: `${text}${aside}`,
    op,
    control: applied.control,
    ping,
    retryIssue: applied.effects.retryIssue ?? null,
    mode: applied.effects.mode ?? null,
    logged: ping ? formatOp(op) : null,
  }
}

// controlTool: the tool's handler: input { op: string }, then runOp.
export async function controlTool(io: FileIo, paths: ControlPaths, input: unknown, now: Ms, from: OpFrom = {}): Promise<OpReply> {
  const o = input !== null && typeof input === 'object' && !Array.isArray(input) ? (input as Record<string, unknown>) : null
  if (o === null || typeof o.op !== 'string') return refused(`Not changed: op is required, as text. Ops: ${allUsage()}`)
  return runOp(io, paths, o.op, now, from)
}

// `/factory`: immediate, so a directive typed while a long wake turn runs (a task may take
// hours) applies at once; the hook only reads and writes files.
export const FACTORY_COMMAND: CommandSpec = {
  name: 'factory',
  description:
    'Factory loop owner controls: pause, prioritise, retry or drop issues, set the mode; see /factory help',
  argumentHint: hintText(),
  immediate: true,
}

// mcp__factory-loop__control: the same ops for the model, when the owner says so in chat (the
// judge skill's Owner chat section). Behind ToolSearch, as the answer tool is, so it costs the
// prompt nothing between directives.
export const CONTROL_TOOL: ToolSpec = {
  name: 'control',
  description:
    "Set the factory loop's owner directives (control.json) when the owner asks, as `/factory <op>` does; " +
    'one op per call, answered in one line, and a malformed op changes nothing. Ops: ' +
    'status (what the loop is doing); config [set <key> <value>|unset <key>] (no argument: the settings it runs with, each with its source; config set <key> <value> saves one setting in the workspace config file and config unset <key> removes it, checked as the loader reads it, only when the owner asks); pause <N> / unpause <N> (no action at all on N; its claim still renews); ' +
    'skip <N> / noskip <N> (never claim N); priority <N...>|off (claim these first, in order); ' +
    'only <N...>|off (claim only these; a tracker stands for its open sub-issues); serial on|off (one issue in ' +
    'flight at a time); new on|off (off: no new claims, designs or implementations); override <pct> <hours>|off ' +
    '(run past the usage tiers up to pct for hours); resume <N...> ["note"]|<run id> (release what waits on you: ' +
    'under planner v2 unpark issues, the note going to their next step; under v1 a hold on an issue or a run); ' +
    "retry <N> (clear N's exhausted actions); update [<reason>]|off (drain, then restart this workspace for an " +
    'update); drop <N> (abandon N); note [<N>] <text> (an instruction the next agent prompts carry); ' +
    "mode off|observe|act (only when the owner asks for that mode); trace on|off (each pass's timing to a local " +
    'trace file, for troubleshooting); planner v1|v2 (the layer that plans and acts, only when the owner asks).',
  inputSchema: {
    type: 'object',
    properties: {
      op: { type: 'string', description: 'one op as /factory takes it, e.g. "only 522" or "new off"' },
    },
    required: ['op'],
    additionalProperties: false,
  },
  isDeferred: true,
}

files.hooks/exec.ts:
// The act half's contract (SPEC 6, 7, 8): what an executor is given and what it reports.
// register.ts builds ActIo over $ (the only module that holds $); every executor module
// (act-cli.ts, act-merge.ts, act-agents.ts, wake.ts) takes an ExecCtx and returns an Exec,
// and the driver records the result in the ledger (ledger.ts). Executors decide nothing:
// plan already did. They turn one action into commands, an agent spawn or a wake, and say
// what happened.
import type { Runtime } from './observe'
import type { Action, ActionKind, LedgerEntry, Ms, Outcome, State } from './types'
import type { V2Io } from './v2/types'

export type RunInit = { cwd?: string; stdin?: string; timeoutMs: number }
export type RunResult = { exitCode: number; stdout: string; stderr: string }

export type SpawnInput = {
  subagentType: string
  prompt: string
  description: string
  name?: string
  model?: string
  // the slot an agent step runs in (v2 SPEC 10.3): its prompt opens with the slot line
  cwd?: string
}

// ActIo: the engine calls the act half makes. Commands always go through ExecCtx.cmd, which
// adds the repo, the mode's environment (SPEC 11.1) and the decision log's command list.
export type ActIo = {
  now: () => Promise<Ms>
  run: (argv: string[], init: RunInit & { cwd: string; env: Record<string, string> }) => Promise<RunResult>
  // $.agent.spawn: resolves once the agent started; its answer arrives as its turn.complete
  spawnAgent: (input: SpawnInput) => Promise<{ agentId?: string; deny?: string }>
  // TaskStop through $.tool.call, for one of the loop's own agents only (SPEC 6.1, 13)
  stopAgent: (agentId: string) => Promise<{ stopped: boolean; error?: string }>
  // $.prompt.submit: a turn of its own once the session is idle (SPEC 8.1)
  submit: (text: string) => Promise<void>
  // $.command.run rename (SPEC 9.1)
  rename: (title: string) => Promise<void>
  // $.session.usage().rateLimits as percentages, for the pre-check before a token-spending
  // action (SPEC 10.7); null where the session has no reading
  usage: () => Promise<{ fiveHour: number | null; sevenDay: number | null }>
  readFile: (path: string) => Promise<string | null>
  writeFile: (path: string, text: string) => Promise<void>
  // v2's live records and the driver's ping (v2 SPEC 3.3, 4.6), for the transition executor; absent
  // where the driver keeps no records (a test's fake, a hook outside act mode)
  v2?: V2Io
}

export type ExecCtx = {
  io: ActIo
  rt: Runtime
  // the state this pass planned from
  state: State
  // this attempt's ledger entry, already running with its attempt counted
  entry: LedgerEntry
  // runs a command from the main checkout (or init.cwd) with the repo and mode environment;
  // never through a shell unless the argv itself is `sh -c` for a detached launch
  cmd: (argv: string[], init: RunInit) => Promise<RunResult>
  // logs one factory event through callum-flow-event (SPEC 7.4)
  event: (state: string, fields: EventFields) => Promise<void>
  // a fresh wake id, unique across restarts (SPEC 8.1 `id=`)
  wakeId: () => string
}

export type EventFields = {
  issue?: number | null
  run?: string | null
  branch?: string | null
  pr?: number | null
  head?: string | null
  note?: string | null
}

// An extra done entry an executor records beside its own: a guard FAIL that `merge` printed
// is a guard outcome for its PR and head, so rule M2 handles it next pass (SPEC 5.5), while the
// merge itself counts as a failed attempt that plan retries once the guard is clean.
export type ExtraEntry = {
  key: string
  kind: ActionKind
  issue: number | null
  run: string | null
  pr: number | null
  head: string | null
  outcome: Outcome
}

// What an executor reports:
// - done / failed: finished within the pass, with the outcome plan reads next pass;
// - running: continues past the pass. An agent ends in its turn.complete (agentId), a wake
//   with its answer (wakeId), a detached respond by the run moving (rule P3a);
// - skipped: a pre-check refused it (a usage tier that forbids its class, a rail), so no
//   attempt is counted and the entry is dropped.
// noRetry: a usage error (exit 2) is a loop bug, never retried (SPEC 10.1).
// rateLimited: stderr showed a GitHub rate limit; the driver sets githubBackoffUntil (SPEC 10.2).
export type Exec =
  | { status: 'done'; outcome?: Outcome; summary: string; extra?: ExtraEntry[] }
  | { status: 'failed'; outcome?: Outcome; summary: string; noRetry?: boolean; rateLimited?: boolean; extra?: ExtraEntry[] }
  | { status: 'running'; agentId?: string; wakeId?: string; outcome?: Outcome; summary: string }
  | { status: 'skipped'; summary: string }

export type Executor<A extends Action = Action> = (ctx: ExecCtx, action: A) => Promise<Exec>

// One agent's answer, as its turn.complete gives it.
export type AgentAnswer = { agentId: string; answer: string; reason: 'answer' | 'aborted' | 'refusal' | 'error' }

// GitHub's rate-limit signatures in a command's stderr (SPEC 10.2).
export function rateLimited(stderr: string): boolean {
  return /API rate limit exceeded|secondary rate limit|HTTP (403|429)[^\n]*rate.?limit/i.test(stderr)
}

// The first 2 000 characters of a failed command's stderr, for the outcome (SPEC 10.1).
export function detailOf(r: RunResult): string {
  return (r.stderr.trim() || r.stdout.trim()).slice(0, 2000)
}

// Where an agent's raw answer is kept (act-agents.ts writes it), so a judge(report) or
// judge(handoff) wake points the model at the file instead of pasting the report (SPEC 7.2).
export function answerPath(loopDir: string, key: string): string {
  return `${loopDir}/answers/${key.replace(/[^A-Za-z0-9._-]+/g, '_')}.txt`
}

// The answer script under the plugin's root (#561): agents record their answer with it while the
// registered answer tools cannot be reached (config answerChannel `script`, a workaround).
export const ANSWER_SCRIPT = 'bin/factory-answer'

// Where an agent records its answer with the answer script: a path unique to the ledger entry and
// its attempt (the attempt's number and start), so the loop reads only what this attempt's agent
// wrote, never a stale or another agent's file. The job file beside it (contract.mjs jobPathOf)
// is the loop's; the name has contract.mjs's ANSWER_NAME shape.
export function scriptAnswerPath(loopDir: string, entry: Pick<LedgerEntry, 'key' | 'attempts' | 'startedAt'>): string {
  const key = entry.key.replace(/[^A-Za-z0-9._-]+/g, '_')
  return `${loopDir}/answers/${key}.a${entry.attempts}.${Math.trunc(entry.startedAt)}.answer.json`
}

// The detached respond's log (act-merge.ts writes it; task(respond-stuck) names it): one per
// ledger key and attempt, so a retry or a later gate of the same run never overwrites it.
export function respondLogPath(loopDir: string, key: string, attempt: number): string {
  return `${loopDir}/respond/${key.replace(/[^A-Za-z0-9._-]+/g, '_')}-${attempt}.log`
}

// The last line of every wake prompt (skills/judge/SKILL.md answers by it).
export const WAKE_POINTER = 'Answer with the factory-loop:judge skill.'

// The loop dir's files that only grow (SPEC 11.6): spawn records, saved answers, respond logs,
// recorded states and the decision logs, kept as long as the ledger keeps entries (7 days).
export const LOOP_FILES_KEEP_DAYS = 7

// pruneArgvs: the commands that delete those files once older than `days`, then the day
// directories of states/ left empty. Everything else in the loop dir (the act lock, control.json,
// the event sink) is never touched.
export function pruneArgvs(loopDir: string, days: number): string[][] {
  const under = (dir: string) => ['-path', `${loopDir}/${dir}/*`]
  return [
    ['find', loopDir, '-mindepth', '1', '-type', 'f', '(', ...under('spawns'), '-o', ...under('answers'), '-o', ...under('respond'), '-o', ...under('states'), '-o', '-name', 'decisions-*.jsonl', ')', '-mmin', `+${days * 24 * 60}`, '-delete'],
    ['find', `${loopDir}/states`, '-mindepth', '1', '-type', 'd', '-empty', '-delete'],
  ]
}

files.hooks/ledger.ts:
// The ledger (SPEC 7): every action the loop started, under its idempotency key, with its
// status, attempts and outcome, so plan sees what is running or done and re-planning an
// unchanged state yields nothing new. Pure functions over LedgerEntry[] (no engine calls, no
// clock: the time comes in as `now`): the driver starts and finishes an entry around each
// executor, marks what a reload or the agent list proves (SPEC 7.5, 10.4), and keeps the ledger
// in $.store through the thin StoreIo below. The other half, the ledger rebuilt from the event
// log after a lost store, is derive.ts's deriveLedger. Every function returns a new array and
// replaces only the entries it changes, so changedEntries() can tell the driver what moved.
import { ACTION_KINDS, DEFAULT_CONFIG } from './config'
import { loopEventArgs } from './derive'
import type { Exec, ExtraEntry } from './exec'
import { turnEnded } from './plan'
import type {
  Action,
  ActionClass,
  ActionKind,
  AgentStatus,
  AgentType,
  Config,
  LedgerEntry,
  LedgerStatus,
  Ms,
  Outcome,
} from './types'
import { AGENT_STEPS } from './v2/types'

const DAY = 86_400_000
// Entries are kept 7 days after they end; running entries are never pruned (SPEC 7.1).
export const KEEP_MS = 7 * DAY
// The store holds 4 MiB of JSON for all of the plugin's keys together. The ledger keeps to three
// quarters of it, so the driver's few small keys always fit; a busy week needs about half of
// this, and dev-system's real weeks far less (SPEC 7.1).
export const LEDGER_MAX_BYTES = 3 * 1024 * 1024
// An executor's summary is a few words for the decision log; a longer one is cut.
const SUMMARY_MAX = 300

const WAKES: readonly ActionKind[] = ['judge', 'task', 'tell']
// Agents and wakes log a `loop` event (owner notices and rate-cap notices are tells); CLI work
// logs its own events and gets none (D-09, SPEC 7.4). A v2 agent step is an agent entry: its
// events are for the trail, and a lost store never rebuilds it (derive.ts entryFromLoop).
const LOOP_KINDS: readonly ActionKind[] = ['spawn', 'delegate', 'judge', 'task', 'tell', 'agent-step']
const STATUSES: readonly LedgerStatus[] = ['running', 'done', 'failed', 'timed-out', 'lost']
const CLASSES: readonly ActionClass[] = ['free', 'owner', 'drive', 'develop', 'start']
const AGENT_TYPES: readonly AgentType[] = ['designer', 'implementer', 'adjudicator', 'fixer']

// --- one attempt: start and finish -------------------------------------------------------

export type Started = { ledger: LedgerEntry[]; entry: LedgerEntry; prev: LedgerEntry | null }

// start: the entry for this attempt (SPEC 5.1: a retry keeps the key and adds an attempt). A
// new key starts at attempt 1; a key that failed, timed out or was lost runs again as attempt
// n + 1, its last outcome, agent and wake cleared. A done key started again (only the title,
// which plan compares rather than keys) starts its count over: success resets it. The subject's
// fields come from the action. prev is the entry as it stood, so a pre-check that refuses the
// attempt can put it back (finish with status skipped). A wake records the session submitting it.
// A v2 transition carries its facts (the row, the state and step it leaves, the event, the via
// code) from its start, marked not yet stored: a crash after the records store took the seq but
// before the entry was saved done leaves a lost entry that still names them (v2 SPEC 3.3), and
// the executor's done outcome replaces them.
export function start(ledger: readonly LedgerEntry[], action: Action, now: Ms, session = ''): Started {
  const prev = ledger.find(e => e.key === action.key) ?? null
  const entry: LedgerEntry = {
    key: action.key,
    kind: action.kind,
    class: action.class,
    rule: action.rule,
    issue: action.issue,
    run: 'run' in action && typeof action.run === 'string' ? action.run : null,
    pr: 'pr' in action && typeof action.pr === 'number' ? action.pr : null,
    head: 'head' in action && typeof action.head === 'string' ? action.head : null,
    status: 'running',
    attempts: prev === null || prev.status === 'done' ? 1 : prev.attempts + 1,
    startedAt: now,
    endedAt: null,
  }
  // a delegate spawns the implementer, so its entry is that agent's (plan reads it so)
  if (action.kind === 'spawn') entry.agent = action.agent
  else if (action.kind === 'delegate') entry.agent = 'implementer'
  else if (action.kind === 'agent-step') entry.step = action.step
  else if (action.kind === 'transition') {
    entry.outcome = {
      kind: 'transition',
      row: action.row,
      event: action.event,
      cause: action.cause ?? null,
      from: action.fromState ?? null,
      to: action.next.state,
      step: action.fromStep ?? null,
      stored: false,
      via: action.via ?? action.row,
    }
  }
  if (action.maxAttempts !== undefined) entry.maxAttempts = action.maxAttempts
  if (action.kind === 'judge' || action.kind === 'task' || action.kind === 'tell') {
    entry.wake = action.wake
    if (session !== '') entry.session = session
  }
  return { ledger: put(ledger, entry), entry, prev }
}

// An end that arrives outside the pass, or a transition the driver applies itself: an agent's
// turn.complete, a wake's answer, reminder or timeout, a tell delivered.
export type Completion = {
  status: LedgerStatus
  outcome?: Outcome
  summary?: string
  agentId?: string
  wakeId?: string
  turnId?: string
  reminded?: boolean
  // the count to keep: an orphaned wake gives its attempt back (wake.ts orphanedWakes)
  attempts?: number
}

export type FinishOptions = {
  // the settings in force: a usage error (noRetry) uses up exactly its kind's attempts
  config?: Config
  // start's prev: a skipped attempt puts the entry back as it stood (null: it was new)
  prev?: LedgerEntry | null
}

// finish: apply an executor's Exec or a completion to the entry under key: its status, outcome,
// agent or wake id and summary, and endedAt (none while it runs on). A finished attempt keeps
// the last outcome when the result carries none (a respond's launch record, say).
// - skipped: no attempt is counted: the entry goes back to prev, or is dropped when it was new.
// - failed with noRetry (exit 2, a loop bug): the attempts are used up, so plan never retries
//   it and tells the owner instead (SPEC 10.1).
// - extra: each ExtraEntry is recorded as a done entry of its own (a guard FAIL that `merge`
//   printed is a guard outcome, so rule M2 handles it next pass, SPEC 5.5).
// - a guard, a refused fast-forward, or an update-checkout that found exactly what the one before
//   it found replaces that one (foldRecheck).
// - a stop-agent of rule A1 that ended, stopped or not, marks the agent it stopped timed-out
//   (SPEC A1; SPEC 13: an agent TaskStop could not stop is left running, marked timed-out).
// It applies whatever the entry's status; a key the ledger no longer holds (pruned, say) is left
// alone. An agent's answer is matched to its entry by agentId, which a retry clears, so the
// answer of an agent a retry replaced finds no entry.
export function finish(
  ledger: readonly LedgerEntry[],
  key: string,
  result: Exec | Completion,
  now: Ms,
  opts: FinishOptions = {},
): LedgerEntry[] {
  const current = ledger.find(e => e.key === key)
  if (current === undefined) return [...ledger]
  if (result.status === 'skipped') return unstart(ledger, current, opts.prev, now, result.summary)
  const next: LedgerEntry = { ...current, status: result.status, endedAt: result.status === 'running' ? null : now }
  if (result.outcome !== undefined) next.outcome = result.outcome
  if (result.summary !== undefined) next.summary = result.summary.slice(0, SUMMARY_MAX)
  if ('agentId' in result && result.agentId !== undefined) next.agentId = result.agentId
  if ('wakeId' in result && result.wakeId !== undefined) next.wakeId = result.wakeId
  if ('turnId' in result && result.turnId !== undefined) next.turnId = result.turnId
  if ('reminded' in result && result.reminded !== undefined) next.reminded = result.reminded
  if ('attempts' in result && result.attempts !== undefined) next.attempts = result.attempts
  if (result.status === 'failed' && 'noRetry' in result && result.noRetry === true) {
    next.attempts = Math.max(next.attempts, next.maxAttempts ?? maxAttemptsOf(opts.config ?? DEFAULT_CONFIG, attemptsKindOf(next)))
  }
  let out = foldRecheck(put(ledger, next), next)
  for (const extra of 'extra' in result ? (result.extra ?? []) : []) {
    const x = extraEntry(extra, next, now)
    out = foldRecheck(put(out, x), x)
  }
  if (next.kind === 'stop-agent' && next.rule === 'A1' && next.status !== 'running' && key.startsWith('stop:')) {
    const agentId = key.slice('stop:'.length)
    const why = next.status === 'done' ? 'timed out: stopped' : 'timed out: the stop failed, the agent may still run'
    out = out.map(e => (e.status === 'running' && e.agentId === agentId && !isWake(e) ? ended(e, 'timed-out', now, why) : e))
  }
  return out
}

// unstart: undo start for an attempt a pre-check refused. Without prev (the driver did not keep
// it) a retried entry keeps its count and waits a backoff: failed, ended now.
function unstart(ledger: readonly LedgerEntry[], current: LedgerEntry, prev: LedgerEntry | null | undefined, now: Ms, why: string) {
  if (prev !== undefined && prev !== null) return put(ledger, prev)
  if (prev === null || current.attempts <= 1) return ledger.filter(e => e.key !== current.key)
  return put(ledger, ended({ ...current, attempts: current.attempts - 1 }, 'failed', now, `skipped: ${why}`))
}

// foldRecheck: a done guard whose outcome is exactly that of the guard before it on the same PR
// and head replaces that entry, and so does a refused fast-forward after a refused one, and an
// update-checkout after one that said the same. A PR held on one failure is re-checked every
// guardTtlMs (#550), a lagging dirty worktree is tried again each time (#551), and the main
// checkout is updated every checkoutEveryMs (#555); kept one entry per re-check, a week fills
// the ledger toward fit() (SPEC 7.1). Plan numbers the next guard past the highest key
// (guardSeq), so a dropped number is never reused, and reads only the newest refused
// fast-forward and the newest update-checkout.
function foldRecheck(ledger: LedgerEntry[], e: LedgerEntry): LedgerEntry[] {
  const refused = (o: LedgerEntry) => o.outcome?.kind === 'fast-forward' && o.outcome.result === 'refused'
  if (e.status !== 'done' || !(e.outcome?.kind === 'guard' || e.outcome?.kind === 'update-checkout' || refused(e))) return ledger
  let before: LedgerEntry | undefined
  for (const o of ledger) {
    if (o.kind !== e.kind || o.key === e.key || o.pr !== e.pr || o.head !== e.head || o.startedAt > e.startedAt) continue
    if (before === undefined || o.startedAt >= before.startedAt) before = o
  }
  if (before?.status !== 'done' || JSON.stringify(before.outcome) !== JSON.stringify(e.outcome)) return ledger
  return ledger.filter(o => o !== before)
}

// extraEntry: an ExtraEntry as the done entry it records, under the rule of the action that
// printed it, started when that action started.
function extraEntry(x: ExtraEntry, parent: LedgerEntry, now: Ms): LedgerEntry {
  return {
    key: x.key,
    kind: x.kind,
    class: classOf(x.kind, parent.class),
    rule: parent.rule,
    issue: x.issue,
    run: x.run,
    pr: x.pr,
    head: x.head,
    status: 'done',
    attempts: 1,
    startedAt: parent.startedAt,
    endedAt: now,
    outcome: x.outcome,
  }
}

// classOf: an action kind's class (SPEC 6.1); a spawn's depends on its agent and a v2 agent
// step's on its step, so each is the caller's.
function classOf(kind: ActionKind, spawn: ActionClass): ActionClass {
  if (kind === 'claim') return 'start'
  if (kind === 'delegate') return 'develop'
  if (kind === 'respond' || kind === 'env-retry' || kind === 'judge' || kind === 'task') return 'drive'
  if (kind === 'tell') return 'owner'
  return kind === 'spawn' || kind === 'agent-step' ? spawn : 'free'
}

// --- what a reload and the agent list prove (SPEC 3.3, 7.5, 10.4) -------------------------

// onLoad: on module load, every running CLI entry (no agent id, not a wake) is lost: its process
// died with the old session or module (SPEC 7.5 step 1). Plan then re-derives what to do from
// the state. Agents wait for the agent list (reconcileAgents); wakes for their answer or timeout.
export function onLoad(ledger: readonly LedgerEntry[], now: Ms): LedgerEntry[] {
  return ledger.map(e =>
    e.status === 'running' && e.agentId === undefined && !isWake(e) ? ended(e, 'lost', now, 'lost: the loop reloaded mid-action') : e,
  )
}

// reconcileAgents: a running agent entry against the session's agent list. An id the list
// lacks is lost (SPEC 3.3, 7.5); one listed failed or killed is failed (SPEC 10.4); one listed
// completed or idle (its turn ended, plan.ts turnEnded, #560) while its entry still runs ended
// with no answer, so it is lost. The list must be a successful read: an empty list marks every
// running agent lost.
export function reconcileAgents(
  ledger: readonly LedgerEntry[],
  agents: readonly { id: string; status: AgentStatus }[],
  now: Ms,
): LedgerEntry[] {
  const status = new Map(agents.map(a => [a.id, a.status]))
  return ledger.map(e => {
    if (e.status !== 'running' || e.agentId === undefined || isWake(e)) return e
    const seen = status.get(e.agentId)
    if (seen === undefined) return ended(e, 'lost', now, 'lost: gone from the agent list')
    if (seen === 'failed' || seen === 'killed') return ended(e, 'failed', now, `agent ${seen}`)
    if (turnEnded(seen)) return ended(e, 'lost', now, `lost: ${seen} with no answer`)
    return e
  })
}

// --- keeping it small -------------------------------------------------------------------

// prune: drop entries that ended more than KEEP_MS ago; a running entry stays whatever its age
// (SPEC 7.1). An entry with no end time ages from its start.
export function prune(ledger: readonly LedgerEntry[], now: Ms): LedgerEntry[] {
  return ledger.filter(e => e.status === 'running' || now - endOf(e) <= KEEP_MS)
}

// fit: the ledger within maxBytes of JSON, the entries that ended longest ago dropped first,
// never a running one. A safety valve only: a busy week is well below LEDGER_MAX_BYTES, and a store
// over its limit would refuse the whole save, losing every change since the last one.
export function fit(ledger: readonly LedgerEntry[], maxBytes = LEDGER_MAX_BYTES): LedgerEntry[] {
  const sized = ledger.map(entry => ({ entry, size: bytes(JSON.stringify(entry)) + 1 }))
  // the envelope: { v, savedAt, entries }
  let total = sized.reduce((sum, s) => sum + s.size, 64)
  if (total <= maxBytes) return [...ledger]
  const drop = new Set<LedgerEntry>()
  const oldest = sized.filter(s => s.entry.status !== 'running').sort((a, b) => endOf(a.entry) - endOf(b.entry))
  for (const s of oldest) {
    if (total <= maxBytes) break
    drop.add(s.entry)
    total -= s.size
  }
  return ledger.filter(e => !drop.has(e))
}

// --- the store and the derived ledger (SPEC 7.1, 7.5) -------------------------------------

export type LedgerSource = 'store' | 'events' | 'none'
export type Chosen = { ledger: LedgerEntry[]; source: LedgerSource }

// choose: the store wins whenever it holds a ledger. A missing or empty store (a new device, a
// wiped config) falls back to the ledger derive.ts rebuilt from the event log; null there means
// the log could not be read. The source goes in the decision log.
export function choose(
  stored: readonly LedgerEntry[] | null | undefined,
  derived: readonly LedgerEntry[] | null | undefined,
): Chosen {
  if (stored !== null && stored !== undefined && stored.length > 0) return { ledger: [...stored], source: 'store' }
  if (derived !== null && derived !== undefined && derived.length > 0) return { ledger: [...derived], source: 'events' }
  return { ledger: [], source: 'none' }
}

// $.store, or anything shaped like it (a test's fake).
export type StoreIo = {
  get: (key: string) => Promise<unknown>
  set: (key: string, value: unknown) => Promise<void>
}

export type StoredLedger = { v: 1; savedAt: Ms; entries: LedgerEntry[] }

export function storeKey(repo: string): string {
  return `ledger:${repo}`
}

// toStored: what save writes: the ledger pruned and within its size budget.
export function toStored(ledger: readonly LedgerEntry[], now: Ms): StoredLedger {
  return { v: 1, savedAt: now, entries: fit(prune(ledger, now)) }
}

// fromStored: the entries of a stored ledger, or null when the value is none (another version,
// or not a ledger at all). An entry missing a field plan relies on is dropped, and of two
// entries under one key the later start wins, as in plan.
export function fromStored(raw: unknown): LedgerEntry[] | null {
  const o = record(raw)
  if (o === null || o.v !== 1 || !Array.isArray(o.entries)) return null
  const byKey = new Map<string, LedgerEntry>()
  for (const item of o.entries) {
    const entry = entryOf(item)
    if (entry === null) continue
    const seen = byKey.get(entry.key)
    if (seen === undefined || entry.startedAt >= seen.startedAt) byKey.set(entry.key, entry)
  }
  return [...byKey.values()]
}

// load: the ledger saved for this repo, or null when the store holds none. A failing store read
// throws: replacing a ledger the loop could not read would lose its holds.
export async function load(store: StoreIo, repo: string): Promise<LedgerEntry[] | null> {
  return fromStored(await store.get(storeKey(repo)))
}

// save: prune, keep within the budget, write; returns the entries written.
export async function save(store: StoreIo, repo: string, ledger: readonly LedgerEntry[], now: Ms): Promise<LedgerEntry[]> {
  const stored = toStored(ledger, now)
  await store.set(storeKey(repo), stored)
  return stored.entries
}

// --- /factory retry (D-38) -------------------------------------------------------------------

export type Retried = { ledger: LedgerEntry[]; cleared: string[]; notices: string[] }

// retryIssue: `/factory retry <N>` clears the attempts of the issue's entries that ran out of
// them, so their rules try again (D-38, SPEC 7.1). Exhausted is plan's own rule (gate in
// plan.ts): failed, timed-out or lost with attempts at the kind's maximum. Each such entry stays
// with its count at 0 rather than going: a rule may need the failed entry to act at all (D4b
// re-delegates from the last delegate entry), and the next attempt counts from 1. The owner
// notice each one raised (agent-failed, task-timeout, update-behind) goes, unless it is still
// open, so a retry that runs out again is told again.
export function retryIssue(ledger: readonly LedgerEntry[], issue: number, config: Config): Retried {
  // an env-retry stays spent: the owner's resume, not a retry, allows the next rerun (#537)
  const spent = ledger.filter(e => e.issue === issue && e.kind !== 'env-retry' && exhausted(e, config))
  const cleared = spent.map(e => e.key)
  const raised = new Set(spent.flatMap(noticesOf))
  const notices = ledger.filter(e => raised.has(e.key) && e.status !== 'running').map(e => e.key)
  const out = ledger
    .filter(e => !notices.includes(e.key))
    .map(e => (cleared.includes(e.key) ? { ...e, attempts: 0, summary: 'attempts cleared by the owner (/factory retry)' } : e))
  return { ledger: out, cleared, notices }
}

function noticesOf(entry: LedgerEntry): string[] {
  const out = [`tell:agent-failed:${entry.key}`, `tell:task-timeout:${entry.key}`]
  if (entry.kind === 'update-behind') out.push(`tell:${entry.key}`)
  return out
}

// exhausted: plan's rule exactly (gate in plan.ts, foundation.ts): a failed, timed-out or lost
// entry whose attempts reached its key's own cap, else the maximum for its kind or agent.
// Heartbeat and sweep never are: they retry at their cadence (plan.ts cadenceOf, SPEC 6.1).
export function exhausted(entry: LedgerEntry, config: Config): boolean {
  if (entry.status === 'running' || entry.status === 'done') return false
  if (entry.kind === 'heartbeat' || entry.kind === 'sweep') return false
  return entry.attempts >= (entry.maxAttempts ?? maxAttemptsOf(config, attemptsKindOf(entry)))
}

// attemptsKindOf: what plan counts an entry's attempts against: a spawn's agent, the implementer
// for a delegate, otherwise its kind.
export function attemptsKindOf(entry: LedgerEntry): ActionKind | AgentType {
  if (entry.kind === 'spawn') return entry.agent ?? entry.kind
  if (entry.kind === 'delegate') return 'implementer'
  return entry.kind
}

// maxAttemptsOf: plan's maxAttempts: update-behind runs updateBehindRetries + 1 times (rule
// M2b); anything else its config.maxAttempts entry, 3 when it has none.
export function maxAttemptsOf(config: Config, kind: ActionKind | AgentType): number {
  if (kind === 'update-behind') return config.updateBehindRetries + 1
  // once per owner resume, whatever the config says (#537)
  if (kind === 'env-retry') return 1
  return config.maxAttempts[kind] ?? 3
}

// --- the loop's own events (D-09, SPEC 7.4) -------------------------------------------------

// loopEvent: the callum-flow-event argv for a `loop` event about this entry, for agent and wake
// entries (owner notices and rate-cap notices are tells) at their start and end; null for CLI
// kinds, which log their own events.
export function loopEvent(entry: LedgerEntry): string[] | null {
  return LOOP_KINDS.includes(entry.kind) ? ['callum-flow-event', ...loopEventArgs(entry)] : null
}

// changedEntries: the entries `after` holds that `before` did not hold as they are: new or
// changed by a transition, for the driver's loop events.
export function changedEntries(before: readonly LedgerEntry[], after: readonly LedgerEntry[]): LedgerEntry[] {
  const had = new Set(before)
  return after.filter(e => !had.has(e))
}

// --- helpers ---------------------------------------------------------------------------------

function isWake(entry: LedgerEntry): boolean {
  return WAKES.includes(entry.kind) || entry.wakeId !== undefined
}

function ended(entry: LedgerEntry, status: LedgerStatus, now: Ms, summary: string): LedgerEntry {
  return { ...entry, status, endedAt: now, summary }
}

function endOf(entry: LedgerEntry): Ms {
  return entry.endedAt ?? entry.startedAt
}

// put: the ledger with entry under its key, in place of the one there, else at the end.
function put(ledger: readonly LedgerEntry[], entry: LedgerEntry): LedgerEntry[] {
  const i = ledger.findIndex(e => e.key === entry.key)
  if (i < 0) return [...ledger, entry]
  const out = [...ledger]
  out[i] = entry
  return out
}

// bytes: an upper bound of a string's UTF-8 size (a non-ASCII UTF-16 unit counts 3 bytes).
function bytes(text: string): number {
  let extra = 0
  for (let i = 0; i < text.length; i++) if (text.charCodeAt(i) > 0x7f) extra += 2
  return text.length + extra
}

function record(v: unknown): Record<string, unknown> | null {
  return v !== null && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : null
}

const isNumOrNull = (v: unknown): v is number | null => v === null || (typeof v === 'number' && Number.isFinite(v))
const isStrOrNull = (v: unknown): v is string | null => v === null || typeof v === 'string'

// entryOf: one stored entry, checked field by field. The ledger is the loop's own writing, so an
// outcome is taken as written once it names its kind.
function entryOf(raw: unknown): LedgerEntry | null {
  const o = record(raw)
  if (o === null) return null
  const { key, rule, issue, run, pr, head, attempts, startedAt, endedAt } = o
  const kind = ACTION_KINDS.find(k => k === o.kind)
  const klass = CLASSES.find(c => c === o.class)
  const status = STATUSES.find(s => s === o.status)
  if (typeof key !== 'string' || key === '' || typeof rule !== 'string') return null
  if (kind === undefined || klass === undefined || status === undefined) return null
  if (typeof attempts !== 'number' || !Number.isInteger(attempts) || attempts < 0) return null
  if (typeof startedAt !== 'number' || !Number.isFinite(startedAt) || !isNumOrNull(endedAt)) return null
  if (!isNumOrNull(issue) || !isNumOrNull(pr) || !isStrOrNull(run) || !isStrOrNull(head)) return null
  const entry: LedgerEntry = { key, kind, class: klass, rule, issue, run, pr, head, status, attempts, startedAt, endedAt }
  const agent = AGENT_TYPES.find(a => a === o.agent)
  if (agent !== undefined) entry.agent = agent
  if (typeof o.wake === 'string') entry.wake = o.wake
  if (typeof o.agentId === 'string') entry.agentId = o.agentId
  if (typeof o.wakeId === 'string') entry.wakeId = o.wakeId
  if (typeof o.turnId === 'string') entry.turnId = o.turnId
  if (typeof o.reminded === 'boolean') entry.reminded = o.reminded
  if (typeof o.session === 'string') entry.session = o.session
  if (typeof o.summary === 'string') entry.summary = o.summary
  const step = AGENT_STEPS.find(s => s === o.step)
  if (step !== undefined) entry.step = step
  if (typeof o.maxAttempts === 'number' && Number.isInteger(o.maxAttempts) && o.maxAttempts >= 1) entry.maxAttempts = o.maxAttempts
  const outcome = record(o.outcome)
  if (outcome !== null && typeof outcome.kind === 'string') entry.outcome = outcome as Outcome
  return entry
}

