// buildState: what observe read, assembled into the State plan takes (SPEC 3.1, 3.2). Pure,
// so the pass driver, the shadow run and the replay harness build state the same way.
import type { Facts } from './derive'
import { runsFromEvents } from './derive'
import type { Factory, IssueFacts, PipelineRun } from './parse'
import { issueFromBranch } from './plan'
import type {
  AgentView,
  Brief,
  Checkout,
  Control,
  IssueView,
  LedgerEntry,
  Milestone,
  ReleaseInfo,
  Pool,
  RunView,
  Source,
  SourceName,
  State,
  Usage,
} from './types'

export type GithubIssue = { facts: IssueFacts | null; trusted: boolean; brief: Brief | null }

export type Observed = {
  now: number
  repo: string
  device: string
  loadedAt: number
  sources: Record<SourceName, Source>
  factory: Factory | null
  facts: Facts | null
  // runSource local: the pipeline watcher's runs (runsFromWatch); null for runSource events
  // (built here from the event log)
  runs: RunView[] | null
  queue: number[] | null
  github: Map<number, GithubIssue>
  // each tracker's open sub-issues, direct ones only, from its timeline (parseSubIssues): read
  // for trackers named in control.only and nested trackers among their sub-issues (D-35)
  timelines: Map<number, number[]>
  usage: Usage | null
  pool: Pool | null
  agents: AgentView[]
  milestone: Milestone | null
  release?: ReleaseInfo | null
  ledger: LedgerEntry[]
  control: Control
  lastTitle: string | null
  lastTitleAt: number | null
  githubBackoffUntil: number | null
  // config trackerTitle: a title matching it marks a tracker
  trackerTitle: string
  // the main checkout (#544); the replay harness leaves it out: not read
  checkout?: Checkout | null
}

const UNAVAILABLE: Usage = { fiveHour: null, sevenDay: null, fiveHourResetsAt: null, sevenDayResetsAt: null, unavailable: true }

// How deep trackers nest under a tracker named in `only` before observe stops reading them.
export const TRACKER_DEPTH = 3

// subIssuesOf: a tracker's open sub-issues, those of nested trackers included, ascending; null
// when its timeline was not read. Nesting is followed TRACKER_DEPTH levels deep, and a loop in
// the links is cut.
export function subIssuesOf(n: number, timelines: Map<number, number[]>, depth = TRACKER_DEPTH, seen: number[] = []): number[] | null {
  const direct = timelines.get(n)
  if (direct === undefined) return null
  const all = new Set<number>()
  for (const sub of direct) {
    if (sub === n || seen.includes(sub)) continue
    all.add(sub)
    const nested = depth > 1 ? subIssuesOf(sub, timelines, depth - 1, [...seen, n]) : null
    for (const m of nested ?? []) if (m !== n) all.add(m)
  }
  return [...all].sort((a, b) => a - b)
}

// --- runSource local: pipeline-watch.sh --once (SPEC 3.3, 3.4) -----------------------------

// A watcher line with when observe first saw that run in that state, at that head and step.
export type SeenRun = PipelineRun & { since: number }

// seenRuns: this poll's lines, each keeping the `since` of the same run in the same state, head
// and step in the last poll, else seen now. A run the poll no longer prints is dropped, so one
// that comes back starts over. Without a step (the watcher could not read one), `since` is what
// tells two parks on one head apart (plan's gateOf), so it must hold across passes.
export function seenRuns(prev: readonly SeenRun[], lines: readonly PipelineRun[], now: number): SeenRun[] {
  return lines.map(line => {
    const same = prev.find(
      p => p.branch === line.branch && p.run === line.run && p.state === line.state && p.head === line.head && p.step === line.step,
    )
    return { ...line, since: same?.since ?? now }
  })
}

// runsFromWatch: the watcher's runs as plan reads them: the issue from the branch name (issue-<N>),
// and review rounds, verdicts and supersession from the event log, as runsFromEvents does. A run
// with no known id has no facts. Sorted by issue, then branch, so the digest does not move with
// the watcher's order.
export function runsFromWatch(seen: readonly SeenRun[], facts: Facts | null): RunView[] {
  return seen
    .map(s => {
      const known = s.run !== 'unknown' && facts !== null
      return {
        branch: s.branch,
        issue: issueFromBranch(s.branch),
        run: s.run,
        state: s.state,
        head: s.head,
        step: s.step,
        detail: s.detail,
        pr: s.pr,
        since: s.since,
        reviewFixRounds: known ? (facts.reviewFixes.get(s.run) ?? 0) : 0,
        verdicts: known ? (facts.verdicts.get(s.run) ?? []) : [],
        superseded: known ? facts.superseded.has(s.run) : false,
      }
    })
    .sort((a, b) => (a.issue ?? 0) - (b.issue ?? 0) || (a.branch < b.branch ? -1 : a.branch > b.branch ? 1 : 0))
}

export function buildState(o: Observed): State {
  const tracker = new RegExp(o.trackerTitle, 'i')
  // the replay harness (plain JS) may leave the timelines out
  const timelines = o.timelines ?? new Map<number, number[]>()
  const numbers = new Set<number>()
  for (const issue of o.factory?.issues ?? []) numbers.add(issue.number)
  for (const n of o.queue ?? []) numbers.add(n)
  for (const entry of o.ledger) if (entry.issue !== null) numbers.add(entry.issue)
  // the issues `only` names, and the sub-issues a tracker among them stands for (D-35)
  for (const n of o.control.only) {
    numbers.add(n)
    for (const sub of subIssuesOf(n, timelines) ?? []) numbers.add(sub)
  }

  const issues: IssueView[] = [...numbers]
    .sort((a, b) => a - b)
    .map(n => {
      const f = o.factory?.issues.find(i => i.number === n && !i.ended) ?? o.factory?.issues.find(i => i.number === n)
      const g = o.github.get(n)
      return {
        number: n,
        stage: f?.stage ?? null,
        stageSince: f?.stageSince ?? null,
        holder: f?.holder ?? null,
        run: f?.run ?? null,
        pr: f?.pr ?? null,
        stuck: f?.stuck ?? null,
        open: g?.facts?.open ?? f?.github?.open ?? null,
        trusted: g === undefined ? null : g.trusted,
        labels: g?.facts?.labels ?? f?.github?.labels ?? null,
        blockedBy: g?.facts?.blockedBy ?? null,
        blocking: g?.facts?.blocking ?? null,
        subIssues: g?.facts?.subIssues ?? null,
        epic: g?.facts ? tracker.test(g.facts.title) : null,
        subIssueList: subIssuesOf(n, timelines),
        brief: g?.brief ?? null,
        delegatedBrief: o.facts?.briefs.get(n) ?? null,
        claimLapsedAt: f !== undefined && !f.ended ? f.lapsedAt : null,
        reclaimedAt: o.facts?.reclaimed.get(n) ?? null,
      }
    })

  const runs = o.runs ?? (o.factory !== null && o.facts !== null ? runsFromEvents(o.factory, o.facts) : [])
  return {
    now: o.now,
    repo: o.repo,
    device: o.device,
    loadedAt: o.loadedAt,
    sources: o.sources,
    usage: o.usage ?? UNAVAILABLE,
    issues,
    queue: o.queue ?? [],
    runs,
    pool: o.pool,
    agents: o.agents,
    milestone: o.milestone,
    release: o.release ?? null,
    ledger: o.ledger,
    control: o.control,
    lastTitle: o.lastTitle,
    lastTitleAt: o.lastTitleAt,
    githubBackoffUntil: o.githubBackoffUntil,
    checkout: o.checkout ?? null,
  }
}

// digestOf: a short hash of the state without its clock readings, so a pass that saw nothing
// new is easy to spot in the decision log (SPEC 12). FNV-1a over a stable rendering.
export function digestOf(state: State): string {
  const { now: _now, sources, lastTitle: _title, lastTitleAt: _titleAt, ...rest } = state
  const quiet = { ...rest, sources: Object.fromEntries(Object.entries(sources).map(([k, v]) => [k, v.ok])) }
  let hash = 0x811c9dc5
  for (const ch of stable(quiet)) {
    hash ^= ch.charCodeAt(0)
    hash = Math.imul(hash, 0x01000193) >>> 0
  }
  return hash.toString(16).padStart(8, '0')
}

function stable(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stable).join(',')}]`
  if (value !== null && typeof value === 'object') {
    const entries = Object.entries(value as Record<string, unknown>).filter(([, v]) => v !== undefined)
    return `{${entries.sort(([a], [b]) => (a < b ? -1 : 1)).map(([k, v]) => `${JSON.stringify(k)}:${stable(v)}`).join(',')}}`
  }
  return JSON.stringify(value) ?? 'null'
}

files.hooks/trace.ts:
// Trace mode (#552): with config `trace` on, each pass writes one record to
// <loop dir>/trace-YYYY-MM-DD.jsonl beside its decision-log line, for troubleshooting and for
// measuring the loop: what asked for the pass, how long it and each of its phases took, every
// command it ran (the source it read, its exit, its bytes), each action's times, the wakes'
// latencies, and what each issue waits on and since when. The files stay within config
// traceMaxBytes: the oldest go first, and today's is cut short rather than pass it (traceRoom).
// register.ts holds the clock and the files; a Tracer only times the calls it is handed, and the
// rest here is pure.
import type { ActOutcome } from './act'
import type { ActIo, RunResult } from './exec'
import type { Io } from './observe'
import type { ActionKind, LedgerEntry, LedgerStatus, Ms, PlanResult, Skip, SourceName, Stage, State } from './types'

// A pass's phases in the order they run, each ending where the next begins: setup (the settings,
// the kill switch, the agent list), rails (act mode's checks and the act lock), observe, plan, act
// (the actions, the title, the notices and the store writes after them) and log (the decision log,
// a recorded state, the daily prune).
export const PHASES = ['setup', 'rails', 'observe', 'plan', 'act', 'log'] as const
export type Phase = (typeof PHASES)[number]

// What an observe command reads: a State source, or the main checkout.
export type TraceSource = SourceName | 'checkout'

// One command or engine call: the phase it ran in, the source it read (observe's reads), when it
// started (t, ms into the pass), how long it took, its exit and the bytes it printed; error when
// it threw or was refused.
export type Command = { phase: Phase; source?: TraceSource; cmd: string; t: number; ms: number; exit?: number | null; bytes?: number; error?: string }

export type Tracer = {
  // performance.now(), and its reading when the pass started
  now: () => number
  t0: number
  // the loop's clock at one reading of `now`: a clock time (an action's start) as a pass time
  anchor: { at: Ms; t: number }
  phase: Phase
  lapAt: number
  phases: Record<Phase, number>
  commands: Command[]
  // the pass's time in store writes, event writes and the act lock, whatever phase they ran in
  persistMs: number
  eventsMs: number
  lockMs: number
}

const CMD_MAX = 160
const ERROR_MAX = 200
const WAKES: readonly ActionKind[] = ['judge', 'task', 'tell']
const LIVE: readonly Stage[] = ['designing', 'implementing', 'in pipeline', 'parked', 'ready to merge']
const encoder = new TextEncoder()

// to a tenth of a millisecond: plan takes a few
const tenth = (ms: number) => Math.round(ms * 10) / 10
const iso = (ms: Ms) => new Date(ms).toISOString()

export function byteLength(text: string): number {
  return encoder.encode(text).length
}

// newTracer: a pass that started at t0 (a reading of now), with the loop's clock at `at` now.
export function newTracer(now: () => number, t0: number, at: Ms): Tracer {
  const t = now()
  return {
    now,
    t0,
    anchor: { at, t },
    phase: 'setup',
    lapAt: t0,
    phases: { setup: 0, rails: 0, observe: 0, plan: 0, act: 0, log: 0 },
    commands: [],
    persistMs: 0,
    eventsMs: 0,
    lockMs: 0,
  }
}

// begin: the phase running ends now and the next one starts.
export function begin(tr: Tracer | null, phase: Phase) {
  if (tr === null) return
  const t = tr.now()
  tr.phases[tr.phase] += t - tr.lapAt
  tr.lapAt = t
  tr.phase = phase
}

// carve: ms of the phase running belong to another (act mode plans inside its act step).
export function carve(tr: Tracer | null, phase: Phase, ms: number) {
  if (tr === null) return
  tr.phases[phase] += ms
  tr.lapAt += ms
}

// passTime: a time on the loop's clock as ms into the pass.
export function passTime(tr: Tracer, at: Ms): number {
  return tenth(at - tr.anchor.at + tr.anchor.t - tr.t0)
}

// spent: work, its time added to one of the pass's totals.
export async function spent<T>(tr: Tracer | null, total: 'persistMs' | 'eventsMs' | 'lockMs', work: () => Promise<T>): Promise<T> {
  if (tr === null) return work()
  const start = tr.now()
  try {
    return await work()
  } finally {
    tr[total] += tr.now() - start
  }
}

// timed: one call, recorded in the order calls start.
async function timed<T>(tr: Tracer, cmd: string, work: () => Promise<T>, read: (r: T) => Partial<Command> = () => ({}), source?: TraceSource): Promise<T> {
  const start = tr.now()
  const at = { cmd: cmd.slice(0, CMD_MAX), t: tenth(start - tr.t0), ms: 0 }
  const c: Command = source === undefined ? { phase: tr.phase, ...at } : { phase: tr.phase, source, ...at }
  tr.commands.push(c)
  try {
    const r = await work()
    Object.assign(c, read(r))
    return r
  } catch (err) {
    c.exit = null
    c.error = (err instanceof Error ? err.message : String(err)).slice(0, ERROR_MAX)
    throw err
  } finally {
    c.ms = tenth(tr.now() - start)
  }
}

// called: an engine call the driver makes itself (the pass's agent list), recorded.
export function called<T>(tr: Tracer | null, cmd: string, work: () => Promise<T>, read?: (r: T) => Partial<Command>): Promise<T> {
  return tr === null ? work() : timed(tr, cmd, work, read)
}

const ran = (r: RunResult): Partial<Command> => ({ exit: r.exitCode, bytes: byteLength(r.stdout) })

// sourceOf: the State source an observe command reads (observe.ts), from its program.
export function sourceOf(argv: readonly string[]): TraceSource | undefined {
  const [cmd = '', ...args] = argv
  const tool = cmd.slice(cmd.lastIndexOf('/') + 1)
  if (cmd === 'callum-flow-factory-state') return 'factory'
  if (cmd === 'dev-query') return 'facts'
  if (tool === 'pipeline-watch.sh') return 'runs'
  if (tool === 'queue-watch.sh' || (cmd === 'callum-flow-issue-read' && args.includes('--list'))) return 'queue'
  if (cmd === 'callum-flow-issue-read') return 'github'
  if (tool === 'usage-check.sh') return 'usage'
  // a pool slot's reflog or tree (git -C <slot>, #563) is the pool's
  if (cmd === 'treehouse' || (cmd === 'git' && args[0] === '-C')) return 'pool'
  if (cmd === 'git') return 'checkout'
  if (cmd === 'callum-flow-milestone') return 'milestone'
  return undefined
}

// tracedIo: observe's engine calls, each recorded with the source it reads.
export function tracedIo(tr: Tracer, io: Io): Io {
  return {
    ...io,
    run: (argv, init) => timed(tr, argv.join(' '), () => io.run(argv, init), ran, sourceOf(argv)),
    readFile: path => timed(tr, `fs.read ${path}`, () => io.readFile(path), text => (text === null ? {} : { bytes: byteLength(text) })),
    sessionLimits: () => timed(tr, 'session.usage', () => io.sessionLimits()),
  }
}

// tracedActIo: the act half's engine calls, each recorded; event writes also count in eventsMs.
export function tracedActIo(tr: Tracer, io: ActIo): ActIo {
  const refused = (r: { deny?: string; error?: string }): Partial<Command> => {
    const why = r.deny ?? r.error
    return why === undefined ? {} : { error: why.slice(0, ERROR_MAX) }
  }
  return {
    ...io,
    run: (argv, init) => {
      const call = () => timed(tr, argv.join(' '), () => io.run(argv, init), ran)
      return argv[0] === 'callum-flow-event' ? spent(tr, 'eventsMs', call) : call()
    },
    spawnAgent: input => timed(tr, `agent.spawn ${input.name ?? input.subagentType}`, () => io.spawnAgent(input), refused),
    stopAgent: agentId => timed(tr, `TaskStop ${agentId}`, () => io.stopAgent(agentId), refused),
    submit: text => timed(tr, `prompt.submit ${text.split('\n', 1)[0] ?? ''}`, () => io.submit(text)),
    rename: title => timed(tr, 'rename', () => io.rename(title)),
    usage: () => timed(tr, 'session.usage', () => io.usage()),
    readFile: path => timed(tr, `fs.read ${path}`, () => io.readFile(path), text => (text === null ? {} : { bytes: byteLength(text) })),
    writeFile: (path, text) => timed(tr, `fs.write ${path}`, () => io.writeFile(path, text), () => ({ bytes: byteLength(text) })),
  }
}

// lockTimed: one write of the act lock (rails.ts LOCK_CAS_SCRIPT), recorded as `act lock`, its
// time, the flock wait included, counted in lockMs.
export function lockTimed<T extends RunResult>(tr: Tracer | null, work: () => Promise<T>): Promise<T> {
  if (tr === null) return work()
  return spent(tr, 'lockMs', () => timed(tr, 'act lock', work, r => ({ exit: r.exitCode })))
}

// --- the record's parts -----------------------------------------------------------------------

// One source as the pass found it: read (`reads` commands, `ms` in all) or taken from the observe
// cache, how old State says its data is, and why it failed.
export type SourceRow = { ok: boolean; cached: boolean; reads: number; ms: number; ageMs: Ms | null; error?: string }

// sourceRows: each State source and the main checkout. A source that ran no command of its own
// this pass took its data from the observe cache (GitHub when no issue was due), unless it is one
// of `made`, built each pass from another source (a shadow's runs from the event log, its pool
// from the pool size).
export function sourceRows(state: State, commands: readonly Command[], made: readonly SourceName[] = []): Record<string, SourceRow> {
  const read = (name: TraceSource) => {
    const own = commands.filter(c => c.source === name)
    return { reads: own.length, ms: tenth(own.reduce((n, c) => n + c.ms, 0)) }
  }
  const out: Record<string, SourceRow> = {}
  for (const [name, s] of Object.entries(state.sources) as [SourceName, State['sources'][SourceName]][]) {
    const r = read(name)
    const row: SourceRow = { ok: s.ok, cached: r.reads === 0 && s.at !== null && !made.includes(name), ...r, ageMs: s.at === null ? null : state.now - s.at }
    if (s.error !== undefined) row.error = s.error
    out[name] = row
  }
  if (state.checkout !== null) {
    const failed = 'error' in state.checkout ? state.checkout.error : null
    out.checkout = { ok: failed === null, cached: false, ...read('checkout'), ageMs: failed === null ? 0 : null, ...(failed === null ? {} : { error: failed }) }
  }
  return out
}

// One executed action: when plan handed it over, when it started and ended (ms into the pass;
// null for one held before it started), and how long it ran. A spawn's ms is its time to start:
// it returns once the agent started.
export type ActionRow = { key: string; kind: ActionKind; status: ActOutcome['status']; queued: number | null; started: number | null; ended: number | null; ms: Ms }

export function actionRows(tr: Tracer, outcomes: readonly ActOutcome[], queuedAt: Ms | null): ActionRow[] {
  return outcomes.map(o => {
    const started = o.at === undefined ? null : passTime(tr, o.at)
    return {
      key: o.key,
      kind: o.kind,
      status: o.status,
      queued: queuedAt === null ? null : passTime(tr, queuedAt),
      started,
      ended: started === null ? null : tenth(started + o.ms),
      ms: o.ms,
    }
  })
}

// attemptOf: one attempt of a ledger entry (a retry keeps the key, not the start).
export function attemptOf(e: LedgerEntry): string {
  return `${e.key}@${e.startedAt}`
}

// One wake's latencies: queued (its submit), delivered (its turn started), ended (answered, or
// timed out or lost), the ms between them.
export type WakeRow = {
  key: string
  wake: string | null
  status: LedgerStatus
  queued: string
  delivered: string | null
  ended: string | null
  deliverMs: Ms | null
  answerMs: Ms | null
}

// wakeRows: every open wake, and each wake that ended at or after `since` and was not reported
// yet, with the attempts it reports ended (attemptOf), so the caller reports each once.
// delivered: when each attempt's turn first started (register.ts records it at turn.start).
export function wakeRows(
  ledger: readonly LedgerEntry[],
  delivered: ReadonlyMap<string, Ms>,
  reported: ReadonlySet<string>,
  since: Ms,
): { rows: WakeRow[]; reported: string[] } {
  const rows: WakeRow[] = []
  const ended: string[] = []
  for (const e of ledger) {
    if (!WAKES.includes(e.kind)) continue
    const end = e.status === 'running' ? null : (e.endedAt ?? e.startedAt)
    if (end !== null && (reported.has(attemptOf(e)) || end < since)) continue
    if (end !== null) ended.push(attemptOf(e))
    const at = delivered.get(attemptOf(e)) ?? null
    rows.push({
      key: e.key,
      wake: e.wake ?? null,
      status: e.status,
      queued: iso(e.startedAt),
      delivered: at === null ? null : iso(at),
      ended: end === null ? null : iso(end),
      deliverMs: at === null ? null : at - e.startedAt,
      answerMs: at === null || end === null ? null : end - at,
    })
  }
  return { rows, reported: ended }
}

// What one issue waits on (null: the whole pass, a source down), since when, and for how long.
export type WaitRow = { issue: number | null; stage: Stage | null; rule: string | null; on: string; since: string | null; forMs: Ms | null }

const waitKey = (s: Skip) => `${s.issue}:${s.rule}`

// waitSince: when each skip, by issue and rule, was first seen in a run of passes: one that keeps
// coming keeps its start, so a stall shows as a growing age (its words may change, as a
// countdown's do); one that stops is forgotten.
export function waitSince(prev: ReadonlyMap<string, Ms>, skipped: readonly Skip[], now: Ms): Map<string, Ms> {
  const next = new Map<string, Ms>()
  for (const s of skipped) if (!next.has(waitKey(s))) next.set(waitKey(s), prev.get(waitKey(s)) ?? now)
  return next
}

// waitingRows: each skip plan gave (the rule's reason, with how long it has been given), each
// running ledger entry an issue waits for, and each live issue of this device that nothing acts
// on and nothing names, waiting in its stage.
export function waitingRows(state: State, result: PlanResult, ledger: readonly LedgerEntry[], since: ReadonlyMap<string, Ms>): WaitRow[] {
  const stageOf = (n: number | null) => (n === null ? null : (state.issues.find(i => i.number === n)?.stage ?? null))
  const rows: WaitRow[] = []
  const seen = new Set<string>()
  for (const s of result.skipped) {
    if (seen.has(waitKey(s))) continue
    seen.add(waitKey(s))
    const at = since.get(waitKey(s)) ?? state.now
    rows.push({ issue: s.issue, stage: stageOf(s.issue), rule: s.rule, on: s.why, since: iso(at), forMs: state.now - at })
  }
  for (const e of ledger) {
    if (e.status !== 'running' || e.issue === null) continue
    rows.push({ issue: e.issue, stage: stageOf(e.issue), rule: e.rule, on: `${e.key} running`, since: iso(e.startedAt), forMs: state.now - e.startedAt })
  }
  for (const i of state.issues) {
    if (i.stage === null || !LIVE.includes(i.stage) || i.holder !== state.device) continue
    if (rows.some(r => r.issue === i.number) || result.actions.some(a => a.issue === i.number)) continue
    const at = i.stageSince
    rows.push({ issue: i.number, stage: i.stage, rule: null, on: 'no rule acts on it', since: at === null ? null : iso(at), forMs: at === null ? null : state.now - at })
  }
  return rows.sort((a, b) => (a.issue ?? 0) - (b.issue ?? 0))
}

export type TraceInput = {
  tr: Tracer
  // the decision-log line's fields the record repeats, so the two join
  line: { at: string; pass: number; loaded: string; mode: string; executed: boolean; trigger: string }
  state: State
  // the sources built each pass from another (sourceRows)
  made: readonly SourceName[]
  outcomes: readonly ActOutcome[]
  // when plan handed the actions over, on the loop's clock; null when the pass did not act
  queuedAt: Ms | null
  wakes: WakeRow[]
  waiting: WaitRow[]
}

// traceRecord: the pass's record, its log phase ending now: start and end on the loop's clock
// (`at` is the decision log's, when observe began), ms between them.
export function traceRecord(input: TraceInput): Record<string, unknown> {
  const { tr } = input
  begin(tr, 'log')
  const start = Math.round(tr.anchor.at - (tr.anchor.t - tr.t0))
  const ms = tenth(tr.lapAt - tr.t0)
  return {
    v: 1,
    ...input.line,
    start: iso(start),
    end: iso(Math.round(start + ms)),
    ms,
    phases: Object.fromEntries(PHASES.map(p => [p, tenth(tr.phases[p])])),
    persistMs: tenth(tr.persistMs),
    eventsMs: tenth(tr.eventsMs),
    lockMs: tenth(tr.lockMs),
    sources: sourceRows(input.state, tr.commands, input.made),
    commands: tr.commands,
    actions: actionRows(tr, input.outcomes, input.queuedAt),
    wakes: input.wakes,
    waiting: input.waiting,
  }
}

// --- the files and their cap --------------------------------------------------------------------

const TRACE_NAME = /^trace-\d{4}-\d{2}-\d{2}\.jsonl$/
// a record is written only while the line that cuts today's file short would still fit after it
export const CUT_ROOM = 256

export function traceName(day: string): string {
  return `trace-${day}.jsonl`
}

// cutLine: the last line of a trace file the cap cut short (under CUT_ROOM bytes).
export function cutLine(at: string, cap: number): string {
  return JSON.stringify({ v: 1, at, cut: cutText(cap) }) + '\n'
}

function cutText(cap: number): string {
  return `the trace cap (${cap} bytes) is reached: nothing more is traced today`
}

// isCutLine: the line is the cut line of this cap, so the file it ends stays closed today; a cut
// under another cap does not close it (SPEC 12.1).
export function isCutLine(line: string, cap: number): boolean {
  try {
    const v: unknown = JSON.parse(line)
    return v !== null && typeof v === 'object' && (v as { cut?: unknown }).cut === cutText(cap)
  } catch {
    return false
  }
}

export type Room = { remove: string[]; write: 'record' | 'cut' | 'none' }

// traceRoom: what one more record of `bytes` takes under the cap, given the loop dir's files:
// the oldest trace files are deleted first (by the day in their names, never today's) until it
// fits; when today's file alone leaves no room, it is cut short with one line (cutLine), and
// once cut (`cut`) nothing more goes in it. The files never pass the cap.
export function traceRoom(files: readonly { name: string; size: number }[], day: string, bytes: number, cap: number, cut: boolean): Room {
  if (cut) return { remove: [], write: 'none' }
  const today = traceName(day)
  const traces = files.filter(f => TRACE_NAME.test(f.name)).sort((a, b) => a.name.localeCompare(b.name))
  let total = traces.reduce((n, f) => n + f.size, 0)
  const fits = (more: number) => total + more <= cap
  const remove: string[] = []
  for (const f of traces) {
    if (fits(bytes + CUT_ROOM)) break
    if (f.name === today) continue
    remove.push(f.name)
    total -= f.size
  }
  if (fits(bytes + CUT_ROOM)) return { remove, write: 'record' }
  return { remove, write: fits(CUT_ROOM) ? 'cut' : 'none' }
}

files.hooks/types.ts:
// The factory loop's data: what observe builds (State), what plan returns (Action), and
// what the ledger keeps. docs/factory-loop/SPEC.md is the contract; section numbers below
// point into it. Types only: plan.ts imports nothing else, so it stays pure. The v2 rule layer's
// vocabulary (docs/factory-loop/v2/SPEC.md) is v2/types.ts's; its action kinds, actions,
// outcomes and State fields join the unions here, so the dispatcher, the ledger and the store
// carry them as they carry v1's.
import type { AgentStep, Model, Planner, Shadow, SplitReasons, StateTimeouts, V2Action, V2ActionKind, V2Outcome, V2State } from './v2/types'

export type Ms = number

export type Tier = 'normal' | 'slow' | 'stop-new' | 'stop-all'

// Each action has one class; the tier decides which classes may run (SPEC 5.2).
export type ActionClass = 'free' | 'owner' | 'drive' | 'develop' | 'start'

export type Stage =
  | 'queued'
  | 'designing'
  | 'implementing'
  | 'in pipeline'
  | 'parked'
  | 'ready to merge'
  | 'merged'
  | 'closed without merge'

export type SourceName = 'factory' | 'facts' | 'runs' | 'queue' | 'github' | 'usage' | 'pool' | 'milestone'

// ok: the last read worked. at: when the data in State was read (null: never).
export type Source = { ok: boolean; at: Ms | null; error?: string }

// Each window's reading and when it resets: a reading taken before its window reset counts as
// zero once the reset has passed (the next read confirms it).
export type Usage = {
  fiveHour: number | null
  sevenDay: number | null
  fiveHourResetsAt: Ms | null
  sevenDayResetsAt: Ms | null
  unavailable: boolean
}

export type Brief = { url: string; at: Ms }

export type IssueView = {
  number: number
  stage: Stage | null
  stageSince: Ms | null
  holder: string | null
  run: string | null
  pr: number | null
  stuck: string | null
  open: boolean | null
  trusted: boolean | null
  labels: string[] | null
  blockedBy: number | null
  // the open issues waiting on this one, or null if unread
  blocking: number | null
  subIssues: number | null
  // the title marks it a tracker (config trackerTitle, e.g. 'Epic: ...'), or null if unread
  epic: boolean | null
  // a tracker's open sub-issues, nested ones included, ascending, from its timeline; read only
  // for trackers named in control.only (D-35). null: not read.
  subIssueList: number[] | null
  brief: Brief | null
  delegatedBrief: string | null
  // the factory source shows the holder's claim lapsed: its lease ended then, with no renewal (v2 H1)
  claimLapsedAt: Ms | null
  // the newest `reclaimed` event of the issue: a sweep or a release gave its claim back (v2 H1)
  reclaimedAt: Ms | null
}

export type RunState =
  | 'merge-ready'
  | 'head-mismatch'
  | 'conflict'
  | 'ci-stalled'
  | 'parked'
  | 'failed'
  | 'cancelled'
  | 'running'
  | 'pending'

export type RunView = {
  branch: string
  issue: number | null
  run: string
  state: RunState
  head: string | null
  step: string | null
  detail: string | null
  pr: number | null
  since: Ms | null
  reviewFixRounds: number
  verdicts: string[]
  superseded: boolean
}

// The main checkout, where every agent the loop starts begins and its own commands run (#544):
// the branch checked out (null when HEAD is detached), its commit, origin's default branch and
// the tracked paths with changes (untracked files are not the checkout moving). A read that
// failed is { error }.
export type Checkout = { branch: string | null; head: string | null; defaultBranch: string; dirty: string[] } | { error: string }

// A treehouse pool slot (#563): the branch checked out (null when detached), and the lease's
// id, start and branch: the branch it has checked out, else the newest issue branch its HEAD
// reflog shows checked out since the lease began (an implementer detaches its slot once the
// pipeline holds the branch). dirty: uncommitted changes, untracked files included, read only for
// a slot rule H3 might return (null: not read).
export type Slot = {
  path: string
  branch: string | null
  state: string
  dirty: boolean | null
  busy: boolean
  lease: string | null
  leasedAt: Ms | null
  leaseBranch: string | null
}
export type Pool = { free: number; total: number; slots: Slot[] }

export type AgentStatus = 'pending' | 'running' | 'waiting' | 'idle' | 'completed' | 'failed' | 'killed'
export type AgentView = { id: string; type: string; status: AgentStatus }

export type Bump = 'patch' | 'minor' | 'major'
export type Milestone = { open: number; closed: number; expected: Bump | null }
// ReleaseInfo: the last release tag (null: the repo has no release yet) and when the oldest merge
// into the default branch since that tag happened (null: unknown or none)
export type ReleaseInfo = { tag: string | null; oldest: Ms | null }

export type Control = {
  paused: number[]
  noNewWork: boolean
  skip: number[]
  priority: number[]
  only: number[]
  serial: boolean
  usageOverride: { untilPct: number; expiresAt: Ms } | null
  // an update is due (rule H4, D-15): set by the reconciler or `/factory update`
  updateDue: { reason: string; at: Ms } | null
  // a v2 resume carries its note for the issue's next step (v2 SPEC 11, P1)
  resumed: { subject: string; at: Ms; note?: string }[]
  dropped: { issue: number; at: Ms }[]
  notes: { issue: number | null; text: string; at: Ms }[]
}

export type AgentType = 'designer' | 'implementer' | 'adjudicator' | 'fixer'
export type AdjudicatorPurpose = 'gate' | 'weakening' | 'merge'
export type FixerPurpose = 'gate' | 'conflict' | 'regate' | 'weakening' | 'review' | 'guard' | 'handoff' | 'resume'
export type Rollout = 'merge' | 'run-it' | 'keep-open'

export type GuardFail = { name: string; reason: string }

// An adjudicator's one ACTION line, parsed (SPEC 7.3). `merge` and `hold` answer purpose
// merge only (rule M4, D-05).
export type AdjudicatorAction =
  | { type: 'approve'; reason: string | null }
  // ignore: the judged findings the fix leaves unselected, declined by name (respond --ignore,
  // which no-mistakes 1.90+ requires); null when none
  | { type: 'fix'; findings: string | null; instructions: string | null; addFinding: string | null; ignore: string | null }
  | { type: 'skip' }
  | { type: 'escalate'; why: string }
  | { type: 'fixer'; instructions: string }
  | { type: 'merge' }
  | { type: 'hold'; reason: string }

// The merge adjudicator's report lines (SPEC 7.3): SUMMARY, BUMP and FLAGS. A flag marks what
// release sequencing must know: a base image or template change, a restart, a run-it rollout.
export type MergeFlag = 'image' | 'template' | 'restart' | 'run-it'
export type MergeReport = { summary: string; bump: Bump; bumpReason: string; flags: MergeFlag[] }

// What an executor recorded about a finished action (SPEC 7). An agent reply the parser
// cannot read is recorded as a failed attempt, except the designer's, which goes to the
// model as `judge(report)` and is recorded as { unparsed: true }.
export type Outcome =
  // a CLI's exit code; on failure the first 2 000 characters of its stderr (SPEC 10.1)
  | { kind: 'cli'; exit: number; detail?: string }
  // a detached respond or env-retry (SPEC 6.1): the slot it runs in and the log its launch was
  // read back from
  | { kind: 'respond'; slot: string; log: string }
  | { kind: 'claim'; result: 'claimed' | 'lost' }
  | { kind: 'designer'; brief: string | null; created: number[]; pendingDecision: boolean }
  | { kind: 'designer'; unparsed: true }
  | { kind: 'adjudicator'; verdicts: string[]; action: AdjudicatorAction; report: MergeReport | null }
  | { kind: 'handoff'; notGated: boolean; run: string | null; head: string | null; newBranch: string | null }
  | { kind: 'guard'; fails: GuardFail[]; warns: string[] }
  | { kind: 'update-behind'; result: 'updated' | 'fail' | 'skip'; from: string | null; to: string | null; line: string }
  // a worktree the pipeline's own commits left behind its branch, fast-forwarded (rule M2,
  // #551): forwarded, current (nothing lagged) or refused (dirty, diverged, origin moved)
  | { kind: 'fast-forward'; result: 'forwarded' | 'current' | 'refused'; line: string }
  // the main checkout brought up to date with origin's default branch (rule H5, #555): updated
  // (the line names both commits), current, or refused (moved, dirty, or commits origin lacks)
  | { kind: 'update-checkout'; result: 'updated' | 'current' | 'refused'; line: string }
  | { kind: 'merge'; result: 'merged' | 'refused'; rollout: Rollout | null; closeIssue: number | null; line: string }
  // callum-flow-rollout for a merge the loop did not make (a hand merge, rule M7, D-29)
  | { kind: 'rollout'; rollout: Rollout | null; closeIssue: number | null }
  | {
      kind: 'wake'
      decision: string
      reason: string | null
      instructions: string | null
      bump: Bump | null
      bumpReason: string | null
      fields: Record<string, string | number | boolean | number[] | null>
    }
  | V2Outcome

export type ActionKind =
  | 'heartbeat'
  | 'sweep'
  | 'claim'
  | 'spawn'
  | 'delegate'
  | 'respond'
  | 'env-retry'
  | 'guard'
  | 'update-behind'
  | 'fast-forward'
  | 'update-checkout'
  | 'fix-linkage'
  | 'merge'
  | 'close-issue'
  | 'release-parent'
  | 'abandon'
  | 'milestone-later'
  | 'milestone-expect'
  | 'pr-reopen'
  | 'pr-comment'
  | 'pr-close'
  | 'release-worktree'
  | 'restart-self'
  | 'rollout'
  | 'stop-agent'
  | 'judge'
  | 'task'
  | 'tell'
  | 'title'
  | V2ActionKind

export type LedgerStatus = 'running' | 'done' | 'failed' | 'timed-out' | 'lost'

export type LedgerEntry = {
  key: string
  kind: ActionKind
  class: ActionClass
  rule: string
  issue: number | null
  run: string | null
  pr: number | null
  head: string | null
  agent?: AgentType
  wake?: string
  status: LedgerStatus
  attempts: number
  startedAt: Ms
  endedAt: Ms | null
  agentId?: string
  outcome?: Outcome
  // a wake's id (SPEC 8.1 `id=`), the turn it started, whether its reminder went out (for an
  // agent, its one repair message, #548), and the session that submitted it (a restart ends the
  // wakes of the session before, SPEC 7.5)
  wakeId?: string
  turnId?: string
  reminded?: boolean
  session?: string
  // the executor's last few words, for the decision log
  summary?: string
  // a v2 agent step's kind, which the per-issue rate cap counts by (D-24; v2 appendix B)
  step?: AgentStep
  // the key's own attempt cap, when its action set one (a v2 slot op's, appendix B)
  maxAttempts?: number
}

export type State = {
  now: Ms
  repo: string
  device: string
  loadedAt: Ms
  sources: Record<SourceName, Source>
  usage: Usage
  issues: IssueView[]
  queue: number[]
  runs: RunView[]
  pool: Pool | null
  agents: AgentView[]
  milestone: Milestone | null
  // null until the first successful read, which happens only while the milestone qualifies
  release: ReleaseInfo | null
  ledger: LedgerEntry[]
  control: Control
  lastTitle: string | null
  // when the last rename went out; null until one has since the module loaded
  lastTitleAt: Ms | null
  githubBackoffUntil: Ms | null
  // null: not read (the replay harness, a state built outside a pass)
  checkout: Checkout | null
  // what v2 reads besides (v2 SPEC 2.4): set when the planner is v2 or the v2 shadow is on
  v2?: V2State
}

export type Mode = 'off' | 'observe' | 'act'

export type Config = {
  mode: Mode
  // observe mode only: plan as this device (the live orchestrator's) to shadow its work
  shadowDevice: string | null
  readyLabel: string
  inDevLabel: string
  skipLabels: string[]
  // a title matching this pattern marks a tracker, like sub-issues do (MEM: trackers are never claimed)
  trackerTitle: string
  usageSlowPct: number
  usageStopNewPct: number
  usageStopAllPct: number
  passEveryMs: Ms
  // the repo expects a release at least this often; the release wake names it (#772)
  minimumReleaseCadenceMs: Ms
  // the title is renamed at most this often (O1 is a throttle)
  titleEveryMs: Ms
  // the factory report is built at most this often (#684)
  reportEveryMs: Ms
  queueEveryMs: Ms
  githubEveryMs: Ms
  usageEveryMs: Ms
  milestoneEveryMs: Ms
  // a usage reading older than this counts as unavailable
  usageStaleMs: Ms
  heartbeatEveryMs: Ms
  sweepEveryMs: Ms
  // the main checkout is brought up to date with origin at least this often (rule H5, #555)
  checkoutEveryMs: Ms
  slowGapMs: Ms
  maxStartsPerPass: number
  // null: no cap on this device's live issues
  maxInFlightIssues: number | null
  worktreeReserve: number
  reviewFixCap: number
  guardRecheckMs: Ms
  guardTtlMs: Ms
  respondSettleMs: Ms
  updateBehindRetryMs: Ms
  updateBehindRetries: number
  ciStallRecheckMs: Ms
  blindNoticeAfterMs: Ms
  agentTimeoutMs: Record<AgentType, Ms>
  wakeTimeoutMs: Record<WakeKind, Ms>
  maxAttempts: Partial<Record<ActionKind | AgentType, number>>
  retryBackoffMs: Ms
  // per rolling hour; merges are never capped (D-24)
  rateCaps: { start: number; spawn: number; wake: number; perIssueKind: number }
  // act mode without DEV_ROLE=orchestrator, for a testbed (SPEC 11.2)
  allowActOutsideOrchestrator: boolean
  // one timing record per pass in trace-YYYY-MM-DD.jsonl (#552); the workspace file's own
  // `trace`, which `/factory trace` writes, overrides the repo's
  trace: boolean
  // the trace files' total size: the oldest go first, and today's is cut short past it
  traceMaxBytes: number
  // how the prompts and the repair message ask agents to answer (SPEC 4.2): through the checked
  // answer script (script, the default: a workaround until a timer-spawned agent reaches the
  // loop's tool hook, #560, #561), through their answer tools (tool, the intended design, #548),
  // or in text alone; text stays every channel's fallback. The workspace file's own
  // `answerChannel` overrides the repo's
  answerChannel: AnswerChannel
  // --- v2 (v2 SPEC 2.3, appendix A) ---
  // the layer whose plan the act step executes, and the v2 shadow that plans beside v1 and is
  // only logged
  planner: Planner
  shadow: Shadow
  // the step timeouts and the waiting states' tell periods (v2 SPEC 4.4)
  stateTimeoutMs: StateTimeouts
  // a wait on GitHub: no check started this long after the head was first seen, or one running
  // this long, is unknown (v2 SPEC 4.4)
  ciStartMs: Ms
  ciRunMs: Ms
  // a PR's read stands this long, unless something the loop knows makes it due sooner (v2 SPEC 2.4)
  prEveryMs: Ms
  // triage calls per life (v2 SPEC 5.1); its agent's model (5.2)
  maxTriages: number
  // the lives an issue gets: a release at the last one rejects it instead of putting it back in the
  // queue (v2 SPEC 6.4)
  maxLives: number
  triageModel: Model
  // the review step's implementation and its model (v2 SPEC 8.2, 8.3)
  reviewer: string
  reviewerModel: Model
  // the stop gate's commands in the slot, joined with &&, and their one budget (v2 SPEC 10.6)
  gateCommands: string[]
  gateTimeoutMs: Ms
}

export type AnswerChannel = 'script' | 'tool' | 'text'

export type WakeKind = 'judge' | 'task' | 'tell'

// What every action carries. maxAttempts: the key's own cap, for a kind whose ops differ (v2's
// slot); otherwise config.maxAttempts holds the kind's.
export type ActionBase = { key: string; class: ActionClass; rule: string; reason: string; issue: number | null; maxAttempts?: number }
type Base = ActionBase

// What a wake asks: the line's first word is the action kind (judge, task, tell), the
// second this wake name, then key=value fields with no spaces. Context lines follow it in
// the visible prompt: a mod cannot attach hidden context to its own prompt (SPEC 8.1).
export type Action =
  | (Base & { kind: 'heartbeat' | 'sweep' | 'claim' | 'close-issue' | 'milestone-later' })
  | (Base & { kind: 'spawn'; agent: 'designer'; model: string | null; notes: string[] })
  | (Base & {
      kind: 'spawn'
      agent: 'adjudicator'
      purpose: AdjudicatorPurpose
      run: string
      branch: string
      step: string | null
      head: string | null
      pr: number | null
      brief: string | null
      model: string | null
      warns: string[]
      // purpose merge: pointers only, never a diff (D-05). The implementer's handoff head, the
      // run's verdict lines and the latest guard lines for this head; empty for other purposes.
      handoffHead: string | null
      verdicts: string[]
      guard: string[]
    })
  | (Base & {
      kind: 'spawn'
      agent: 'fixer'
      purpose: FixerPurpose
      run: string | null
      branch: string
      head: string | null
      pr: number | null
      brief: string | null
      model: string | null
      instructions: string
    })
  | (Base & { kind: 'delegate'; brief: string })
  | (Base & {
      kind: 'respond'
      run: string
      branch: string
      // the gate's step name; null when unknown (a park seen only in the event log, a failed run
      // the watcher printed no step for): respond then takes the step awaiting approval
      step: string | null
      head: string
      action: 'approve' | 'fix' | 'skip'
      findings: string | null
      instructions: string | null
      addFinding: string | null
      ignore: string | null
      approveReason: string | null
      logReview: boolean
    })
  // Only rule P2a may launch this command; SPEC 5.4 owns resume eligibility.
  | (Base & { kind: 'env-retry'; run: string; branch: string; step: string | null; head: string })
  | (Base & { kind: 'guard' | 'update-behind'; pr: number; run: string; head: string })
  // the worktrees on the run's branch, moved to the run's head when origin holds it, or the head the loop's own update-behind pushed (#551, #595)
  | (Base & { kind: 'fast-forward'; pr: number; run: string; head: string; origin: string; branch: string })
  // rule H5: the main checkout, on origin's default branch, fast-forwarded to origin's (#555);
  // head: its commit as observe read it, so plan knows whether a refusal still stands
  | (Base & { kind: 'update-checkout'; branch: string; head: string | null })
  | (Base & { kind: 'fix-linkage' | 'pr-reopen'; pr: number })
  | (Base & { kind: 'merge'; pr: number; run: string; head: string; bump: Bump | null; bumpReason: string | null })
  | // reasons and childWhys: the split's reasons and each child's why (childWhys aligned with created);
  // null (or absent, for v1's plan) when the life's design answer can no longer be read
  | (Base & { kind: 'release-parent'; created: number[]; reasons?: SplitReasons | null; childWhys?: string[] | null })
  | (Base & { kind: 'abandon'; run: string | null; branch: string | null; note: string })
  | (Base & { kind: 'milestone-expect'; bump: Bump; why: string })
  | (Base & { kind: 'pr-comment'; pr: number; body: string })
  // rule M8: the PR of a superseded run, and the PR on the branch its work moved to (#553)
  | (Base & { kind: 'pr-close'; pr: number; run: string; newBranch: string; by: number })
  // rule H3: the slot, the branch its lease worked, and the lease the return is pinned to (#563)
  | (Base & { kind: 'release-worktree'; path: string; branch: string; lease: string })
  // rule H4: why the update is due, and when it was asked for (the key's subject)
  | (Base & { kind: 'restart-self'; why: string; at: Ms })
  // rule M7 for a hand merge: read the merged issue's rollout
  | (Base & { kind: 'rollout'; pr: number | null })
  | (Base & { kind: 'stop-agent'; agentId: string; entry: string })
  | (Base & { kind: WakeKind; wake: string; fields: Record<string, string>; context: string[] })
  | (Base & { kind: 'title'; text: string })
  | V2Action

export type Skip = { rule: string; issue: number | null; why: string }

export type PlanResult = {
  tier: Tier
  overridden: boolean
  actions: Action[]
  skipped: Skip[]
  title: string
  owner: number
  // each rate cap tripped this pass: a bucket (start, spawn, wake) or a per-issue key
  // '<kind>:<issue>' (SPEC 11.4)
  capped: string[]
  // a claim was held back by maxInFlightIssues this pass (SPEC 4.2)
  atCap: boolean
}

files.hooks/v2/act-events.ts:
// The events the loop writes outside a plan's actions (docs/factory-loop/v2/SPEC.md 7.2): an owner
// op's person intervention, which register.ts ownerOp logs here once the op has landed (every op
// but status and help, with planner v2 in act mode before or after it; opLanded in ops.ts says
// which). One event per issue the op names, each attached to its issue; an op that names none
// (mode, pause of the whole loop, serial) is fleet-level and attached to none. Every event goes
// through events.ts. What the op wrote to control.json or the settings is kept as the loop's own
// version when it is written (store.ts noteWritten), so it is never read as a hand edit.
// logEvent writes a v2 event logged outside a plan's actions. The `event` executor (act-state.ts)
// runs the same events.ts argv through its ExecCtx, so both carry the actor events.ts names (a
// fixer's `verdict`, 7.1).
import { commandOf } from '../act'
import type { ActEnv } from '../act'
import type { ExecCtx } from '../exec'
import { eventArgv, intervention } from './events'
import type { InterventionEvent, V2Event } from './events'
import { factKey } from './keys'

// callum-flow-event is one jq call and one append; a minute is ample (act.ts EVENT_TIMEOUT_MS)
const EVENT_TIMEOUT_MS = 60_000

// What an op that landed was: its canonical text (control.ts formatOp), its name and the issues
// it names.
export type OpLanded = { text: string; name: string; issues: number[]; at: number }

// The ops that change nothing and are no intervention (7.2, appendix E).
const NOT_INTERVENTIONS = ['status', 'help']

// opInterventions: the person interventions one op is: one per issue it names, else one with no
// issue. The fact is the op at its time, `op:<name>/<i<N>|fleet>/<ms, base 36>`.
export function opInterventions(op: OpLanded): InterventionEvent[] {
  if (op.name === '' || NOT_INTERVENTIONS.includes(op.name)) return []
  const at = Math.trunc(op.at).toString(36)
  // a landed `config set|unset` is the settings file changed by the owner through the loop
  const cause = op.name === 'config' ? 'config-file' : `op:${op.name}`
  const issues: (number | null)[] = op.issues.length === 0 ? [null] : [...new Set(op.issues)]
  return issues.map(issue => intervention('person', cause, factKey(cause, issue === null ? 'fleet' : `i${issue}`, at), op.text, { issue, life: null, pr: null }))
}

// logEvent: one v2 event through callum-flow-event, as events.ts builds it (its actor included,
// which ExecCtx.event cannot pass). Like ExecCtx.event (act.ts eventOf), a refusal throws with the
// exit as `exitCode`: callum-flow-event exits non-zero only on a usage error (2), a loop bug that is
// never retried.
export async function logEvent(cmd: ExecCtx['cmd'], e: V2Event): Promise<void> {
  const r = await cmd(eventArgv(e), { timeoutMs: EVENT_TIMEOUT_MS })
  if (r.exitCode === 0) return
  const why = r.stderr.trim().split('\n').pop() ?? ''
  throw Object.assign(new Error(`callum-flow-event ${e.state}: exit ${r.exitCode}${why === '' ? '' : `: ${why}`}`), { exitCode: r.exitCode })
}

// logOwnerOp: the op's interventions, logged; notes on what failed, for the decision log.
export async function logOwnerOp(env: Pick<ActEnv, 'io' | 'rt' | 'commands'>, op: OpLanded): Promise<string[]> {
  const cmd = commandOf(env.io, env.rt, env.commands)
  const notes: string[] = []
  for (const e of opInterventions(op)) {
    try {
      await logEvent(cmd, e)
    } catch (err) {
      notes.push(`intervention ${e.cause}${e.issue === null ? '' : ` #${e.issue}`} not logged: ${(err instanceof Error ? err.message : String(err)).slice(0, 200)}`)
    }
  }
  return notes
}

files.hooks/v2/observe.ts:
// What v2 reads (docs/factory-loop/v2/SPEC.md 2.4), beside what observe.ts reads for both layers:
// the records (the store's, else a rebuild from events, 3.3), the heads first seen, the pool's
// leases by holder (no reflog reads, 10.1), the newest read of each issue, the trusted comments of
// a parked record whose label a person removed (11), the facts the event log holds as logged (from
// observe.ts's read of the log, 7.2), and the source modules: the PRs
// (sources-prs.ts) and the interventions' facts (sources-interventions.ts). observe.ts calls
// observeV2 when the planner is v2 or the v2 shadow is on; register.ts keeps the store keys
// records:<repo> and heads:<repo> with the codecs here. Commands run through observe's own `run`,
// so they join the pass's command list and, outside act mode, send their events to the sink.
import type { FactoryEvent } from '../derive'
import { eventsFromRows } from '../derive'
import type { Cache, Io, Runtime } from '../observe'
import { parseCsv } from '../parse'
import type { LedgerEntry, Ms, Source, State } from '../types'
import { onceKey } from './events'
import { checkoutBaseOf } from './reconcile'
import type { CheckoutBase } from './reconcile'
import { REBUILD_DAYS, REBUILD_SQL, recordsFromEvents } from './record'
import { readDualWrite } from './sources-dualwrite'
import type { DualWriteRead } from './sources-dualwrite'
import { readInterventions } from './sources-interventions'
import type { FilesSeen } from './sources-interventions'
import { EMPTY_PRS, readPrs } from './sources-prs'
import type { PrView, PrsRead, PrUnread } from './sources-prs'
import { readWorkspace } from './sources-workspace'
import { CLOSED_WHYS, FACTORY_LABELS, ISSUE_STATES, STEP_KINDS } from './types'
import type { HeadSeen, IssueComment, IssueRead, IssueRecord, Lease, V2SourceName, V2State } from './types'

const DAY = 86_400_000
// a closed record goes this long after it closed, as ledger entries do (3.3, v1 SPEC 7.1)
export const RECORD_KEEP_MS = 7 * DAY

// What a source module gets (sources-*.ts): the pass's time and runtime, observe's read (its
// commands logged), the State observe built, the records and heads, the records whose PR it may
// read this pass (prBudget: K, a budget of its own beside v1's issue reads; none during a GitHub
// backoff or after a rate limit this pass), whether a rate limit met this pass ends its reads, the
// PRs the last pass tried that did not read (sources-prs.ts, PrUnread.since), and the views of
// earlier passes whose read is not due, which stand for this pass's (observeV2).
export type SourceCtx = {
  now: Ms
  rt: Runtime
  run: (argv: string[], stdin?: string, timeoutMs?: number) => Promise<{ exitCode: number; stdout: string; stderr: string }>
  readFile: Io['readFile']
  state: State
  records: readonly IssueRecord[]
  heads: Record<string, HeadSeen>
  prBudget: number
  limited: () => boolean
  unread: readonly PrUnread[]
  kept: readonly PrView[]
}

// What the store holds for v2, as register.ts passes it (v2/store.ts): records null when the key
// holds none (a rebuild may fill it); error when the store could not be read or holds no stored
// records under the key, so nothing is known of the records; files: the owner's files as the loop
// last read or wrote them (7.2), absent or null when none are kept.
export type V2Stored = { records: IssueRecord[] | null; heads: Record<string, HeadSeen> | null; files?: FilesSeen | null; error: string | null }

// What survives between passes in the module: the heads (an observe pass keeps none in the store),
// the last rebuild, the comments read per issue read, the checkout R1's tripwire last settled on
// (reconcile.ts checkoutBaseOf), and the last pass's PR read: its views, which stand until their
// read is due, and the PRs it tried that did not read, so a run of failed reads keeps its start (a
// new session starts both afresh).
export type V2Cache = {
  heads: Record<string, HeadSeen>
  rebuilt: { at: Ms; records: IssueRecord[] } | null
  comments: Map<number, { readAt: Ms; comments: IssueComment[] }>
  checkoutBase: CheckoutBase | null
  // the last pass's V2State.changed: a read of an issue older than its entry is due (observe.ts)
  changed: Record<number, Ms>
  prs: PrsRead
  // the dual-write probe and the new log's read, once per load; null: not yet read
  dualWrite: { at: Ms; read: DualWriteRead } | null
}

export function emptyV2Cache(): V2Cache {
  return { heads: {}, rebuilt: null, comments: new Map(), checkoutBase: null, changed: {}, prs: EMPTY_PRS, dualWrite: null }
}

// --- the store's records and heads (3.3, 2.4) -------------------------------------------------------

export const recordsKey = (repo: string) => `records:${repo}`
export const headsKey = (repo: string) => `heads:${repo}`

export type StoredRecords = { v: 1; savedAt: Ms; records: IssueRecord[] }

// recordsToStore: what the store keeps: every record but those closed more than RECORD_KEEP_MS ago.
export function recordsToStore(records: readonly IssueRecord[], now: Ms): StoredRecords {
  return { v: 1, savedAt: now, records: records.filter(r => r.state !== 'closed' || now - r.since <= RECORD_KEEP_MS) }
}

// recordsFromStore: the stored records, each checked field by field (one that does not read is
// dropped); null when the value is not stored records at all.
export function recordsFromStore(raw: unknown): IssueRecord[] | null {
  const o = raw !== null && typeof raw === 'object' && !Array.isArray(raw) ? (raw as Record<string, unknown>) : null
  if (o === null || o.v !== 1 || !Array.isArray(o.records)) return null
  return o.records.map(recordOf).filter((r): r is IssueRecord => r !== null)
}

const isStr = (v: unknown): v is string => typeof v === 'string'
const isNum = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v)
const isInt = (v: unknown, min: number): v is number => typeof v === 'number' && Number.isInteger(v) && v >= min
const strOrNull = (v: unknown): v is string | null => v === null || typeof v === 'string'

// recordOf: one record as the store or an event holds it, every field checked; null when one does
// not read.
export function recordOf(raw: unknown): IssueRecord | null {
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) return null
  const o = raw as Record<string, unknown>
  const state = ISSUE_STATES.find(s => s === o.state)
  const resumeTo = o.resumeTo === null ? null : ISSUE_STATES.find(s => s === o.resumeTo)
  const step = o.step === null ? null : STEP_KINDS.find(s => s === o.step)
  const why = o.why === null ? null : CLOSED_WHYS.find(w => w === o.why)
  if (state === undefined || resumeTo === undefined || step === undefined || why === undefined) return null
  if (!isInt(o.issue, 1) || !isStr(o.life) || o.life === '' || !isInt(o.seq, 0) || !isNum(o.seqAt) || !isNum(o.since)) return null
  if (!isStr(o.branch) || o.branch === '' || !(o.pr === null || isInt(o.pr, 1)) || !strOrNull(o.head) || !strOrNull(o.approvedPatch) || !strOrNull(o.brief)) return null
  if (!isInt(o.attempt, 0) || typeof o.cut !== 'boolean' || !isInt(o.triages, 0) || !isInt(o.fixes, 0) || !isInt(o.round, 0)) return null
  if (!strOrNull(o.question) || !Array.isArray(o.notes) || !o.notes.every(isStr) || !strOrNull(o.prClosedAt)) return null
  // a record stored before the field carries no count: its life is read as a first one
  const lives = o.lives === undefined ? 1 : o.lives
  if (!isInt(lives, 1)) return null
  return {
    issue: o.issue,
    life: o.life,
    seq: o.seq,
    seqAt: o.seqAt,
    state,
    since: o.since,
    resumeTo,
    branch: o.branch,
    pr: o.pr as number | null,
    head: o.head,
    approvedPatch: o.approvedPatch,
    brief: o.brief,
    step,
    attempt: o.attempt,
    cut: o.cut,
    triages: o.triages,
    fixes: o.fixes,
    round: o.round,
    question: o.question,
    why,
    notes: [...o.notes],
    prClosedAt: o.prClosedAt,
    lives,
  }
}

// headsToStore and headsFromStore: the heads first seen, { v: 1, heads: { <sha>: { pr, at } } }.
export function headsToStore(heads: Record<string, HeadSeen>): { v: 1; heads: Record<string, HeadSeen> } {
  return { v: 1, heads }
}

export function headsFromStore(raw: unknown): Record<string, HeadSeen> | null {
  const o = raw !== null && typeof raw === 'object' ? (raw as Record<string, unknown>) : null
  const heads = o !== null && o.v === 1 && o.heads !== null && typeof o.heads === 'object' ? (o.heads as Record<string, unknown>) : null
  if (heads === null) return null
  const out: Record<string, HeadSeen> = {}
  for (const [sha, v] of Object.entries(heads)) {
    const h = v !== null && typeof v === 'object' ? (v as Record<string, unknown>) : null
    if (/^[0-9a-f]{7,64}$/.test(sha) && h !== null && isInt(h.pr, 1) && isNum(h.at)) out[sha] = { pr: h.pr, at: h.at }
  }
  return out
}

// --- leases (10.1) ------------------------------------------------------------------------------------

// The holder the loop leases a slot with: factory-loop:<N>:<life>.
export function holderOf(issue: number, life: string): string {
  return `factory-loop:${issue}:${life}`
}

const HOLDER = /^factory-loop:([1-9]\d*):([0-9a-z]+)$/

// leasesOf: the pool's leased slots from `treehouse status --json`, by holder: the loop finds its
// own by `factory-loop:<N>:<life>` and never infers an owner from a reflog. null when it does not
// read.
export function leasesOf(json: string): Lease[] | null {
  try {
    const list: unknown = JSON.parse(json)
    if (!Array.isArray(list)) return null
    const out: Lease[] = []
    for (const raw of list) {
      const w = raw !== null && typeof raw === 'object' ? (raw as Record<string, unknown>) : {}
      const lease = typeof w.lease_id === 'string' ? w.lease_id : ''
      if (lease === '' || typeof w.path !== 'string') continue
      const holder = typeof w.lease_holder === 'string' ? w.lease_holder : ''
      const m = HOLDER.exec(holder)
      out.push({
        path: w.path,
        lease,
        holder,
        issue: m?.[1] === undefined ? null : Number(m[1]),
        life: m?.[2] ?? null,
        status: typeof w.status === 'string' ? w.status : 'unknown',
        busy: Array.isArray(w.processes) && w.processes.length > 0,
      })
    }
    return out
  } catch {
    return null
  }
}

// --- the read cadence and order (2.4) ------------------------------------------------------------------

// readDue: a read is due when there is none, it is everyMs old, or something the loop knows
// changed what it read at or after it was taken (changedAt). The queue, issue and PR reads all
// take this one rule (2.4).
export function readDue(at: Ms | undefined, now: Ms, everyMs: Ms, changedAt: Ms): boolean {
  return at === undefined || now - at >= everyMs || changedAt >= at
}

// lastEnded: when the newest ledger entry `pick` takes ended; -Infinity when none has.
export function lastEnded(ledger: readonly LedgerEntry[], pick: (e: LedgerEntry) => boolean): Ms {
  return Math.max(-Infinity, ...ledger.flatMap(e => (pick(e) && e.endedAt !== null ? [e.endedAt] : [])))
}

// readOrder: the records' issues in the order GitHub reads take them: the merge queue's head, the
// other records in reviewing and merge-queue, parked records, then the other live ones. The
// queue's head is the merge-queue record whose step is `queue` with the oldest seqAt (9.1).
export function readOrder(records: readonly IssueRecord[]): number[] {
  const live = records.filter(r => r.state !== 'closed')
  const byAge = (a: IssueRecord, b: IssueRecord) => a.seqAt - b.seqAt || a.issue - b.issue
  const head = live.filter(r => r.state === 'merge-queue' && r.step === 'queue').sort(byAge)[0]
  const rank = (r: IssueRecord) => (r === head ? 0 : r.state === 'reviewing' || r.state === 'merge-queue' ? 1 : r.state === 'parked' ? 2 : 3)
  return [...new Set([...live].sort((a, b) => rank(a) - rank(b) || byAge(a, b)).map(r => r.issue))]
}

// --- one pass's v2 reads ---------------------------------------------------------------------------------

// The source modules' reads, a test's own in place of the real ones.
export type V2Readers = { prs: typeof readPrs; interventions: typeof readInterventions }
const READERS: V2Readers = { prs: readPrs, interventions: readInterventions }

export type ObserveV2Input = {
  io: Io
  rt: Runtime
  cache: V2Cache
  // observe's own run, which logs each command and runs it with the environment it is given
  run: (argv: string[], stdin?: string, timeoutMs?: number, env?: Record<string, string>) => Promise<{ exitCode: number; stdout: string; stderr: string }>
  state: State
  // the store's, as register.ts read it; undefined when it read none
  stored: V2Stored | undefined
  // `treehouse status --json` as observe read it this pass; null when it did not
  poolJson: string | null
  github: Cache['github']
  // the pass's read of the event log (observe.ts: the rebuild's week on the pass it ran, else the
  // facts read); none when the caller has none
  events?: readonly FactoryEvent[]
  // a GitHub backoff holds this pass's reads; limited: a rate limit met this pass ends them
  backoff: boolean
  limited: () => boolean
  readers?: V2Readers
}

const NOT_READ = (why: string): Source => ({ ok: false, at: null, error: why })

// observeV2: the State fields v2 reads (2.4), and the heads to keep. Its GitHub reads go in 2.4's
// order with budgets of their own: the PRs of the queue's head, then of the other records in
// reviewing and merge-queue (sources-prs.ts, at most K records), then the comments of parked
// records a person unparked; v1's issue reads before them took the records' issues first
// (observe.ts, readOrder).
export async function observeV2(input: ObserveV2Input): Promise<{ v2: V2State; heads: Record<string, HeadSeen> }> {
  const { rt, cache, state } = input
  const readers = input.readers ?? READERS
  const now = state.now
  const sources = {} as Record<V2SourceName, Source>
  const blocked = () => input.backoff || input.limited()
  // a shadow's own reads send their events to the sink, as observe mode's do (2.3)
  const run: SourceCtx['run'] =
    rt.config.planner === 'v2' ? (argv, stdin, t) => input.run(argv, stdin, t) : (argv, stdin, t) => input.run(argv, stdin, t, { ...rt.env, CALLUM_EVENTS_DIR: `${rt.loopDir}/sink-events` })

  // the records: the store's, else a rebuild from this device's transition events (3.3); none
  // when the store could not be read, which the planner reads as blind for them
  const stored = input.stored
  let records: IssueRecord[] = stored?.records ?? []
  let recordsFrom: V2State['recordsFrom'] = stored?.records !== null && stored?.records !== undefined ? 'store' : 'none'
  sources.store = stored?.error ? NOT_READ(stored.error) : { ok: true, at: now }
  if (recordsFrom === 'none' && !stored?.error && REBUILD_SQL !== null) {
    if (cache.rebuilt === null || now - cache.rebuilt.at >= rt.config.githubEveryMs) {
      try {
        const argv = ['dev-query', '--csv', '-v', `repo=${rt.repo}`, '-v', `device=${rt.device}`, '-v', `at=${new Date(now).toISOString()}`, '-v', `days=${REBUILD_DAYS}`]
        const r = await run(argv, REBUILD_SQL)
        if (r.exitCode === 0) {
          const events: FactoryEvent[] = eventsFromRows(parseCsv(r.stdout))
          cache.rebuilt = { at: now, records: recordsFromEvents(events, rt.device) }
        } else {
          sources.store = { ok: false, at: cache.rebuilt?.at ?? null, error: `the rebuild's read failed: exit ${r.exitCode}` }
        }
      } catch (err) {
        sources.store = { ok: false, at: cache.rebuilt?.at ?? null, error: `the rebuild's read failed: ${String(err).slice(0, 200)}` }
      }
    }
    if (cache.rebuilt !== null && cache.rebuilt.records.length > 0) {
      records = cache.rebuilt.records
      recordsFrom = 'events'
    }
  }

  // the newest read of each issue observe holds
  const reads: Record<number, IssueRead> = {}
  for (const [n, c] of input.github) reads[n] = { at: c.at, open: c.value.facts?.open ?? null, labels: c.value.facts?.labels ?? null }

  // the leases, by holder
  const leases = input.poolJson === null ? null : leasesOf(input.poolJson)
  sources.leases = leases === null ? NOT_READ(input.poolJson === null ? 'the pool was not read' : 'treehouse status did not read') : { ok: true, at: now }

  // the PRs first: the queue's head, then reviewing and merge-queue, at most K records (2.4); a
  // view stands until its read is due: prEveryMs, or its record's transition or an action of the
  // loop's own on its PR since
  const heads = input.stored?.heads ?? cache.heads
  const kept = cache.prs.prs.filter(v => {
    const r = records.find(x => x.issue === v.issue)
    return r !== undefined && !readDue(v.readAt, now, rt.config.prEveryMs, Math.max(r.seqAt, lastEnded(state.ledger, e => e.pr === v.pr)))
  })
  const ctx: SourceCtx = {
    now,
    rt,
    run,
    readFile: input.io.readFile,
    state,
    records,
    heads,
    prBudget: blocked() ? 0 : (rt.config.maxInFlightIssues ?? rt.poolSize),
    limited: input.limited,
    unread: cache.prs.unread ?? [],
    kept,
  }
  const prs = await readers.prs(ctx)
  sources.prs = prs.source
  cache.heads = prs.heads
  cache.prs = prs.read
  cache.changed = {}
  for (const p of prs.read.prs) if (p.state !== 'open' && p.closedAt !== null) cache.changed[p.issue] = Date.parse(p.closedAt)

  // then parked records whose label a read newer than their park lacks: their trusted comments,
  // once per read, for the resume's note (11)
  const comments: Record<number, IssueComment[]> = {}
  let commentsOk = true
  for (const r of records.filter(x => x.state === 'parked')) {
    const read = reads[r.issue]
    if (read === undefined || read.at <= r.since || read.labels === null || read.labels.includes(FACTORY_LABELS.parked.name)) continue
    const kept = cache.comments.get(r.issue)
    if (kept !== undefined && kept.readAt === read.at) {
      comments[r.issue] = kept.comments
      continue
    }
    if (blocked()) {
      commentsOk = false
      continue
    }
    try {
      const c = await run(['callum-flow-issue-read', '--json', String(r.issue), '--comments'])
      const parsed = c.exitCode === 0 ? commentsOf(c.stdout) : null
      if (parsed === null) commentsOk = false
      else {
        cache.comments.set(r.issue, { readAt: read.at, comments: parsed })
        comments[r.issue] = parsed
      }
    } catch {
      commentsOk = false
    }
  }
  for (const n of [...cache.comments.keys()]) if (!records.some(r => r.issue === n && r.state === 'parked')) cache.comments.delete(n)
  sources.comments = commentsOk ? { ok: true, at: now } : NOT_READ(blocked() ? 'GitHub rate limit' : 'a comment read failed')

  const facts = await readers.interventions({ ...ctx, heads: prs.heads })
  sources.interventions = facts.source

  // dual write (4.1): act mode with the v2 planner only, once per load; a failed read retries when due
  let dualWrite: V2State['dualWrite'] = null
  sources.dualWrite = { ok: true, at: now }
  if (rt.mode === 'act' && rt.config.planner === 'v2') {
    if (cache.dualWrite === null || (cache.dualWrite.read.error !== null && now - cache.dualWrite.at >= rt.config.githubEveryMs)) {
      cache.dualWrite = { at: now, read: await readDualWrite(ctx) }
    }
    dualWrite = cache.dualWrite.read.dualWrite
    if (cache.dualWrite.read.error !== null) sources.dualWrite = { ok: false, at: null, error: cache.dualWrite.read.error }
  }

  // the tripwire's base moves only past a read with nothing left untold (10.7)
  cache.checkoutBase = checkoutBaseOf(cache.checkoutBase, state.checkout, state.ledger, now)
  // the workspace rail: does the companion run in this session and process (10.9)
  const workspace = rt.workspace === undefined ? undefined : await readWorkspace(input.io, rt.loopDir, rt.workspace.session, rt.workspace.process, now)
  const v2: V2State = {
    sources,
    records,
    recordsFrom,
    heads: prs.heads,
    leases: leases ?? [],
    reads,
    comments,
    prs: prs.read,
    changed: cache.changed,
    interventions: { ...facts.read, seen: stored?.files ?? null },
    logged: [...new Set((input.events ?? []).flatMap(e => (e.device === null || e.device === rt.device ? (onceKey(e) ?? []) : [])))],
    checkoutBase: cache.checkoutBase,
    dualWrite,
  }
  if (workspace !== undefined) v2.workspace = workspace
  return { v2, heads: prs.heads }
}

// commentsOf: the trusted comments of `callum-flow-issue-read --json N --comments`, oldest first;
// null when it does not read.
export function commentsOf(json: string): IssueComment[] | null {
  try {
    const list: unknown = (JSON.parse(json) as { comments?: unknown }).comments
    if (!Array.isArray(list)) return null
    const out: IssueComment[] = []
    for (const raw of list) {
      const c = raw !== null && typeof raw === 'object' ? (raw as Record<string, unknown>) : {}
      const at = typeof c.created_at === 'string' ? Date.parse(c.created_at) : Number.NaN
      if (typeof c.body !== 'string' || Number.isNaN(at)) continue
      out.push({ body: c.body, at, url: typeof c.html_url === 'string' ? c.html_url : null })
    }
    return out.sort((a, b) => a.at - b.at)
  } catch {
    return null
  }
}

// emptyV2State: a V2State with nothing read, for a state built outside a pass (the replay harness).
export function emptyV2State(now: Ms, records: IssueRecord[] = []): V2State {
  const off: Source = { ok: false, at: null, error: 'not read' }
  return {
    sources: { store: { ok: true, at: now }, leases: off, prs: off, interventions: off, comments: off, dualWrite: { ok: true, at: now } },
    records,
    recordsFrom: records.length > 0 ? 'store' : 'none',
    heads: {},
    leases: [],
    reads: {},
    comments: {},
    prs: { prs: [] },
    changed: {},
    interventions: { companion: [], controlDigest: null, configDigest: null },
    logged: [],
    checkoutBase: null,
    dualWrite: null,
  }
}

files.hooks/v2/ops.ts:
// The owner ops under planner v2 (docs/factory-loop/v2/SPEC.md appendix E, 7.2, 11): `resume
// <N...> ["note"]` unparks (P1) and takes no run id, `drop <N>` closes the record of the life it
// names (E1) and leaves the issue open, a resume of an issue that is not parked changes nothing,
// and an op that landed with v2 acting before or after it is a person intervention. control.ts delegates to these when
// planner v2 is in force, and register.ts asks parkedOf and opLanded; v1's meanings stay in
// control.ts until the delete wave. Pure.
import type { Op } from '../control'
import type { Control, Mode, Ms } from '../types'
import type { OpLanded } from './act-events'
import type { IssueRecord, Planner } from './types'

// v2's resume: unpark these issues, with the note for their next step (11, P1).
export type Unpark = { op: 'unpark'; issues: number[]; note: string | null }

// What an op changes in control.json, and the line it answers.
export type V2Applied = { patch: Partial<Control>; text: string }

// parseUnpark: `resume <N...> ["note"]` after the op name: one or more issue numbers, then the note,
// if any, in double quotes; why not, when it does not read.
export function parseUnpark(rest: string, issueOf: (word: string) => number | null, noteMax: number): Unpark | string {
  const m = /^([^"]*?)\s*(?:"(.*)")?\s*$/s.exec(rest)
  const items = (m?.[1] ?? '').split(/[\s,]+/).filter(w => w !== '')
  const issues = items.map(issueOf)
  if (m === null || items.length === 0 || issues.some(n => n === null)) return 'under planner v2, takes issue numbers and an optional note in double quotes'
  const note = (m[2] ?? '').trim()
  if (note.length > noteMax) return `the note is at most ${noteMax} characters`
  return { op: 'unpark', issues: [...new Set(issues as number[])], note: note === '' ? null : note }
}

// onlyParked: the resume narrowed to the issues parked now (parked: as the last pass's records say;
// null when not known, which keeps them all), with a line for each one left out; refused when
// none is parked.
export function onlyParked(op: Unpark, parked: readonly number[] | null | undefined): { op: Unpark; aside: string } | { refused: string } {
  if (parked === undefined || parked === null) return { op, aside: '' }
  const not = op.issues.filter(n => !parked.includes(n))
  const notes = not.map(n => `#${n} is not parked; use /factory note ${n}.`).join(' ')
  if (not.length === op.issues.length) return { refused: `Not changed: ${notes}` }
  return { op: { ...op, issues: op.issues.filter(n => parked.includes(n)) }, aside: not.length === 0 ? '' : ` ${notes}` }
}

// applyUnpark: the resumes control.json records, each with the note.
export function applyUnpark(control: Control, op: Unpark, now: Ms): V2Applied {
  const resumed = op.issues.map(n => (op.note === null ? { subject: `issue:${n}`, at: now } : { subject: `issue:${n}`, at: now, note: op.note }))
  const noted = op.note === null ? '' : ', with your note for its next step'
  return { patch: { resumed: [...control.resumed, ...resumed] }, text: `Resumed ${tagsOf(op.issues)}: back to queued, then on from where it parked${noted}.` }
}

// applyDrop: a drop applies to the life it closes, so a drop of an issue claimed again since is
// recorded again (4.1).
export function applyDrop(control: Control, issue: number, now: Ms): V2Applied {
  return {
    patch: { dropped: [...control.dropped.filter(d => d.issue !== issue), { issue, at: now }] },
    text: `Dropped #${issue}: its record closes and its factory labels go; the issue stays open, and adding ready brings it back.`,
  }
}

// parkedOf: the issues parked now, as the last pass's records say, under planner v2; null otherwise
// or when no pass read them.
export function parkedOf(planner: Planner, records: readonly IssueRecord[] | undefined): number[] | null {
  return planner === 'v2' && records !== undefined ? records.filter(r => r.state === 'parked').map(r => r.issue) : null
}

// The planner and the mode in force.
export type InForce = { planner: Planner; mode: Mode }

// opLanded: an op that landed (logged) with planner v2 in act mode in force before it or after it,
// as the person intervention act-events.ts logs (7.2): its text, its name and the issues it names;
// null for any other. The op's own effect counts, so the ops that turn the loop on (`mode act`,
// `planner v2`) and off are logged too.
export function opLanded(before: InForce, op: Op, logged: string | null, issues: readonly number[], at: Ms): OpLanded | null {
  const after: InForce = { planner: op.op === 'planner' ? op.planner : before.planner, mode: op.op === 'mode' ? op.mode : before.mode }
  const acts = (s: InForce) => s.planner === 'v2' && s.mode === 'act'
  if (logged === null || !(acts(before) || acts(after))) return null
  return { text: logged, name: logged.split(' ')[0] ?? '', issues: [...issues], at }
}

function tagsOf(issues: readonly number[]): string {
  return issues.map(n => `#${n}`).join(' ')
}

