// The record's rules (docs/factory-loop/v2/SPEC.md 3, 4, 5, 11, 14.1): H1 renews and re-claims
// (rules-claim.ts); for each record, S3 plans its seq's entry actions (rules-entry.ts), then the
// one event that changes it this pass, the first present in 4.1's order (pr-merged, issue-closed,
// claim-lost, drop, pr-closed, the step's result, unpark), through the table (table.ts rowFor): a
// changing row is one `transition` action (S3 for a step result, S4 the unknown path, S5 triage,
// S6 the owner's and GitHub's events), and the rows that change nothing (E6's tell, E7's log line)
// run beside it and never stop it; S2 starts the record's step through its plan when nothing else
// takes the record (rules-agent.ts, and each unit's own step plans); then S0 and S1 make records
// and claim new work (rules-claim.ts). And O1's counts, which the title and the decision log show.
//
// - A running step past its timeout is unknown (timeout), in every state; a waiting record's
//   timeout is its tell period (E6); a held step has no clock (4.4).
// - GitHub events are edges (4.1): pr-closed compares GitHub's closedAt with the record's
//   prClosedAt, a drop and an unpark compare the op's time with the life's claim and the park.
// - 4.1's order holds across sources: the PRs are read every pass, the issue less often, so a
//   PR's close waits for a read of its issue made after it (observe makes that read due), and an
//   issue closed with its PR closes rather than parks.
// - The next transition waits until the seq's `transition` event is logged (3.3), and an effect
//   that used up its attempts holds the record's step (4.5).
// - Every record that is not closed ends a pass with a running step, a planned action or a skip
//   line naming why it waits (property 3).
//
// Pure: the time is state.now.
import { skip, wake, want } from '../foundation'
import type { Ms } from '../types'
import { entryKey, lifeAt, transitionKey } from './keys'
import { agentPlan, causeOf, leaseOf, leaseStep, lifeEntries, notBuiltStep, triggerOf } from './rules-agent'
import type { StepPlan, StepRead } from './rules-agent'
import { claimRules, heartbeatRules, reclaimLost } from './rules-claim'
import { dualWriteRules } from './rules-dualwrite'
import { ensureActions, entryDone, entryItems, parkedTell, stalledOf, stalledTell, transitionLogged } from './rules-entry'
import type { EntryItem } from './rules-entry'
import { PLANS as QUEUE } from './rules-queue'
import { PLANS as REVIEW, lifePr } from './rules-review'
import { PLANS as WORK } from './rules-work'
import { mayHaveMerged } from './steps-queue'
import { nextRecord, normalize, rowFor, viaOf } from './table'
import { FACTORY_LABELS } from './types'
import { workspaceHold } from './workspace'
import type { IssueRecord, Row, StepKind, TableEvent, Trigger, V2Ctx } from './types'

const HOUR = 3_600_000
// The title's M: issues merged in this window (D-23).
const MERGED_WINDOW_MS = 6 * HOUR
const NOTE_MAX = 2000

// Each step's plan: the generic agent step and the lease here, each unit's own over them (U5's
// work steps, U6's review, U7's merge queue), triage always the generic agent step.
const PLANS: Readonly<Record<StepKind, StepPlan>> = {
  lease: leaseStep,
  design: agentPlan('design'),
  build: agentPlan('build'),
  fix: agentPlan('fix'),
  review: notBuiltStep('review', 'U6'),
  queue: notBuiltStep('queue', 'U7'),
  ...WORK,
  ...REVIEW,
  ...QUEUE,
  triage: agentPlan('triage'),
}

// An event present for a record this pass, and what its transition re-checks; wait: why the
// record holds instead, when an event before it in 4.1's order may not be read yet.
type Present = { event: TableEvent; trigger: Trigger; wait?: string }

const fact = (f: string): Trigger => ({ kind: 'fact', fact: f })

// ruleOf: the rule id a row's transition is planned under (14.1).
function ruleOf(row: Row): string {
  if (row.id === 'S0') return 'S1'
  if (row.id.startsWith('U')) return 'S4'
  if (row.id.startsWith('X')) return 'S5'
  return row.id.startsWith('T') ? 'S3' : 'S6'
}

function describe(e: TableEvent): string {
  const tail = e.choice ?? e.why ?? e.reason
  const text = `${e.kind}${tail === undefined ? '' : ` (${tail})`}`
  return text.length > 120 ? `${text.slice(0, 117)}...` : text
}

const sameSha = (a: string | null, b: string | null) => a !== null && b !== null && (a.startsWith(b) || b.startsWith(a))

// --- the owner's and GitHub's events (4.1) ---------------------------------------------------------------

// loopMerged: a queue-merge of this life merged, or may have (running or lost), at this head when
// one is given: the merge is the queue step's own result, never a hand merge (4.1). A refusal,
// done but not merged, is not one.
function loopMerged(ctx: V2Ctx, r: IssueRecord, head: string | null): boolean {
  return lifeEntries(ctx, r, 'queue-merge').some(e => mayHaveMerged(e) && (head === null || sameSha(e.head, head)))
}

// earlyEvents: the events present before the step's result, in 4.1's order.
function earlyEvents(ctx: V2Ctx, r: IssueRecord): Present[] {
  const out: Present[] = []
  const n = r.issue
  const born = lifeAt(r.life) ?? 0
  // the life's PR: the record's, else the one the review step's ensure named (8.1), so a PR merged
  // or closed by hand during its first review round is seen too
  const known = lifePr(ctx.state.ledger, r)
  const pr = known === null ? undefined : ctx.v2.prs.prs.find(p => p.pr === known)
  if (pr?.state === 'merged' && !loopMerged(ctx, r, pr.mergedHead)) {
    out.push({ event: { kind: 'pr-merged', data: { pr: pr.pr, ...(pr.mergedHead === null ? {} : { head: pr.mergedHead }) } }, trigger: fact(`pr-merged:${pr.pr}@${pr.mergedHead ?? 'unknown'}`) })
  }
  const read = ctx.v2.reads[n]
  const closedByLoop = loopMerged(ctx, r, null) || ctx.state.ledger.some(e => e.kind === 'close-issue' && e.issue === n && e.startedAt >= born && e.status !== 'failed')
  if (read !== undefined && read.open === false && read.at > born && !closedByLoop) out.push({ event: { kind: 'issue-closed' }, trigger: fact(`issue-closed:${n}@${read.at}`) })
  const lost = reclaimLost(ctx, r)
  if (lost !== null) out.push({ event: { kind: 'claim-lost', reason: lost.summary ?? 'another device holds a live claim' }, trigger: triggerOf(lost) })
  const drop = ctx.state.control.dropped.filter(d => d.issue === n && d.at > born).sort((a, b) => a.at - b.at).at(-1)
  if (drop !== undefined) out.push({ event: { kind: 'drop' }, trigger: fact(`drop:${n}@${drop.at}`) })
  if (pr?.state === 'closed' && pr.closedAt !== null && (r.prClosedAt === null || pr.closedAt > r.prClosedAt)) {
    const since = ctx.v2.changed[n]
    const wait = since !== undefined && (read === undefined || read.at <= since) ? { wait: `issue #${n} is not read since PR #${pr.pr} closed` } : {}
    out.push({ event: { kind: 'pr-closed', data: { pr: pr.pr, closedAt: pr.closedAt } }, trigger: fact(`pr-closed:${pr.pr}@${pr.closedAt}`), ...wait })
  }
  return out
}

// unparkOf: a parked record's unpark (4.1, 11): a `/factory resume N` newer than the park, with
// its note; or a read of the issue made after the park's label write that lacks `factory:parked`,
// with the trusted comments posted after the park's comment as the note. 'wait': the label is
// gone, but those comments are not read yet.
function unparkOf(ctx: V2Ctx, r: IssueRecord): Present | 'wait' | null {
  const n = r.issue
  const pr = r.pr === null ? undefined : ctx.v2.prs.prs.find(p => p.pr === r.pr)
  const closedAt = pr?.state === 'closed' && pr.closedAt !== null ? { closedAt: pr.closedAt } : {}
  const ops = ctx.state.control.resumed.filter(x => x.subject === `issue:${n}` && x.at > r.since).sort((a, b) => a.at - b.at)
  const op = ops.at(-1)
  if (op !== undefined) {
    const note = ops.flatMap(x => (x.note === undefined ? [] : [x.note])).join('\n')
    return { event: { kind: 'unpark', reason: 'op', data: { ...closedAt, ...(note === '' ? {} : { note: clip(note) }) } }, trigger: fact(`unpark:${n}@${op.at}`) }
  }
  const label = ctx.byKey.get(entryKey(r, 'label'))
  const read = ctx.v2.reads[n]
  if (label?.status !== 'done' || label.endedAt === null || read === undefined || read.at <= label.endedAt || read.labels === null) return null
  if (read.labels.some(l => l.toLowerCase() === FACTORY_LABELS.parked.name)) return null
  const comments = ctx.v2.comments[n]
  if (comments === undefined) return 'wait'
  const after = ctx.byKey.get(entryKey(r, 'comment'))?.endedAt ?? r.since
  const note = comments
    .filter(c => c.at > after && !c.body.includes('<!-- factory-loop:'))
    .map(c => c.body.trim())
    .join('\n\n')
  return { event: { kind: 'unpark', reason: 'label', data: { ...closedAt, ...(note === '' ? {} : { note: clip(note) }) } }, trigger: fact(`unpark-label:${n}@${read.at}`) }
}

function clip(text: string): string {
  return text.length > NOTE_MAX ? `${text.slice(0, NOTE_MAX - 3)}...` : text
}

// --- E6: the waiting states' tells (4.4) ---------------------------------------------------------------

// periodOf: a waiting state's tell period: queued, the merge queue behind its head, parked.
function periodOf(ctx: V2Ctx, r: IssueRecord): Ms {
  const t = ctx.config.stateTimeoutMs
  return r.state === 'parked' ? t.parked : r.state === 'queued' ? t.queued : t.queueWait
}

// waitTell: E6, once per period: tell(waiting), or tell(parked) as the daily reminder (an owner
// item, counted once per record).
function waitTell(ctx: V2Ctx, r: IssueRecord, why: string): void {
  const k = Math.floor((ctx.state.now - r.since) / periodOf(ctx, r))
  if (k < 1) return
  if (r.state === 'parked') {
    want(ctx, parkedTell(r, k))
    ctx.owner.delete(entryKey(r, 'tell'))
    return
  }
  const hours = Math.floor((ctx.state.now - r.since) / HOUR)
  want(ctx, wake('tell', 'waiting', `${entryKey(r, 'tell')}/waiting/${k}`, 'S6', r.issue, { issue: r.issue, state: r.state, hours }, [why]))
}

// --- one record ----------------------------------------------------------------------------------------------

// take: the row for this event. A changing row plans its transition, once the seq's transition
// event is logged; E6 tells and E7 logs, and neither stops the next event. True when the record
// is taken this pass.
function take(ctx: V2Ctx, r: IssueRecord, p: Present, logged: boolean, why: string): boolean {
  const row = rowFor(r, p.event, ctx.config)
  if (row.id === 'E7') {
    skip(ctx, 'S6', r.issue, `E7: ${describe(p.event)} means nothing in ${r.state}${r.step === null ? '' : `/${r.step}`}`)
    return false
  }
  if (row.id === 'E6') {
    waitTell(ctx, r, why)
    return false
  }
  const rule = ruleOf(row)
  if (!logged || p.wait !== undefined) {
    skip(ctx, rule, r.issue, `${row.id} waits: ${p.wait ?? `the transition event of seq ${r.seq} is not logged yet`}`)
    return true
  }
  const ev = normalize(r, p.event)
  const next = nextRecord(r, row, p.event, ctx.state.now)
  const key = transitionKey(next)
  const g = want(ctx, {
    kind: 'transition',
    key,
    class: 'free',
    rule,
    reason: `${row.id}: ${describe(ev)}`,
    issue: r.issue,
    row: row.id,
    event: p.event.kind,
    from: { issue: r.issue, life: r.life, seq: r.seq },
    fromState: r.state,
    fromStep: r.step,
    next,
    trigger: p.trigger,
    cause: ev.cause ?? null,
    via: viaOf(row, ev),
  })
  if (g === 'exhausted') {
    const e = ctx.byKey.get(key)
    skip(ctx, rule, r.issue, `stalled: ${key}: ${e?.summary ?? 'used up its attempts'}`)
    want(ctx, stalledTell(r, key, e?.summary ?? 'used up its attempts', e?.endedAt ?? 0))
  }
  return true
}

// stepRead: the record's step this pass, through its plan.
function stepRead(ctx: V2Ctx, r: IssueRecord, start: boolean, hold: string | null): StepRead | null {
  if (r.step === null) return null
  return PLANS[r.step]({ ctx, r, slot: leaseOf(ctx, r), start, hold })
}

function recordRules(ctx: V2Ctx, r: IssueRecord, items: readonly EntryItem[]): void {
  const { state } = ctx
  const n = r.issue
  const mark = { out: ctx.out.length, skipped: ctx.skipped.length }
  for (const item of items) {
    // a best-effort action that ended is done with, however it ended
    const e = item.soft ? ctx.byKey.get(item.action.key) : undefined
    if (e === undefined || e.status === 'running') want(ctx, item.action)
  }
  const stalled = stalledOf(ctx, r)
  if (stalled !== null) {
    skip(ctx, 'S3', n, `stalled: ${stalled.key}: ${stalled.error}`)
    want(ctx, stalledTell(r, stalled.key, stalled.error, stalled.at))
  }
  if (r.state === 'closed') return
  const logged = transitionLogged(ctx, r)
  for (const p of earlyEvents(ctx, r)) if (take(ctx, r, p, logged, '')) return
  let running = false
  if (r.state === 'parked') {
    if (state.now - r.since >= periodOf(ctx, r)) take(ctx, r, { event: { kind: 'timeout' }, trigger: fact(`parked:${n}`) }, logged, 'parked')
    const u = unparkOf(ctx, r)
    if (u === 'wait') skip(ctx, 'S6', n, 'unpark: the label is off; waits for the trusted comments to be read')
    else if (u === null) skip(ctx, 'S6', n, 'parked: waits on the owner')
    else take(ctx, r, u, logged, '')
  } else {
    const hold = !logged ? `its transition event of seq ${r.seq} is not logged yet` : stalled !== null ? `stalled: ${stalled.key}` : !entryDone(ctx, items) ? 'its entry actions run first' : workspaceHold(ctx, r.step)
    const read = stepRead(ctx, r, hold === null, hold)
    if (read?.kind === 'running') {
      running = true
      if (state.now - read.since > read.timeoutMs) {
        const entry = ctx.byKey.get(read.key) ?? null
        const reason = `${r.step ?? 'the step'} ran past its ${Math.round(read.timeoutMs / 60_000)} min`
        // a running step's timeout is its unknown, whatever the state: E6's tell is only for a
        // record that waits (below), so a hung merge-queue head takes U1 to U4 (4.3, 4.4)
        const event: TableEvent = { kind: 'unknown', why: 'timeout', reason, cause: causeOf(ctx, r, entry, 'timeout') ?? undefined }
        take(ctx, r, { event, trigger: entry === null ? fact(`timeout:${read.key}`) : triggerOf(entry) }, logged, '')
      }
    } else if (read?.kind === 'result') {
      if (stalled === null) take(ctx, r, { event: read.event, trigger: read.trigger }, logged, '')
    } else if (read?.kind === 'waiting') {
      if (state.now - r.since >= periodOf(ctx, r)) take(ctx, r, { event: { kind: 'timeout' }, trigger: fact(`waiting:${n}`) }, logged, read.why)
      skip(ctx, 'S2', n, read.why)
    } else if (read?.kind === 'held' && read.why !== '') {
      skip(ctx, r.step === 'triage' ? 'S5' : 'S2', n, read.why)
    }
  }
  // property 3: no record is silent
  const acted = ctx.out.slice(mark.out).some(a => a.issue === n)
  const said = ctx.skipped.slice(mark.skipped).some(s => s.issue === n)
  if (!acted && !said && !running) skip(ctx, 'S2', n, `${r.state}${r.step === null ? '' : `/${r.step}`}: its planned work runs`)
}

// stateRules: H1, then each record (S2 to S6), then S0 and S1. The seven labels are made first on a
// pass that writes one (3.4).
export function stateRules(ctx: V2Ctx): void {
  heartbeatRules(ctx)
  dualWriteRules(ctx)
  const records = [...ctx.v2.records].sort((a, b) => a.issue - b.issue || (lifeAt(a.life) ?? 0) - (lifeAt(b.life) ?? 0))
  const items = records.map(r => entryItems(ctx, r, leaseOf(ctx, r)))
  const labels = items.some(list => list.some(i => i.action.kind === 'label' && ctx.byKey.get(i.action.key)?.status !== 'done'))
  if (labels) for (const a of ensureActions(ctx)) want(ctx, a)
  records.forEach((r, i) => recordRules(ctx, r, items[i] ?? []))
  claimRules(ctx)
}

// The records by where they are: queued, in flight (designing to merge-queue) and parked.
export type StateCounts = { queued: number; flight: number; parked: number }

export function stateCounts(records: readonly IssueRecord[]): StateCounts {
  const out: StateCounts = { queued: 0, flight: 0, parked: 0 }
  for (const r of records) {
    if (r.state === 'queued') out.queued += 1
    else if (r.state === 'parked') out.parked += 1
    else if (r.state !== 'closed') out.flight += 1
  }
  return out
}

// stateTitle: the title's counts, Q (the ready queue and the queued records), D (in flight) and M
// (merged in the last 6 hours), and its words of the layer's own: parked <n>.
export function stateTitle(ctx: V2Ctx): { counts: string; after: string[] } {
  const c = stateCounts(ctx.v2.records)
  const merged = ctx.v2.records.filter(r => r.state === 'closed' && (r.why === 'merged' || r.why === 'merged-by-hand') && ctx.state.now - r.since <= MERGED_WINDOW_MS).length
  return { counts: `Q:${ctx.state.queue.length + c.queued} - D:${c.flight} - M:${merged}`, after: c.parked > 0 ? [`parked ${c.parked}`] : [] }
}

files.hooks/v2/settings.ts:
// The repo-local settings under planner v2 (docs/factory-loop/v2/SPEC.md section 15, "Both settings
// files are read every pass; the workspace file may set any key"): nothing in v2 keeps the main
// checkout current, so the repo's .claude/factory-loop.json is read from origin's default branch
// with `git show`, again every githubEveryMs. When that branch cannot be read, the main checkout's
// file stands, and the decision log's config problems say so: settings are never silently stale.
// register.ts calls repoLoaded once per runtime read, with its own cache.
import { loadConfig } from '../config'
import type { LoadedConfig } from '../config'
import type { Ms } from '../types'

const FILE = '.claude/factory-loop.json'
// origin/HEAD is not always set (a clone made with --single-branch, or by hand); then main
const FALLBACK_REF = 'origin/main'
const GIT_TIMEOUT_MS = 10_000
const ERROR_MAX = 200

export type SettingsIo = {
  run: (argv: string[], opts: { cwd: string; timeoutMs: number }) => Promise<{ exitCode: number; stdout: string; stderr: string }>
  now: () => Promise<Ms>
}

// What origin's default branch gave: its file's settings ({} when it has none), or why it could
// not be read.
export type OriginRead = { ok: true; raw: Record<string, unknown> } | { ok: false; error: string }

// The last read, kept by the caller between passes.
export type SettingsCache = { value: { at: Ms; checkout: string; read: OriginRead } | null }

export function newSettingsCache(): SettingsCache {
  return { value: null }
}

// defaultRef: origin's default branch as a ref (origin/main), from origin/HEAD, else main.
async function defaultRef(io: SettingsIo, checkout: string): Promise<string> {
  try {
    const r = await io.run(['git', 'symbolic-ref', '--quiet', '--short', 'refs/remotes/origin/HEAD'], { cwd: checkout, timeoutMs: GIT_TIMEOUT_MS })
    const ref = r.stdout.trim()
    return r.exitCode === 0 && /^origin\/[\w./-]+$/.test(ref) ? ref : FALLBACK_REF
  } catch {
    return FALLBACK_REF
  }
}

// originSettings: the repo-local settings file as origin's default branch holds it, read again
// every everyMs.
export async function originSettings(io: SettingsIo, cache: SettingsCache, checkout: string, everyMs: Ms): Promise<OriginRead> {
  const now = await io.now()
  const kept = cache.value
  if (kept !== null && kept.checkout === checkout && now - kept.at < everyMs) return kept.read
  const ref = await defaultRef(io, checkout)
  let read: OriginRead
  try {
    const r = await io.run(['git', 'show', `${ref}:${FILE}`], { cwd: checkout, timeoutMs: GIT_TIMEOUT_MS })
    if (r.exitCode === 0) read = { ok: true, raw: objectOf(r.stdout) }
    else if (/does not exist in|exists on disk, but not in/.test(r.stderr)) read = { ok: true, raw: {} }
    else read = { ok: false, error: `${ref}: ${firstLine(r.stderr) || `exit ${r.exitCode}`}` }
  } catch (err) {
    read = { ok: false, error: `${ref}: ${firstLine(err instanceof Error ? err.message : String(err))}` }
  }
  cache.value = { at: now, checkout, read }
  return read
}

// repoLoaded: the repo-local file (the checkout's, tree) under the workspace file's keys (over),
// with what that file says (raw). Under planner v2 the file is origin's, or, when origin's branch
// cannot be read, the main checkout's stands, with a problem that names it and no raw.
export async function repoLoaded(io: SettingsIo, cache: SettingsCache, checkout: string, tree: Record<string, unknown>, over: Record<string, unknown>): Promise<LoadedConfig & { raw: Record<string, unknown> | null }> {
  const fromTree = loadConfig(tree, over)
  if (fromTree.config.planner !== 'v2') return { ...fromTree, raw: tree }
  const read = await originSettings(io, cache, checkout, fromTree.config.githubEveryMs)
  if (read.ok) return { ...loadConfig(read.raw, over), raw: read.raw }
  return { ...fromTree, problems: [...fromTree.problems, `settings: origin's default branch not read (${read.error}); the main checkout's file is used`], raw: null }
}

function objectOf(text: string): Record<string, unknown> {
  try {
    const v: unknown = JSON.parse(text)
    return v !== null && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : {}
  } catch {
    return {}
  }
}

function firstLine(text: string): string {
  const line = text.trim().split('\n')[0] ?? ''
  return line.length > ERROR_MAX ? `${line.slice(0, ERROR_MAX - 3)}...` : line
}

files.hooks/v2/store.ts:
// v2's store keys in the pass driver (docs/factory-loop/v2/SPEC.md 2.3, 2.4, 3.3, 7.2): the records
// (records:<repo>), the PR heads first seen (heads:<repo>) and the owner's files as the loop last
// read or wrote them (files:<repo>, sources-interventions.ts), kept in memory beside the ledger as
// the ledger is. register.ts holds one V2Live and the engine; each function here is one call from
// it: loadV2 with the ledger, storedV2 and readStoredV2 for observe, keepV2 after it, v2IoOf for
// the transition executor (ActIo.v2), and for the owner's files notingIo with noteWritten (an op's
// writes, the clearing of a done update), noteKillSwitch (a pass that found the OFF file) and
// noteIdle (each tick: the settings as the loop read them while it did not act).
//
// - A read keeps three cases apart: the store could not be read (or holds no stored records under
//   the key), so nothing is loaded and v2 plans nothing that releases or starts (v2/plan.ts); the
//   key is absent, so a rebuild from events may fill it (3.3); and stored records, an empty list
//   included, which are the truth.
// - A record change is kept in memory only once the store took it: a write that fails leaves both
//   at the old seq, so the transition executor's compare finds the record where the store has it
//   and its retry stores the new seq (3.3).
import type { FileIo } from '../control'
import type { Runtime } from '../observe'
import type { LedgerEntry, Ms, State } from '../types'
import { headsFromStore, headsKey, headsToStore, recordsFromStore, recordsKey, recordsToStore } from './observe'
import type { V2Stored } from './observe'
import { EMPTY_FILES, baseOf, filesFromStore, filesKey, keepFiles, seenOf } from './sources-interventions'
import type { FileSeen, FilesSeen } from './sources-interventions'
import { editOf } from './rules-interventions'
import type { HeadSeen, IssueRecord, V2Io } from './types'

const ERROR_MAX = 200

// The store as the driver gives it: get throws when the store cannot be read.
export type V2StoreIo = {
  get: (key: string) => Promise<unknown>
  set: (key: string, value: unknown) => Promise<void>
  now: () => Promise<Ms>
}

// The live records and heads of an acting session.
export type V2Live = {
  repo: string
  records: IssueRecord[]
  // the key held nothing at the load, and nothing was written since: a rebuild may fill it
  absent: boolean
  heads: Record<string, HeadSeen> | null
  // files:<repo>, kept whether or not the records are loaded
  files: FilesSeen | null
  // the workspace config.json as the newest tick that did not act under planner v2 read it, in
  // memory only (noteIdle); null once an acting tick has kept it
  idle: { repo: string; seen: FileSeen } | null
  loaded: boolean
  // why the records are not loaded: the store's read failed, or the key holds no stored records
  error: string | null
}

export function newV2Live(): V2Live {
  return { repo: '', records: [], absent: true, heads: null, files: null, idle: null, loaded: false, error: 'not loaded yet' }
}

// What a read of records:<repo> gave.
type RecordsRead = { ok: true; records: IssueRecord[] | null } | { ok: false; error: string }

async function readRecords(io: V2StoreIo, repo: string): Promise<RecordsRead> {
  const key = recordsKey(repo)
  let raw: unknown
  try {
    raw = await io.get(key)
  } catch (err) {
    return { ok: false, error: `${key} could not be read: ${message(err)}` }
  }
  if (raw === undefined || raw === null) return { ok: true, records: null }
  const records = recordsFromStore(raw)
  return records === null ? { ok: false, error: `${key} holds no stored records: fix or remove it` } : { ok: true, records }
}

async function readHeads(io: V2StoreIo, repo: string): Promise<Record<string, HeadSeen> | null> {
  try {
    return headsFromStore(await io.get(headsKey(repo)))
  } catch {
    // the heads only bound waits: a failed read starts them afresh
    return null
  }
}

async function readFiles(io: V2StoreIo, repo: string): Promise<FilesSeen | null> {
  try {
    return filesFromStore(await io.get(filesKey(repo)))
  } catch {
    // a failed read keeps nothing: the next acting read keeps what it reads
    return null
  }
}

// loadV2: the store's records, heads and files into the live copy, with the ledger (whose lease keeps
// them too) and again on any pass while they are not loaded.
export async function loadV2(live: V2Live, io: V2StoreIo, repo: string): Promise<void> {
  const read = await readRecords(io, repo)
  live.repo = repo
  live.heads = await readHeads(io, repo)
  live.files = await readFiles(io, repo)
  if (!read.ok) {
    live.records = []
    live.absent = false
    live.loaded = false
    live.error = read.error
    return
  }
  live.records = read.records ?? []
  live.absent = read.records === null
  live.loaded = true
  live.error = null
}

// storedV2: what an acting pass hands observe: the live copy, loaded again when it is not.
export async function storedV2(live: V2Live, io: V2StoreIo, repo: string): Promise<V2Stored> {
  if (!live.loaded || live.repo !== repo) await loadV2(live, io, repo)
  if (!live.loaded) return { records: null, heads: live.heads, files: live.files, error: live.error ?? 'not loaded' }
  return { records: live.absent ? null : live.records, heads: live.heads, files: live.files, error: null }
}

// readStoredV2: what a pass that does not act hands observe: the store's, read and never written
// (2.3).
export async function readStoredV2(io: V2StoreIo, repo: string): Promise<V2Stored> {
  const read = await readRecords(io, repo)
  const heads = await readHeads(io, repo)
  const files = await readFiles(io, repo)
  return read.ok ? { records: read.records, heads, files, error: null } : { records: null, heads, files, error: read.error }
}

// keepV2: what a pass acting under planner v2 keeps of v2's reads: the records a lost store was
// rebuilt into, as the ledger's are (3.3), the PR heads first seen (2.4), and the owner's files
// with the edits they show, to log (7.2, keepFiles). A shadow keeps nothing.
export async function keepV2(live: V2Live, heads: Record<string, HeadSeen> | null, state: State, keep: (key: string, value: unknown) => Promise<void>): Promise<void> {
  if (!live.loaded) return
  if (state.v2 !== undefined && state.v2.recordsFrom === 'events' && live.absent) {
    live.records = [...state.v2.records]
    live.absent = false
    await keep(recordsKey(state.repo), recordsToStore(live.records, state.now))
  }
  if (heads !== null && JSON.stringify(heads) !== JSON.stringify(live.heads ?? {})) {
    live.heads = heads
    await keep(headsKey(state.repo), headsToStore(heads))
  }
  const facts = state.v2?.interventions
  const logged = new Set(state.ledger.filter(e => e.status === 'done').map(e => e.key))
  const files = facts === undefined ? null : keepFiles(live.files, facts, state.now, key => logged.has(key))
  if (files !== null) {
    live.files = files
    await keep(filesKey(state.repo), files)
  }
}

// --- the owner's files between passes (7.2) -----------------------------------------------------------

// updateFiles: files:<repo> changed by fn (null: no change), in the live copy when it holds this
// repo (whose next save writes it), else read and written in the store. Never throws: this is the
// loop's bookkeeping, and an op or a pass that it serves goes on without it.
async function updateFiles(live: V2Live, io: V2StoreIo, repo: string, fn: (f: FilesSeen | null) => FilesSeen | null): Promise<void> {
  try {
    if (live.loaded && live.repo === repo) {
      const next = fn(live.files)
      if (next === null) return
      live.files = next
      await io.set(filesKey(repo), next)
      return
    }
    const next = fn(await readFiles(io, repo))
    if (next !== null) await io.set(filesKey(repo), next)
  } catch {
    // kept nowhere: the next acting read compares against the version before
  }
}

// A write of an owner's file: its path, the text it replaced (null: it could not be read) and the
// text written.
export type Written = (path: string, before: string | null, after: string) => Promise<void>

// notingIo: file writes that tell `note` what they replaced, once each has landed.
export function notingIo(io: FileIo, note: Written): FileIo {
  return {
    readFile: io.readFile,
    writeFile: async (path, body) => {
      let before: string | null
      try {
        before = (await io.readFile(path)) ?? ''
      } catch {
        before = null
      }
      await io.writeFile(path, body)
      await note(path, before, body).catch(() => undefined)
    },
  }
}

// noteWritten: the loop wrote an owner's file (an op, or the clearing of a done update): the
// version it wrote is the loop's own, and a change it found already there (what it replaced, against
// the version kept) is a person's edit, kept to log. Nothing is kept before the loop keeps any.
export function noteWritten(live: V2Live, io: V2StoreIo, rt: Pick<Runtime, 'repo' | 'loopDir'>): Written {
  return async (path, before, after) => {
    const part = path === `${rt.loopDir}/control.json` ? 'control' : path === `${baseOf(rt.loopDir)}/config.json` ? 'workspace' : null
    if (part === null) return
    // an op while the loop does not act (`mode act` among them) writes the version it reads next
    if (part === 'workspace' && live.idle !== null && live.idle.repo === rt.repo) live.idle = { repo: rt.repo, seen: seenOf(after) }
    const at = await io.now()
    await updateFiles(live, io, rt.repo, f => {
      if (f === null) return null
      const was = f[part]
      const edit = was === null || before === null ? null : editOf(part, was.text, before, at)
      return { ...f, [part]: seenOf(after), edits: edit === null ? f.edits : [...f.edits, edit] }
    })
  }
}

// noteKillSwitch: a pass found the OFF file. The loop never writes it, so under planner v2 in act
// mode its use is a person's edit, kept once to log until a pass acts again (keepFiles clears the
// flag). Returns whether the kill switch is on.
export async function noteKillSwitch(live: V2Live, io: V2StoreIo, rt: Pick<Runtime, 'repo' | 'mode' | 'config'>, killed: boolean): Promise<boolean> {
  if (!killed || rt.mode !== 'act' || rt.config.planner !== 'v2' || rt.repo === '') return killed
  if (live.loaded && live.repo === rt.repo && live.files?.off === true) return killed
  const at = await io.now().catch(() => null)
  if (at === null) return killed
  await updateFiles(live, io, rt.repo, f => {
    const base = f ?? EMPTY_FILES
    if (base.off) return null
    return { ...base, off: true, edits: [...base.edits, { what: 'control', at, issues: [], detail: 'the OFF file was created' }] }
  })
  return killed
}

// noteIdle: each tick, before its pass (7.2). While the loop does not act under planner v2 (mode off
// or observe, or planner v1), the workspace config.json it reads is kept in memory, never in the
// store, which only an acting pass writes. The first tick that acts under v2 again makes that the
// version files:<repo> holds for the workspace file, so the edit that turned the loop on (`mode`,
// `planner`) is compared like any other and logged once as config-file; an op's write is the
// loop's own version (noteWritten). A read that fails changes nothing. Never throws.
export async function noteIdle(live: V2Live, io: V2StoreIo, files: Pick<FileIo, 'readFile'>, rt: Pick<Runtime, 'repo' | 'mode' | 'config' | 'loopDir'>): Promise<void> {
  if (rt.repo === '') return
  if (rt.mode !== 'act' || rt.config.planner !== 'v2') {
    const text = await files.readFile(`${baseOf(rt.loopDir)}/config.json`).catch(() => null)
    if (text !== null) live.idle = { repo: rt.repo, seen: seenOf(text) }
    return
  }
  const idle = live.idle
  live.idle = null
  if (idle === null || idle.repo !== rt.repo) return
  await updateFiles(live, io, rt.repo, f => ({ ...(f ?? EMPTY_FILES), workspace: idle.seen }))
}

// What the driver gives v2IoOf: whether the ledger is loaded and this session may act on it, a
// write queued after every store write before it that runs only while this session may still write
// the store (false when it did not run, or threw), and the driver's ping.
export type V2IoDeps = {
  ready: () => boolean
  write: (save: () => Promise<void>) => Promise<boolean>
  ping: (why: string) => void
  // the live ledger, for the transition executor's trigger
  ledger?: () => readonly LedgerEntry[]
}

const UNCHANGED = { changed: false, saved: false } as const

// v2IoOf: the live records for the transition executor (4.6). A change is stored before it is
// kept in memory; one the store refused is kept nowhere and reported unchanged, as V2Io says.
export function v2IoOf(live: V2Live, io: V2StoreIo, deps: V2IoDeps): V2Io {
  return {
    records: () => live.records,
    updateRecords: async fn => {
      if (!live.loaded || !deps.ready()) return UNCHANGED
      const before = live.records
      const next = fn(before)
      if (next === null) return UNCHANGED
      const repo = live.repo
      const saved = await deps.write(async () => {
        if (!live.loaded || live.repo !== repo || live.records !== before) throw new Error('the records changed while the write waited')
        await io.set(recordsKey(repo), recordsToStore(next, await io.now()))
      })
      if (!saved) return UNCHANGED
      live.records = next
      live.absent = false
      return { changed: true, saved: true }
    },
    ping: deps.ping,
    ...(deps.ledger === undefined ? {} : { ledger: deps.ledger }),
  }
}

function message(err: unknown): string {
  const text = err instanceof Error ? err.message : String(err)
  return text.length > ERROR_MAX ? `${text.slice(0, ERROR_MAX - 3)}...` : text
}

files.hooks/report.ts:
// The factory report (#712, epic #684): a pure view of the v2 records as two markdown tables, the
// issues in flight and the last merges, and a digest that changes when the picture does and not
// when only time passes. Nothing here reads a clock, a store or GitHub; delivery comes later. It
// lives in hooks/, not hooks/v2/, so it stays out of the planner's import closure.
import type { Ms } from './types'
import { lifeAt } from './v2/keys'
import { SLOT_STATES } from './v2/types'
import type { IssueRecord, IssueState } from './v2/types'

export const MERGED_SHOWN = 5
export const WHAT_MAX = 40

const SEC = 1000
const MIN = 60 * SEC
const HOUR = 60 * MIN
const DAY = 24 * HOUR

// duration: Xs under a minute, Xm under an hour, XhYm under a day, XdYh from a day up.
export function duration(ms: Ms): string {
  const t = Math.max(0, ms)
  if (t < MIN) return `${Math.floor(t / SEC)}s`
  if (t < HOUR) return `${Math.floor(t / MIN)}m`
  if (t < DAY) return `${Math.floor(t / HOUR)}h${Math.floor((t % HOUR) / MIN)}m`
  return `${Math.floor(t / DAY)}d${Math.floor((t % DAY) / HOUR)}h`
}

// The state in words (the one table); a detail, where one helps, comes from stageOf.
const STAGE_WORDS: Readonly<Record<IssueState, string>> = {
  queued: 'queued',
  designing: 'designing',
  building: 'building',
  reviewing: 'reviewing',
  fixing: 'fixing',
  'merge-queue': 'merge queue',
  parked: 'parked',
  closed: 'closed',
}

export function stageOf(r: IssueRecord): string {
  const word = STAGE_WORDS[r.state]
  if (r.state === 'reviewing' && r.approvedPatch !== null) return `${word} (approved, heading to merge)`
  if (r.state === 'parked' && r.question) return `${word} (owner question)`
  return word
}

// whatOf: a title shortened: the prefix up to the first ": " dropped, the rest cut at a word
// boundary to at most WHAT_MAX characters, "|" escaped. No title gives an empty string.
export function whatOf(title: string | undefined): string {
  if (!title) return ''
  const i = title.indexOf(': ')
  let s = (i >= 0 ? title.slice(i + 2) : title).trim().replace(/\s+/g, ' ')
  if (s.length > WHAT_MAX) {
    const cut = s.slice(0, WHAT_MAX + 1)
    const space = cut.lastIndexOf(' ')
    s = space > 0 ? cut.slice(0, space) : cut.slice(0, WHAT_MAX)
  }
  return s.trim().replace(/\|/g, '\\|')
}

const isMerged = (r: IssueRecord) => r.state === 'closed' && (r.why === 'merged' || r.why === 'merged-by-hand')
const isInFlight = (r: IssueRecord) => SLOT_STATES.includes(r.state) || r.state === 'parked'

const claimAt = (r: IssueRecord): Ms | null => lifeAt(r.life)

function table(head: string[], rows: string[][]): string {
  return [`| ${head.join(' | ')} |`, `|${head.map(() => ' --- ').join('|')}|`, ...rows.map(r => `| ${r.join(' | ')} |`)].join('\n')
}

export type Report = { text: string | null; digest: string }

export function reportOf(records: readonly IssueRecord[], titles: Readonly<Record<number, string>> | ReadonlyMap<number, string>, now: Ms, repo: string): Report {
  const title = (n: number) => (titles instanceof Map ? titles.get(n) : (titles as Readonly<Record<number, string>>)[n])
  const link = (n: number) => `[#${n}](https://github.com/${repo}/issues/${n})`

  const flight = records.filter(isInFlight).sort((a, b) => {
    const x = claimAt(a)
    const y = claimAt(b)
    if (x === null || y === null) return x === y ? a.issue - b.issue : x === null ? 1 : -1
    return x - y || a.issue - b.issue
  })
  const merged = records.filter(isMerged).sort((a, b) => b.since - a.since || a.issue - b.issue)

  const digest = [
    flight.map(r => `${r.issue}:${r.life}:${r.state}:${r.seq}`).join(','),
    merged.map(r => `${r.issue}:${r.life}`).sort().join(','),
  ].join('|')
  if (flight.length === 0 && merged.length === 0) return { text: null, digest }

  const flightRows = flight.map(r => {
    const at = claimAt(r)
    return [link(r.issue), whatOf(title(r.issue)), stageOf(r), duration(now - r.since), at === null ? '' : duration(now - at)]
  })
  const mergedRows = merged.slice(0, MERGED_SHOWN).map(r => {
    const at = claimAt(r)
    return [link(r.issue), whatOf(title(r.issue)), at === null ? '' : duration(r.since - at), String(r.fixes)]
  })
  const text = [
    `### In flight (${flight.length})`,
    flightRows.length > 0 ? table(['Issue', 'What', 'Stage', 'In stage', 'Since claim'], flightRows) : 'Nothing in flight.',
    '',
    '### Merged',
    mergedRows.length > 0 ? table(['Issue', 'What', 'Claim to merge', 'Fix rounds'], mergedRows) : 'Nothing merged yet.',
  ].join('\n')
  return { text, digest }
}

// titleBook: the title book after a pass: the known titles, with every title the pass's issue
// reads carry, and only for issues that have a v2 record. It makes no GitHub call.
export function titleBook(prev: unknown, reads: ReadonlyMap<number, { facts: { title: string } | null }>, records: readonly Pick<IssueRecord, 'issue'>[]): Record<number, string> {
  const known: Record<number, string> = {}
  if (prev !== null && typeof prev === 'object' && !Array.isArray(prev)) {
    for (const [k, v] of Object.entries(prev)) if (typeof v === 'string' && /^\d+$/.test(k)) known[Number(k)] = v
  }
  for (const [n, g] of reads ?? []) if (g.facts && g.facts.title) known[n] = g.facts.title
  const out: Record<number, string> = {}
  for (const r of records) if (known[r.issue] !== undefined) out[r.issue] = known[r.issue]
  return out
}

// keepTitles: the title book in the store, written only when it changed. A store that cannot be
// read or written is a problem line, never a throw.
export async function keepTitles(
  io: { get: (key: string) => Promise<unknown>; set: (key: string, value: unknown) => Promise<unknown> },
  key: string,
  reads: ReadonlyMap<number, { facts: { title: string } | null }>,
  records: readonly Pick<IssueRecord, 'issue'>[],
  problems: string[],
): Promise<void> {
  try {
    const prev = await io.get(key)
    const next = titleBook(prev, reads, records)
    if (JSON.stringify(next) !== JSON.stringify(prev)) await io.set(key, next)
  } catch (err) {
    problems.push(`store: ${key} not saved: ${String(err instanceof Error ? err.message : err).slice(0, 200)}`)
  }
}

files.hooks/v2/types.ts:
// The v2 rule layer's vocabulary (docs/factory-loop/v2/SPEC.md): the issue record and its states
// (section 3), the transition table's events and rows (4), the action kinds of appendix B with
// their outcomes, the State fields v2 reads (2.4), the labels and notices of appendix D and the
// rule ids of 14.1. Each closed list is a frozen array here, and its type is derived from it, so
// a value read from text is checked against the same list the code is typed by. Types and
// constants only: the pure planner imports this, so nothing here may run a command or read a
// clock.
import type { PlanCtx } from '../foundation'
import type { ActionBase, ActionClass, Config, LedgerEntry, LedgerStatus, Ms, Source } from '../types'
import type { V2Event } from './events'
import type { CheckoutBase } from './reconcile'
import type { InterventionFacts } from './sources-interventions'
import type { PrsRead } from './sources-prs'
import type { WorkspaceRead } from './workspace'

// --- states, steps and the record (SPEC 3.1, 3.2) ------------------------------------------------

export const ISSUE_STATES = ['queued', 'designing', 'building', 'reviewing', 'fixing', 'merge-queue', 'parked', 'closed'] as const
export type IssueState = (typeof ISSUE_STATES)[number]

export const STEP_KINDS = ['lease', 'design', 'build', 'review', 'fix', 'queue', 'triage'] as const
export type StepKind = (typeof STEP_KINDS)[number]

export const CLOSED_WHYS = ['merged', 'merged-by-hand', 'dropped', 'split', 'closed-on-github', 'claim-lost'] as const
export type ClosedWhy = (typeof CLOSED_WHYS)[number]

// The states that hold a slot and count in flight (3.1): designing to merge-queue.
export const SLOT_STATES: readonly IssueState[] = ['designing', 'building', 'reviewing', 'fixing', 'merge-queue']

// The step each state runs (4.2). Parked and closed run none; a merge-queue record runs `queue`
// only while it is the queue's head (9.1).
export const STATE_STEP: Readonly<Record<IssueState, StepKind | null>> = {
  queued: 'lease',
  designing: 'design',
  building: 'build',
  reviewing: 'review',
  fixing: 'fix',
  'merge-queue': 'queue',
  parked: null,
  closed: null,
}

// The steps an agent runs (4.2), each in the issue's slot.
export const AGENT_STEPS = ['design', 'build', 'review', 'fix', 'triage'] as const
export type AgentStep = (typeof AGENT_STEPS)[number]

// Writers may write only inside their slot and push only the record's branch; readers may not
// write inside the repository (4.2, 10.4).
export type Role = 'writer' | 'reader'
export const STEP_ROLE: Readonly<Record<AgentStep, Role>> = { design: 'reader', build: 'writer', review: 'reader', fix: 'writer', triage: 'reader' }

// The class of an agent step (appendix B): develop for design and build, drive for the rest.
export const STEP_CLASS: Readonly<Record<AgentStep, ActionClass>> = { design: 'develop', build: 'develop', review: 'drive', fix: 'drive', triage: 'drive' }

// The loop-owned agent type each step spawns (5.2, 8.3, 8.7). The model is never offered them
// (register.ts agent.offer). designer-v2 is renamed designer at the delete wave.
export const STEP_AGENT: Readonly<Record<AgentStep, `factory-loop:${string}`>> = {
  design: 'factory-loop:designer-v2',
  build: 'factory-loop:builder',
  review: 'factory-loop:reviewer',
  fix: 'factory-loop:fixer',
  triage: 'factory-loop:triage',
}

// The record (3.2). The slot is not a field: a record holds the slot whose lease holder is
// `factory-loop:<N>:<life>` (10.1).
export type IssueRecord = {
  issue: number
  // the claim's start time in base-36 seconds: unique per life (3.3, keys.ts lifeOf)
  life: string
  // +1 on every transition; part of every per-seq key
  seq: number
  // when this seq's transition happened
  seqAt: Ms
  state: IssueState
  // when it entered this state
  since: Ms
  // queued: where a lease leads (default designing); parked: where an unpark leads
  resumeTo: IssueState | null
  // fixed for the life (3.5)
  branch: string
  // adopted at claim, or set when reviewing ends (8.1)
  pr: number | null
  // the head a writer step last confirmed on origin
  head: string | null
  // the patch id the reviewer approved (8.4)
  approvedPatch: string | null
  // the design brief comment URL
  brief: string | null
  // the step this seq runs: the state's own, or 'triage'; null when waiting
  step: StepKind | null
  // attempt of that step: 1 or 2 (5.1)
  attempt: number
  // this attempt already had its one free re-run (row U1)
  cut: boolean
  // triage calls in this life, at most maxTriages
  triages: number
  // entries to fixing in this life, at most fixCap
  fixes: number
  // entries to reviewing in this life
  round: number
  // parked: the question for the owner
  question: string | null
  // closed: why
  why: ClosedWhy | null
  // owner, triage and decline notes for the step of this seq
  notes: string[]
  // GitHub's closedAt of the newest hand close the record has handled (E4, P1)
  prClosedAt: string | null
  // this life's number among the issue's lives since its count last started (6.4, lives.ts): 1
  // for the first claim, and again for the first claim after the owner lifts factory:rejected
  lives: number
}

// A record's identity at one seq: what the transition executor compares before it stores (3.3).
export type RecordRef = { issue: number; life: string; seq: number }

// --- the table's input and rows (SPEC 4.1, 4.6, 5) -------------------------------------------------

export const EVENT_KINDS = ['ok', 'not-ok', 'unknown', 'triage', 'drop', 'unpark', 'issue-closed', 'pr-merged', 'pr-closed', 'claim-lost', 'timeout'] as const
export type EventKind = (typeof EVENT_KINDS)[number]

// The causes outside the issue that earn one free re-run per attempt (5.1, row U1).
export const OUTSIDE_CAUSES = ['load', 'usage', 'breaker', 'slot'] as const
export type OutsideCause = (typeof OUTSIDE_CAUSES)[number]

// Why a step ended unknown (7.2, intervention `unknown:<why>`). rate-limited is an API rate limit
// (a 429, or the usage window); api is any other API error (a 5xx, overloaded).
export const UNKNOWN_WHYS = ['timeout', 'agent-dead', 'bad-answer', 'api', 'rate-limited', 'spawn', 'cli', 'github-wait'] as const
export type UnknownWhy = (typeof UNKNOWN_WHYS)[number]

// The outside cause an unknown's why is by itself (5.1): a rate limit is `usage`, a free re-run
// that the step-unknown breaker does not count (5.3). Every other why is unexplained unless a fact
// plan holds (the load, the tier, the breaker, the lease) says otherwise.
export const WHY_CAUSE: Readonly<Partial<Record<UnknownWhy, OutsideCause>>> = { 'rate-limited': 'usage' }

// The triage menu (5.2).
export const TRIAGE_CHOICES = ['retry', 'fix', 'redesign', 'park', 'drop'] as const
export type TriageChoice = (typeof TRIAGE_CHOICES)[number]

// One event for a record (4.6): its kind and what the row's guard and change read.
export type TableEvent = { kind: EventKind; reason?: string; cause?: OutsideCause; why?: UnknownWhy; choice?: TriageChoice; data?: unknown }

// The reused event states a seq logs beside its `transition` on entry to a state (4.5, 7.1).
export const EMIT_STATES = ['delegated', 'fix_requested', 'merge_ready', 'abandoned'] as const
export type EmitState = (typeof EMIT_STATES)[number]

// One row of the table (4.6). `rowFor` in table.ts is the only lookup.
export type Row = {
  id: string
  states: readonly IssueState[]
  on: EventKind
  // pure guard: the guards on one (state, step, event) are exclusive and exhaustive
  when?: (r: IssueRecord, e: TableEvent, c: Config) => boolean
  next: IssueState | 'same' | 'resumeTo'
  // pure: the fields the row changes
  change: (r: IssueRecord, e: TableEvent, now: Ms) => Partial<IssueRecord>
  // the transition note's `via` code
  via: string
}

// --- what a step reports (SPEC 4.2, 5.1, 10.8) -----------------------------------------------------

// A step's result, as steps.ts records it on the step's ledger entry and plan reads it: ok,
// not-ok with a reason, or unknown with why. head: a writer's head, read on origin. choice: a
// triage's. data: the checked answer the step's contract gave (contracts-*.mjs).
export type StepResult = {
  event: 'ok' | 'not-ok' | 'unknown'
  reason: string | null
  why: UnknownWhy | null
  head: string | null
  choice: TriageChoice | null
  data: unknown
}

// unknownResult: a step's unknown, with why and a short reason.
export function unknownResult(why: UnknownWhy, reason: string): StepResult {
  return { event: 'unknown', reason: reason.length > 200 ? `${reason.slice(0, 197)}...` : reason, why, head: null, choice: null, data: null }
}

// The guard's FAIL classes in --patch mode (9.3, 9.4).
export const GUARD_CLASSES = ['behind', 'conflict', 'checks', 'patch', 'linkage', 'read', 'policy'] as const
export type GuardClass = (typeof GUARD_CLASSES)[number]

export const SLOT_OPS = ['lease', 'prepare', 'kill', 'free'] as const
export type SlotOp = (typeof SLOT_OPS)[number]

// The outcomes the v2 executors record (one member of types.ts Outcome each).
export type V2Outcome =
  | { kind: 'step'; step: AgentStep; result: StepResult }
  // what a transition did, so the breaker and the interventions read it from the ledger (5.3, 7.2)
  | {
      kind: 'transition'
      row: string
      event: EventKind
      cause: OutsideCause | null
      from: IssueState | null
      to: IssueState
      step: StepKind | null
      // false from the entry's start until the executor stored the record (a lost entry may carry
      // false: the seq is the record's when the store holds it at that seq)
      stored: boolean
      // the transition note's via code (table.ts viaOf), carried from the entry's start (ledger.ts
      // start): the row's own code, with the detail its event gave where the row takes one:
      // `free:<cause>` (U1), `unknown:<why>` (U2 to U4), `fix:<review|ci|conflict>` (T9),
      // `triage:<choice>` (X1 to X5), `unpark:<op|label>` (P1). The seq's entry actions log it and
      // the interventions read it (rules-interventions.ts), so nothing is inferred from other entries.
      via: string
    }
  | { kind: 'pr'; pr: number; created: boolean; reopened: boolean }
  | { kind: 'split'; child: number }
  // leftovers: the patch file a prepare or a free saved the slot's leftovers to (10.2): its uncommitted
  // work and its commits not on origin, against the commit the next step starts from; a retry's
  // prompt names it (5.1), and a resumed life finds a free's through rules-agent.ts leftoversOf; null
  // when nothing would have been lost
  | { kind: 'slot'; op: SlotOp; path: string | null; lease: string | null; head: string | null; killed: number | null; leftovers?: string | null }
  | { kind: 'queue'; op: 'update' | 'merge'; merged: boolean; head: string | null; failClass: GuardClass | null; lines: string[] }
  // an open PR adopted at claim (3.5)
  | { kind: 'adopt'; branch: string; pr: number | null; others: number[] }

// --- the action kinds (appendix B) ----------------------------------------------------------------

export const V2_ACTION_KINDS = ['transition', 'label', 'comment', 'event', 'pr', 'split', 'agent-step', 'ci-rerun', 'queue-update', 'queue-merge', 'slot'] as const
export type V2ActionKind = (typeof V2_ACTION_KINDS)[number]

// What the transition executor re-checks against the live ledger and records before it stores
// (3.3): the life's claim entry (row S0), a step's entry as plan saw it, or an owner or GitHub
// fact (an edge whose time the record already carries).
export type Trigger =
  | { kind: 'claim'; key: string }
  | { kind: 'entry'; key: string; status: LedgerStatus; startedAt: Ms }
  | { kind: 'fact'; fact: string }

// The step marker the slot carries in its git dir (10.2), which the companion reads.
export type StepMarker = {
  v: 1
  repo: string
  issue: number
  life: string
  seq: number
  step: AgentStep
  role: Role
  branch: string
  // the issue's PR, when it has one (the companion's notes carry it); an older marker has none
  pr: number | null
  gateCommands: string[]
  gateTimeoutMs: Ms
  loopDir: string
  // the step attempt's scratch folder (keys.ts scratchOf), which the companion exports as TMPDIR; the
  // slot executor fills it, like loopDir
  scratch: string
}

// The four reasons of a designer's split (8.7; contracts-work.mjs REASON_KEYS).
export type SplitReasons = { why_split: string; why_count: string; why_parts: string; why_order: string }

// A child a designer's split asks for (8.7).
export type SplitChild = { key: string; title: string; why: string; body: string; blockedBy: string[]; ready: boolean }

export type V2Action =
  // cause: the outside cause of an unknown (5.1), which the breaker reads; via: the note's code;
  // fromState and fromStep: the state and step the record leaves, which the entry carries from its
  // start (ledger.ts start), so a crash before it is saved done loses none of them (3.3)
  | (ActionBase & {
      kind: 'transition'
      row: string
      event: EventKind
      from: RecordRef | null
      next: IssueRecord
      trigger: Trigger
      cause?: OutsideCause | null
      via?: string
      fromState?: IssueState | null
      fromStep?: StepKind | null
    })
  // set: add the state's label and remove the other six; ensure: create the eight; clear: remove
  // the seven state labels (3.4); requeue: the seven off and `ready` on (ready: the repo's ready
  // label); reject: the seven off and factory:rejected on (both R1's release, 6.4)
  | (ActionBase & { kind: 'label'; op: LabelOp; label: FactoryLabel | null; ready?: string })
  // the body carries the hidden key <!-- factory-loop:<ledger key> --> (4.5)
  | (ActionBase & { kind: 'comment'; on: 'issue' | 'pr'; number: number; body: string })
  // built only by events.ts (7.1); logged: the event log already holds it (events.ts logOnce), so
  // the executor settles it done with no second write
  | (ActionBase & { kind: 'event'; event: V2Event; logged?: true })
  | (ActionBase & {
      kind: 'pr'
      op: 'ensure' | 'body'
      branch: string
      base: string
      pr: number | null
      title: string
      summary: string
      evidence: string | null
      brief: string | null
    })
  // one child per action; blockedBy: the issue numbers it waits on: siblings made, or existing issues
  | (ActionBase & { kind: 'split'; parent: number; child: SplitChild; blockedBy: number[] })
  | (ActionBase & { kind: 'agent-step'; step: AgentStep; life: string; seq: number; attempt: number; branch: string; slot: string | null; notes: string[] })
  | (ActionBase & { kind: 'ci-rerun'; pr: number; runId: string; round: number })
  // base: main's head at plan time (the key's); head: the PR's head as observe read it
  | (ActionBase & { kind: 'queue-update'; pr: number; base: string; head: string })
  | (ActionBase & { kind: 'queue-merge'; issue: number; pr: number; head: string; patch: string })
  | (ActionBase & { kind: 'slot'; op: SlotOp; life: string; path: string | null; lease: string | null; branch: string | null; marker: StepMarker | null; keepScratch: boolean })

// --- labels and notices (appendix D) ---------------------------------------------------------------

export const LABEL_OPS = ['set', 'ensure', 'clear', 'requeue', 'reject'] as const
export type LabelOp = (typeof LABEL_OPS)[number]

export const FACTORY_LABEL_PREFIX = 'factory:'

export type FactoryLabel = `factory:${Exclude<IssueState, 'closed'>}`

// Each state's label (closed has none), with its colour and description (appendix D).
export const FACTORY_LABELS: Readonly<Record<Exclude<IssueState, 'closed'>, { name: FactoryLabel; color: string; description: string }>> = {
  queued: { name: 'factory:queued', color: 'c5def5', description: 'Factory loop: claimed, waiting for a slot' },
  designing: { name: 'factory:designing', color: 'bfd4f2', description: 'Factory loop: the designer is at work' },
  building: { name: 'factory:building', color: '0e8a16', description: 'Factory loop: the implementer is at work' },
  reviewing: { name: 'factory:reviewing', color: 'fbca04', description: 'Factory loop: review and CI on the PR' },
  fixing: { name: 'factory:fixing', color: 'd93f0b', description: 'Factory loop: a fixer is at work' },
  'merge-queue': { name: 'factory:merge-queue', color: '5319e7', description: 'Factory loop: approved and green, waiting to merge' },
  parked: { name: 'factory:parked', color: 'b60205', description: 'Factory loop: waits on the owner; remove this label to resume' },
}

// resumeStep: how the owner resumes a parked issue (11), one text for every message that says so:
// the park comment, its tell and reminders, and the triage prompt's park choice.
export function resumeStep(issue: number): string {
  return `answer on the issue and remove the \`factory:parked\` label, or run \`/factory resume ${issue} "your answer"\`; a comment alone does not resume`
}

// The label of an issue R1 released at its last life (6.4): not a state, since the issue is out of
// the factory. S1 never claims an issue carrying it; the owner removing it and adding `ready`
// brings the issue back with its life count started again.
export const REJECTED_LABEL: { name: 'factory:rejected'; color: string; description: string } = {
  name: 'factory:rejected',
  color: '6a737d',
  description: 'Factory loop: its last life ended without a merge; remove this label and add ready to try again',
}

// Every label the loop makes (op ensure): the seven state labels, then factory:rejected.
export const ALL_FACTORY_LABELS: readonly { name: string; color: string; description: string }[] = [...Object.values(FACTORY_LABELS), REJECTED_LABEL]

// labelOf: a state's label, or null for closed.
export function labelOf(state: IssueState): FactoryLabel | null {
  return state === 'closed' ? null : FACTORY_LABELS[state].name
}

// The notice (TELL) kinds v2 adds; the first seven are owner items, which go out before any other
// wake (O2). The foundation's own (runaway, blind, heartbeat-other, old-watcher, pass-error) stay.
export const V2_OWNER_TELLS = ['parked', 'breaker', 'stalled', 'checkout', 'workspace', 'rejected', 'keep-open-blocks'] as const
export const V2_TELLS = [...V2_OWNER_TELLS, 'waiting', 'task-timeout'] as const
export type V2Tell = (typeof V2_TELLS)[number]

// --- rule ids (SPEC 14.1) -------------------------------------------------------------------------

export const V2_RULES = [
  'G1', 'G2', 'G3', 'G4', 'H1', 'H2', 'R1', 'R2', 'S1', 'S2', 'S3', 'S4', 'S5', 'S6', 'Q1', 'Q2', 'W1', 'W2', 'O1', 'O2', 'O3',
] as const
export type V2Rule = (typeof V2_RULES)[number]

// --- interventions (SPEC 7.2) ---------------------------------------------------------------------

export type InterventionWho = 'person' | 'loop'

// The cause families; `op:<name>`, `unknown:<why>`, `free:<cause>`, `fix:<what>`, `queue:<what>`
// and `guard:<what>` take their suffix from the lists above or the op's name.
export const PERSON_CAUSES = ['op', 'unpark', 'push', 'hand-merge', 'pr-closed', 'issue-closed', 'control-file', 'config-file', 'restart', 'reconcile', 'unreject', 'rescue'] as const
export const LOOP_CAUSES = [
  'triage', 'unknown', 'free', 'park', 'fix', 'ci-rerun', 'queue', 'guard', 'gate-unknown', 'prompt-denied', 'tripwire', 'breaker', 'stalled', 'workspace', 'reconcile', 'rejected', 'reclaim', 'wake',
] as const

// --- what v2 reads (SPEC 2.4) ---------------------------------------------------------------------

// A pool slot's lease, by its holder (10.1): `factory-loop:<N>:<life>` names the loop's own.
export type Lease = { path: string; lease: string; holder: string; issue: number | null; life: string | null; status: string; busy: boolean }

// The newest issue read observe holds, and when it was taken: the parked label's absence in a
// read newer than the park is the unpark signal (3.4).
export type IssueRead = { at: Ms; open: boolean | null; labels: string[] | null }

// A trusted comment on an issue (callum-flow-issue-read --comments), for a resume's note (11).
export type IssueComment = { body: string; at: Ms; url: string | null }

// When observe first saw a PR head (2.4): it bounds the waits on GitHub (4.4).
export type HeadSeen = { pr: number; at: Ms }

export const V2_SOURCES = ['store', 'leases', 'prs', 'interventions', 'comments', 'dualWrite'] as const
// What the new event log holds, read once per load when dual write is on (sources-dualwrite.ts): when it
// was read and the "<issue>:<life>:<seq>" of this device's transitions it holds.
export type DualWrite = { readAt: Ms; seen: ReadonlySet<string> }

export type V2SourceName = (typeof V2_SOURCES)[number]

// The State fields v2 adds (2.4), as State.v2: observeV2 reads them when the planner is v2 or the
// v2 shadow is on; absent otherwise.
export type V2State = {
  sources: Record<V2SourceName, Source>
  records: IssueRecord[]
  // where the records came from: the store (act mode's), the event log (a rebuild), or neither
  recordsFrom: 'store' | 'events' | 'none'
  // by head sha
  heads: Record<string, HeadSeen>
  leases: Lease[]
  // the newest read of each issue observe holds, by issue number
  reads: Record<number, IssueRead>
  // trusted comments of parked records whose label a person removed, by issue number
  comments: Record<number, IssueComment[]>
  prs: PrsRead
  // when the PR reads showed each issue's PR closed or merged (GitHub's closedAt), by issue number:
  // an older read of the issue is due at once, and pr-closed waits for it (4.1)
  changed: Record<number, Ms>
  interventions: InterventionFacts
  // the onceKeys (events.ts) of this device's events in the pass's read of the event log (the facts
  // read, 2.4, or the rebuild's week): which facts are logged, when a wiped store lost their ledger
  // keys (7.2)
  logged: string[]
  // the main checkout the tripwire last settled on, which R1 compares this pass's read with
  // (10.7; reconcile.ts checkoutBaseOf); null before the first read that did not fail
  checkoutBase: CheckoutBase | null
  // the new log's transitions; null when dual write is off or not read (act mode, planner v2 only)
  dualWrite: DualWrite | null
  // the workspace rail: the companion's handshake for this session (10.9; workspace.ts); absent
  // when not read, which holds nothing
  workspace?: WorkspaceRead
}

// The pure planner's context: the foundation's, with the v2 fields every rule reads.
export type V2Ctx = PlanCtx & { v2: V2State }

// --- what the executors may change beside the ledger (SPEC 3.3, 4.6) -------------------------------

// The live records: only the transition executor updates them, under the act lock. update applies
// fn to the records as they are now (null: no change), saves them to the store, and resolves once
// saved; changed is false when fn changed nothing or the store refused the write.
export type V2Io = {
  records: () => readonly IssueRecord[]
  // the live ledger, which the transition executor re-checks its trigger against (3.3)
  ledger?: () => readonly LedgerEntry[]
  updateRecords: (fn: (records: readonly IssueRecord[]) => IssueRecord[] | null) => Promise<{ changed: boolean; saved: boolean }>
  // asks the driver for the next pass at once: a transition's next event is taken without delay
  ping: (why: string) => void
}

// --- settings (appendix A) ------------------------------------------------------------------------

export const PLANNERS = ['v1', 'v2'] as const
export type Planner = (typeof PLANNERS)[number]
export const SHADOWS = ['off', 'v2'] as const
export type Shadow = (typeof SHADOWS)[number]
// the model aliases the agent tool accepts; a setting named *Model takes one of them
export const MODELS = ['sonnet', 'opus', 'haiku', 'fable'] as const
export type Model = (typeof MODELS)[number]

// The timeouts and tell periods of 4.4, by step and waiting state.
export type StateTimeouts = { design: Ms; build: Ms; review: Ms; fix: Ms; triage: Ms; queued: Ms; queueWait: Ms; parked: Ms }

files.hooks/v2/workspace.ts:
// The loop's side of the companion plugin `factory-loop-workspace` (docs/factory-loop/v2/SPEC.md
// 10.3, 10.5, 10.9), pure: the slot line and folder each agent step's spawn carries, the Bash
// timeout the loop sets for its session, and the workspace rail. The companion writes a handshake
// for each session it runs in, again every minute; without a fresh one for this session, an agent
// would start in the main checkout, unguarded, so every agent step is held with the skip line
// `workspace`, and the owner is told once (tell(workspace)). sources-workspace.ts reads and judges
// the handshake, observeV2 puts it in the State, and rules-state.ts and plan.ts hold and tell
// from it.
import { skip, wake, want } from '../foundation'
import type { Ms } from '../types'
import { AGENT_STEPS } from './types'
import type { StepKind, V2Ctx } from './types'

// The 10-minute Bash timeout (10.5): the loop's session.start sets BASH_DEFAULT_TIMEOUT_MS and
// BASH_MAX_TIMEOUT_MS to it; the companion also gives a loop agent's Bash call with no timeout the
// same value.
export const BASH_TIMEOUT_MS = '600000'

// The rail's owner notice waits this long after the module loaded, so the companion's own
// session.start, which may finish after the loop's first pass, is not told as missing. The hold
// starts at once.
export const WORKSPACE_GRACE_MS = 2 * 60_000

// withSlotLine: the spawn's prompt, opening with `factory-slot: <slot>`, which the companion reads
// to start the agent in its slot (10.3). A prompt that opens with it already is kept; one that
// opens with another slot's has that line replaced. No slot: the prompt as it is.
export function withSlotLine(prompt: string, slot: string | undefined): string {
  if (slot === undefined) return prompt
  const line = `factory-slot: ${slot}`
  const nl = prompt.indexOf('\n')
  const first = nl === -1 ? prompt : prompt.slice(0, nl)
  if (first === line) return prompt
  if (first.startsWith('factory-slot: ')) return nl === -1 ? line : `${line}${prompt.slice(nl)}`
  return `${line}\n${prompt}`
}

// handshakePath: where the companion says it runs in a session (its hooks/register.ts
// handshakePath): one file per session under the loop's base directory.
export function handshakePath(loopBase: string, session: string): string {
  return `${loopBase}/workspace/${session.replace(/[^A-Za-z0-9._-]/g, '_')}.json`
}

// processIdOf: the process that /proc/<pid>/stat describes, by its pid and start time, as the
// companion names its own in the handshake (its hooks/register.ts processIdOf). No other process
// has it: not a child, not a later one given the same pid. undefined: no stat to read.
export function processIdOf(stat: string | null): string | undefined {
  const pid = stat?.split(' ', 1)[0] ?? ''
  const start = stat?.slice(stat.lastIndexOf(') ') + 2).split(' ')[19] ?? ''
  return /^\d+$/.test(pid) && /^\d+$/.test(start) ? `${pid}:${start}` : undefined
}

// What the rail read for this session and this process (null: its id is unknown): the handshake
// is there, names both, and is fresh, or why not (sources-workspace.ts workspaceRead).
export type WorkspaceRead = { session: string; process: string | null } & ({ ok: true; version: string | null } | { ok: false; why: string })

// workspaceHold: why a record's step may not start: an agent step while the rail fails. null: it
// may (the rail passed, or was not read).
export function workspaceHold(ctx: V2Ctx, step: StepKind | null): string | null {
  const w = ctx.v2.workspace
  if (w === undefined || w.ok || step === null || !(AGENT_STEPS as readonly string[]).includes(step)) return null
  return `workspace: ${w.why}; agent steps are held`
}

// workspaceTell: the owner told once per process the rail failed in, after the grace: the
// supervisor resumes the same session in each new process, and each outage is told.
export function workspaceTell(ctx: V2Ctx): void {
  const w = ctx.v2.workspace
  if (w === undefined || w.ok) return
  const since: Ms = ctx.state.loadedAt
  if (ctx.state.now - since < WORKSPACE_GRACE_MS) {
    skip(ctx, 'O2', null, `workspace: told after ${WORKSPACE_GRACE_MS / 60_000} minutes without the companion: ${w.why}`)
    return
  }
  const key = `tell:workspace:${`${w.session}/${w.process ?? 'unknown'}`.replace(/[^A-Za-z0-9._-]/g, '_')}`
  const context = [w.why, 'Enable the factory-loop-workspace plugin beside factory-loop in this workspace, then restart the session. Until then no agent step starts.']
  want(ctx, wake('tell', 'workspace', key, 'O2', null, { session: w.session }, context))
}

files.hooks/wake.ts:
// Waking the model and reading its answers (SPEC 8, 9.2, 10.8; DECISIONS D-04, D-25, D-26).
// A judge, task or tell is one prompt the loop submits: a machine-shaped first line, plain-text
// detail lines, and the judge skill's pointer last (SPEC 8.1). The model answers a judge or a
// task with an `ANSWER <id> <decision>` block in its final message, or with the answer tool
// (D-04); a tell is delivered when its own turn completes (D-25). Only the executor touches the
// engine: everything else is a pure function over the ledger that returns the updates for the
// driver to apply (ledger.ts finish) and the prompts for it to submit, so the tests and the
// replay harness drive it without the engine. What must survive a reload is on the wake's ledger
// entry: its id (wakeId), the turn it started (turnId), whether its reminder went out
// (reminded), and its first line (summary), which the reminder repeats.
import type { ToolSpec } from 'claude-code'

import { WAKE_POINTER, answerPath } from './exec'
import type { Executor } from './exec'
import type { Action, ActionKind, Config, LedgerEntry, LedgerStatus, Ms, Outcome, WakeKind } from './types'

const MIN = 60_000
const HOUR = 60 * MIN
// ledger.ts keeps this much of a summary; a wake's summary is its first line (see lineSummary)
export const WAKE_SUMMARY_MAX = 300
// a reason or instructions past this is cut: answers are short (SPEC 8.4)
const VALUE_MAX = 2000
// a reminder repeats at most this many of the reasons the last answer was refused
const REFUSALS_SHOWN = 3

const HEADS: Record<WakeKind, string> = { judge: 'JUDGE', task: 'TASK', tell: 'TELL' }
const KINDS: Record<string, WakeKind> = { JUDGE: 'judge', TASK: 'task', TELL: 'tell' }
// first-line fields the loop sets itself
const RESERVED = ['id', 'repo', 'reminder']

export type WakeAction = Extract<Action, { kind: WakeKind }>

// A transition of one wake's entry, for the driver to apply with ledger.ts
// finish(ledger, update.key, update, now); structurally a ledger.ts Completion.
export type WakeUpdate = {
  key: string
  status: LedgerStatus
  outcome?: Outcome
  summary?: string
  wakeId?: string
  turnId?: string
  reminded?: boolean
  // an attempt given back (orphanedWakes)
  attempts?: number
}

export function isWakeAction(action: Action): action is WakeAction {
  return action.kind === 'judge' || action.kind === 'task' || action.kind === 'tell'
}

function wakeKind(kind: ActionKind): WakeKind | null {
  return kind === 'judge' || kind === 'task' || kind === 'tell' ? kind : null
}

// --- the prompt (SPEC 8.1) -------------------------------------------------------------------

// A first-line value holds no spaces: whitespace is percent-encoded.
function value(v: string): string {
  return v.replace(/\s/g, c => encodeURIComponent(c))
}

// wakeLine: `<JUDGE|TASK|TELL> <name> id=<id> repo=<owner/name> key=value ...`, the fields in
// plan's order. repo= lets the model build issue and PR links (the skill's TELL format).
export function wakeLine(action: WakeAction, id: string, repo: string): string {
  const parts = [HEADS[action.kind], value(action.wake), `id=${value(id)}`, `repo=${value(repo)}`]
  for (const [k, v] of Object.entries(action.fields)) {
    if (!RESERVED.includes(k)) parts.push(`${k.replace(/[^\w-]/g, '_')}=${value(v)}`)
  }
  return parts.join(' ')
}

// wakeDetails: the detail lines the executor adds after plan's context, so the model reads files
// rather than pasted reports: the agent's saved answer for judge(report) and judge(handoff)
// (SPEC 7.2, act-agents.ts writes it), and every respond log of the run for task(respond-stuck)
// (D-37), from its respond entries in the ledger.
export function wakeDetails(action: WakeAction, loopDir: string, ledger: readonly LedgerEntry[]): string[] {
  const entry = action.fields.entry
  if (action.kind === 'judge' && (action.wake === 'report' || action.wake === 'handoff') && entry !== undefined) {
    return [`saved answer: ${answerPath(loopDir, entry)}`]
  }
  if (action.kind === 'task' && action.wake === 'respond-stuck') {
    const run = action.fields.run
    const logs = ledger
      .filter(e => e.kind === 'respond' && run !== undefined && e.run === run)
      .sort((a, b) => a.startedAt - b.startedAt)
      .flatMap(e => (e.outcome?.kind === 'respond' ? [e.outcome.log] : []))
    return [...new Set(logs)].map(log => `respond log: ${log}`)
  }
  return []
}

// wakePrompt: the first line, each detail as its own plain-text line (a value with line breaks
// becomes several), then the skill pointer as the last line (SPEC 8.1).
export function wakePrompt(first: string, details: readonly string[]): string {
  const lines = details.flatMap(d => d.split(/\r?\n/)).filter(l => l.trim() !== '')
  return [first, ...lines, WAKE_POINTER].join('\n')
}

// lineSummary: the first line as the running entry's summary, which a reminder repeats after a
// reload. A line longer than the ledger keeps is cut after its last whole field.
export function lineSummary(first: string): string {
  if (first.length <= WAKE_SUMMARY_MAX) return first
  const cut = first.lastIndexOf(' ', WAKE_SUMMARY_MAX)
  return cut > 0 ? first.slice(0, cut) : first.slice(0, WAKE_SUMMARY_MAX)
}

// The executor for judge, task and tell (SPEC 6.1): submit the prompt and run on until the
// answer, the delivery or the timeout. Submit starts a turn of its own once the session is idle.
// A prompt the engine refused or dropped started no turn, so it is skipped, no attempt counted,
// and plan asks again next pass (a wake gets one attempt, which a drop must not use up).
const wake: Executor = async (ctx, action) => {
  if (!isWakeAction(action)) return { status: 'failed', summary: `not a wake: ${action.kind}`, noRetry: true }
  const id = ctx.wakeId()
  const first = wakeLine(action, id, ctx.rt.repo)
  const details = [...action.context, ...wakeDetails(action, ctx.rt.loopDir, ctx.state.ledger)]
  try {
    await ctx.io.submit(wakePrompt(first, details))
  } catch (err) {
    return { status: 'skipped', summary: `submit failed: ${String(err).slice(0, 200)}` }
  }
  return { status: 'running', wakeId: id, summary: lineSummary(first) }
}

export const wakeExecutors: Partial<Record<ActionKind, Executor>> = { judge: wake, task: wake, tell: wake }

// --- answers (SPEC 8.2) ----------------------------------------------------------------------

// What each wake may answer, and the field a decision needs (SPEC 8.2's table). A tell takes no
// answer. A judge or task whose name this table lacks may only hold, with a reason (the skill:
// `reason: unknown wake <name>`).
export type DecisionNeed = 'reason' | 'instructions' | 'fields' | null
const TASK_DECISIONS: Record<string, DecisionNeed> = { done: null, failed: 'reason', hold: null }
export const WAKE_DECISIONS: Record<'judge' | 'task', Record<string, Record<string, DecisionNeed>>> = {
  judge: {
    sequence: { merge: null, hold: 'reason' },
    'guard-fail': { fixer: 'instructions', wait: null, hold: 'reason' },
    cancelled: { redrive: null, drop: 'reason' },
    handoff: { ok: null, fixer: 'instructions', hold: 'reason' },
    report: { parsed: 'fields', hold: null },
  },
  task: { redrive: TASK_DECISIONS, 'run-it': TASK_DECISIONS, release: TASK_DECISIONS, 'respond-stuck': TASK_DECISIONS },
}
const UNKNOWN_WAKE: Record<string, DecisionNeed> = { hold: 'reason' }

function decisionsOf(kind: 'judge' | 'task', name: string): Record<string, DecisionNeed> {
  const table = WAKE_DECISIONS[kind]
  return Object.hasOwn(table, name) ? (table[name] ?? UNKNOWN_WAKE) : UNKNOWN_WAKE
}

// allowedDecisions: the decisions a wake of this kind and name accepts; none for a tell.
export function allowedDecisions(kind: WakeKind, name: string): string[] {
  return kind === 'tell' ? [] : Object.keys(decisionsOf(kind, name))
}

// One `ANSWER <id> <decision>` block as written; checkAnswer validates it.
export type AnswerBlock = {
  id: string
  decision: string
  reason: string | null
  instructions: string | null
  // the raw `fields:` value, one line of JSON
  fields: string | null
}

export type ParsedAnswers = { blocks: AnswerBlock[]; problems: string[] }

const ANSWER_LINE = /^ANSWER\s+(\S+)\s+(\S+)$/
const KEY_LINE = /^([A-Za-z][\w-]*)\s*:\s*(.*)$/

// An ANSWER line the model wrapped in backticks or bold reads the same.
function bare(line: string): string {
  return line.replace(/^[`*]+|[`*]+$/g, '').trim()
}

function clip(text: string, max = 120): string {
  return text.length > max ? `${text.slice(0, max - 3)}...` : text
}

// parseAnswers: every ANSWER block in a turn's final text, wherever it sits. A block is the
// `ANSWER <id> <decision>` line and the `key: value` lines after it (reason, instructions,
// fields); a blank line, the end, or any other line (a code fence, prose) ends it. The first
// value of a key counts. An ANSWER line of another shape and an unknown key are named in
// problems, for the decision log.
export function parseAnswers(text: string): ParsedAnswers {
  const lines = text.split(/\r?\n/).map(l => l.trim())
  const blocks: AnswerBlock[] = []
  const problems: string[] = []
  for (let i = 0; i < lines.length; i++) {
    const line = bare(lines[i] ?? '')
    if (!/^ANSWER\b/.test(line)) continue
    const m = ANSWER_LINE.exec(line)
    if (m === null) {
      problems.push(`not an ANSWER line: ${clip(line)}`)
      continue
    }
    const block: AnswerBlock = { id: m[1] ?? '', decision: m[2] ?? '', reason: null, instructions: null, fields: null }
    for (let j = i + 1; j < lines.length; j++) {
      const kv = KEY_LINE.exec(lines[j] ?? '')
      if (kv === null) break
      i = j
      const key = (kv[1] ?? '').toLowerCase()
      const v = (kv[2] ?? '').trim()
      if (key === 'reason' || key === 'instructions' || key === 'fields') {
        if (block[key] === null && v !== '') block[key] = v
      } else {
        problems.push(`ANSWER ${block.id}: unknown key ${clip(key, 40)}`)
      }
    }
    blocks.push(block)
  }
  return { blocks, problems }
}

// An answer from either channel: a parsed block, or the answer tool's input.
export type AnswerInput = {
  id: string
  decision: string
  reason?: string | null
  instructions?: string | null
  // a block's raw JSON line, or the tool's object
  fields?: unknown
}

export type Checked = { ok: true; update: WakeUpdate } | { ok: false; problem: string }

type WakeFields = Extract<Outcome, { kind: 'wake' }>['fields']

const finite = (n: unknown): n is number => typeof n === 'number' && Number.isFinite(n)

function text(v: string | null | undefined): string | null {
  const t = (v ?? '').trim()
  return t === '' ? null : t.slice(0, VALUE_MAX)
}

// fieldsOf: the fields as the outcome keeps them (strings, numbers, booleans, null, lists of
// numbers), null when there are none, or a string saying what is wrong.
function fieldsOf(raw: unknown): WakeFields | null | string {
  if (raw === undefined || raw === null || raw === '') return null
  let v = raw
  if (typeof raw === 'string') {
    try {
      v = JSON.parse(raw)
    } catch {
      return 'fields is not one line of JSON'
    }
  }
  if (v === null || typeof v !== 'object' || Array.isArray(v)) return 'fields must be a JSON object'
  const out: WakeFields = {}
  for (const [k, x] of Object.entries(v as Record<string, unknown>)) {
    if (x === null || typeof x === 'string' || typeof x === 'boolean' || finite(x)) out[k] = x
    else if (Array.isArray(x) && x.every(finite)) out[k] = x
    else return `fields.${clip(k, 40)} must be a string, number, boolean, null or a list of numbers`
  }
  return out
}

// A brief is a comment URL on the wake's issue of this repo (SPEC 7.2, as the designer's
// RESULT line; replies.ts isBriefUrl is the same rule).
function briefOk(url: string, repo: string, issue: number | null): boolean {
  const m = /^https:\/\/github\.com\/([^/\s]+\/[^/\s]+)\/issues\/(\d+)#issuecomment-\d+$/.exec(url)
  if (m === null || (m[1] ?? '').toLowerCase() !== repo.toLowerCase()) return false
  return issue === null || Number(m[2]) === issue
}

// reportProblem: what is wrong with judge(report)'s `parsed` fields, or null. All three are
// needed: a missing pendingDecision could delegate a design that waits on the owner.
function reportProblem(fields: WakeFields | null, repo: string, issue: number | null): string | null {
  if (fields === null) return 'parsed needs fields: brief, created, pendingDecision'
  const { brief, created, pendingDecision } = fields
  if (brief === undefined || (brief !== null && (typeof brief !== 'string' || !briefOk(brief, repo, issue)))) {
    return `fields.brief must be null or a comment URL on ${repo} issue ${issue ?? '<N>'}`
  }
  if (!Array.isArray(created) || !created.every(n => Number.isInteger(n) && n > 0)) {
    return 'fields.created must be a list of issue numbers ([] for none)'
  }
  if (typeof pendingDecision !== 'boolean') return 'fields.pendingDecision must be true or false'
  if (brief === null && created.length === 0) return 'parsed needs a brief or created issues; with neither, answer hold'
  return null
}

function isOpenWake(e: LedgerEntry): boolean {
  return e.status === 'running' && wakeKind(e.kind) !== null
}

// checkAnswer: an answer against the ledger. The id must be an open judge or task, the decision
// one its kind and name allow, with the field that decision needs; fields must be one JSON
// object of plain values. A refused answer leaves the wake open, and the problem goes to the
// decision log (and into the reminder). `via` says which channel answered, for the summary.
export function checkAnswer(ledger: readonly LedgerEntry[], input: AnswerInput, repo: string, via: 'block' | 'tool' = 'block'): Checked {
  const id = input.id.trim().replace(/^id=/, '')
  const decision = input.decision.trim().toLowerCase()
  const refuse = (why: string): Checked => ({ ok: false, problem: `ANSWER ${clip(id, 40)} ${clip(decision, 40)}: ${why}` })
  const entry = ledger.find(e => e.wakeId === id && isOpenWake(e))
  if (entry === undefined) {
    const seen = ledger.find(e => e.wakeId === id)
    return refuse(seen === undefined ? 'no wake has this id' : `that wake is not open (${seen.status})`)
  }
  const kind = wakeKind(entry.kind)
  if (kind === null || kind === 'tell') return refuse('a TELL takes no answer')
  const name = entry.wake ?? ''
  const allowed = decisionsOf(kind, name)
  if (!Object.hasOwn(allowed, decision)) return refuse(`${HEADS[kind]} ${name} allows ${Object.keys(allowed).join(', ')}`)
  const need = allowed[decision] ?? null
  const reason = text(input.reason)
  const instructions = text(input.instructions)
  if (need === 'reason' && reason === null) return refuse('needs a reason')
  if (need === 'instructions' && instructions === null) return refuse('needs instructions')
  const fields = fieldsOf(input.fields)
  if (typeof fields === 'string') return refuse(fields)
  if (need === 'fields') {
    const bad = reportProblem(fields, repo, entry.issue)
    if (bad !== null) return refuse(bad)
  }
  const outcome: Outcome = { kind: 'wake', decision, reason, instructions, bump: null, bumpReason: null, fields: fields ?? {} }
  const summary = `answered ${decision}${via === 'tool' ? ' (tool)' : ''}${reason === null ? '' : `: ${reason}`}`
  return { ok: true, update: { key: entry.key, status: 'done', outcome, summary } }
}

// --- turns (SPEC 8.2, 10.8) ------------------------------------------------------------------

const HEAD_LINE = /^(JUDGE|TASK|TELL) (\S+) id=(\S+)(?: |$)/

// onTurnStart: a turn whose text starts with a wake's first line (a reminder's too) is that
// wake's turn; its id goes on the entry, so the turn's end is told apart from the owner's chat.
// Submit can start the turn before the executor returns, while the entry has no wake id yet:
// then the one such running entry of that kind and name is it, and the update sets both ids.
export function onTurnStart(ledger: readonly LedgerEntry[], text: string, turnId: string): WakeUpdate | null {
  const m = HEAD_LINE.exec(text.trimStart())
  const kind = KINDS[m?.[1] ?? '']
  const name = m?.[2]
  const id = m?.[3]
  if (kind === undefined || name === undefined || id === undefined) return null
  const open = ledger.filter(e => e.status === 'running' && e.kind === kind && e.wake !== undefined && value(e.wake) === name)
  const pending = open.filter(e => e.wakeId === undefined)
  const entry = open.find(e => e.wakeId === id) ?? (pending.length === 1 ? pending[0] : undefined)
  return entry === undefined ? null : { key: entry.key, status: 'running', wakeId: id, turnId }
}

// A main-loop turn as its turn.complete gives it; agentId is set on an agent's turn.
export type TurnEnd = { turnId: string; answer: string; reason: 'answer' | 'aborted' | 'refusal' | 'error'; agentId?: string }

export type TurnOutcome = { updates: WakeUpdate[]; prompts: string[]; problems: string[] }

// reminderLine: the wake's first line again with ` reminder=1`, from the summary the executor
// left on its entry; an entry without it (an older build) gets the head, the repo and its ids.
export function reminderLine(entry: LedgerEntry, repo: string): string {
  const kind = wakeKind(entry.kind) ?? 'judge'
  const head = `${HEADS[kind]} ${value(entry.wake ?? 'unknown')} id=${value(entry.wakeId ?? '')}`
  const summary = entry.summary ?? ''
  if (summary === head || summary.startsWith(`${head} `)) return `${summary} reminder=1`
  const ids: [string, string | number | null][] = [['issue', entry.issue], ['pr', entry.pr], ['run', entry.run], ['head', entry.head]]
  const known = ids.flatMap(([k, v]) => (v === null ? [] : [`${k}=${value(String(v))}`]))
  return [head, `repo=${value(repo)}`, ...known, 'reminder=1'].join(' ')
}

// onTurnComplete: a main-loop turn ended (an agent's turn is act-agents.ts's). Every valid
// ANSWER block in its text closes its wake, whichever turn it came in. Then the open wakes this
// turn belonged to: a tell is delivered once its turn said something (D-25); a judge or task
// that is still open gets exactly one reminder, which repeats why its answer was refused, and
// after that waits for its timeout (SPEC 8.2, 10.8).
export function onTurnComplete(ledger: readonly LedgerEntry[], turn: TurnEnd, repo: string): TurnOutcome {
  const out: TurnOutcome = { updates: [], prompts: [], problems: [] }
  if (turn.agentId !== undefined) return out
  const parsed = parseAnswers(turn.answer)
  out.problems.push(...parsed.problems)
  const refused: string[] = [...parsed.problems]
  let current = [...ledger]
  for (const block of parsed.blocks) {
    const checked = checkAnswer(current, block, repo)
    if (!checked.ok) {
      out.problems.push(checked.problem)
      refused.push(checked.problem)
      continue
    }
    const { update } = checked
    out.updates.push(update)
    // a second block for the same id finds it answered
    current = current.map(e => (e.key === update.key ? { ...e, status: update.status } : e))
  }
  for (const entry of current) {
    if (!isOpenWake(entry) || entry.turnId !== turn.turnId) continue
    const label = `${HEADS[wakeKind(entry.kind) ?? 'judge']} ${entry.wake ?? ''} ${entry.wakeId ?? ''}`
    if (entry.kind === 'tell') {
      if (turn.reason === 'answer' && turn.answer.trim() !== '') out.updates.push({ key: entry.key, status: 'done', summary: 'delivered' })
      else out.problems.push(`${label}: its turn ended (${turn.reason}) with nothing said; it waits for its timeout`)
      continue
    }
    if (entry.reminded === true) {
      out.problems.push(`${label}: no answer after its reminder; it waits for its timeout`)
      continue
    }
    out.updates.push({ key: entry.key, status: 'running', reminded: true })
    const why = refused.slice(0, REFUSALS_SHOWN).map(p => `not accepted: ${p}`)
    out.prompts.push(wakePrompt(reminderLine(entry, repo), why))
  }
  return out
}

// --- timeouts (SPEC 8.2, 10.8) ---------------------------------------------------------------

function duration(ms: Ms): string {
  if (ms > 0 && ms % HOUR === 0) return `${ms / HOUR}h`
  if (ms > 0 && ms % MIN === 0) return `${ms / MIN}m`
  return `${Math.round(ms / 1000)}s`
}

// fallback: an open wake that will get no answer, ended as its timeout ends it. It never acts: a
// judge is done with decision hold (plan holds on it), a task is timed-out (plan tells the owner,
// task-timeout), a tell is timed-out (dropped). why: what ended it; undelivered: the same for a tell.
function fallback(e: LedgerEntry, kind: WakeKind, why: string, undelivered: string): WakeUpdate {
  if (kind === 'judge') {
    const reason = `${why}, so the loop holds`
    const outcome: Outcome = { kind: 'wake', decision: 'hold', reason, instructions: null, bump: null, bumpReason: null, fields: {} }
    return { key: e.key, status: 'done', outcome, summary: `timed out: ${reason}` }
  }
  if (kind === 'task') return { key: e.key, status: 'timed-out', summary: `timed out: ${why}` }
  return { key: e.key, status: 'timed-out', summary: `dropped: ${undelivered}` }
}

// expireWakes: the open wakes past config.wakeTimeoutMs for their kind, counted from the submit,
// ended by their fallback.
export function expireWakes(ledger: readonly LedgerEntry[], now: Ms, config: Config): WakeUpdate[] {
  const out: WakeUpdate[] = []
  for (const e of ledger) {
    const kind = wakeKind(e.kind)
    if (kind === null || e.status !== 'running') continue
    const limit = config.wakeTimeoutMs[kind]
    if (now - e.startedAt < limit) continue
    out.push(fallback(e, kind, `no answer within ${duration(limit)}`, `not delivered within ${duration(limit)}`))
  }
  return out
}

// orphanedWakes: the open wakes no one can answer any more (SPEC 7.5): one another session
// submitted, or one that records no session (an older build, or rebuilt from the event log) and
// started before this load. Its prompt went with that session, so it is lost at once with its
// attempt given back, as a late drop is (D-55): it holds no other wake (O2) until its timeout,
// and its rule decides again next pass. A module reload within one session keeps its wakes.
export function orphanedWakes(ledger: readonly LedgerEntry[], session: string, loadedAt: Ms): WakeUpdate[] {
  const out: WakeUpdate[] = []
  for (const e of ledger) {
    if (wakeKind(e.kind) === null || e.status !== 'running') continue
    const gone = e.session === undefined ? e.startedAt < loadedAt : session !== '' && e.session !== session
    if (!gone) continue
    const why = e.session === undefined ? 'it was open before this load' : 'its session ended'
    out.push({ key: e.key, status: 'lost', attempts: Math.max(0, e.attempts - 1), summary: `lost: ${why}` })
  }
  return out
}

// --- the answer tool (SPEC 8.2, D-04) --------------------------------------------------------

// mcp__factory-loop__answer: the same answer as the block. The block is the primary channel (a
// turn that starts during a plugin reload lacks the tool), so the tool waits behind ToolSearch
// and costs the prompt nothing.
export const ANSWER_TOOL: ToolSpec = {
  name: 'answer',
  description:
    "Answer the factory loop's open JUDGE or TASK wake, as the ANSWER block in your final message " +
    'does (send one or the other, never both). id: the wake line\'s id= value; decision: one the ' +
    'factory-loop:judge skill allows for that wake; reason and instructions: one line each; fields: ' +
    "judge report's object { brief, created, pendingDecision }.",
  inputSchema: {
    type: 'object',
    properties: {
      id: { type: 'string', description: "the wake line's id= value" },
      decision: { type: 'string', description: 'a decision the wake allows' },
      reason: { type: 'string', description: 'one line, for the owner' },
      instructions: { type: 'string', description: "one line, for the agent's prompt" },
      fields: { type: 'object', description: 'judge report: { brief, created, pendingDecision }' },
    },
    required: ['id', 'decision'],
    additionalProperties: false,
  },
  isDeferred: true,
}

export type ToolReply = { ok: boolean; text: string; update: WakeUpdate | null }

// answerTool: the tool's handler, through checkAnswer. `text` is what the tool answers; the
// driver applies `update`. Only the main conversation answers a wake: a call from inside an
// agent's loop (tool.call's agentId) is refused, as an agent's ANSWER block is ignored.
export function answerTool(ledger: readonly LedgerEntry[], input: unknown, repo: string, from: { agentId?: string } = {}): ToolReply {
  const no = (why: string): ToolReply => ({ ok: false, text: `Not recorded: ${why}.`, update: null })
  if (from.agentId !== undefined) return no('only the main conversation answers a wake')
  const o = input !== null && typeof input === 'object' && !Array.isArray(input) ? (input as Record<string, unknown>) : null
  if (o === null || typeof o.id !== 'string' || typeof o.decision !== 'string') return no('id and decision are required, as text')
  for (const key of ['reason', 'instructions'] as const) {
    if (o[key] !== undefined && o[key] !== null && typeof o[key] !== 'string') return no(`${key} must be text`)
  }
  const reason = typeof o.reason === 'string' ? o.reason : null
  const instructions = typeof o.instructions === 'string' ? o.instructions : null
  const checked = checkAnswer(ledger, { id: o.id, decision: o.decision, reason, instructions, fields: o.fields }, repo, 'tool')
  if (!checked.ok) return no(checked.problem)
  const outcome = checked.update.outcome
  const decision = outcome?.kind === 'wake' ? outcome.decision : o.decision
  return { ok: true, text: `Recorded: ${o.id.trim()} ${decision}. No ANSWER block is needed.`, update: checked.update }
}

