// The agent steps (docs/factory-loop/v2/SPEC.md 4.2, 5.1, 10.3, 10.8), generic over their kinds:
// the `agent-step` executor, and the reading of a step's answer into the result plan reads. Each
// step kind is a StepModule of steps-work.ts (design, build, fix), steps-review.ts (review) or
// steps-triage.ts (triage): its agent's prompt and model, its answer contract
// (v2/contracts-*.mjs, through contract.mjs) and what a checked answer means.
//
// - The executor first looks for a valid answer already recorded for its key (10.8), then writes
//   the answer script's job file and the step's record, and spawns the step's own agent type
//   (types.ts STEP_AGENT) with the answer script on the prompt: agents answer with the script only
//   (D-74). A spawn refused or failed is a failed attempt, which plan reads as unknown.
// - An answer ends the step when it is read (10.8): at the agent's turn end, every pass while the
//   entry runs, and before the agent list marks it lost. A writer's ok is taken only at its turn's
//   end, so the stop gate has its say first. One repair message goes to an agent that ended its
//   turn without a valid answer (D-68); a second miss is unknown (bad-answer).
// - Every read result is a done entry with the outcome { kind: 'step', step, result }, unknown
//   ones included, so plan reads why; a turn that ended in error, aborted or refused is unknown
//   (rate-limited for a 429, api for another API error, else agent-dead), unless a valid answer
//   was recorded before it, which is the result (a writer's ok excepted: the stop gate never ran).
// act.ts applies what these give to the live ledger, as it does for v1's agents.
import { V2_CONTRACTS, jobPathOf, jobText, parseAnswer } from '../contract.mjs'
import type { Job, V2Contract, V2ContractName } from '../contract.mjs'
import { ANSWER_SCRIPT, answerPath } from '../exec'
import type { AgentAnswer, Exec, ExecCtx, Executor } from '../exec'
import { scriptShaped } from '../prompts'
import type { ScriptPlace } from '../prompts'
import type { Action, ActionKind, LedgerEntry } from '../types'
import { STEPS as QUEUE } from './steps-queue'
import { STEPS as REVIEW } from './steps-review'
import { STEPS as TRIAGE } from './steps-triage'
import { STEPS as WORK } from './steps-work'
import { AGENT_STEPS, STEP_AGENT, STEP_ROLE, unknownResult } from './types'
import type { AgentStep, Role, StepResult, UnknownWhy } from './types'

const SUMMARY_MAX = 200
// a spawn record or answer file is a few KiB; anything far past this is not one of ours
const RECORD_MAX = 256 * 1024

export type AgentStepAction = Extract<Action, { kind: 'agent-step' }>

// What a step module gives for one attempt: the prompt (which names the answer script and file it
// is handed), the model (null: the agent's own), and the data its contract's check needs.
export type StepSpawn = { prompt: string; model: string | null; data: Record<string, unknown> | null }

// What the executor keeps beside the answer (spawns/<key>.json), so the answer is read and
// checked at the turn's end, after a reload, or by the next pass, the same way.
export type StepRecord = {
  v: 2
  key: string
  issue: number
  step: AgentStep
  life: string
  seq: number
  attempt: number
  branch: string
  slot: string | null
  role: Role
  subagentType: string
  model: string | null
  contract: V2ContractName
  data: Record<string, unknown> | null
  answerFile: string
  prompt: string
}

// One step kind (steps-*.ts). spawn: what to start for this attempt, or why it cannot (a loop
// bug: the attempt fails, never retried). result: what a checked answer means; a writer's reads
// its head on origin (10.8), and a failed read is unknown, never not-ok. says: what a checked
// answer claims of itself, pure and before any read of origin; a writer's module gives it, so its
// not-ok ends the step when read while its ok waits for the turn's end (a writer's module without
// it has every answer wait).
export type StepModule = {
  step: AgentStep
  contract: V2ContractName
  spawn: (ctx: ExecCtx, action: AgentStepAction, place: ScriptPlace) => Promise<StepSpawn | string>
  result: (ctx: ExecCtx, record: StepRecord, answer: unknown) => Promise<StepResult>
  says?: (answer: unknown) => 'ok' | 'not-ok'
}

export const STEP_MODULES: Partial<Record<AgentStep, StepModule>> = { ...WORK, ...REVIEW, ...TRIAGE, ...QUEUE }

// What the step machinery reads steps and answers by: the step modules and the contracts, the
// real ones but in a test, which hands its own.
export type StepDeps = { modules: Partial<Record<AgentStep, StepModule>>; contracts: Readonly<Record<string, V2Contract>> }
export const STEP_DEPS: StepDeps = { modules: STEP_MODULES, contracts: V2_CONTRACTS }

// --- paths and records ------------------------------------------------------------------------------

const fileName = (key: string) => key.replace(/[^A-Za-z0-9._-]+/g, '_')

// stepAnswerPath: where a step's agent records its answer with the answer script: one file per
// key, and a step key is one attempt, so a re-dispatch of the key finds an answer already there.
export function stepAnswerPath(loopDir: string, key: string): string {
  return `${loopDir}/answers/${fileName(key)}.answer.json`
}

export function stepRecordPath(loopDir: string, key: string): string {
  return `${loopDir}/spawns/${fileName(key)}.json`
}

// parseStepRecord: a step record's text, or null when it is not one.
export function parseStepRecord(text: string | null, contracts: StepDeps['contracts'] = V2_CONTRACTS): StepRecord | null {
  if (text === null || text.length > RECORD_MAX) return null
  try {
    const o = JSON.parse(text) as Record<string, unknown>
    if (o === null || typeof o !== 'object' || o.v !== 2) return null
    const step = AGENT_STEPS.find(s => s === o.step)
    const contract = Object.keys(contracts).find(c => c === o.contract) as V2ContractName | undefined
    const str = (v: unknown) => typeof v === 'string' && v !== ''
    const int = (v: unknown) => typeof v === 'number' && Number.isInteger(v) && v > 0
    const data = o.data === null || (typeof o.data === 'object' && !Array.isArray(o.data)) ? (o.data as Record<string, unknown> | null) : undefined
    if (step === undefined || contract === undefined || data === undefined) return null
    if (!str(o.key) || !int(o.issue) || !str(o.life) || !int(o.seq) || !int(o.attempt) || !str(o.branch) || !str(o.subagentType) || !str(o.answerFile)) return null
    if (o.role !== 'writer' && o.role !== 'reader') return null
    return {
      v: 2,
      key: String(o.key),
      issue: Number(o.issue),
      step,
      life: String(o.life),
      seq: Number(o.seq),
      attempt: Number(o.attempt),
      branch: String(o.branch),
      slot: typeof o.slot === 'string' ? o.slot : null,
      role: o.role,
      subagentType: String(o.subagentType),
      model: typeof o.model === 'string' ? o.model : null,
      contract,
      data,
      answerFile: String(o.answerFile),
      prompt: typeof o.prompt === 'string' ? o.prompt : '',
    }
  } catch {
    return null
  }
}

// --- results ----------------------------------------------------------------------------------------

function doneWith(step: AgentStep, result: StepResult, summary: string): Exec {
  return { status: 'done', outcome: { kind: 'step', step, result }, summary: clip(summary) }
}

function refused(why: string): Exec {
  return { status: 'failed', summary: clip(`refused: ${why}`), noRetry: true }
}

function describe(result: StepResult): string {
  const tail = result.reason === null ? '' : `: ${result.reason}`
  return result.event === 'unknown' ? `unknown (${result.why ?? 'unknown'})${tail}` : `${result.event}${tail}`
}

// The answer an entry's agent recorded, checked against its record's contract, or the problem.
async function recordedAnswer(ctx: ExecCtx, record: StepRecord, deps: StepDeps): Promise<{ answer: unknown } | { problem: string } | null> {
  let body: string | null
  try {
    body = await ctx.io.readFile(record.answerFile)
  } catch {
    body = null
  }
  if (body === null) return null
  const job: Job = { contract: record.contract, purpose: null, repo: ctx.rt.repo, issue: record.issue, branch: record.branch }
  if (record.data !== null) job.data = record.data
  const file = parseAnswer(body, record.contract)
  const contract = deps.contracts[record.contract]
  if (contract === undefined) return { problem: `no contract ${record.contract} checks this answer` }
  const check = file.ok ? contract.check(file.outcome, job) : file
  return check.ok ? { answer: check.outcome } : { problem: `the answer recorded with the answer script does not pass its checks: ${check.problems.join('; ')}` }
}

async function recordOf(ctx: ExecCtx, key: string, deps: StepDeps): Promise<StepRecord | null> {
  try {
    return parseStepRecord(await ctx.io.readFile(stepRecordPath(ctx.rt.loopDir, key)), deps.contracts)
  } catch {
    return null
  }
}

// resultOf: a recorded answer as its step's result, through its module.
async function resultOf(ctx: ExecCtx, record: StepRecord, answer: unknown, deps: StepDeps): Promise<StepResult> {
  const module = deps.modules[record.step]
  if (module === undefined) return unknownResult('bad-answer', `no module reads a ${record.step} answer`)
  try {
    return await module.result(ctx, record, answer)
  } catch (err) {
    return unknownResult('cli', `the ${record.step} answer could not be read: ${message(err)}`)
  }
}

// waitsForGate: a writer's answer that says ok (or whose module cannot say) is taken only at its
// turn's normal end, so the stop gate has its say first (10.6, 10.8). It is decided on the answer
// itself, before the module reads origin, so nothing runs for it until then.
function waitsForGate(record: StepRecord, answer: unknown, deps: StepDeps): boolean {
  if (record.role !== 'writer') return false
  const says = deps.modules[record.step]?.says
  if (says === undefined) return true
  try {
    return says(answer) !== 'not-ok'
  } catch {
    return true
  }
}

// stepRecorded: the result of a valid answer already recorded for this entry's attempt, as the
// Exec that finishes it; null when there is none. Before the turn's end (a pass's read, or an
// agent the list shows gone), a writer's ok is not taken yet: it waits for the stop gate.
export async function stepRecorded(ctx: ExecCtx, entry: LedgerEntry, atTurnEnd: boolean, deps: StepDeps = STEP_DEPS): Promise<Exec | null> {
  const record = await recordOf(ctx, entry.key, deps)
  if (record === null) return null
  const read = await recordedAnswer(ctx, record, deps)
  if (read === null || 'problem' in read) return null
  if (!atTurnEnd && waitsForGate(record, read.answer, deps)) return null
  const result = await resultOf(ctx, record, read.answer, deps)
  return doneWith(record.step, result, `${record.step} #${record.issue}: ${describe(result)}${atTurnEnd ? '' : ' (read before its turn ended)'}`)
}

// The running agent steps a pass reads the answers of (10.8): each one whose answer is recorded
// ends when it is read, a writer's ok excepted, which waits for its turn's end. act.ts applies
// each Exec to the live ledger while its entry still runs as read.
export async function stepAnswers(entries: readonly LedgerEntry[], ctxOf: (entry: LedgerEntry) => ExecCtx, deps: StepDeps = STEP_DEPS): Promise<{ entry: LedgerEntry; exec: Exec }[]> {
  const out: { entry: LedgerEntry; exec: Exec }[] = []
  for (const entry of entries.filter(e => e.kind === 'agent-step' && e.status === 'running')) {
    const exec = await stepRecorded(ctxOf(entry), entry, false, deps)
    if (exec !== null) out.push({ entry, exec })
  }
  return out
}

// agentTypeOf: a recorded agent type, plugin:name, or null.
function agentTypeOf(text: string | undefined): `${string}:${string}` | null {
  return text !== undefined && /^[\w-]+:[\w-]+$/.test(text) ? (text as `${string}:${string}`) : null
}

// What an agent's turn end gave (act.ts agentAnswered): the Exec to finish the entry with, or,
// with a problem and a repair message, the one more ask before it (D-68).
export type StepTaken = { exec: Exec; problem: string | null; repair: string | null; subagentType: `${string}:${string}` }

// A rate limit (a 429 or the usage window), as a turn's last words name it: unknown
// (rate-limited), which plan reads as the outside cause `usage`, a free re-run (5.1). Any other API
// error (a 5xx, overloaded) is unknown (api) and counts as unexplained (5.3).
const RATE_LIMIT = /\b429\b|rate.?limit|usage limit|too many requests/i
const API_ERROR = /\b(500|502|503|504|529)\b|overloaded|API Error/i
const WORDS_MAX = 120

// lostTurn: the unknown of a turn that ended in error, aborted or refused, with an excerpt of its
// last words, so triage and the decision log see what it said.
function lostTurn(answer: AgentAnswer): StepResult {
  const why: UnknownWhy = RATE_LIMIT.test(answer.answer) ? 'rate-limited' : API_ERROR.test(answer.answer) ? 'api' : 'agent-dead'
  const words = answer.answer.replace(/\s+/g, ' ').trim()
  const excerpt = words.length > WORDS_MAX ? `${words.slice(0, WORDS_MAX - 3)}...` : words
  return unknownResult(why, `its turn ended: ${answer.reason}${excerpt === '' ? '' : `: ${excerpt}`}`)
}

// stepAnswered: an agent step's turn ended. Its final words are saved for the owner and the
// triage (exec.ts answerPath), then its recorded answer is read.
export async function stepAnswered(ctx: ExecCtx, entry: LedgerEntry, answer: AgentAnswer, deps: StepDeps = STEP_DEPS): Promise<StepTaken> {
  const record = await recordOf(ctx, entry.key, deps)
  const step = record?.step ?? entry.step ?? 'build'
  const subagentType = agentTypeOf(record?.subagentType) ?? STEP_AGENT[step]
  const notes: string[] = []
  try {
    await ctx.io.writeFile(answerPath(ctx.rt.loopDir, entry.key), answer.answer)
  } catch (err) {
    notes.push(`answer not saved: ${message(err)}`)
  }
  const note = (exec: Exec): Exec => (notes.length === 0 ? exec : { ...exec, summary: clip(`${exec.summary}; ${notes.join('; ')}`) })
  if (record === null) return { exec: refused(`${entry.key}: no step record to read its answer by`), problem: null, repair: null, subagentType }
  const read = await recordedAnswer(ctx, record, deps)
  if (answer.reason !== 'answer') {
    // a valid answer recorded before the turn ended in error is the result (10.8), but a writer's
    // ok, which the stop gate never passed
    const kept = read !== null && 'answer' in read && !waitsForGate(record, read.answer, deps) ? read : null
    const result = kept !== null ? await resultOf(ctx, record, kept.answer, deps) : lostTurn(answer)
    const tail = kept !== null ? ` (recorded before its turn ended: ${answer.reason})` : ''
    return { exec: note(doneWith(step, result, `${step} #${record.issue}: ${describe(result)}${tail}`)), problem: null, repair: null, subagentType }
  }
  if (read !== null && 'answer' in read) {
    const result = await resultOf(ctx, record, read.answer, deps)
    return { exec: note(doneWith(step, result, `${step} #${record.issue}: ${describe(result)}`)), problem: null, repair: null, subagentType }
  }
  const problem = read === null ? 'no answer was recorded with the answer script' : read.problem
  const result = unknownResult('bad-answer', problem)
  const place: ScriptPlace = { bin: `${ctx.rt.pluginRoot}/${ANSWER_SCRIPT}`, file: record.answerFile }
  const repair = `Your answer was not recorded: ${problem}. Record it now with \`${place.bin} --to ${place.file}\` and the JSON object your prompt asks for, then end your turn.`
  return { exec: note(doneWith(step, result, `${step} #${record.issue}: ${describe(result)}`)), problem, repair, subagentType }
}

// --- the executor -----------------------------------------------------------------------------------

const TITLE: Record<AgentStep, string> = { design: 'Design', build: 'Build', review: 'Review', fix: 'Fix', triage: 'Triage' }

// stepExecutor: the agent-step executor: one attempt of an agent step, in the record's slot.
export const stepExecutor = (deps: StepDeps = STEP_DEPS): Executor => async (ctx, action) => {
  if (action.kind !== 'agent-step') return refused(`the agent-step executor got a ${action.kind} action`)
  if (action.issue === null) return refused(`${action.key} names no issue`)
  const module = deps.modules[action.step]
  if (module === undefined) return refused(`no module runs the ${action.step} step`)
  const place: ScriptPlace = { bin: `${ctx.rt.pluginRoot}/${ANSWER_SCRIPT}`, file: stepAnswerPath(ctx.rt.loopDir, action.key) }
  const jobFile = jobPathOf(place.file)
  if (jobFile === null || !scriptShaped(place)) return refused(`the answer script or file of ${action.key} is not a plain absolute path`)
  // an answer already recorded for this key is the result (10.8)
  const earlier = await stepRecorded(ctx, ctx.entry, true, deps)
  if (earlier !== null) return earlier
  const spawn = await module.spawn(ctx, action, place)
  if (typeof spawn === 'string') return refused(spawn)
  const job: Job = { contract: module.contract, purpose: null, repo: ctx.rt.repo, issue: action.issue, branch: action.branch }
  if (spawn.data !== null) job.data = spawn.data
  const subagentType = STEP_AGENT[action.step]
  const record: StepRecord = {
    v: 2,
    key: action.key,
    issue: action.issue,
    step: action.step,
    life: action.life,
    seq: action.seq,
    attempt: action.attempt,
    branch: action.branch,
    slot: action.slot,
    role: STEP_ROLE[action.step],
    subagentType,
    model: spawn.model,
    contract: module.contract,
    data: spawn.data,
    answerFile: place.file,
    prompt: spawn.prompt,
  }
  try {
    await ctx.io.writeFile(jobFile, jobText(job))
    await ctx.io.writeFile(stepRecordPath(ctx.rt.loopDir, action.key), JSON.stringify(record, null, 2))
  } catch (err) {
    return { status: 'failed', summary: clip(`${action.key}: its job file or record could not be written: ${message(err)}`) }
  }
  const input: { subagentType: string; prompt: string; description: string; name: string; model?: string; cwd?: string } = {
    subagentType,
    prompt: spawn.prompt,
    description: `${TITLE[action.step]} #${action.issue}`,
    name: `${action.step}-${action.issue}-s${action.seq}-a${action.attempt}`,
  }
  if (spawn.model !== null) input.model = spawn.model
  // the companion starts the agent there (10.3)
  if (action.slot !== null) input.cwd = action.slot
  let r: { agentId?: string; deny?: string }
  try {
    r = await ctx.io.spawnAgent(input)
  } catch (err) {
    return { status: 'failed', summary: clip(`${subagentType}: the spawn threw: ${message(err)}`) }
  }
  if (typeof r.deny === 'string') return { status: 'failed', summary: clip(`${subagentType} denied: ${r.deny}`) }
  if (r.agentId === undefined || r.agentId === '') return { status: 'failed', summary: `${subagentType}: started with no agent id` }
  return { status: 'running', agentId: r.agentId, summary: clip(`${subagentType} started for #${action.issue} (${action.key}): ${r.agentId}`) }
}

export const executors: Partial<Record<ActionKind, Executor>> = { 'agent-step': stepExecutor() }

function clip(text: string): string {
  return text.length > SUMMARY_MAX ? `${text.slice(0, SUMMARY_MAX - 3)}...` : text
}

function message(err: unknown): string {
  return err instanceof Error ? err.message : String(err)
}

files.hooks/replies.ts:
// The agents' replies, parsed: the designer's RESULT line (SPEC 7.2), the adjudicator's verdict
// and ACTION lines with the merge review's report (SPEC 7.3, plugins/callum-flow/agents/
// adjudicator.md), and the implementer's and fixer's handoff (the RESULT line prompts.ts asks
// for after the implement-issue handoff). Pure: text in, an Outcome or null out; each read*
// says instead what kept a reply from parsing, for the one repair message (#548). A reply that
// is not the contract is unparseable, never guessed: act-agents.ts records it as a failed
// attempt, except the designer's, which goes to the model as judge(report) (rule D3). The same
// contracts as structured answers (the answer tools and the answer script) are contract.mjs's,
// whose words and shapes the lines here share.
import { ACTIONS_FOR, BUMPS, FINDING_ID, FLAGS, HANDOFF_SHAPES, declinedFindings, gatedWithoutRun, handoffOutcome, isBriefUrl } from './contract.mjs'
import type { AdjudicatorOutcome, DesignResult, HandoffFields, HandoffOutcome } from './contract.mjs'
import type { AdjudicatorAction, AdjudicatorPurpose, Bump, MergeFlag, MergeReport, Outcome } from './types'

export { ACTIONS_FOR, BUMPS, FINDING_ID, FLAGS, HANDOFF_SHAPES, VERDICTS, gatedWithoutRun, handoffOutcome, isBriefUrl } from './contract.mjs'
export type { AdjudicatorOutcome, DesignResult, HandoffFields, HandoffOutcome }
export type DesignerOutcome = Extract<Outcome, { kind: 'designer' }>

// The machine lines, as the prompts ask for them (prompts.ts quotes these).
export const DESIGNER_RESULT = 'RESULT brief=<comment URL|none> created=<n1,n2|none> pending_decision=<yes|no>'
export const HANDOFF_RESULT = 'RESULT run=<id|none> head=<sha|none> commit=<sha|none> gated=<yes|no> branch=<name> pr=<n|none>'

const VERDICT_LINE = /^(CORRECT|WRONG|NIT|ENV|DUP):\s*\S/
const VERDICT_WORD = /^(CORRECT|WRONG|NIT|ENV|DUP):/
// a contract word with decoration around it (`- WRONG:`, `**ACTION**:`, `` `NIT`: ``), then its colon
const MISSHAPEN_LINE = /^\W*(CORRECT|WRONG|NIT|ENV|DUP|ACTION|SUMMARY|BUMP|FLAGS)\W*:/

// A reply's lines, trimmed, blank ones left out.
function lines(text: string): string[] {
  return text
    .split(/\r?\n/)
    .map(l => l.trim())
    .filter(l => l !== '')
}

// A machine line an agent wrapped in backticks reads the same.
function bare(line: string): string {
  return line.length > 1 && line.startsWith('`') && line.endsWith('`') ? line.slice(1, -1).trim() : line
}

// A reply's line quoted in a problem, cut to a readable length.
function quote(line: string): string {
  return JSON.stringify(line.length > 120 ? `${line.slice(0, 117)}...` : line)
}

const parsed = <T>(r: T | string): T | null => (typeof r === 'string' ? null : r)

// --- the designer (SPEC 7.2) -----------------------------------------------------------------

const DESIGNER_LINE = /^RESULT\s+brief=(\S+)\s+created=(\S+)\s+pending_decision=(yes|no)$/

// parseDesigner: the report's last line, exactly the RESULT shape, with a brief URL on the
// designed issue of this repo. Anything else is { unparsed: true }: judge(report) hands the
// model the saved report and asks for the fields.
export function parseDesigner(answer: string, repo: string, issue: number | null): DesignerOutcome {
  return parsed(readDesigner(answer, repo, issue)) ?? { kind: 'designer', unparsed: true }
}

// readDesigner: parseDesigner's result, or what kept the report from parsing.
export function readDesigner(answer: string, repo: string, issue: number | null): DesignResult | string {
  const all = lines(answer)
  const last = all[all.length - 1]
  const m = last === undefined ? null : bare(last).match(DESIGNER_LINE)
  if (last === undefined || m === null) {
    if (last !== undefined && /^RESULT\b/.test(bare(last))) return `the last line is not in the shape ${DESIGNER_RESULT}: ${quote(last)}`
    return all.some(l => /^RESULT\b/.test(bare(l))) ? 'the RESULT line is not the last line' : 'no RESULT line'
  }
  const [, briefRaw = '', createdRaw = '', pending] = m
  if (briefRaw !== 'none' && !isBriefUrl(briefRaw, repo, issue)) return `brief= is neither none nor a comment URL on ${repo} issue ${issue ?? '<N>'}`
  if (createdRaw !== 'none' && !/^[1-9]\d*(,[1-9]\d*)*$/.test(createdRaw)) return 'created= is neither none nor issue numbers joined by commas'
  const created = createdRaw === 'none' ? [] : [...new Set(createdRaw.split(',').map(Number))]
  return { kind: 'designer', brief: briefRaw === 'none' ? null : briefRaw, created, pendingDecision: pending === 'yes' }
}

// --- the adjudicator (SPEC 7.3) ----------------------------------------------------------------

// parseAdjudicator: verdict lines `<VERDICT>: <reason>`, exactly one `ACTION:` line, and for
// purpose merge exactly one each of SUMMARY, BUMP and FLAGS. Any other line inside the contract,
// an ACTION the purpose does not take, or a second ACTION makes the reply unparseable (rule P2
// retries it); notes after a complete contract are not read (#559).
export function parseAdjudicator(answer: string, purpose: AdjudicatorPurpose): AdjudicatorOutcome | null {
  return parsed(readAdjudicator(answer, purpose))
}

// readAdjudicator: parseAdjudicator's result, or what kept the reply from parsing.
export function readAdjudicator(answer: string, purpose: AdjudicatorPurpose): AdjudicatorOutcome | string {
  const verdicts: string[] = []
  const actions: { line: string; action: AdjudicatorAction | null }[] = []
  let summary: string | null = null
  let bump: { bump: Bump; reason: string } | null = null
  let flags: MergeFlag[] | null = null
  // prose before the contract is skipped (agents often open with a sentence of context, as the
  // testbed showed), but a contract line in the wrong shape (a bulleted or bold verdict, a fenced
  // block) is not prose; from the first contract line on, any other line makes the reply
  // unparseable. Only a contract word followed by its colon is a contract line: a sentence that
  // merely opens with one ("CORRECT is not warranted", "CORRECT/WRONG judgments:") is prose.
  // Once the contract is complete (its ACTION line and, for a merge review, its three report
  // lines), the first line with no contract word and its colon starts notes, which are not read
  // ("What I checked:" and its bullets, as testbed run 3's merge reviews added, #559). A line
  // with a contract word and its colon in any shape (a second ACTION, a verdict, a report line,
  // `- WRONG:`) is no note: in the notes it makes the reply unparseable, as before the contract.
  let started = false
  let notes = false
  for (const line of lines(answer)) {
    if (notes) {
      if (MISSHAPEN_LINE.test(line)) return `a contract line after the notes that follow the contract: ${quote(line)}`
      continue
    }
    if (!started && !VERDICT_LINE.test(line) && !/^(ACTION|SUMMARY|BUMP|FLAGS):/.test(line)) {
      if (MISSHAPEN_LINE.test(line) || /^[A-Z]{2,}:/.test(line) || line.startsWith('```')) return `a contract line in the wrong shape: ${quote(line)}`
      continue
    }
    started = true
    if (VERDICT_LINE.test(line)) {
      verdicts.push(line)
      continue
    }
    const act = line.match(/^ACTION:\s*(.*)$/)
    if (act !== null) {
      actions.push({ line, action: parseAction(act[1] ?? '') })
      continue
    }
    const report = line.match(/^(SUMMARY|BUMP|FLAGS):\s*(.*)$/)
    const complete = actions.length === 1 && (purpose !== 'merge' || (summary !== null && bump !== null && flags !== null))
    if (report === null && complete && !MISSHAPEN_LINE.test(line)) {
      notes = true
      continue
    }
    if (report === null) return `a line after the first contract line that is not a contract line: ${quote(line)}`
    const [, name, value = ''] = report
    if (purpose !== 'merge') return `${name} answers a merge review only, and this is a ${purpose} review`
    if (name === 'SUMMARY') {
      if (summary !== null) return 'more than one SUMMARY line'
      if (value === '') return 'an empty SUMMARY line'
      summary = value
    } else if (name === 'BUMP') {
      const parsed = parseBump(value)
      if (bump !== null) return 'more than one BUMP line'
      if (parsed === null) return `the BUMP line is not patch, minor or major and its reason: ${quote(line)}`
      bump = parsed
    } else {
      const parsed = parseFlags(value)
      if (flags !== null) return 'more than one FLAGS line'
      if (parsed === null) return `the FLAGS line is not none or a comma list of ${FLAGS.join(', ')}: ${quote(line)}`
      flags = parsed
    }
  }
  const only = actions.length === 1 ? actions[0] : undefined
  if (only === undefined) return actions.length === 0 ? 'no ACTION line' : 'more than one ACTION line'
  const action = only.action
  if (action === null) return `the ACTION line does not read as any action the contract allows: ${quote(only.line)}`
  if (!ACTIONS_FOR[purpose].includes(action.type)) return `ACTION ${action.type} does not answer a ${purpose} review, which takes ${ACTIONS_FOR[purpose].join(', ')}`
  if (action.type === 'fix') action.ignore = declinedFindings(verdicts.map(verdictId).filter(id => id !== null), action.findings)
  if (purpose !== 'merge') return { kind: 'adjudicator', verdicts, action, report: null }
  const missing = [summary === null ? 'SUMMARY' : '', bump === null ? 'BUMP' : '', flags === null ? 'FLAGS' : ''].filter(n => n !== '')
  if (summary === null || bump === null || flags === null) return `a merge review needs its ${missing.join(', ')} line${missing.length === 1 ? '' : 's'}`
  const report: MergeReport = { summary, bump: bump.bump, bumpReason: bump.reason, flags }
  return { kind: 'adjudicator', verdicts, action, report }
}

// verdictId: the finding id a verdict line opens its reason with (`NIT: review-2 naming` or
// `NIT: review-2: naming`), or null when it opens with prose instead.
function verdictId(line: string): string | null {
  const word = line.replace(VERDICT_WORD, '').trim().split(/\s/)[0]?.replace(/[:,;.]+$/, '') ?? ''
  return /^[A-Za-z][\w.]*-\d+$/.test(word) ? word : null
}

// `<patch|minor|major> <reason>`; a reason led by a dash or colon reads the same.
function parseBump(value: string): { bump: Bump; reason: string } | null {
  const m = value.match(/^(\S+)\s*(.*)$/)
  const bump = BUMPS.find(b => b === m?.[1]?.toLowerCase())
  if (m === null || bump === undefined) return null
  return { bump, reason: (m[2] ?? '').replace(/^[-:]\s*/, '').trim() }
}

// `none`, or a comma list of the four flags; a flag the loop does not know may matter for
// sequencing, so it makes the reply unparseable rather than being dropped.
function parseFlags(value: string): MergeFlag[] | null {
  if (value.toLowerCase() === 'none') return []
  const out: MergeFlag[] = []
  for (const word of value.split(',').map(w => w.trim().toLowerCase())) {
    const flag = FLAGS.find(f => f === word)
    if (flag === undefined) return null
    if (!out.includes(flag)) out.push(flag)
  }
  return out.length > 0 ? out : null
}

const FIX_FLAGS = ['--findings', '--instructions', '--add-finding'] as const
const APPROVE_FLAGS = ['--reason'] as const

// parseAction: what follows `ACTION:`, by the definition's contract: `approve [--reason <text>]`,
// `fix` with `--findings <ids>`, `--instructions <text>` and/or `--add-finding <json>`, `skip`,
// `fixer: <instructions>`, `escalate: <why>`, and the merge review's `merge` and `hold <reason>`.
// A value may be quoted as in a shell ('...' or "...") or bare, up to the next flag.
export function parseAction(text: string): AdjudicatorAction | null {
  const m = text.trim().match(/^(approve|fixer|fix|skip|escalate|merge|hold)\b(:?)\s*([\s\S]*)$/)
  if (m === null) return null
  const [, type, colon, rest = ''] = m
  if (colon === ':' && type !== 'fixer' && type !== 'escalate' && type !== 'hold') return null
  switch (type) {
    case 'skip':
      return rest === '' ? { type: 'skip' } : null
    case 'merge':
      return rest === '' ? { type: 'merge' } : null
    case 'approve': {
      if (rest === '') return { type: 'approve', reason: null }
      const reason = parseOptions(rest, APPROVE_FLAGS)?.get('--reason')
      return reason === undefined ? null : { type: 'approve', reason }
    }
    case 'fix': {
      const flags = parseOptions(rest, FIX_FLAGS)
      if (flags === null || flags.size === 0) return null
      // finding ids as no-mistakes names them (review-1); a stray flag is no id
      const ids = flags.get('--findings')?.split(/[\s,]+/).filter(id => id !== '')
      if (ids !== undefined && (ids.length === 0 || !ids.every(id => FINDING_ID.test(id)))) return null
      const findings = ids === undefined ? null : ids.join(',')
      const json = flags.get('--add-finding')
      const addFinding = json === undefined ? null : findingJson(json)
      if (addFinding === '') return null
      return { type: 'fix', findings, instructions: flags.get('--instructions') ?? null, addFinding, ignore: null }
    }
    case 'fixer':
      return rest === '' ? null : { type: 'fixer', instructions: unquote(rest) }
    case 'escalate':
      return rest === '' ? null : { type: 'escalate', why: unquote(rest) }
    case 'hold':
      return rest === '' ? null : { type: 'hold', reason: unquote(rest) }
    default:
      return null
  }
}

// The finding no-mistakes adds (`--add-finding`, one JSON object), compacted; '' when it is not
// a JSON object, which the caller rejects.
function findingJson(text: string): string {
  try {
    const v: unknown = JSON.parse(text)
    return v !== null && typeof v === 'object' && !Array.isArray(v) ? JSON.stringify(v) : ''
  } catch {
    return ''
  }
}

function unquote(text: string): string {
  const t = text.trim()
  const q = t[0]
  return t.length > 1 && (q === '"' || q === "'") && t.endsWith(q) ? t.slice(1, -1).trim() : t
}

// parseOptions: `--flag value` pairs from the allowed set, each at most once, every value
// non-empty. Anything else (an unknown flag such as --yes, stray words) is null.
function parseOptions(text: string, allowed: readonly string[]): Map<string, string> | null {
  const out = new Map<string, string>()
  const flagAt = (j: number) =>
    allowed.find(f => text.startsWith(f, j) && (j + f.length === text.length || /[\s=]/.test(text[j + f.length] ?? ''))) ?? null
  let i = 0
  for (;;) {
    while (i < text.length && /\s/.test(text[i] ?? '')) i++
    if (i >= text.length) return out
    const flag = flagAt(i)
    if (flag === null || out.has(flag)) return null
    i += flag.length
    if (text[i] === '=') i++
    while (i < text.length && /\s/.test(text[i] ?? '')) i++
    const read = readValue(text, i, flagAt)
    if (read === null || read.value === '') return null
    out.set(flag, read.value)
    i = read.end
  }
}

// readValue: one value at i: quoted, a JSON object or array (balanced), or bare up to the next
// allowed flag that starts a word.
function readValue(text: string, i: number, flagAt: (j: number) => string | null): { value: string; end: number } | null {
  const c = text[i]
  const endsWord = (j: number) => j >= text.length || /\s/.test(text[j] ?? '')
  if (c === '"' || c === "'") {
    let value = ''
    let j = i + 1
    while (j < text.length && text[j] !== c) {
      // inside double quotes a backslash escapes " \ $ and ` (POSIX sh)
      if (c === '"' && text[j] === '\\' && '"\\$`'.includes(text[j + 1] ?? 'x')) j++
      value += text[j] ?? ''
      j++
    }
    if (j >= text.length || !endsWord(j + 1)) return null
    return { value: value.trim(), end: j + 1 }
  }
  if (c === '{' || c === '[') {
    const end = jsonEnd(text, i)
    return end === null || !endsWord(end) ? null : { value: text.slice(i, end), end }
  }
  let j = i
  while (j < text.length && !(/\s/.test(text[j] ?? '') && flagAt(j + 1) !== null)) j++
  return { value: text.slice(i, j).trim(), end: j }
}

// jsonEnd: the index after the bracket that closes the one at i, minding JSON strings.
function jsonEnd(text: string, i: number): number | null {
  let depth = 0
  let inString = false
  for (let j = i; j < text.length; j++) {
    const c = text[j]
    if (inString) {
      if (c === '\\') j++
      else if (c === '"') inString = false
    } else if (c === '"') inString = true
    else if (c === '{' || c === '[') depth++
    else if (c === '}' || c === ']') {
      depth--
      if (depth === 0) return j + 1
    }
  }
  return null
}

// --- implementer and fixer handoffs ----------------------------------------------------------

const HANDOFF_LINE = /^RESULT\s+run=(\S+)\s+head=(\S+)\s+commit=(\S+)\s+gated=(yes|no)\s+branch=(\S+)\s+pr=(\S+)$/

// handoffFields: one RESULT line's fields, each checked for its shape, or null.
function handoffFields(line: string): HandoffFields | null {
  const m = bare(line).match(HANDOFF_LINE)
  if (m === null) return null
  const [, run = '', head = '', commit = '', gated, branch = '', pr = ''] = m
  const shapes: [string, RegExp][] = [
    [run, HANDOFF_SHAPES.run],
    [head, HANDOFF_SHAPES.sha],
    [commit, HANDOFF_SHAPES.sha],
    [branch, HANDOFF_SHAPES.branch],
    [pr, /^#?\d+$/],
  ]
  if (shapes.some(([v, shape]) => v !== 'none' && !shape.test(v))) return null
  const opt = (v: string) => (v === 'none' ? null : v)
  return {
    run: opt(run),
    head: opt(head)?.toLowerCase() ?? null,
    commit: opt(commit)?.toLowerCase() ?? null,
    gated: gated === 'yes',
    branch: opt(branch),
    pr: pr === 'none' ? null : Number(pr.replace('#', '')),
  }
}

// parseHandoff: the last RESULT line of an implementer's or fixer's handoff. It is not gated
// when it says so, or when the run's head is not the agent's commit (implement-issue section 8:
// never rationalise a mismatch away). newBranch is the branch it reports when that is not the
// one the spawn named (an implementer is named none). With no RESULT line, the words NOT GATED
// still say enough for rule D5; anything else is unparseable.
export function parseHandoff(answer: string, namedBranch: string | null): HandoffOutcome | null {
  return parsed(readHandoff(answer, namedBranch))
}

// readHandoff: parseHandoff's result, or what kept the handoff from parsing.
export function readHandoff(answer: string, namedBranch: string | null): HandoffOutcome | string {
  const all = lines(answer)
  const found = all.map(handoffFields).filter(f => f !== null)
  const fields = found[found.length - 1]
  if (fields === undefined) {
    if (/\bNOT GATED\b/.test(answer)) return { kind: 'handoff', notGated: true, run: null, head: null, newBranch: null }
    const misshapen = all.filter(l => /^RESULT\b/.test(bare(l))).pop()
    return misshapen === undefined ? 'no RESULT line, and it does not say NOT GATED' : `the RESULT line is not in the shape ${HANDOFF_RESULT}: ${quote(misshapen)}`
  }
  if (gatedWithoutRun(fields)) return 'the RESULT line says gated=yes with run=none, and with no pipeline run nothing is gated: name the run, or say gated=no'
  return handoffOutcome(fields, namedBranch)
}

