// Pure parsers for what observe reads: each turns one command's output into typed values,
// or reports that it could not. No I/O here, so the tests and the replay harness (plain
// Node) drive them directly. Types only are imported.
import type { Bump, Checkout, Milestone, Pool, RunState, Stage, Usage } from './types'

const STAGES: readonly Stage[] = [
  'queued',
  'designing',
  'implementing',
  'in pipeline',
  'parked',
  'ready to merge',
  'merged',
  'closed without merge',
]

export function isoMs(value: unknown): number | null {
  if (typeof value !== 'string' || value === '') return null
  const ms = Date.parse(value)
  return Number.isNaN(ms) ? null : ms
}

// --- callum-flow-factory-state --format json ------------------------------------------------

export type FactoryIssue = {
  number: number
  stage: Stage
  stageSince: number | null
  holder: string | null
  run: string | null
  pr: number | null
  stuck: string | null
  // the lease end of a claim the tool shows lapsed (its detail `claim lapsed at <ISO>`), else null
  lapsedAt: number | null
  ended: boolean
  github: { open: boolean | null; labels: string[] | null } | null
}

export type Factory = { at: number; issues: FactoryIssue[] }

// parseFactoryState: the repo's live and recently ended issues, or null when the document is
// not a factory-state report for that repo.
export function parseFactoryState(json: string, repo: string): Factory | null {
  let doc: { at?: unknown; repos?: { repo?: unknown; issues?: unknown[]; recent?: unknown[] }[] }
  try {
    doc = JSON.parse(json)
  } catch {
    return null
  }
  const at = isoMs(doc.at)
  const entry = Array.isArray(doc.repos) ? doc.repos.find(r => r.repo === repo) : undefined
  if (at === null || entry === undefined) return null
  const issues: FactoryIssue[] = []
  const take = (list: unknown[] | undefined, ended: boolean) => {
    for (const raw of list ?? []) {
      const i = raw as Record<string, unknown>
      const stage = i.stage as Stage
      if (typeof i.issue !== 'number' || !STAGES.includes(stage)) continue
      const stuck = i.stuck as { rule?: unknown } | null
      const gh = i.github as { state?: unknown; labels?: unknown } | null
      issues.push({
        number: i.issue,
        stage,
        stageSince: isoMs(i.entered_at),
        holder: typeof i.holder === 'string' ? i.holder : null,
        run: typeof i.run === 'string' ? i.run : null,
        pr: typeof i.pr === 'number' ? i.pr : null,
        stuck: stuck !== null && typeof stuck === 'object' && typeof stuck.rule === 'string' ? stuck.rule : null,
        lapsedAt: typeof i.detail === 'string' ? isoMs(/^claim lapsed at (\S+)/.exec(i.detail)?.[1]) : null,
        ended,
        github:
          gh !== null && typeof gh === 'object'
            ? {
                open: gh.state === 'open' ? true : gh.state === 'closed' ? false : null,
                labels: Array.isArray(gh.labels) ? gh.labels.filter((l): l is string => typeof l === 'string') : null,
              }
            : null,
      })
    }
  }
  take(entry.issues, false)
  take(entry.recent, true)
  return { at, issues }
}

// --- dev-query --csv ---------------------------------------------------------------------

// parseCsv: RFC 4180 rows (quoted fields may hold commas, quotes and newlines), header first.
export function parseCsv(text: string): Record<string, string>[] {
  const rows: string[][] = []
  let field = ''
  let row: string[] = []
  let quoted = false
  for (let i = 0; i < text.length; i++) {
    const c = text[i]
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') {
        field += '"'
        i++
      } else if (c === '"') {
        quoted = false
      } else {
        field += c
      }
    } else if (c === '"') {
      quoted = true
    } else if (c === ',') {
      row.push(field)
      field = ''
    } else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++
      row.push(field)
      rows.push(row)
      row = []
      field = ''
    } else {
      field += c
    }
  }
  if (field !== '' || row.length > 0) {
    row.push(field)
    rows.push(row)
  }
  const header = rows.shift()
  if (header === undefined) return []
  return rows
    .filter(r => r.length === header.length)
    .map(r => Object.fromEntries(header.map((h, i) => [h, r[i] ?? ''])))
}

// --- callum-flow-issue-read --json <N> ------------------------------------------------------

export type IssueFacts = {
  open: boolean
  labels: string[]
  blockedBy: number | null
  // the open issues waiting on this one (issue_dependencies_summary.blocking)
  blocking: number | null
  subIssues: number | null
  title: string
}

export function parseIssueRead(json: string): IssueFacts | null {
  try {
    const issue = JSON.parse(json)?.issue
    if (issue === null || typeof issue !== 'object') return null
    const deps = issue.issue_dependencies_summary
    const subs = issue.sub_issues_summary
    return {
      open: issue.state === 'open',
      labels: Array.isArray(issue.labels) ? issue.labels.map((l: { name?: unknown }) => String(l?.name ?? '')).filter(Boolean) : [],
      blockedBy: typeof deps?.blocked_by === 'number' ? deps.blocked_by : null,
      blocking: typeof deps?.blocking === 'number' ? deps.blocking : null,
      subIssues: typeof subs?.total === 'number' ? subs.total : null,
      title: typeof issue.title === 'string' ? issue.title : '',
    }
  } catch {
    return null
  }
}

// parseBrief: the newest '## Design brief' comment among an issue's trusted comments
// (callum-flow-issue-read --json <N> --comments), by its heading only.
export function parseBrief(json: string): { url: string; at: number } | null {
  try {
    const comments = JSON.parse(json)?.comments
    if (!Array.isArray(comments)) return null
    let best: { url: string; at: number } | null = null
    for (const c of comments) {
      if (typeof c?.body !== 'string' || !c.body.trimStart().startsWith('## Design brief')) continue
      const at = isoMs(c.created_at)
      const url = typeof c.html_url === 'string' ? c.html_url : null
      if (at === null || url === null) continue
      if (best === null || at > best.at) best = { url, at }
    }
    return best
  } catch {
    return null
  }
}

// parseSubIssues: a tracker's open sub-issues on this repo, ascending, from its timeline
// (`callum-flow-issue-read --json --timeline <N>`: {events, stripped}), by replaying its
// sub_issue_added and sub_issue_removed events in order, as the replay harness does (D-35).
// Each event carries the sub-issue as GitHub returns it now, so its state is current. Only
// trusted actors' events reach here: the reader drops the rest.
export function parseSubIssues(json: string, repo: string): number[] | null {
  try {
    const events = JSON.parse(json)?.events
    if (!Array.isArray(events)) return null
    const subs = new Map<number, boolean>()
    const timed = events
      .filter((e: { created_at?: unknown }) => isoMs(e?.created_at) !== null)
      .sort((a: { created_at: string }, b: { created_at: string }) => (isoMs(a.created_at) ?? 0) - (isoMs(b.created_at) ?? 0))
    for (const e of timed) {
      const sub = e.sub_issue
      if (typeof sub?.number !== 'number') continue
      const where = sub.repository?.full_name
      if (typeof where === 'string' && where.toLowerCase() !== repo.toLowerCase()) continue
      if (e.event === 'sub_issue_added') subs.set(sub.number, sub.state === 'open')
      else if (e.event === 'sub_issue_removed') subs.delete(sub.number)
    }
    return [...subs.entries()]
      .filter(([, open]) => open)
      .map(([n]) => n)
      .sort((a, b) => a - b)
  } catch {
    return null
  }
}

// parseQueue: the open issue numbers of `callum-flow-issue-read --json --list --label <L>`.
export function parseQueue(json: string): number[] | null {
  try {
    const issues = JSON.parse(json)?.issues
    if (!Array.isArray(issues)) return null
    return issues
      .map((i: { number?: unknown }) => i?.number)
      .filter((n: unknown): n is number => typeof n === 'number')
      .sort((a: number, b: number) => a - b)
  } catch {
    return null
  }
}

// --- queue-watch.sh --once ------------------------------------------------------------------

// parseQueueOnce: the one line `queue-watch.sh --once` prints (SPEC 3.4),
// `queue known=<n1,n2|none> now=<n1,n2|none>`, as ascending issue numbers; null for anything
// else, so a garbled read is a failed source, never an empty queue.
export function parseQueueOnce(text: string): { known: number[]; now: number[] } | null {
  const m = /^queue known=(none|[1-9]\d*(?:,[1-9]\d*)*) now=(none|[1-9]\d*(?:,[1-9]\d*)*)$/.exec(text.trim())
  if (m?.[1] === undefined || m[2] === undefined) return null
  const list = (v: string) => (v === 'none' ? [] : [...new Set(v.split(',').map(Number))].sort((a, b) => a - b))
  return { known: list(m[1]), now: list(m[2]) }
}

// --- pipeline-watch.sh --once ---------------------------------------------------------------

// One branch's newest run that is not completed, as `pipeline-watch.sh --once` reports it.
export type PipelineRun = {
  state: RunState
  branch: string
  // a ULID, or 'unknown' for a run no source knows the id of
  run: string
  head: string | null
  // the gate a parked run waits at, or the step a failed run failed (null: not known)
  step: string | null
  // the state's own detail, as the watcher logs it in its event's note: head-mismatch's
  // 'run=<sha> branch=<sha>[ worktree=<sha>]', ci-stalled's 'reason=<r>'
  detail: string | null
  pr: number | null
}

const RUN_STATES: readonly RunState[] = [
  'merge-ready',
  'head-mismatch',
  'conflict',
  'ci-stalled',
  'parked',
  'failed',
  'cancelled',
  'running',
  'pending',
]
const ULID = /^[0-9A-HJKMNP-TV-Z]{26}$/i
const SHA = /^[0-9a-f]{4,64}$/i

// parsePipelineLine: one line, `<state> <branch> <run-id>[ key=value...] head=<sha>`, split on
// single spaces. The pairs come in a fixed order: the state's own detail (head-mismatch:
// run=, branch= and an optional worktree=; ci-stalled: reason=no-workflow|no-checks), then
// step= (parked and failed only), then an optional pr=. A SHA or step of 'unknown' reads as
// null. Null for a line that breaks any of it: a watcher the loop does not understand must not
// be read as some other state.
export function parsePipelineLine(line: string): PipelineRun | null {
  const tokens = line.split(' ')
  if (tokens.length < 4 || tokens.includes('')) return null
  const [state, branch, run] = tokens as [string, string, string]
  const last = tokens[tokens.length - 1] as string
  const kind = RUN_STATES.find(s => s === state)
  if (kind === undefined || (run !== 'unknown' && !ULID.test(run)) || !last.startsWith('head=')) return null
  const sha = (v: string | undefined) => (v === undefined ? undefined : v === 'unknown' ? null : SHA.test(v) ? v : undefined)
  const head = sha(last.slice('head='.length))
  if (head === undefined) return null

  const pairs = tokens.slice(3, -1)
  let at = 0
  // take: the next pair's value when its key is `key`, else undefined (the pair stays)
  const take = (key: string) => {
    const pair = pairs[at]
    if (pair === undefined || !pair.startsWith(`${key}=`) || pair.length === key.length + 1) return undefined
    at++
    return pair.slice(key.length + 1)
  }
  let detail: string | null = null
  if (kind === 'head-mismatch') {
    const own = [take('run'), take('branch')]
    const worktree = take('worktree')
    if (worktree !== undefined) own.push(worktree)
    if (own.some(v => sha(v) === undefined)) return null
    detail = pairs.slice(0, at).join(' ')
  } else if (kind === 'ci-stalled') {
    const reason = take('reason')
    if (reason !== 'no-workflow' && reason !== 'no-checks') return null
    detail = `reason=${reason}`
  }
  let step: string | null = null
  if (kind === 'parked' || kind === 'failed') {
    const value = take('step')
    if (value === undefined) return null
    step = value === 'unknown' ? null : value
  }
  const pr = take('pr')
  if (pr !== undefined && !/^[1-9]\d*$/.test(pr)) return null
  // anything left over is a pair this grammar does not have
  if (at !== pairs.length) return null
  return { state: kind, branch, run, head, step, detail, pr: pr === undefined ? null : Number(pr) }
}

// parsePipelineOnce: every line of one `pipeline-watch.sh --once` poll, and the lines that
// broke the grammar (observe fails the source on any: SPEC 3.3). A branch it does not print
// has no run in flight.
export function parsePipelineOnce(text: string): { runs: PipelineRun[]; bad: string[] } {
  const runs: PipelineRun[] = []
  const bad: string[] = []
  for (const line of text.split('\n')) {
    if (line.trim() === '') continue
    const parsed = parsePipelineLine(line)
    if (parsed === null) bad.push(line)
    else runs.push(parsed)
  }
  return { runs, bad }
}

// --- usage-check.sh -------------------------------------------------------------------------

export function parseUsage(line: string): Usage {
  const field = (name: string) => line.match(new RegExp(`(?:^|\\s)${name}=(\\S+)`))?.[1]
  if (line.startsWith('usage=unavailable') || field('five_hour') === undefined) {
    return { fiveHour: null, sevenDay: null, fiveHourResetsAt: null, sevenDayResetsAt: null, unavailable: true }
  }
  const pct = (name: string) => {
    const n = Number(field(name))
    return Number.isFinite(n) ? n : null
  }
  return {
    fiveHour: pct('five_hour'),
    sevenDay: pct('seven_day'),
    fiveHourResetsAt: isoMs(field('resets_at') ?? ''),
    sevenDayResetsAt: isoMs(field('seven_day_resets_at') ?? ''),
    unavailable: false,
  }
}

// --- treehouse status --json ------------------------------------------------------------------

// parsePool: the worktree pool. `treehouse status --json` lists the slots that exist; the
// pool grows up to maxTrees (treehouse.toml), so a slot not yet made counts as free. Whether a
// slot's tree is dirty is not in the listing, nor the branch of a lease whose slot was detached
// (`branch: ""`): observe asks git for the slots it might release (#563).
export function parsePool(json: string, maxTrees: number): Pool | null {
  try {
    const list = JSON.parse(json)
    if (!Array.isArray(list)) return null
    const slots = list.map(raw => {
      const w = raw as Record<string, unknown>
      const branch = typeof w.branch === 'string' && w.branch !== '' ? w.branch : null
      return {
        path: String(w.path ?? ''),
        branch,
        state: String(w.status ?? 'unknown'),
        dirty: null,
        busy: Array.isArray(w.processes) && w.processes.length > 0,
        lease: typeof w.lease_id === 'string' && w.lease_id !== '' ? w.lease_id : null,
        leasedAt: isoMs(w.leased_at),
        leaseBranch: branch,
      }
    })
    const free = slots.filter(s => s.state === 'available').length + Math.max(0, maxTrees - slots.length)
    return { free, total: Math.max(maxTrees, slots.length), slots }
  } catch {
    return null
  }
}

// parseReflog: the branches a slot's checkouts moved to since its lease began (ms), newest first,
// from `git reflog show --date=unix --format=%gd%x09%gs HEAD`: `HEAD@{<unix seconds>}<tab>checkout:
// moving from <a> to <b>`, or a rebase's `... returning to refs/heads/<b>`. Only destinations
// count: the lease's agent moved there itself (its `checkout -b` or `switch`, which its later
// detach leaves behind), while a branch the slot only moved from may be an earlier lease's, left
// checked out when this one began. A detached HEAD and a commit id are no branch, and entries
// before the lease are an earlier lease's (#563), allowing REFLOG_SLACK_S: `treehouse get --lease
// -b` checks the branch out before it records `leased_at`. null when a line does not read.
const REFLOG_SLACK_S = 2
export function parseReflog(text: string, since: number): string[] | null {
  const branches: string[] = []
  for (const line of text.split('\n')) {
    if (line.trim() === '') continue
    const m = line.match(/^HEAD@\{(\d+)\}\t(.*)$/)
    if (m === null) return null
    if (Number(m[1]) < Math.floor(since / 1000) - REFLOG_SLACK_S) continue
    const subject = m[2] ?? ''
    const to = subject.match(/^checkout: moving from \S+ to (\S+)$/)?.[1] ?? subject.match(/ returning to refs\/heads\/(\S+)$/)?.[1]
    if (to !== undefined && to !== 'HEAD' && !/^[0-9a-f]{7,64}$/.test(to)) branches.push(to)
  }
  return branches
}

// changedPath: the path of one `git status --porcelain=v2` line that is a tracked change; null for
// a header, an untracked or ignored file or a blank line; undefined for a line that does not read.
// Ordinary (1), renamed (2, then a score and `<path>\t<orig>`) and unmerged (u) entries carry 8,
// 9 and 10 fields before the path.
function changedPath(line: string): string | null | undefined {
  if (line === '' || line.startsWith('#') || line.startsWith('? ') || line.startsWith('! ')) return null
  const fields = line.startsWith('1 ') ? 8 : line.startsWith('2 ') ? 9 : line.startsWith('u ') ? 10 : null
  if (fields === null) return undefined
  return line.split(' ').slice(fields).join(' ').split('\t')[0] ?? ''
}

// parseDirty: whether `git status --porcelain=v2 --untracked-files=normal` lists a tracked change
// or an untracked file (a pool slot's tree, rule H3): `treehouse return` counts both as uncommitted
// changes and keeps the slot, but not an ignored one (`!`, listed only with --ignored). null when
// a line does not read.
export function parseDirty(status: string): boolean | null {
  let dirty = false
  for (const line of status.split('\n')) {
    if (line.startsWith('? ')) {
      dirty = true
      continue
    }
    const path = changedPath(line)
    if (path === undefined) return null
    if (path !== null) dirty = true
  }
  return dirty
}

// --- the main checkout (#544) -------------------------------------------------------------------

// parseCheckout: origin's default branch, from `git symbolic-ref --short refs/remotes/origin/HEAD`
// (`origin/main`), and the checkout's branch, commit and changed tracked paths, from `git status
// --porcelain=v2 --branch --untracked-files=no` (`# branch.head (detached)` when detached, then
// one line per changed path; untracked files are allowed); null when either does not read.
export function parseCheckout(originHead: string, status: string): Checkout | null {
  const defaultBranch = originHead.trim().match(/^origin\/(\S+)$/)?.[1]
  if (defaultBranch === undefined) return null
  let branch: string | null | undefined
  let head: string | null = null
  const dirty: string[] = []
  for (const line of status.split('\n')) {
    const header = line.match(/^# branch\.(oid|head) (.+)$/)
    if (header?.[1] === 'head') branch = header[2] === '(detached)' ? null : (header[2] ?? null)
    else if (header?.[1] === 'oid') head = header[2] === '(initial)' ? null : (header[2] ?? null)
    const path = changedPath(line)
    if (path === undefined) return null
    if (path !== null) dirty.push(path)
  }
  return branch === undefined ? null : { branch, head, defaultBranch, dirty }
}

// --- callum-flow-milestone show next -----------------------------------------------------------

// parseMilestone: counts of the Next release milestone's open and closed items, and its
// Expected bump; null when the repo has not opted in (the command prints nothing for it).
export function parseMilestone(text: string): Milestone | null {
  if (!/Next release/i.test(text)) return null
  let open = 0
  let closed = 0
  for (const line of text.split('\n')) {
    const m = line.match(/^#\d+\s+(open|closed)\s/)
    if (m?.[1] === 'open') open++
    else if (m?.[1] === 'closed') closed++
  }
  const bump = text.match(/Expected:\s*(patch|minor|major)\b/)?.[1] as Bump | undefined
  return { open, closed, expected: bump ?? null }
}

// --- the last release and the oldest merge since it --------------------------------------------

// parseReleaseTag: the tag of `gh release view --json tagName`; null when it is not that shape.
export function parseReleaseTag(text: string): string | null {
  try {
    const tag: unknown = JSON.parse(text)?.tagName
    return typeof tag === 'string' && tag.trim() !== '' ? tag.trim() : null
  } catch {
    return null
  }
}

// parseCommitDate: the one ISO date line `gh api .../commits/<tag> --jq .commit.committer.date`
// prints, as epoch ms; null when it is not a date.
export function parseCommitDate(text: string): number | null {
  const t = text.trim()
  if (!/^\d{4}-\d\d-\d\dT/.test(t)) return null
  const ms = Date.parse(t)
  return Number.isNaN(ms) ? null : ms
}

// parseTagCommit: the two lines `gh api .../commits/<tag> --jq '.sha,.commit.committer.date'`
// prints: the commit sha, then its date as epoch ms; null when it is not that.
export function parseTagCommit(text: string): { sha: string; at: number } | null {
  const [sha, date, ...rest] = text.trim().split('\n').map((l) => l.trim())
  if (rest.length > 0 || !/^[0-9a-f]{7,64}$/.test(sha ?? '')) return null
  const at = parseCommitDate(date ?? '')
  return at === null ? null : { sha, at }
}

// parseOldestMerge: the earliest mergedAt of `gh pr list --state merged --json mergedAt,mergeCommit`,
// as epoch ms, leaving out the PR whose merge commit is `skipSha` (the release's own bump PR);
// undefined when the output is not a list of that shape, null when no PR is left.
export function parseOldestMerge(text: string, skipSha?: string): number | null | undefined {
  let list: unknown
  try {
    list = JSON.parse(text)
  } catch {
    return undefined
  }
  if (!Array.isArray(list)) return undefined
  let oldest: number | null = null
  for (const p of list) {
    const ms = typeof p?.mergedAt === 'string' ? Date.parse(p.mergedAt) : Number.NaN
    if (Number.isNaN(ms)) return undefined
    if (skipSha !== undefined && p?.mergeCommit?.oid === skipSha) continue
    if (oldest === null || ms < oldest) oldest = ms
  }
  return oldest
}

files.hooks/passes.ts:
// The loop's pass summary (#680): once a minute, one `loop` event with `kind=passes` sums up the
// passes that ended in the minute before. Pure: no engine calls. register.ts feeds it every pass
// as it ends (notePass), closes a minute on its own timer (closeMinute) and sends what
// passesEventArgv builds. The event is bookkeeping, never a stage or progress; entryFromLoop
// returns null for it, so it never rebuilds a ledger entry. The reader does any weighting.

export const MINUTE_MS = 60_000

// One finished pass: how long it took, whether it acted (a non-title outcome) and whether it threw.
export type PassRecord = { ms: number; acted: boolean; error: boolean }

// The passes recorded, by the start (epoch ms) of the UTC minute in which each ended.
export type PassBook = Map<number, PassRecord[]>

// What the note carries besides the numbers: the last runtime the loop resolved.
export type PassSettings = { mode: string; planner: string; passEveryMs: number }

export type PassSummary = {
  from: number
  to: number
  passes: number
  mean: number | null
  p50: number | null
  p90: number | null
  max: number | null
  acting: number
  actingMean: number | null
  idleMean: number | null
  errors: number
  settings: PassSettings
}

export const minuteOf = (ms: number): number => Math.floor(ms / MINUTE_MS) * MINUTE_MS

// notePass: a pass ended at endedAtMs and took ms.
export function notePass(book: PassBook, endedAtMs: number, ms: number, acted: boolean, error: boolean): void {
  const minute = minuteOf(endedAtMs)
  const list = book.get(minute)
  const rec = { ms: Math.round(ms), acted, error }
  if (list === undefined) book.set(minute, [rec])
  else list.push(rec)
}

const mean = (xs: readonly number[]): number | null => (xs.length === 0 ? null : Math.round(xs.reduce((a, b) => a + b, 0) / xs.length))

// nearest rank: the value at ceil(p * n) of the sorted values
function percentile(sorted: readonly number[], p: number): number | null {
  if (sorted.length === 0) return null
  return sorted[Math.min(sorted.length, Math.max(1, Math.ceil(p * sorted.length))) - 1] ?? null
}

// closeMinute: the summary of the minute starting at minuteStartMs (passes=0 when none ended in
// it), and the book let go of that minute and every older one, so memory stays bounded.
export function closeMinute(book: PassBook, minuteStartMs: number, settings: PassSettings): PassSummary {
  const recs = book.get(minuteStartMs) ?? []
  for (const k of [...book.keys()]) if (k <= minuteStartMs) book.delete(k)
  const all = recs.map(r => r.ms)
  const sorted = [...all].sort((a, b) => a - b)
  const acting = recs.filter(r => r.acted)
  const idle = recs.filter(r => !(r.acted))
  return {
    from: minuteStartMs,
    to: minuteStartMs + MINUTE_MS,
    passes: recs.length,
    mean: mean(all),
    p50: percentile(sorted, 0.5),
    p90: percentile(sorted, 0.9),
    max: sorted.length === 0 ? null : (sorted[sorted.length - 1] ?? null),
    acting: acting.length,
    actingMean: mean(acting.map(r => r.ms)),
    idleMean: mean(idle.map(r => r.ms)),
    errors: recs.filter(r => r.error).length,
    settings,
  }
}

const opt = (v: number | null) => (v === null ? 'none' : String(v))

// passesNote: `kind=passes key=passes:<from> status=done ...` (key= and status= are what
// callum-flow-event requires of every loop note). No value holds a space.
export function passesNote(s: PassSummary): string {
  return [
    'kind=passes',
    `key=passes:${s.from}`,
    'status=done',
    `from=${new Date(s.from).toISOString()}`,
    `to=${new Date(s.to).toISOString()}`,
    `passes=${s.passes}`,
    `mean_ms=${opt(s.mean)}`,
    `p50_ms=${opt(s.p50)}`,
    `p90_ms=${opt(s.p90)}`,
    `max_ms=${opt(s.max)}`,
    `acting=${s.acting}`,
    `acting_mean_ms=${opt(s.actingMean)}`,
    `idle_mean_ms=${opt(s.idleMean)}`,
    `errors=${s.errors}`,
    `mode=${s.settings.mode}`,
    `planner=${s.settings.planner}`,
    `pass_every_ms=${s.settings.passEveryMs}`,
  ].join(' ')
}

export function passesEventArgv(s: PassSummary): string[] {
  return ['callum-flow-event', 'loop', '--note', passesNote(s)]
}

files.hooks/v2/events.ts:
// The one seam for every event v2 writes (docs/factory-loop/v2/SPEC.md 7.1): the state, the
// columns, the note and the argv of `callum-flow-event`, and the note's parser. The `event`
// executor (act-state.ts), the owner ops' interventions (act-events.ts), the rebuild of records
// (record.ts) and the migration tool build and read their events here alone, so a later format
// change touches this module only.
//
// The format is today's (owner, 2026-10-15; SPEC 15 "v2's events use today's format"): existing
// `callum-flow-event` states and columns (issue, branch, pr, head; actor for a fixer's verdict),
// and v2's extra fields as `key=value` tokens in the note, encoded as the `loop` notes are
// (derive.ts loopNote, enc):
// - tokens are separated by single spaces, and a value holds no space: `%` and whitespace are
//   percent-encoded (a list item's `,` too);
// - a missing value is `none` (a string that is literally `none` is written `%6Eone`), a list is
//   comma-joined (`none` when empty), a flag is `yes` or `no`;
// - the identifying tokens come first, free text (a question, notes, a reason, a path) last;
//   nothing is clipped: each field is bounded where it is made (a record's free text by the
//   table, a reason by oneLine), so a note carries every field whole.
// The reused states keep the note today's queries read (`brief <url>`, `review`, `CORRECT: ..`),
// verbatim; only `abandoned`, which no query parses, gains a `reason=` token, so the metrics can
// tell a drop, a split, a triage drop and a reconcile release apart (7.3).
//
// Pure: no clock, no command. The executors run eventArgv's argv through ExecCtx.cmd.
import type { FactoryEvent } from '../derive'
import { CLOSED_WHYS, ISSUE_STATES, STEP_KINDS } from './types'
import type { IssueRecord, IssueState } from './types'

// an intervention's reason is one line of at most this many characters (7.1)
export const REASON_MAX = 200

// --- the events ---------------------------------------------------------------------------------

// A state change (4.6), and again after a re-claim (4.1): every record field travels with it, so
// a record can be rebuilt from its newest one (3.3).
export type TransitionEvent = { state: 'transition'; record: IssueRecord; row: string; from: IssueState | null; via: string }

// One review result (8.3).
export type ReviewedEvent = {
  state: 'reviewed'
  issue: number
  branch: string
  pr: number
  head: string
  verdict: 'approve' | 'changes' | 'unknown'
  round: number
  patch: string
  errors: number
  warnings: number
  infos: number
  reviewer: string
  answer: string
}

export const INTERVENTION_WHO = ['person', 'loop'] as const

// One intervention (7.2): who, the cause code, a one-line reason, and the key of the fact it
// records (its ledger key is iv/<fact>), so readers count it once.
export type InterventionEvent = {
  state: 'intervention'
  who: (typeof INTERVENTION_WHO)[number]
  cause: string
  reason: string
  issue: number | null
  life: string | null
  pr: number | null
  fact: string
}

// How a release ends (6.4): back in the queue (requeue), out of the factory (leave), or rejected at
// the issue's last life (reject).
export const RELEASE_OUTCOMES = ['requeue', 'leave', 'reject'] as const

// A reconcile release (6.4): reclaimed when it puts the issue back in the queue, abandoned when the
// issue leaves the factory or is rejected. lives: the released life's number since the issue's
// count last started, null for the migration's.
export type ReleaseEvent = {
  state: 'reclaimed' | 'abandoned'
  issue: number
  branch: string | null
  pr: number | null
  stage: string
  checked: string
  reason: 'reconcile'
  outcome: (typeof RELEASE_OUTCOMES)[number]
  lives: number | null
}

// The reused states, each with the meaning it already has (7.1); the note is today's.
export type ReusedEvent = {
  state: 'delegated' | 'fix_requested' | 'merge_ready' | 'abandoned' | 'merged' | 'verdict'
  issue: number
  branch: string | null
  pr: number | null
  head: string | null
  note: string
}

export type V2Event = TransitionEvent | ReviewedEvent | InterventionEvent | ReleaseEvent | ReusedEvent

export const REUSED_STATES = ['delegated', 'fix_requested', 'merge_ready', 'abandoned', 'merged', 'verdict'] as const
// The states v2 writes, each through this module; the first three are new in callum-flow-event.
export const V2_EVENT_STATES = ['transition', 'reviewed', 'intervention', 'reclaimed', ...REUSED_STATES] as const

// Why an issue was abandoned, as the `reason=` token of the note says it (7.3, claim completion):
// a drop by the owner (E1), a designer's split (T4), a triage drop (X5), a reconcile release (6.4).
export const ABANDON_REASONS = ['dropped', 'split', 'triage', 'reconcile', 'other'] as const
export type AbandonReason = (typeof ABANDON_REASONS)[number]

// abandonReason: a reused `abandoned` event's reason, from its note: a note that already carries
// a `reason=` token keeps it; else its first word says (`dropped`, `split into ..`, `triage`).
export function abandonReason(note: string): AbandonReason {
  const given = tokensOf(note).get('reason')
  const named = ABANDON_REASONS.find(r => r === given)
  if (named !== undefined) return named
  const word = /^\W*(\w+)/.exec(note)?.[1]?.toLowerCase() ?? ''
  if (word === 'split') return 'split'
  if (word === 'triage') return 'triage'
  if (word === 'drop' || word === 'dropped') return 'dropped'
  return 'other'
}

// --- the value codec (derive.ts enc, dec) ---------------------------------------------------------

const NONE = 'none'

// enc: a value with no space in it: `%` and whitespace percent-encoded, so URLs stay readable.
export function enc(v: string): string {
  return v.replace(/[%\s]/g, c => encodeURIComponent(c))
}

export function dec(v: string): string {
  try {
    return decodeURIComponent(v)
  } catch {
    return v
  }
}

// A string, or `none` for null. A string that is literally `none` has its first letter encoded,
// so it reads back as itself.
function str(v: string | null): string {
  if (v === null) return NONE
  return v === NONE ? '%6Eone' : enc(v)
}

function unstr(v: string | undefined): string | null | undefined {
  if (v === undefined) return undefined
  return v === NONE ? null : dec(v)
}

function num(v: number | null): string {
  return v === null ? NONE : String(v)
}

function unnum(v: string | undefined): number | null | undefined {
  if (v === undefined) return undefined
  if (v === NONE) return null
  const n = Number(v)
  return v.trim() !== '' && Number.isFinite(n) ? n : undefined
}

// A list: its items comma-joined, each encoded (a `,` in an item too); `none` when empty.
export function list(v: readonly string[]): string {
  return v.length === 0 ? NONE : v.map(i => str(i).replace(/,/g, '%2C')).join(',')
}

function unlist(v: string | undefined): string[] | undefined {
  if (v === undefined) return undefined
  return v === NONE ? [] : v.split(',').map(dec)
}

const yn = (v: boolean) => (v ? 'yes' : 'no')

// tokensOf: a note's `key=value` tokens, the first of each key; words without `=` are skipped.
export function tokensOf(note: string | null): Map<string, string> {
  const out = new Map<string, string>()
  if (note === null) return out
  for (const word of note.split(' ')) {
    const i = word.indexOf('=')
    if (i > 0 && !out.has(word.slice(0, i))) out.set(word.slice(0, i), word.slice(i + 1))
  }
  return out
}

// noteToken: one token's value, decoded (`none` is null); undefined when the note lacks it. For
// readers that need a field or two, as the factory tools' do.
export function noteToken(note: string | null, key: string): string | null | undefined {
  return unstr(tokensOf(note).get(key))
}

// --- the notes --------------------------------------------------------------------------------------

// What travels in an event's own columns.
export type EventColumns = { issue: number | null; branch: string | null; pr: number | null; head: string | null }

export function eventColumns(e: V2Event): EventColumns {
  switch (e.state) {
    case 'transition':
      return { issue: e.record.issue, branch: e.record.branch, pr: e.record.pr, head: e.record.head }
    case 'reviewed':
      return { issue: e.issue, branch: e.branch, pr: e.pr, head: e.head }
    case 'intervention':
      return { issue: e.issue, branch: null, pr: e.pr, head: null }
    default:
      return { issue: e.issue, branch: e.branch, pr: e.pr, head: 'head' in e ? e.head : null }
  }
}

// The actor the event is logged as: a fixer's dispositions are the fixer's (7.1, section 15);
// null: the CLI's default.
export function eventActor(e: V2Event): string | null {
  return e.state === 'verdict' ? 'fixer' : null
}

function transitionNote(e: TransitionEvent): string {
  const r = e.record
  return [
    `row=${str(e.row)}`,
    `life=${str(r.life)}`,
    `seq=${r.seq}`,
    `from=${str(e.from)}`,
    `to=${r.state}`,
    `seqAt=${r.seqAt}`,
    `since=${r.since}`,
    `resumeTo=${str(r.resumeTo)}`,
    `step=${str(r.step)}`,
    `attempt=${r.attempt}`,
    `cut=${yn(r.cut)}`,
    `triages=${r.triages}`,
    `fixes=${r.fixes}`,
    `round=${r.round}`,
    `why=${str(r.why)}`,
    `approvedPatch=${str(r.approvedPatch)}`,
    `prClosedAt=${str(r.prClosedAt)}`,
    `lives=${r.lives}`,
    `via=${str(e.via)}`,
    `brief=${str(r.brief)}`,
    `question=${str(r.question)}`,
    `notes=${list(r.notes)}`,
  ].join(' ')
}

function reviewedNote(e: ReviewedEvent): string {
  return [
    `verdict=${e.verdict}`,
    `round=${e.round}`,
    `patch=${str(e.patch)}`,
    `errors=${e.errors}`,
    `warnings=${e.warnings}`,
    `infos=${e.infos}`,
    `reviewer=${str(e.reviewer)}`,
    `answer=${str(e.answer)}`,
  ].join(' ')
}

// oneLine: a reason as one line of at most REASON_MAX characters.
export function oneLine(text: string): string {
  const line = text.replace(/\s+/g, ' ').trim()
  return line.length <= REASON_MAX ? line : `${line.slice(0, REASON_MAX - 3)}...`
}

function interventionNote(e: InterventionEvent): string {
  return [`who=${e.who}`, `cause=${str(e.cause)}`, `life=${str(e.life)}`, `fact=${str(e.fact)}`, `reason=${str(oneLine(e.reason))}`].join(' ')
}

function releaseNote(e: ReleaseEvent): string {
  return [`reason=${e.reason}`, `outcome=${e.outcome}`, `lives=${num(e.lives)}`, `stage=${str(e.stage)}`, `pr=${num(e.pr)}`, `checked=${str(e.checked)}`].join(' ')
}

// A drop, a split or a triage drop; `reconcile` is a release's alone (releaseNote).
function abandonedNote(e: ReusedEvent): string {
  const reason = abandonReason(e.note)
  return [`reason=${reason === 'reconcile' ? 'other' : reason}`, `note=${str(e.note)}`].join(' ')
}

// splitNote: the note of a v2 split's `abandoned` event, in the token shape the translator reads
// (factory-event-translate.js shape 3), with the designer's four reasons and each child's why
// (aligned with the children listed). The old `split into ..` words when the reasons can no longer
// be read.
export function splitNote(created: readonly number[], reasons: { why_split: string; why_count: string; why_parts: string; why_order: string } | null, childWhys: readonly string[] | null): string {
  const words = `split into ${created.join(',')}`
  if (reasons === null) return words
  return [
    'reason=split',
    `note=${enc(words)}`,
    `why_split=${enc(reasons.why_split)}`,
    `why_count=${enc(reasons.why_count)}`,
    `why_parts=${enc(reasons.why_parts)}`,
    `why_order=${enc(reasons.why_order)}`,
    `child_whys=${list(childWhys ?? [])}`,
  ].join(' ')
}

// eventNote: the note an event carries.
export function eventNote(e: V2Event): string {
  switch (e.state) {
    case 'transition':
      return transitionNote(e)
    case 'reviewed':
      return reviewedNote(e)
    case 'intervention':
      return interventionNote(e)
    case 'reclaimed':
      return releaseNote(e)
    case 'abandoned':
      return 'reason' in e && e.reason === 'reconcile' ? releaseNote(e) : abandonedNote(e as ReusedEvent)
    default:
      return e.note
  }
}

// eventArgv: `callum-flow-event <state>` for this event: its columns as flags, its actor when it
// has its own, and its note.
export function eventArgv(e: V2Event): string[] {
  const c = eventColumns(e)
  const argv = ['callum-flow-event', e.state]
  if (c.issue !== null) argv.push('--issue', String(c.issue))
  if (c.branch !== null) argv.push('--branch', c.branch)
  if (c.pr !== null) argv.push('--pr', String(c.pr))
  if (c.head !== null) argv.push('--head', c.head)
  const actor = eventActor(e)
  if (actor !== null) argv.push('--actor', actor)
  argv.push('--note', eventNote(e))
  return argv
}

// --- the parser -----------------------------------------------------------------------------------

// What the parser reads of a logged event: its state, its columns and its note.
export type EventRow = Pick<FactoryEvent, 'state' | 'issue' | 'branch' | 'pr' | 'head' | 'note'>

const isState = (v: unknown): v is IssueState => ISSUE_STATES.some(s => s === v)

// parseTransition: the record and row a `transition` event carries, or null when it does not read.
export function parseTransition(row: EventRow): TransitionEvent | null {
  if (row.state !== 'transition' || row.issue === null || row.branch === null) return null
  const t = tokensOf(row.note)
  const life = unstr(t.get('life'))
  const seq = unnum(t.get('seq'))
  const to = t.get('to')
  const fromRaw = unstr(t.get('from'))
  const resumeTo = unstr(t.get('resumeTo'))
  const step = unstr(t.get('step'))
  const why = unstr(t.get('why'))
  const ints = ['seqAt', 'since', 'attempt', 'triages', 'fixes', 'round'].map(k => unnum(t.get(k)))
  const [seqAt, since, attempt, triages, fixes, round] = ints
  const cut = t.get('cut')
  const rowId = unstr(t.get('row'))
  const via = unstr(t.get('via'))
  const brief = unstr(t.get('brief'))
  const question = unstr(t.get('question'))
  const approvedPatch = unstr(t.get('approvedPatch'))
  const prClosedAt = unstr(t.get('prClosedAt'))
  const notes = unlist(t.get('notes'))
  // a note from before the field carries no count: its life is read as a first one
  const lives = t.get('lives') === undefined ? 1 : unnum(t.get('lives'))
  if (typeof life !== 'string' || life === '' || typeof seq !== 'number' || !Number.isInteger(seq) || seq < 0) return null
  if (!isState(to) || (fromRaw !== null && !isState(fromRaw)) || (resumeTo !== null && !isState(resumeTo))) return null
  if (step !== null && !STEP_KINDS.some(s => s === step)) return null
  if (why !== null && !CLOSED_WHYS.some(w => w === why)) return null
  if (ints.some(n => typeof n !== 'number') || (cut !== 'yes' && cut !== 'no')) return null
  if (typeof rowId !== 'string' || via === undefined || brief === undefined || question === undefined) return null
  if (approvedPatch === undefined || prClosedAt === undefined || notes === undefined) return null
  if (typeof lives !== 'number' || !Number.isInteger(lives) || lives < 1) return null
  const record: IssueRecord = {
    issue: row.issue,
    life,
    seq,
    seqAt: seqAt as number,
    state: to,
    since: since as number,
    resumeTo: resumeTo as IssueState | null,
    branch: row.branch,
    pr: row.pr,
    head: row.head,
    approvedPatch,
    brief,
    step: step as IssueRecord['step'],
    attempt: attempt as number,
    cut: cut === 'yes',
    triages: triages as number,
    fixes: fixes as number,
    round: round as number,
    question,
    why: why as IssueRecord['why'],
    notes,
    prClosedAt,
    lives,
  }
  // a via an older, clipped note lost reads back empty
  return { state: 'transition', record, row: rowId, from: fromRaw as IssueState | null, via: via ?? '' }
}

function parseReviewed(row: EventRow): ReviewedEvent | null {
  const t = tokensOf(row.note)
  const verdict = t.get('verdict')
  const [round, errors, warnings, infos] = ['round', 'errors', 'warnings', 'infos'].map(k => unnum(t.get(k)))
  const patch = unstr(t.get('patch'))
  const reviewer = unstr(t.get('reviewer'))
  const answer = unstr(t.get('answer'))
  if (verdict !== 'approve' && verdict !== 'changes' && verdict !== 'unknown') return null
  if (row.issue === null || row.branch === null || row.pr === null || row.head === null) return null
  if ([round, errors, warnings, infos].some(n => typeof n !== 'number') || typeof patch !== 'string' || typeof reviewer !== 'string' || typeof answer !== 'string') return null
  return {
    state: 'reviewed',
    issue: row.issue,
    branch: row.branch,
    pr: row.pr,
    head: row.head,
    verdict,
    round: round as number,
    patch,
    errors: errors as number,
    warnings: warnings as number,
    infos: infos as number,
    reviewer,
    answer,
  }
}

// parseIntervention: an `intervention` event, a hand-recorded rescue included (which may carry
// only who, cause and reason: its fact and life are then null and empty).
export function parseIntervention(row: EventRow): InterventionEvent | null {
  if (row.state !== 'intervention') return null
  const t = tokensOf(row.note)
  const who = INTERVENTION_WHO.find(w => w === t.get('who'))
  const cause = unstr(t.get('cause'))
  if (who === undefined || typeof cause !== 'string' || cause === '') return null
  return {
    state: 'intervention',
    who,
    cause,
    reason: unstr(t.get('reason')) ?? '',
    issue: row.issue,
    life: unstr(t.get('life')) ?? null,
    pr: row.pr,
    fact: unstr(t.get('fact')) ?? '',
  }
}

function parseRelease(row: EventRow): ReleaseEvent | null {
  const t = tokensOf(row.note)
  const stage = unstr(t.get('stage'))
  const pr = unnum(t.get('pr'))
  const checked = unstr(t.get('checked'))
  if (row.state !== 'reclaimed' && row.state !== 'abandoned') return null
  if (t.get('reason') !== 'reconcile' || row.issue === null || typeof stage !== 'string' || pr === undefined || typeof checked !== 'string') return null
  // a release logged before these fields: its state says its outcome, and it carries no count
  const outcome = RELEASE_OUTCOMES.find(o => o === t.get('outcome')) ?? (row.state === 'reclaimed' ? 'requeue' : 'leave')
  const lives = unnum(t.get('lives')) ?? null
  return { state: row.state, issue: row.issue, branch: row.branch, pr, stage, checked, reason: 'reconcile', outcome, lives }
}

// parseEvent: the v2 event a logged row is, or null when it is not one (another state, a note
// that does not read, a `reclaimed` the sweep logged).
export function parseEvent(row: EventRow): V2Event | null {
  switch (row.state) {
    case 'transition':
      return parseTransition(row)
    case 'reviewed':
      return parseReviewed(row)
    case 'intervention':
      return parseIntervention(row)
    case 'reclaimed':
      return parseRelease(row)
    case 'abandoned': {
      const release = parseRelease(row)
      if (release !== null) return release
      const note = unstr(tokensOf(row.note).get('note'))
      if (row.issue === null || typeof note !== 'string') return null
      return { state: 'abandoned', issue: row.issue, branch: row.branch, pr: row.pr, head: row.head, note }
    }
    default: {
      const state = REUSED_STATES.find(s => s === row.state)
      if (state === undefined || row.issue === null) return null
      return { state, issue: row.issue, branch: row.branch, pr: row.pr, head: row.head, note: row.note ?? '' }
    }
  }
}

// --- logged once (7.2) ------------------------------------------------------------------------------

// onceKey: the fact a logged row records, for the events keyed by a fact that outlives the store (a
// companion line, a recorded answer, a head): an intervention by its cause and fact, a review result
// by its answer file, one per review attempt. Read from the note as logged, so a planned event and
// its row read back agree. null for any other event: its ledger key alone logs it once.
export function onceKey(row: EventRow): string | null {
  const t = tokensOf(row.note)
  const id = row.state === 'intervention' ? [t.get('cause'), t.get('fact')] : row.state === 'reviewed' ? [t.get('answer')] : []
  if (id.length === 0 || id.some(v => v === undefined || v === NONE)) return null
  return [row.state, row.issue ?? NONE, ...id].join(' ')
}

// logOnce: an event action's event, marked logged when the event log already holds its fact (its
// onceKey among those of the pass's read of the log, V2State.logged), whatever the ledger lost (a
// wiped store, 3.3): the executor then settles it with no second write.
export function logOnce<E extends V2Event>(logged: readonly string[], event: E): { event: E; logged?: true } {
  const key = onceKey({ state: event.state, ...eventColumns(event), note: eventNote(event) })
  return key !== null && logged.includes(key) ? { event, logged: true } : { event }
}

// --- constructors -----------------------------------------------------------------------------------

// intervention: the event of one intervention, its reason as one line.
export function intervention(who: InterventionEvent['who'], cause: string, fact: string, reason: string, at: { issue: number | null; life: string | null; pr: number | null }): InterventionEvent {
  return { state: 'intervention', who, cause, reason: oneLine(reason), issue: at.issue, life: at.life, pr: at.pr, fact }
}

