// The merge queue (docs/factory-loop/v2/SPEC.md 9): its order, Q1 (update the head when it is
// behind) and Q2 (merge the head when it is clean, green and its patch is the approved one). Only
// the head is ever touched: updated, checked, re-run or merged. A record behind it waits untouched
// however far behind main it falls, told after its period (E6), and no other open PR is updated,
// rebased or closed by any rule.
//
// - Order (9.1): the records in merge-queue whose step is `queue`, oldest seqAt first, ties by
//   issue; paused issues are not in it, and a record on triage is not either. Every transition
//   sets seqAt, so a head whose step ends other than ok goes to the back and the next PR becomes
//   the head (property 14).
// - The head's step (4.2): its result from the tries of its seq (steps-queue.ts), then the PR as
//   read: a changed patch, a conflict, red CI after the one re-run (or GitHub's refusal of it), an
//   untrusted author, a wait on GitHub past its bound; otherwise Q1, a CI re-run, the body written again after a linkage FAIL,
//   the PR reopened after a hand close the record handled, or Q2. A PR that did not read is a wait
//   on GitHub, bounded like any other (4.4); only a GitHub rate limit holds it with no clock.
// - Every action of the head is wanted through the foundation, so one that failed is tried again
//   after its backoff. A queue action or a CI re-run that used up its attempts makes the step
//   unknown, so the queue moves past a head that cannot move (9.1); a PR write is an effect, and
//   one that used up its attempts holds the record as stalled, told to the owner (4.5).
// - PLANS gives that step to rules-state.ts, which calls it with the record's hold, so Q1 and Q2
//   never start before the head's entry actions are done or while another event takes it.
//   queueRules is the composer's hook for rules over the whole queue: there are none, since no
//   record but the head is ever touched.
//
// Pure: the time is state.now.
import { want } from '../foundation'
import type { Gate } from '../foundation'
import type { Action, LedgerEntry } from '../types'
import { prKey, rerunKey, short } from './keys'
import { lifeEntries, triggerOf, unknownOf } from './rules-agent'
import { RERUN_ATTEMPTS } from './rules-review'
import type { StepEnv, StepPlan, StepRead } from './rules-agent'
import type { PrView } from './sources-prs'
import { ciOf, conflictNote, headFacts, mayHaveMerged, mergeKey, mergeResult, mergesAt, pastWait, redNotes, updateKey, updateResult } from './steps-queue'
import type { HeadFacts } from './steps-queue'
import type { IssueRecord, StepKind, TableEvent, Trigger, V2Ctx } from './types'

// The merge tries Q2 makes of one head in one seq: a FAIL of class behind, checks or linkage (after
// the body is written again) earns another, and the guard refusing a head this often while the
// loop reads it as ready is a fact the loop cannot read, so the step is unknown.
export const MERGE_TRIES = 3

// The attempts of one CI re-run (8.5) are the review step's (RERUN_ATTEMPTS, rules-review.ts): a
// call that failed on a transient error re-ran nothing, so it is tried again after its backoff
// before the step is unknown; GitHub's own refusal is never retried.

// The mergeable states GitHub merges from (the guard's CLEAN, UNSTABLE and HAS_HOOKS).
const MERGEABLE: readonly string[] = ['clean', 'unstable', 'has_hooks']

// queueOf: the merge queue, head first (9.1).
export function queueOf(records: readonly IssueRecord[], paused: readonly number[]): IssueRecord[] {
  return records.filter(r => r.state === 'merge-queue' && r.step === 'queue' && !paused.includes(r.issue)).sort((a, b) => a.seqAt - b.seqAt || a.issue - b.issue)
}

// queueRules: the composer's hook (plan.ts) for rules over the whole queue. It plans nothing: the
// head's Q1 and Q2 are its step's (PLANS.queue), and no other record is touched.
export function queueRules(_ctx: V2Ctx): void {}

const fact = (f: string): Trigger => ({ kind: 'fact', fact: f })
const held = (why: string): StepRead => ({ kind: 'held', why })
const result = (event: TableEvent, trigger: Trigger): StepRead => ({ kind: 'result', event, trigger })
const sameSha = (a: string | null, b: string | null) => a !== null && b !== null && (a.startsWith(b) || b.startsWith(a))

// defaultBranch: the branch the queue merges into: the main checkout's origin/HEAD, else the one
// the prs source read main's head of.
function defaultBranch(ctx: V2Ctx): string | null {
  const c = ctx.state.checkout
  if (c !== null && !('error' in c)) return c.defaultBranch
  return ctx.v2.prs.main?.branch ?? null
}

// --- the queue's step (PLANS.queue) ------------------------------------------------------------------

const queuePlan: StepPlan = env => {
  const { ctx, r } = env
  if (ctx.state.control.paused.includes(r.issue)) return held('merge queue: paused by the owner, so the queue moves past it')
  const queue = queueOf(ctx.v2.records, ctx.state.control.paused)
  const at = queue.findIndex(x => x.issue === r.issue && x.life === r.life)
  const head = queue[0]
  if (at > 0 && head !== undefined) return { kind: 'waiting', why: `merge queue: waits behind #${head.issue} (${at + 1} of ${queue.length})` }
  return headStep(env)
}

export const PLANS: Partial<Record<StepKind, StepPlan>> = { queue: queuePlan }

// headStep: the head's step this pass (4.2, 9.2, 9.3).
function headStep(env: StepEnv): StepRead {
  const { ctx, r } = env
  const facts = headFacts(ctx, r)
  if (facts.running !== null) return { kind: 'running', since: facts.running.startedAt, timeoutMs: ctx.config.ciStartMs, key: facts.running.key }
  const base = defaultBranch(ctx)
  const view = r.pr === null ? undefined : ctx.v2.prs.prs.find(p => p.pr === r.pr && p.issue === r.issue)
  // merged: by one of this seq's tries, or at a head a merge of the life names (a hand merge is
  // E3, which rules-state.ts takes before the step)
  const merged = facts.merges.find(e => e.status === 'done' && e.outcome?.kind === 'queue' && e.outcome.merged)
  if (merged !== undefined) return result({ kind: 'ok', data: { pr: r.pr ?? undefined, head: merged.head ?? undefined } }, triggerOf(merged))
  if (view?.state === 'merged') {
    const named = lifeEntries(ctx, r, 'queue-merge').some(e => mayHaveMerged(e) && sameSha(e.head, view.mergedHead))
    if (named) return result({ kind: 'ok', data: { pr: view.pr, head: view.mergedHead ?? undefined } }, fact(`queue-merged:${view.pr}@${short(view.mergedHead ?? '')}`))
    return held(`merge queue: PR #${view.pr} shows merged; GitHub's event is taken first`)
  }
  // the newest try of the seq that ended, unless the PR has moved past the head it tried
  const last = [...facts.updates, ...facts.merges].sort((a, b) => a.startedAt - b.startedAt).at(-1)
  if (last !== undefined) {
    const read = last.kind === 'queue-merge' ? mergeResult(ctx, r, last, base ?? 'the default branch') : updateResult(ctx, r, last, base ?? 'the default branch')
    const moved = view !== undefined && view.state === 'open' && view.head !== null && last.head !== null && !sameSha(view.head, last.head)
    if (read.kind === 'result' && !moved) return result(read.event, triggerOf(last))
  }
  if (!env.start) return held(env.hold ?? 'merge queue: held')
  if (r.pr === null) return result({ kind: 'not-ok', reason: 'patch', data: { text: 'no PR is recorded for the approved work; reviewing ensures one' } }, fact(`queue-no-pr:${r.issue}:s${r.seq}`))
  if (view === undefined) return unread(env, facts, r.pr)
  if (view.state === 'closed') return reopen(env, facts, view, base)
  if (view.head === null) return wait(env, facts, view, `merge queue: the head of PR #${view.pr} is not read`)
  return openHead(env, facts, view, view.head, base)
}

// unread: the head's PR was not read this pass. An untrusted author is a fact (the reader's exit
// 3): policy (9.3, T15). A rate limit that cut the reads short holds the head with no clock, as
// admission holds a step; any other read that failed, or a PR left out for no reason the source
// gives, is a wait on GitHub, bounded (4.4), so a PR that never reads makes the head unknown.
function unread(env: StepEnv, facts: HeadFacts, pr: number): StepRead {
  const { ctx, r } = env
  const prs = ctx.v2.prs
  const failed = prs.unread?.find(u => u.pr === pr && u.issue === r.issue)
  if (failed?.untrusted === true) {
    const text = `PR #${pr} was not opened by a trusted author: the reader refused it (callum-flow-issue-read exit 3)`
    return result({ kind: 'not-ok', reason: 'policy', data: { pr, text } }, fact(`queue-untrusted:${pr}:s${r.seq}`))
  }
  if (failed !== undefined) return wait(env, facts, undefined, `merge queue: PR #${pr} did not read: ${failed.why}`, failed.since)
  if (prs.cut !== undefined) return held(`merge queue: PR #${pr} was not read: ${prs.cut}`)
  const why = ctx.v2.sources.prs.ok ? 'not read this pass' : `not read: ${ctx.v2.sources.prs.error ?? 'the prs source failed'}`
  return wait(env, facts, undefined, `merge queue: PR #${pr} was ${why}`)
}

// openHead: the head's open PR, read: Q2 only when its patch is the approved one, it does not
// conflict, it is not behind and every check passed or was skipped. Behind is a fact the loop
// reads itself: the PR's base is not main's head (GitHub computes mergeability lazily, so it shows
// unknown for a while after main moves), or GitHub says so.
function openHead(env: StepEnv, facts: HeadFacts, view: PrView, head: string, base: string | null): StepRead {
  const { ctx, r } = env
  const at = `${view.pr}@${short(head)}`
  if (view.patch === null) return wait(env, facts, view, `merge queue: the patch id of ${short(head)} is not computed`)
  if (view.patch !== r.approvedPatch) {
    const text = `head ${short(head)} has patch ${short(view.patch)}, not the approved ${r.approvedPatch === null ? 'none' : short(r.approvedPatch)}`
    return result({ kind: 'not-ok', reason: 'patch', data: { pr: view.pr, text } }, fact(`queue-patch:${at}:${short(view.patch)}`))
  }
  if (view.mergeable === 'dirty') {
    const note = conflictNote(r, base ?? 'the default branch')
    return result({ kind: 'not-ok', reason: 'conflict', data: { pr: view.pr, text: note, notes: [note] } }, fact(`queue-conflict:${at}`))
  }
  const tries = mergesAt(facts, head)
  const lastTry = tries.at(-1)
  const lastClass = lastTry?.outcome?.kind === 'queue' ? lastTry.outcome.failClass : null
  if (lastTry !== undefined && lastClass === 'linkage') {
    const linkage = linkageStep(env, view, tries, base)
    if (linkage !== null) return linkage
  }
  const main = ctx.v2.prs.main?.sha ?? null
  const moved = main !== null && view.base !== null && !sameSha(view.base, main)
  if (moved || view.mergeable === 'behind') return update(env, facts, view, head)
  const ci = ciOf(r, view.checks, facts.reruns)
  switch (ci.kind) {
    case 'red': {
      const notes = redNotes(ci.failed, ci.refused)
      return result({ kind: 'not-ok', reason: 'ci-red', data: { pr: view.pr, text: `red CI on ${short(head)}: ${ci.failed.map(c => c.name).join(', ')}`, notes } }, fact(`queue-ci-red:${at}`))
    }
    case 'retry':
      return rerun(env, view, ci.runs)
    case 'pending':
      return wait(env, facts, view, `merge queue: CI runs on ${short(head)} (${ci.done} of ${ci.all} checks done)`)
    case 'none':
      return wait(env, facts, view, `merge queue: no check has reported on ${short(head)} yet`)
  }
  if (!MERGEABLE.includes(view.mergeable ?? '')) return wait(env, facts, view, `merge queue: CI is green on ${short(head)}, and GitHub shows it ${view.mergeable ?? 'not computed'}`)
  return merge(env, view, head, tries)
}

// update: Q1 (9.2): `gh pr update-branch`, keyed by main's head at plan time, once per base in
// the seq.
function update(env: StepEnv, facts: HeadFacts, view: PrView, head: string): StepRead {
  const { ctx, r } = env
  const main = ctx.v2.prs.main?.sha ?? null
  if (main === null) return wait(env, facts, view, `merge queue: PR #${view.pr} is behind, and main's head on origin is not read`)
  const key = updateKey(r, main)
  if (ctx.byKey.has(key)) return wait(env, facts, view, `merge queue: PR #${view.pr} was updated onto ${short(main)}; waits for GitHub to show its new head`)
  const g = want(ctx, { kind: 'queue-update', key, class: 'free', rule: 'Q1', reason: `update PR #${view.pr} onto main ${short(main)}`, issue: r.issue, pr: view.pr, base: main, head, maxAttempts: 1 })
  return planned(env, g, key, `the update of PR #${view.pr}`)
}

// merge: Q2 (9.3): `callum-flow-merge <p> --patch <approvedPatch>`, the guard inside it, keyed by
// the head and the try.
function merge(env: StepEnv, view: PrView, head: string, tries: readonly LedgerEntry[]): StepRead {
  const { ctx, r } = env
  const patch = r.approvedPatch
  if (patch === null) return held('merge queue: no approved patch')
  if (tries.length >= MERGE_TRIES) {
    const entry = tries.at(-1) ?? null
    const event = unknownOf(ctx, r, entry, 'cli', `the merge guard refused ${short(head)} ${tries.length} times while the loop read it as ready`)
    return result(event, entry === null ? fact(`queue-tries:${view.pr}@${short(head)}`) : triggerOf(entry))
  }
  const key = mergeKey(r, head, tries.length + 1)
  const g = want(ctx, { kind: 'queue-merge', key, class: 'free', rule: 'Q2', reason: `merge PR #${view.pr} at ${short(head)}`, issue: r.issue, pr: view.pr, head, patch, maxAttempts: 1 })
  return planned(env, g, key, `the merge of PR #${view.pr}`)
}

// rerun: the one CI re-run of each finished run whose checks failed (8.5), by round and run id,
// tried again when its call failed on a transient error; one used up re-ran nothing, so the checks
// after it are a fact not read, and the step is unknown, never red (in reviewing it is a stalled
// effect instead: the queue moves past a head that cannot move, 9.1).
function rerun(env: StepEnv, view: PrView, runs: readonly string[]): StepRead {
  const { ctx, r } = env
  const reads = runs.map(runId => {
    const key = rerunKey(r, r.round, runId)
    const g = want(ctx, { kind: 'ci-rerun', key, class: 'free', rule: 'S2', reason: `re-run the failed checks of run ${runId} on PR #${view.pr}`, issue: r.issue, pr: view.pr, runId, round: r.round, maxAttempts: RERUN_ATTEMPTS })
    return planned(env, g, key, `the re-run of run ${runId}`)
  })
  return reads.find(x => x.kind === 'result') ?? reads.find(x => x.kind === 'held' && x.why !== '') ?? held('')
}

// linkageStep: after a linkage FAIL the body is written again, once per queue attempt, then Q2
// runs again; a linkage FAIL after that rewrite is policy (8.1, 9.3). A write that failed is tried
// again after its backoff, and one that used up its attempts is stalled (4.5). null: the merge
// may try again.
function linkageStep(env: StepEnv, view: PrView, tries: readonly LedgerEntry[], base: string | null): StepRead | null {
  const { ctx, r } = env
  const action = prAction(ctx, r, 'body', base)
  const g = want(ctx, action)
  if (g !== 'done') return planned(env, g, action.key, `the body of PR #${view.pr}`)
  const body = ctx.byKey.get(action.key)
  const last = tries.at(-1)
  if (body !== undefined && last !== undefined && body.endedAt !== null && last.startedAt > body.endedAt) {
    const lines = last.outcome?.kind === 'queue' ? last.outcome.lines : []
    const text = `the linkage still fails after the body was written again: ${lines.join('; ') || 'no FAIL line'}`
    return result({ kind: 'not-ok', reason: 'policy', data: { pr: view.pr, text } }, fact(`queue-linkage:${view.pr}:s${r.seq}`))
  }
  return null
}

// reopen: a PR a person closed parked the record (E4); the resume brings it back here, so the
// loop's ensure reopens it (8.1, P1).
function reopen(env: StepEnv, facts: HeadFacts, view: PrView, base: string | null): StepRead {
  const action = prAction(env.ctx, env.r, 'ensure', base)
  const g = want(env.ctx, action)
  if (g === 'done') return wait(env, facts, view, `merge queue: PR #${view.pr} was reopened; waits for GitHub to show it open`)
  return planned(env, g, action.key, `the reopening of PR #${view.pr}`)
}

// prAction: the loop's own PR write (8.1, U5's executor): its title, summary and evidence are the
// builder's answer, the newest one of the life.
function prAction(ctx: V2Ctx, r: IssueRecord, op: 'ensure' | 'body', base: string | null): Action {
  const built = lifeEntries(ctx, r, 'agent-step')
    .filter(e => e.status === 'done' && e.outcome?.kind === 'step' && e.outcome.step === 'build' && e.outcome.result.event === 'ok')
    .sort((a, b) => b.startedAt - a.startedAt)[0]
  const said = built?.outcome?.kind === 'step' ? built.outcome.result.data : null
  const o = said !== null && typeof said === 'object' ? (said as Record<string, unknown>) : {}
  const text = (v: unknown): string | null => (typeof v === 'string' && v.trim() !== '' ? v : null)
  return {
    kind: 'pr',
    op,
    key: prKey(r, op, r.attempt),
    class: 'free',
    rule: op === 'body' ? 'Q2' : 'S2',
    reason: op === 'body' ? `write the body of PR #${r.pr ?? '?'} again after a linkage FAIL` : `reopen PR #${r.pr ?? '?'} for the merge queue`,
    issue: r.issue,
    branch: r.branch,
    base: base ?? '',
    pr: r.pr,
    title: text(o.title) ?? `#${r.issue}`,
    summary: text(o.summary) ?? '',
    evidence: text(o.evidence),
    brief: r.brief,
  }
}

// planned: what a step's own action says once wanted: '' when planned this pass, else why not.
// One that used up its attempts is the step's unknown (cli), so the head never holds on it (an
// effect that did, a PR write, holds the record as stalled before the step runs, 4.5).
function planned(env: StepEnv, g: Gate, key: string, what: string): StepRead {
  if (g === 'go') return held('')
  if (g === 'wait') return held(`merge queue: ${what} runs again after its backoff`)
  if (g === 'running') return held(`merge queue: ${what} runs`)
  if (g === 'done') return held(`merge queue: ${what} is done`)
  const entry = env.ctx.byKey.get(key) ?? null
  const event = unknownOf(env.ctx, env.r, entry, 'cli', `${what} used up its attempts: ${entry?.summary ?? entry?.status ?? 'no try recorded'}`)
  return result(event, entry === null ? fact(`queue-exhausted:${key}`) : triggerOf(entry))
}

// wait: the head waits on GitHub with nothing of its own running; past the bound (4.4) it is
// unknown (github-wait), counted from no earlier than `since` (the first of a PR's failed reads in
// a row). A GitHub backoff holds it with no clock, as admission holds a step.
function wait(env: StepEnv, facts: HeadFacts, view: PrView | undefined, why: string, since?: number): StepRead {
  const { ctx, r } = env
  const s = ctx.state
  if (s.githubBackoffUntil !== null && s.now < s.githubBackoffUntil) return held(`${why}; GitHub reads wait out a rate limit`)
  const past = pastWait(ctx, r, view, facts, since)
  if (past === null) return held(why)
  return result(unknownOf(ctx, r, null, 'github-wait', `${why}: ${past}`), fact(`queue-wait:${r.issue}:s${r.seq}`))
}

files.hooks/v2/rules-slots.ts:
// The slots (docs/factory-loop/v2/SPEC.md 10.1, 3.5, 5.1, appendix A, appendix C): W2 frees a loop
// slot no record holds, then W1 leases one for each record that needs one, as far as capacity, the
// pool's reserve and the tier allow. The loop finds its slots only by their lease holder,
// `factory-loop:<N>:<life>` (observe.ts holderOf), in the pool's own listing; it never infers a
// slot's owner from a reflog or a branch.
//
// - W2, free: a slot leased by the loop for an issue's life is freed when no record of that life
//   is queued or in a slot state (designing to merge-queue) and nothing of that life still runs in
//   it (an agent step, or a slot op). A queued record keeps the lease its step is about to take
//   (row T1). So a slot is freed however its issue left: parked, dropped, merged, closed by hand,
//   lost to another device, released by R1, or a record pruned. A second lease of a live life (a
//   lease whose answer was lost, taken again) is freed too, once nothing of the life runs: the
//   record holds the one rules-agent.ts leaseOf names. Keyed by the lease (keys.ts freeKey), so one
//   lease is freed once; from the free's start the lease counts as gone (rules-agent.ts freeing),
//   so a record resumed meanwhile never steps onto a slot being reset and returned.
//   A free of a life with a parked record keeps the life's scratch folders (keepScratch, the
//   tool's --keep-scratch): a resume continues the life; a later free removes them, and the tool
//   prunes any older than 7 days.
// - W1, lease: first each record in a slot state whose lease vanished (it already counts in
//   flight; its running step ends unknown with the cause `slot` at once, rules-agent.ts agentStep,
//   and the lease waits until the stopped step no longer runs), then each queued record with no
//   lease: resumes first, by the time they parked, then new claims, by claim time. A record whose
//   life's old slot is being freed waits for the free: the tool would hand that slot back. A
//   queued record is leased only while the records in flight (designing to merge-queue, a queued
//   record that holds or is taking a lease) number fewer than K (`maxInFlightIssues`), the pool's
//   free slots exceed `worktreeReserve`, and the tier allows the class of the step the lease leads
//   to; a vanished one needs one free slot and the tier.
// - A lease is keyed by its number in the life (keys.ts leaseKey): a failed one runs again under
//   its own key; once one is done and a pool read after it no longer shows it, the next number is
//   taken. A done lease the pool was read before is not leased again: the next pass sees it.
// - W2 is planned before W1, so for one issue the old life's slot goes back first (totality/T-19).
//
// Pure: the time is state.now.
import { ALLOWED, gate, skip, want } from '../foundation'
import type { ActionClass, LedgerEntry, Ms } from '../types'
import { freeKey, keyParts, leaseKey, lifeAt, lifeKey } from './keys'
import { freeing, leaseOf, lifeEntries } from './rules-agent'
import { AGENT_STEPS, SLOT_STATES, STATE_STEP, STEP_CLASS } from './types'
import type { AgentStep, IssueRecord, IssueState, Lease, V2Ctx } from './types'

// The attempts of each op that W1 and W2 plan (appendix B).
export const LEASE_ATTEMPTS = 3
export const FREE_ATTEMPTS = 2

// The entry kinds of a life that run in its slot: while one runs, the slot is in use.
const IN_SLOT: readonly LedgerEntry['kind'][] = ['agent-step', 'slot']

const isAgentStep = (s: string | null): s is AgentStep => s !== null && (AGENT_STEPS as readonly string[]).includes(s)

// classOf: the class of the step a state runs (appendix B): an agent step's own, else free (the
// merge queue's head runs commands, no agent).
export function classOf(state: IssueState): ActionClass {
  const step = STATE_STEP[state]
  return isAgentStep(step) ? STEP_CLASS[step] : 'free'
}

// --- the life's leases --------------------------------------------------------------------------------

const LEASE_N = /^lease\/([1-9]\d*)$/

// leaseEntries: the life's lease attempts (W1), by their number, oldest first.
export function leaseEntries(ctx: V2Ctx, r: Pick<IssueRecord, 'issue' | 'life'>): { n: number; entry: LedgerEntry }[] {
  const out: { n: number; entry: LedgerEntry }[] = []
  for (const e of lifeEntries(ctx, r, 'slot')) {
    const p = keyParts(e.key)
    const m = p === null || p.seq !== null ? null : LEASE_N.exec(p.rest)
    if (m?.[1] !== undefined) out.push({ n: Number(m[1]), entry: e })
  }
  return out.sort((a, b) => a.n - b.n)
}

// What W1 knows of a record's lease beside the pool: its next key; or that one is under way (its
// lease runs, or ended after the pool was read), so it takes its place and its slot already.
type LeaseNext = { kind: 'key'; key: string } | { kind: 'pending'; why: string }

function nextLease(ctx: V2Ctx, r: IssueRecord): LeaseNext {
  // the tool keeps a slot that carries the life's holder, so a new lease waits for the old one to go
  const old = ctx.v2.leases.find(l => l.issue === r.issue && l.life === r.life && freeing(ctx, l))
  if (old !== undefined) return { kind: 'pending', why: `its old slot ${old.path} is being freed (${freeKey(old.lease)})` }
  const last = leaseEntries(ctx, r).at(-1)
  if (last === undefined) return { kind: 'key', key: leaseKey(r, 1) }
  const e = last.entry
  if (e.status === 'running') return { kind: 'pending', why: `its lease ${last.n} runs` }
  if (e.status !== 'done') return { kind: 'key', key: e.key }
  const readAt = ctx.v2.sources.leases.at ?? 0
  if ((e.endedAt ?? e.startedAt) >= readAt) return { kind: 'pending', why: `lease ${last.n} is newer than the pool's read` }
  return { kind: 'key', key: leaseKey(r, last.n + 1) }
}

// runningIn: something of the life still runs in its slot (an agent step, a prepare, a kill).
function runningIn(ctx: V2Ctx, life: Pick<IssueRecord, 'issue' | 'life'>): LedgerEntry | null {
  return lifeEntries(ctx, life).find(e => e.status === 'running' && IN_SLOT.includes(e.kind)) ?? null
}

// parkedAt: when a resumed record parked: the newest transition of its life into parked, before
// its current seq; else when it entered queued.
function parkedAt(ctx: V2Ctx, r: IssueRecord): Ms {
  let at: Ms | null = null
  let seq = -1
  for (const e of lifeEntries(ctx, r, 'transition')) {
    const s = keyParts(e.key)?.seq ?? null
    if (s === null || s >= r.seq || s <= seq || e.outcome?.kind !== 'transition' || e.outcome.to !== 'parked') continue
    seq = s
    at = e.startedAt
  }
  return at ?? r.since
}

// --- W2: free --------------------------------------------------------------------------------------------

// holds: a record of the lease's life is queued (about to take it) or in a slot state.
function holds(ctx: V2Ctx, l: Lease): boolean {
  return ctx.v2.records.some(r => r.issue === l.issue && r.life === l.life && (r.state === 'queued' || SLOT_STATES.includes(r.state)))
}

// parked: a record of the lease's life is parked, so a resume continues the life and its scratch
// folders stay (free --keep-scratch); a later free of the life, after the resume, removes them.
function parked(ctx: V2Ctx, l: Lease): boolean {
  return ctx.v2.records.some(r => r.issue === l.issue && r.life === l.life && r.state === 'parked')
}

function frees(ctx: V2Ctx): void {
  for (const l of [...ctx.v2.leases].sort((a, b) => a.path.localeCompare(b.path))) {
    if (l.issue === null || l.life === null) continue
    const life = { issue: l.issue, life: l.life }
    const held = holds(ctx, l)
    // a live life keeps the one lease leaseOf names; any other of it is a second lease, or one
    // whose free is under way already
    if (held && leaseOf(ctx, life)?.lease === l.lease) continue
    const busy = freeing(ctx, l) ? null : runningIn(ctx, life)
    if (busy !== null) {
      skip(ctx, 'W2', l.issue, `W2: slot ${l.path} of life ${l.life} waits: ${busy.key} still runs in it`)
      continue
    }
    want(ctx, {
      kind: 'slot',
      op: 'free',
      key: freeKey(l.lease),
      class: 'free',
      rule: 'W2',
      reason: held ? `slot ${l.path} is a second lease of #${l.issue} life ${l.life}` : `no record of #${l.issue} life ${l.life} holds slot ${l.path}`,
      issue: l.issue,
      life: l.life,
      path: l.path,
      lease: l.lease,
      branch: null,
      marker: null,
      keepScratch: parked(ctx, l),
      maxAttempts: FREE_ATTEMPTS,
    })
  }
}

// --- W1: lease ---------------------------------------------------------------------------------------------

// tierHolds: why the tier or the owner holds the step a lease leads to, or null.
function tierHolds(ctx: V2Ctx, to: IssueState): string | null {
  const cls = classOf(to)
  if (!ALLOWED[ctx.tier].includes(cls)) return `tier ${ctx.tier} holds ${STATE_STEP[to] ?? to} (${cls})`
  if (ctx.state.control.noNewWork && (cls === 'develop' || cls === 'start')) return `owner: no new work holds ${STATE_STEP[to] ?? to}`
  return null
}

function leases(ctx: V2Ctx): void {
  const { config } = ctx
  const live = ctx.v2.records.filter(r => r.state !== 'closed')
  const vanished = live.filter(r => SLOT_STATES.includes(r.state) && leaseOf(ctx, r) === null)
  const queued = live.filter(r => r.state === 'queued' && leaseOf(ctx, r) === null)
  if (vanished.length === 0 && queued.length === 0) return
  const pool = ctx.state.sources.pool.ok ? ctx.state.pool : null
  // a lease under way holds its place in flight and its slot (nextLease)
  const pending = new Map(queued.concat(vanished).map(r => [r, nextLease(ctx, r)]))
  const underWay = [...pending.values()].filter(p => p.kind === 'pending').length
  let flight = live.filter(r => SLOT_STATES.includes(r.state) || (r.state === 'queued' && (leaseOf(ctx, r) !== null || pending.get(r)?.kind === 'pending'))).length
  let free = pool === null ? null : pool.free - underWay
  const resumes = queued.filter(r => r.seq > 1).map(r => ({ r, at: parkedAt(ctx, r) }))
  const claims = queued.filter(r => r.seq <= 1).map(r => ({ r, at: lifeAt(r.life) ?? r.since }))
  const byTime = (a: { r: IssueRecord; at: Ms }, b: { r: IssueRecord; at: Ms }) => a.at - b.at || a.r.issue - b.r.issue
  const order = [...vanished.sort((a, b) => a.issue - b.issue).map(r => ({ r, at: 0 })), ...resumes.sort(byTime), ...claims.sort(byTime)].map(x => x.r)
  for (const r of order) {
    const lost = r.state !== 'queued'
    const next = pending.get(r) ?? nextLease(ctx, r)
    if (next.kind === 'pending') {
      skip(ctx, 'W1', r.issue, `W1: ${next.why}`)
      continue
    }
    if (gate(ctx, next.key, 'slot', LEASE_ATTEMPTS) === 'exhausted') {
      // the record's stall (rules-entry.ts stalledOf) tells the owner
      skip(ctx, 'W1', r.issue, `W1: stalled: ${next.key}`)
      continue
    }
    const to = lost ? r.state : (r.resumeTo ?? 'designing')
    const busy = lost ? runningIn(ctx, r) : null
    let limit: string | null = null
    if (busy !== null) limit = `its slot is gone and ${busy.key} still runs`
    else if (free === null) limit = `the pool's free slots are not known (${ctx.state.sources.pool.error ?? 'not read'})`
    else if (!lost && config.maxInFlightIssues !== null && flight >= config.maxInFlightIssues) limit = `capacity: ${flight} of ${config.maxInFlightIssues} in flight`
    else if (!lost && free <= config.worktreeReserve) limit = `no free worktree: ${free} free, ${config.worktreeReserve} kept in reserve`
    else if (lost && free <= 0) limit = 'no free worktree'
    else limit = tierHolds(ctx, to)
    if (limit !== null) {
      if (limit.startsWith('capacity')) ctx.atCap = true
      skip(ctx, 'W1', r.issue, `W1: ${limit}`)
      continue
    }
    const g = want(ctx, {
      kind: 'slot',
      op: 'lease',
      key: next.key,
      class: 'free',
      rule: 'W1',
      reason: lost ? `the slot of ${r.state} is gone (${lifeKey(r)})` : `a slot for ${to}`,
      issue: r.issue,
      life: r.life,
      path: null,
      lease: null,
      branch: null,
      marker: null,
      keepScratch: false,
      maxAttempts: LEASE_ATTEMPTS,
    })
    // planned, or waiting out its backoff: either way it takes its place and its slot
    if (g === 'go' || g === 'wait') {
      if (!lost) flight += 1
      if (free !== null) free -= 1
    }
  }
}

// slotRules (W2, then W1): nothing while the pool's leases were not read, since every loop slot
// would look gone and every record unleased.
export function slotRules(ctx: V2Ctx): void {
  if (!ctx.v2.sources.leases.ok) {
    if (ctx.v2.records.some(r => r.state !== 'closed')) skip(ctx, 'W1', null, `W1, W2: the pool's leases were not read (${ctx.v2.sources.leases.error ?? 'not read'}); no slot is leased or freed`)
    return
  }
  frees(ctx)
  leases(ctx)
}

files.hooks/v2/rules-agent.ts:
// The plan side of a record's step (docs/factory-loop/v2/SPEC.md 4.2, 4.4, 5.1, 10.2, 14.1 S2):
// what one step says each pass (StepRead), the generic agent step that the designer, the builder,
// the fixer and the triage run (S2: the slot prepared, then the agent spawned; its result read from
// its ledger entry, an outside cause named from facts the loop holds), and the lease step of a
// queued record. rules-state.ts asks each record's step through its StepPlan; a step whose reading
// is its own unit's (review, U6; the merge queue's head, U7; the work steps' effects, U5) has its
// plan in that unit's rules module, which may build on agentStep here.
//
// Pure: the time is state.now.
import { stepBreaker, want } from '../foundation'
import type { LedgerEntry, Ms, State } from '../types'
import { freeKey, keyParts, lifeAt, prepareKey, stepKey } from './keys'
import type { FixWhy } from './prompts-work'
import type { EventData } from './table'
import { AGENT_STEPS, STEP_CLASS, STEP_ROLE, WHY_CAUSE } from './types'
import type { AgentStep, IssueRecord, Lease, OutsideCause, StepKind, StepMarker, StepResult, TableEvent, Trigger, UnknownWhy, V2Ctx } from './types'

// What a record's step says this pass:
// - running: something of the step runs; its clock started at `since` (4.4) and the step is
//   unknown (timeout) past timeoutMs;
// - result: the step ended with this event for the table, and the trigger the transition
//   re-checks (3.3);
// - waiting: a waiting state (4.4): nothing runs, and E6 tells on the state's period;
// - held: nothing of the step runs, and it has no clock: a start was planned this pass (why is
//   empty), or something holds it, which the skip line names (why).
export type StepRead =
  | { kind: 'running'; since: Ms; timeoutMs: Ms; key: string }
  | { kind: 'result'; event: TableEvent; trigger: Trigger }
  | { kind: 'waiting'; why: string }
  | { kind: 'held'; why: string }

// What a step's plan gets for one record: start says whether S2 may start the step's actions this
// pass (the seq's entry actions are done, nothing stalls the record, no other event takes it), and
// hold says why not; slot is the record's lease, when it holds one.
export type StepEnv = { ctx: V2Ctx; r: IssueRecord; slot: Lease | null; start: boolean; hold: string | null }

export type StepPlan = (env: StepEnv) => StepRead

// --- facts a step reads --------------------------------------------------------------------------------

// freeing: W2's free of this lease runs or is done, so the lease is gone though a pool read made
// before the free ended still shows it (10.1). A free that failed leaves the slot leased and whole.
export function freeing(ctx: V2Ctx, l: Pick<Lease, 'lease'>): boolean {
  const e = ctx.byKey.get(freeKey(l.lease))
  return e !== undefined && (e.status === 'running' || e.status === 'done')
}

// leasesOfLife: the life's leases, by holder factory-loop:<N>:<life> (10.1), but those W2 frees.
export function leasesOfLife(ctx: V2Ctx, r: Pick<IssueRecord, 'issue' | 'life'>): Lease[] {
  return ctx.v2.leases.filter(l => l.issue === r.issue && l.life === r.life && !freeing(ctx, l))
}

// leaseOf: the slot the record holds: its life's lease (leasesOfLife). When the life has two (a
// lease whose answer was lost, taken again), the one its newest done prepare named, else its newest
// done lease, else the first by path, so the choice holds from pass to pass; W2 frees the other.
export function leaseOf(ctx: V2Ctx, r: Pick<IssueRecord, 'issue' | 'life'>): Lease | null {
  const mine = leasesOfLife(ctx, r)
  if (mine.length <= 1) return mine[0] ?? null
  const named = (op: 'prepare' | 'lease') =>
    lifeEntries(ctx, r, 'slot')
      .filter(e => e.status === 'done' && e.outcome?.kind === 'slot' && e.outcome.op === op)
      .sort((a, b) => (b.endedAt ?? b.startedAt) - (a.endedAt ?? a.startedAt))
      .flatMap(e => (e.outcome?.kind === 'slot' && e.outcome.lease !== null ? [e.outcome.lease] : []))
  for (const id of [...named('prepare'), ...named('lease')]) {
    const l = mine.find(x => x.lease === id)
    if (l !== undefined) return l
  }
  return [...mine].sort((a, b) => a.path.localeCompare(b.path))[0] ?? null
}

// lifeEntries: the ledger entries of one life (their keys name it), of one kind or all.
export function lifeEntries(ctx: V2Ctx, r: Pick<IssueRecord, 'issue' | 'life'>, kind?: LedgerEntry['kind']): LedgerEntry[] {
  return ctx.state.ledger.filter(e => {
    if (kind !== undefined && e.kind !== kind) return false
    const p = keyParts(e.key)
    return p !== null && p.issue === r.issue && p.life === r.life
  })
}

// sentToFix: why a transition sent the record toward a fixer, or null when it is not one that
// does: T9 into fixing (fix:<kind>), X2 into fixing (triage:fix), or T10 parking at the fix cap
// (fix-cap:<kind>), whose resume leads back to fixing through queued (T1). X4 shares X2's via but
// parks, so the state it went to counts too.
function sentToFix(to: string, via: string): FixWhy | null {
  if (to === 'fixing' && via === 'triage:fix') return 'triage'
  const kind = (to === 'fixing' ? /^fix:(review|ci|conflict)$/ : to === 'parked' ? /^fix-cap:(review|ci|conflict)$/ : null)?.exec(via)?.[1]
  return kind === undefined ? null : (kind as FixWhy)
}

// fixWhyOf: why the record is in fixing, which the fixer's prompt and the fix_requested note read:
// the newest transition of its life, up to its seq, that sent it toward a fixer (sentToFix). A
// retry inside fixing (U1's free re-run, U2's second attempt, X1's triage retry) and a resume (T1)
// are their own seqs with their own vias, so they keep the reason the fixing began with. null when
// no such transition is in the ledger (a rebuild, a pruned ledger).
export function fixWhyOf(state: State, r: IssueRecord): FixWhy | null {
  let newest: { seq: number; why: FixWhy } | null = null
  for (const e of state.ledger) {
    if (e.kind !== 'transition' || e.status !== 'done' || e.outcome?.kind !== 'transition') continue
    const p = keyParts(e.key)
    if (p === null || p.issue !== r.issue || p.life !== r.life || p.seq === null || p.seq > r.seq) continue
    const why = sentToFix(e.outcome.to, e.outcome.via)
    if (why !== null && (newest === null || p.seq > newest.seq)) newest = { seq: p.seq, why }
  }
  return newest?.why ?? null
}

// leftoversOf: the leftovers files the life's slot ops saved (10.2), newest first: each prepare's,
// and each free's, which a parked or released life's slot left. A retry's or a resumed step's
// prompt names the newest (5.1). A free is keyed by its lease (keys.ts freeKey), so a file is the
// life's by its own name, which the tool builds from the lease's holder: <N>-<life>-...
export function leftoversOf(ledger: readonly LedgerEntry[], r: Pick<IssueRecord, 'issue' | 'life'>): string[] {
  const prefix = `${r.issue}-${r.life}-`
  return ledger
    .flatMap(e => {
      const o = e.outcome
      if (e.kind !== 'slot' || e.status !== 'done' || o?.kind !== 'slot' || typeof o.leftovers !== 'string') return []
      return (o.leftovers.split('/').at(-1) ?? '').startsWith(prefix) ? [{ file: o.leftovers, at: e.endedAt ?? e.startedAt }] : []
    })
    .sort((a, b) => b.at - a.at)
    .map(x => x.file)
}

// timeoutOf: a running step's timeout (4.4).
export function timeoutOf(ctx: V2Ctx, step: AgentStep): Ms {
  return ctx.config.stateTimeoutMs[step]
}

// triggerOf: what a transition from this entry's result re-checks: the entry, as plan saw it.
export function triggerOf(e: LedgerEntry): Trigger {
  return { kind: 'entry', key: e.key, status: e.status, startedAt: e.startedAt }
}

const isAgentStep = (step: StepKind | null): step is AgentStep => step !== null && (AGENT_STEPS as readonly string[]).includes(step)

// causeOf: the cause outside the issue of an unknown that ended now (5.1), each from a fact the
// loop holds, never inferred: the step's entry started before this module load and was lost
// (load); the record's lease is gone (slot); a rate limit, or a tier that stops new work (usage);
// the step-unknown breaker open when it ended, or tripped by this unknown (breaker). null: none.
export function causeOf(ctx: V2Ctx, r: IssueRecord, entry: LedgerEntry | null, why: UnknownWhy): OutsideCause | null {
  const { state } = ctx
  if (entry !== null && entry.status === 'lost' && entry.startedAt < state.loadedAt) return 'load'
  if (ctx.v2.sources.leases.ok && leaseOf(ctx, r) === null && r.state !== 'queued') return 'slot'
  if (WHY_CAUSE[why] !== undefined) return WHY_CAUSE[why] ?? null
  if (ctx.tier === 'stop-new' || ctx.tier === 'stop-all') return 'usage'
  const at = entry?.endedAt ?? state.now
  if (stepBreaker(state.ledger, at) !== null) return 'breaker'
  if (isAgentStep(r.step)) {
    // this unknown, as its transition would record it: does it trip the breaker?
    const probe: LedgerEntry = {
      key: `probe/${r.issue}`,
      kind: 'transition',
      class: 'free',
      rule: 'S4',
      issue: r.issue,
      run: null,
      pr: null,
      head: null,
      status: 'done',
      attempts: 1,
      startedAt: state.now,
      endedAt: state.now,
      outcome: { kind: 'transition', row: 'U2', event: 'unknown', cause: null, from: r.state, to: r.state, step: r.step, stored: true },
    }
    if (stepBreaker([...state.ledger, probe], state.now) !== null) return 'breaker'
  }
  return null
}

// unknownOf: an unknown for the table, with why, a reason and its outside cause: the one given, a
// fact the caller holds (5.1), else causeOf's.
export function unknownOf(ctx: V2Ctx, r: IssueRecord, entry: LedgerEntry | null, why: UnknownWhy, reason: string, cause?: OutsideCause): TableEvent {
  return { kind: 'unknown', why, reason: reason.length > 300 ? `${reason.slice(0, 297)}...` : reason, cause: cause ?? causeOf(ctx, r, entry, why) ?? undefined }
}

// asEventData: the fields of a step's answer the rows read, each of its own type (table.ts
// EventData); anything else is left out.
export function asEventData(x: unknown): EventData {
  if (x === null || typeof x !== 'object' || Array.isArray(x)) return {}
  const o = x as Record<string, unknown>
  const out: EventData = {}
  for (const k of ['text', 'question', 'brief', 'head', 'patch', 'instructions', 'closedAt', 'note'] as const) {
    const v = o[k]
    if (typeof v === 'string' && v !== '') out[k] = v
  }
  if (typeof o.pr === 'number' && Number.isInteger(o.pr) && o.pr > 0) out.pr = o.pr
  if (typeof o.commits === 'boolean') out.commits = o.commits
  if (Array.isArray(o.notes) && o.notes.every(n => typeof n === 'string')) out.notes = [...(o.notes as string[])]
  return out
}

// resultEvent: a step's result as the table reads it. A triage's valid answer is the `triage`
// event with its choice; any other step's ok and not-ok carry the answer's fields (EventData), and
// a not-ok's reason is the step's code (table.ts NOT_OK_REASONS).
export function resultEvent(ctx: V2Ctx, r: IssueRecord, entry: LedgerEntry, step: StepKind, result: StepResult): TableEvent {
  if (result.event === 'unknown') return unknownOf(ctx, r, entry, result.why ?? 'bad-answer', result.reason ?? 'no usable answer')
  const data: EventData = { ...asEventData(result.data), ...(result.head === null ? {} : { head: result.head }) }
  if (step === 'triage') {
    if (result.event !== 'ok' || result.choice === null) return unknownOf(ctx, r, entry, 'bad-answer', 'the triage gave no choice')
    return { kind: 'triage', choice: result.choice, reason: result.reason ?? undefined, data: { ...data, text: data.text ?? result.reason ?? undefined } }
  }
  if (result.event === 'ok') return { kind: 'ok', data }
  return { kind: 'not-ok', reason: result.reason ?? undefined, data }
}

// stepEvent: an ended agent step's entry as the table reads it: its recorded result, or the
// generic agent unknown (4.2): lost or failed with no result, timed out.
export function stepEvent(ctx: V2Ctx, r: IssueRecord, e: LedgerEntry, step: StepKind): TableEvent {
  if (e.status === 'done') {
    const o = e.outcome
    if (o?.kind === 'step') return resultEvent(ctx, r, e, step, o.result)
    return unknownOf(ctx, r, e, 'bad-answer', `${e.key} ended with no result`)
  }
  const said = e.summary ?? e.status
  if (e.status === 'timed-out') return unknownOf(ctx, r, e, 'timeout', said)
  if (e.status === 'lost') return unknownOf(ctx, r, e, 'agent-dead', said)
  // failed: the agent list saw it fail or killed; a job file not written or a refusal (a loop bug)
  // is a CLI result outside the step's outcomes; anything else kept the agent from starting
  if (/^agent (failed|killed)/.test(said)) return unknownOf(ctx, r, e, 'agent-dead', said)
  if (/could not be written|^refused/.test(said)) return unknownOf(ctx, r, e, 'cli', said)
  return unknownOf(ctx, r, e, 'spawn', said)
}

// --- the generic agent step (S2, S5) ---------------------------------------------------------------------

// notesFor: what the step's agent is told: the record's notes for this seq, then the owner's notes
// for the issue (or every issue) made in this life (`/factory note`).
export function notesFor(ctx: V2Ctx, r: IssueRecord): string[] {
  const lifeStart = lifeAt(r.life) ?? 0
  const owner = ctx.state.control.notes.filter(n => (n.issue === null || n.issue === r.issue) && n.at >= lifeStart).map(n => `owner: ${n.text}`)
  return [...r.notes, ...owner]
}

// markerOf: the step marker the slot's git dir carries (10.2). The slot executor sets loopDir, the
// loop's own folder, which plan does not know.
export function markerOf(ctx: V2Ctx, r: IssueRecord, step: AgentStep): StepMarker {
  return {
    v: 1,
    repo: ctx.state.repo,
    issue: r.issue,
    life: r.life,
    seq: r.seq,
    step,
    role: STEP_ROLE[step],
    branch: r.branch,
    pr: r.pr,
    gateCommands: [...ctx.config.gateCommands],
    gateTimeoutMs: ctx.config.gateTimeoutMs,
    loopDir: '',
    scratch: '',
  }
}

export type AgentOpts = {
  step: AgentStep
  // the step attempt's key (default stepKey: one per seq and attempt; review's is by patch and round)
  key?: string
  // the slot's preparation for it (default prepareKey: one per seq and attempt; a reviewer after
  // another of its seq gets its own, keys.ts reviewPrepareKey)
  prepare?: string
  // the rule that starts it (S2; S5 for triage)
  rule?: string
}

// slotLost: how the attempt's slot is gone, or null: with the pool's leases read, the record holds
// no lease, or not the one the attempt's prepare (done) ran in.
function slotLost(ctx: V2Ctx, slot: Lease | null, prep: LedgerEntry | undefined): string | null {
  if (!ctx.v2.sources.leases.ok) return null
  const o = prep?.status === 'done' && prep.outcome?.kind === 'slot' ? prep.outcome : null
  if (slot === null) return `is gone${o?.path ? ` (${o.path})` : ''}`
  if (o !== null && o.lease !== null && o.lease !== slot.lease) return `is gone: it was prepared on lease ${o.lease}, and the record now holds ${slot.lease} (${slot.path})`
  return null
}

// agentStep: one agent step of the record, generic over its kind (S2): the slot prepared for the
// attempt (10.2), then the agent spawned in it (10.3); running while either runs, with the step's
// timeout counted from the start of the running entry (4.4); then the result its entry recorded,
// or the generic agent unknown. A prepare that ended without done is the attempt's unknown
// (cli): it is part of the attempt, one per key. Nothing starts while env.start is false, so a held
// step has no running entry and no clock.
//
// The attempt's slot gone (slotLost) ends it at once, unknown with the cause `slot` (5.1's free
// re-run): a running agent then (agent-dead), so the new seq's entry actions stop it rather than let
// it write on, for up to the step's timeout, in a slot the pool may give another issue (property 6);
// a done prepare whose agent has not started (spawn), so no agent starts in a slot that was never
// prepared for it (10.2). The next attempt prepares the slot W1 leases.
export function agentStep(env: StepEnv, opts: AgentOpts): StepRead {
  const { ctx, r } = env
  const step = opts.step
  const key = opts.key ?? stepKey(r, step, r.attempt)
  const prep = opts.prepare ?? prepareKey(r, r.attempt)
  const rule = opts.rule ?? (step === 'triage' ? 'S5' : 'S2')
  const timeoutMs = timeoutOf(ctx, step)
  const e = ctx.byKey.get(key)
  const p = ctx.byKey.get(prep)
  const lost = slotLost(ctx, env.slot, p)
  if (e !== undefined) {
    if (e.status === 'running' && lost !== null) {
      return { kind: 'result', event: unknownOf(ctx, r, e, 'agent-dead', `the slot of ${step} ${lost}; its agent is stopped`, 'slot'), trigger: triggerOf(e) }
    }
    if (e.status === 'running') return { kind: 'running', since: e.startedAt, timeoutMs, key }
    // a step key is one attempt (maxAttempts 1): whatever it ended with is the attempt's result
    return { kind: 'result', event: stepEvent(ctx, r, e, step), trigger: triggerOf(e) }
  }
  if (p?.status === 'running') return { kind: 'running', since: p.startedAt, timeoutMs, key: prep }
  if (p !== undefined && p.status !== 'done') {
    return { kind: 'result', event: unknownOf(ctx, r, p, 'cli', `the slot could not be prepared for ${step}: ${p.summary ?? p.status}`), trigger: triggerOf(p) }
  }
  if (p !== undefined && lost !== null) {
    return { kind: 'result', event: unknownOf(ctx, r, p, 'spawn', `the slot prepared for ${step} ${lost}; ${step} never started`, 'slot'), trigger: triggerOf(p) }
  }
  if (!env.start) return { kind: 'held', why: env.hold ?? `${step} is held` }
  const slot = env.slot
  if (slot === null) return { kind: 'held', why: `${step} waits for its slot (W1)` }
  if (p === undefined) {
    want(ctx, {
      kind: 'slot',
      op: 'prepare',
      key: prep,
      class: 'free',
      rule,
      reason: `prepare the slot for ${step} attempt ${r.attempt}`,
      issue: r.issue,
      life: r.life,
      path: slot.path,
      lease: slot.lease,
      branch: r.branch,
      marker: markerOf(ctx, r, step),
      keepScratch: false,
      maxAttempts: 1,
    })
    return { kind: 'held', why: '' }
  }
  want(ctx, {
    kind: 'agent-step',
    key,
    class: STEP_CLASS[step],
    rule,
    reason: `${step} attempt ${r.attempt}`,
    issue: r.issue,
    step,
    life: r.life,
    seq: r.seq,
    attempt: r.attempt,
    branch: r.branch,
    slot: slot.path,
    notes: notesFor(ctx, r),
  })
  return { kind: 'held', why: '' }
}

// The design, build, fix and triage steps as the generic agent step; units with more to read
// (U5's work steps) give their own plan in rules-work.ts.
export const agentPlan =
  (step: AgentStep): StepPlan =>
  env =>
    agentStep(env, { step })

// leaseStep: queued's step (4.2): ok once a lease with the record's holder exists, which W1
// leases (10.1); until then the record waits, told on queued's period (E6).
export const leaseStep: StepPlan = ({ ctx, slot }) => {
  if (slot !== null) return { kind: 'result', event: { kind: 'ok' }, trigger: { kind: 'fact', fact: `lease:${slot.lease}` } }
  if (!ctx.v2.sources.leases.ok) return { kind: 'held', why: 'queued: the pool was not read, so no lease is known' }
  return { kind: 'waiting', why: 'queued: waits for a slot (W1)' }
}

// notBuiltStep: the plan of a step whose unit is not built yet: held, and the skip line says so.
export function notBuiltStep(step: StepKind, unit: string): StepPlan {
  return () => ({ kind: 'held', why: `the ${step} step is not built yet (${unit})` })
}

